typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* initializeLinkedList(int N) {
    srand(time(NULL)); //seed random number generator

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    int* RX_tag_set = (int*)malloc(sizeof(int)*N);

    for(int i=0; i<N; i++) {
        //generate random RX_UE_INFORMATION_TAG
        int RX_tag = rand() % (2^31-1);
        while(1) {
            if(!checkRX_tag_collision(RX_tag, RX_tag_set)) {
                break;
            }
            RX_tag = (RX_tag + 1) % (2^31-1);
        }

        //generate random RNTI and CRC_INDICATION_REL8_TAG
        int RNTI = rand() % (2^16-1);
        int CRC_INDICATION_REL8_TAG = rand() % (2^32-1);

        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->RX_UE_INFORMATION_TAG = RX_tag;
        new_node->RNTI = RNTI;
        new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

        if(head == NULL) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    free(RX_tag_set);
    return head;
}

int checkRX_tag_collision(int RX_tag, int* RX_tag_set) {
    for(int i=0; i<sizeof(RX_tag_set)/sizeof(RX_tag_set[0]); i++) {
        if(RX_tag_set[i] == RX_tag)
            return 1;
    }
    return 0;
}
