void manageMemory(int numOffsets, int numRecords, int rangeMin, int rangeMax) {
    // Allocate and initialize offset and key arrays
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    int* keys = (int*)malloc(numOffsets * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed. Reallocating...\n");
        numOffsets *= 2;
        offsets = (long*)realloc(offsets, numOffsets * sizeof(long));
        keys = (int*)realloc(keys, numOffsets * sizeof(int));
    }

    // Initialize arrays
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Allocate and initialize record array
    record* records = (record*)malloc(numRecords * sizeof(record));

    if (!records) {
        printf("Memory allocation failed. Reallocating...\n");
        numRecords *= 2;
        records = (record*)realloc(records, numRecords * sizeof(record));
    }

    // Initialize records
    for (int i = 0; i < numRecords; i++) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(rangeMin, rangeMax);
        records[i].value = dis(gen);
    }

    // Monitor and manage memory usage
    size_t totalMemoryUsed = numOffsets * sizeof(long) + numOffsets * sizeof(int) + numRecords * sizeof(record);

    if (totalMemoryUsed > 1024 * 1024 * 50) {
        printf("Memory usage exceeds threshold. Resizing arrays...\n");
        numOffsets *= 2;
        keys = (int*)realloc(keys, numOffsets * sizeof(int));
        records = (record*)realloc(records, numRecords * sizeof(record));

        totalMemoryUsed = numOffsets * sizeof(long) + numOffsets * sizeof(int) + numRecords * sizeof(record);
    }

    // Retrieve data from external source
    for (int i = 0; i < numRecords; i++) {
        int externalValue = retrieveDataFromExternalSource(i);
        if (externalValue == -1) {
            printf("Error retrieving data. Skipping...\n");
        } else {
            records[i].value = externalValue;
        }
    }

    // Deallocate memory when function returns
    free(offsets);
    free(keys);
    free(records);

}

