#include <stdio.h>
#include <stdlib.h>

#define MAX_BATCH_SIZE 10000
#define MAX_CACHESIZE 1000000

typedef struct {
    int* values;
    size_t size;
} Cache;

Cache create_cache(size_t size) {
    return (Cache){malloc(sizeof(int) * size), 0};
}

void free_cache(Cache* cache) {
    free(cache->values);
}

int find_max_unique(int* batch, size_t batch_size, Cache* cache) {
    int max_unique = INT_MIN;
    for (size_t i = 0; i < batch_size; i++) {
        int val = batch[i];
        if (val != -1 && !cache->values[cache->size++]) {
            cache->values[cache->size++] = val;
            if (max_unique == INT_MIN || val > max_unique) {
                max_unique = val;
            }
        } else if (val != -1) {
            for (size_t j = 0; j < cache->size; j++) {
                if (cache->values[j] == val) {
                    break;
                }
            }
            if (j == cache->size) {
                cache->values[cache->size++] = val;
                if (max_unique == INT_MIN || val > max_unique) {
                    max_unique = val;
                }
            }
        }
    }
    return max_unique;
}

void process_batch(int* batch, size_t batch_size, Cache* cache) {
    int max_unique = find_max_unique(batch, batch_size, cache);
    printf("Largest Unique Integer: %d\n", max_unique);
}

int main() {
    Cache cache = create_cache(MAX_CACHESIZE);
    while (1) {
        int batch[MAX_BATCH_SIZE];
        size_t batch_size = 0;
        while ((batch[batch_size++] = getchar()) != EOF && batch_size < MAX_BATCH_SIZE) {}
        if (ferror(stdin)) {
            printf("Error reading input.\n");
            break;
        }
        process_batch(batch, --batch_size, &cache);
    }
    free_cache(&cache);
    return 0;
}
