#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <pthread.h>

#define LOG_BUFFER_SIZE 1024
#define MAX_APPS 64

typedef struct {
    int buffer[LOG_BUFFER_SIZE];
    int head;
    int tail;
} LogBuffer;

LogBuffer* log_buffers[MAX_APPS];
int num_apps = 0;

void init_log_buffer(int app_id) {
    if (num_apps >= MAX_APPS) return;
    log_buffers[num_apps] = (LogBuffer*)malloc(sizeof(LogBuffer));
    log_buffers[num_apps]->head = log_buffers[num_apps]->tail = 0;
    num_apps++;
}

void log_app(int app_id, const char* format, ...) {
    va_list args;
    va_start(args, format);

    LogBuffer* log_buffer = log_buffers[app_id];
    if (log_buffer->head == LOG_BUFFER_SIZE) {
        log_buffer->tail = 0;
        log_buffer->head = 1; // overwrite oldest entry
    }
    int idx = log_buffer->head % LOG_BUFFER_SIZE;
    sprintf((char*)(&log_buffer->buffer[idx]), format, args);

    va_end(args);
}

void get_latest_entries(int app_id, int count, char* buffer[]) {
    LogBuffer* log_buffer = log_buffers[app_id];
    int idx = log_buffer->tail;
    for (int i = 0; i < count && i < LOG_BUFFER_SIZE; i++) {
        sprintf(buffer[i], "%s", (char*)(&log_buffer->buffer[idx]));
        idx = (idx + 1) % LOG_BUFFER_SIZE;
    }
}

void cleanup() {
    for (int i = 0; i < num_apps; i++) free(log_buffers[i]);
}
