import os
import hashlib
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor, as_completed

def compute_sha256_hash(directory: str, extensions: set = None, ignore_case: bool = False) -> dict:
    result = {}
    executor = ThreadPoolExecutor(max_workers=os.cpu_count())
    futures = []

    def process_file(file_path):
        file_path = Path(file_path)
        if not file_path.is_dir():
            hash_object = hashlib.sha256()
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_object.update(chunk)
            result[file_path.relative_to(Path(directory)).as_posix()] = hash_object.hexdigest()

    for root, dirs, files in os.walk(directory):
        for file in files:
            if (not extensions or Path(file).suffix[1:] in extensions) and not file.startswith('.'):
                futures.append(executor.submit(process_file, os.path.join(root, file)))

    for future in as_completed(futures):
        future.result()

    return result
