    public Report generateReport(List<Pokemon> pokemons, boolean concise) {
        Report report = new Report();
        for (Pokemon pokemon : pokemons) {
            PokemonTypeAnalysis analysis = analyzePokemon(pokemon);
            if (concise) {
                report.addConciseEntry(analysis.getWeaknesses());
