#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure representing a semaphore
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} semaphore_t;

// Function to create a new semaphore with the given initial value
semaphore_t* sem_create(int value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    if (!sem) {
        return NULL;
    }
    sem->value = value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
    return sem;
}

// Function to delete a semaphore
void sem_delete(semaphore_t* sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
    free(sem);
}

// Function to increment the value of a semaphore
void sem_inc(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to decrement the value of a semaphore
void sem_dec(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value++;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to print the current state of a semaphore
void sem_print(semaphore_t* sem) {
    printf("Semaphore value: %d\n", sem->value);
}
