#include <vector>
#include <algorithm>

void insertAndOptimize(std::vector<int>& vec, int target, int insertion, int uniqueKey) {
    auto it = std::find(vec.begin(), vec.end(), target);
    if (it != vec.end()) {
        for (auto& num : vec) {
            if (num == uniqueKey) {
                it = std::remove(it, vec.end(), num);
                vec.erase(it);
                break;
            }
        }
    }

    auto insertPos = vec.begin();
    bool found = false;
    for (auto& num : vec) {
        if (num == target) {
            found = true;
            break;
        }
        insertPos++;
    }

    if (!found) {
        insertPos = std::find(vec.begin(), vec.end(), 0) - vec.begin();
    }

    vec.insert(insertPos, insertion);
}
