class HttpClient {
public:
    void setProxy(const std::string& proxy) { this->proxy = proxy; }
    void sendGetRequest(const std::string& url, const std::string& metadataIp) {
        boost::beast::http::request<boost::beast::http::string_body> request;
        request.method(boost::beast::http::verb::get);
        request.target(url);

        if (proxy.empty()) {
            // Send request directly
            sendRequest(request, metadataIp);
        } else {
            // Use load balancer and proxy server
            setProxy(metadataIp);
            sendRequestThroughProxy(request);
        }
    }

    void sendPostRequest(const std::string& url, const std::string& metadataIp, const std::string& body) {
        boost::beast::http::request<boost::beast::http::string_body> request;
        request.method(boost::beast::http::verb::post);
        request.target(url);

        if (proxy.empty()) {
            // Send request directly
            sendRequest(request, metadataIp, body);
        } else {
            // Use load balancer and proxy server
            setProxy(metadataIp);
            sendRequestThroughProxy(request, body);
        }
    }

private:
    void sendRequest(const boost::beast::http::request<boost::beast::http::string_body>& request, const std::string& metadataIp) {
        // Connect to the server using the connection pool
        boost::asio::io_service ioService;
        boost::asio::ip::tcp::resolver resolver(ioService);
        boost::asio::ip::tcp::endpoint endpoint = *resolver.resolve(metadataIp);

        boost::beast::http::async_write(ioService, request,
            [this, &metadataIp](boost::beast::error_code ec) {
                if (!ec)
                    Logger::log("Request sent to " + metadataIp);
                else
                    Logger::log("Error sending request: " + std::string(ec.message()));
        });
