namespace LoggingFramework {
    namespace {
        std::mutex mtx;
        int logLevel = 0; // Default level: INFO
    }

    class Logger {
    public:
        Logger(const char* logFile) : file(logFile), console(true) {
            // Initialize logging mechanism
        }

        ~Logger() {
            // Close file and console logs
        }

        void setLogLevel(int level) {
            logLevel = level;
        }

        template<typename T>
        void log(int level, const T& message) {
            if (level >= logLevel) {
                // Handle log rotation based on file size
                file << message << std::endl;

                // Write to console for real-time logging
                if (console) {
                    std::cout << message << std::endl;
                }
            }
        }

    private:
        std::ofstream file;
        bool console;
    };

    Logger& getLogger() {
        static Logger logger("log.txt"); // Default log file
        return logger;
    }

    int main() {
        // Configure logging level via environment variable
        setLogLevel(std::atoi(getenv("LOG_LEVEL")));

        // Use the logger
        Logger& logger = getLogger();
        logger.log(DEBUG, "Debug message");
        logger.log(INFO, "Info message");

        return 0;
    }
}
