    public IDataReader ProcessDataParallel(List<Record> records, SqlConnection connection, string query)
    {
        List<Task<SqlDataReader>> tasks = new List<Task<SqlDataReader>>();
        Dictionary<long, Task<SqlDataReader>> taskDictionary = new Dictionary<long, Task<SqlDataReader>>();

        foreach (var record in records)
        {
            long recordId = record.Id;
            Task<SqlDataReader> task = Task.Run(async () =>
            {
                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@recordId", recordId);
                    SqlDataReader reader = await command.ExecuteReaderAsync();
                    return reader;
                }
            });
            tasks.Add(task);
            taskDictionary.Add(recordId, task);
        }

        Task<SqlDataReader>[] parallelTasks = tasks.ToArray();
        IDataReader resultReader = null;

        try
        {
            resultReader = Parallel.ForEach(tasks, (task) =>
            {
                try
                {
                    SqlDataReader reader = task.Result;
                    if (resultReader == null)
                        resultReader = reader;
                    else
                        MergeReaders(resultReader, reader);
                }
                catch (Exception ex)
                {
                    // Handle failure and log error
                    Console.WriteLine("Error processing record: " + ex.Message);
                }
