// Update Resource
function updateResource(req, res) {
  const resourceId = req.params.id;
  const updatedData = req.body;

  // Validate incoming request body against predefined schema
  if (!validateRequestBody(updatedData)) {
    return res.status(400).send({ error: 'Invalid request body' });
  }

  // Get the current version of the resource
  db.get('SELECT * FROM resources WHERE id = ?', resourceId, (err, row) => {
    if (err || !row) {
      return res.status(404).send({ error: 'Resource not found' });
    }
    const currentVersion = row.version;

    // Check for concurrent updates and handle accordingly
    db.get('SELECT * FROM resources WHERE id = ? AND version = ?', resourceId, currentVersion, (err, row) => {
      if (err || !row) {
        return res.status(409).send({ error: 'Concurrent update detected' });
      }

      // Update the resource with optimistic concurrency control
      db.run(`UPDATE resources SET data = ?, version = ? WHERE id = ?`, [updatedData, currentVersion + 1, resourceId], (err) => {
        if (err) {
          return res.status(500).send({ error: 'Server error' });
        }
        res.send({ message: 'Resource updated successfully' });
      });
    });
  });
}

// Delete Resource
function deleteResource(req, res) {
  const resourceId = req.params.id;

  // Get the current version of the resource
  db.get('SELECT * FROM resources WHERE id = ?', resourceId, (err, row) => {
    if (err || !row) {
      return res.status(404).send({ error: 'Resource not found' });
    }
    const currentVersion = row.version;

    // Cascade deletion of associated resources and update related entities with default values
    db.run(`DELETE FROM resources WHERE id = ?`, [resourceId], (err) => {
      if (err) {
        return res.status(500).send({ error: 'Server error' });
      }
      res.send({ message: 'Resource deleted successfully' });
    });
  });
}

