    XPathNavigator navigator = doc.CreateNavigator();

    string directoryName = "Your_directory_name"; // Replace with the required name
    string environmentVariableName = "Your_environment_variable_name"; // Replace with the required name

    if (navigator.SelectSingleNode("/root/*[local-name()='Your_element_name']") != null)
    {
        try
        {
            string directoryPath;
            if (!Environment.GetEnvironmentVariable(environmentVariableName, EnvironmentVariableTarget.Process).IsNullOrEmpty())
            {
                directoryPath = Environment.GetEnvironmentVariable(environmentVariableName, EnvironmentVariableTarget.Process);
            }
            else
            {
                int retryCount = 0;
                while (retryCount < 3)
                {
                    try
                    {
                        directoryPath = Path.Combine(Path.GetDirectoryName(Application.ExecutablePath), directoryName);
                        Directory.CreateDirectory(directoryPath);
                        break;
                    }
                    catch (IOException ex)
                    {
                        if (retryCount >= 2)
                        {
                            Logger.LogError(ex.Message);
                            return;
                        }
                        retryCount++;
                        System.Threading.Thread.Sleep(1000); // Wait for a second before retrying
                    }
                }
                Environment.SetEnvironmentVariable(environmentVariableName, directoryPath, EnvironmentVariableTarget.Process);
            }
        }
        catch (Exception ex)
        {
            Logger.LogError(ex.Message);
        }
    }
    else
    {
        Logger.LogInformation("The required element was not found in the XML document.");
    }
