import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class MD5Service {
    private static final int MEMORY_THRESHOLD = 1000000; // adjust as needed
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private ReentrantLock lock = new ReentrantLock();
    private long thresholdSize = MEMORY_THRESHOLD;
    private long maxAgeMillis = 30000; // 30 seconds

    public void process(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            String hash = bytesToHex(md.digest(input.getBytes()));
            cache.put(input, hash);
            logSuccess(input, hash);
        } catch (NoSuchAlgorithmException e) {
            logFailure(input, e.getMessage());
        }
    }

    private void clearCache() {
        long now = System.currentTimeMillis();
        for (String key : new ArrayList<>(cache.keySet())) {
            if (now - cache.get(key).lastAccessTime() > maxAgeMillis) {
                cache.remove(key);
            } else if (cache.size() >= thresholdSize) {
                cache.remove(key);
            }
        }
    }

    public void run() {
        while (true) {
            try {
                process("your_input_string"); // replace with actual input
            } catch (Exception e) {
                logFailure(e.getMessage());
            } finally {
                clearCache();
            }
            Thread.sleep(100); // adjust as needed
        }
    }

    private void logSuccess(String input, String hash) {
        System.out.println("MD5 generated for " + input + ": " + hash);
    }

    private void logFailure(String message) {
        System.out.println("Error: " + message);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(Integer.toHexString((b & 0xFF) | 0x100).substring(1));
        }
        return result.toString();
    }
}
