function manageUserRequests() {
    $input = $_POST;
    $validationResult = validateInput($input);
    if (!$validationResult) {
        return json_encode(['status' => 'error', 'message' => 'Invalid input']);
    }

    $action = getActionFromInput($input);

    switch ($action) {
        case 'create':
            createUserAccount($input);
            break;
        case 'update':
            updateUserAccount($input);
            break;
        case 'delete':
            deleteUserAccount($input['id']);
            break;
    }

    return json_encode(['status' => 'success', 'message' => 'Operation completed successfully']);
}

function validateInput(array $input) {
    if (!isset($input['name']) || strlen($input['name']) < 3) {
        return false;
    }
    if (!filter_var($input['email'], FILTER_VALIDATE_EMAIL)) {
        return false;
    }
    if (!isset($input['password'])) {
        return true; // No password, so no validation needed
    }
    $rules = [
        'min' => 8,
        'require_uppercase' => true,
        'require_lowercase' => true,
        'require_digit' => true,
    ];
    if (!validatePassword($input['password'], $rules)) {
        return false;
    }

    return true;
}

function getActionFromInput(array $input) {
    if (isset($input['id'])) {
        return 'update';
    }
    if (isset($input['sub_action']) && $input['sub_action'] === 'delete') {
        return 'delete';
    }
    return 'create';
}

function createUserAccount(array $input) {
    // Connect to the database
    $db = connectToDatabase();
    try {
        $query = "INSERT INTO users (name, email, password) VALUES (:name, :email, :password)";
        $stmt = $db->prepare($query);
        $stmt->execute([':name' => $input['name'], ':email' => $input['email'], ':password' => $input['password']]);
    } catch (Exception $e) {
        logError('createUserAccount', $e);
        return;
    }
}

function updateUserAccount(array $input) {
    // Connect to the database
    $db = connectToDatabase();
    try {
        $query = "UPDATE users SET name = :name, email = :email WHERE id = :id";
