        logError('connectToDatabase', $e);
        return;
    }

    return $db;
}

function validatePassword(string $password, array $rules) {
    // Check the password against the given rules
    if (strlen($password) < $rules['min']) {
        return false;
    }
    if (!preg_match('/[A-Z]/', $password)) {
        return false;
    }
    if (!preg_match('/[a-z]/', $password)) {
        return false;
    }
    if (!preg_match('/\d/', $password)) {
        return false;
    }

    return true;
}

function logError(string $operation, Exception $e) {
    // Log the error
    file_put_contents('error.log', $operation . ': ' . $e->getMessage() . "\n", FILE_APPEND);
}
