const fs = require('fs');
const path = require('path');
const axios = require('axios');

async function processFiles(directory) {
  const filesReport = [];
  const apiToken = 'YOUR_API_TOKEN';

  async function readAndProcessFile(file) {
    try {
      const fileContents = await fs.promises.readFile(file.path, 'utf8');
      // Process file contents to extract metadata (e.g., JSON.parse(), regex matching)
      const metadata = JSON.parse(fileContents);
      // Extract relevant information from metadata
      const extractedData = { ...metadata };
      // Integrate with external API for additional data validation
      try {
        const apiResponse = await axios.get(`https://api.example.com/validation`, {
          headers: { 'Authorization': `Bearer ${apiToken}` },
          params: { id: file.name }
        });
        extractedData.apiValidated = apiResponse.data;
      } catch (error) {
        console.error(`Error validating file "${file.name}":`, error);
      }
      return extractedData;
    } catch (error) {
      console.error(`Error processing file "${file.path}":`, error);
      return null;
    }
  }

  async function processDirectory(directory) {
    const files = await fs.promises.readdir(directory, { withFileTypes: true });
    for (const file of files) {
      if (file.isDirectory()) {
        // Recursively process subdirectories
        await processDirectory(path.join(directory, file.name));
      } else {
        const fileMetadata = await readAndProcessFile(file);
        if (fileMetadata) {
          filesReport.push(fileMetadata);
        }
      }
    }
  }

  await processDirectory(directory);

  return filesReport;
}
