function processExperimentDocument(documentChunk) {
  const phases = ['hypothesis', 'methods', 'results', 'conclusions'];
  const langDet = new LanguageDetector();
  const languageTranslations = {};

  async function extractPhases(chunk) {
    let sectionPhases = {};
    for (const phase of phases) {
      sectionPhases[phase] = [];
    }

    for await (let text of chunk.split('\n\n')) {
      if (!text) continue;

      const language = langDet.detect(text);
      if (!languageTranslations[language]) {
        try {
          languageTranslations[language] = natural.LANGUAGE PACKS[language];
        } catch (e) {
          console.error(`Failed to detect or translate language: ${e}`);
        }
      }

      for (const phase in sectionPhases) {
        const regex = new RegExp(phase + ': (.*)', 'i');
        if (regex.test(text)) {
          sectionPhases[phase].push(translateText(text, languageTranslations[language]));
        }
      }
    }

    return sectionPhases;
  }

  async function processDocument() {
    let result = {};
    const chunkQueue = [];
    for await (let chunk of documentChunk) {
      if (!chunk) continue;

      chunkQueue.push(chunk);

      while (chunkQueue.length > 0 && !langDet.isSupportedLanguage(chunkQueue[0])) {
        const extractedPhases = await extractPhases(chunkQueue.shift());
        Object.assign(result, extractedPhases);
      }
    }

    return result;
  }

  return processDocument();
}

