function generateFooterScripts(scripts, maxScripts) {
    const dependencies = {};
    scripts.forEach(script => {
        let id = script.id;
        if (dependencies[id]) {
            id += `_${Date.now()}`;
        }
        dependencies[id] = script.type;

        script.id = id;
        script.src = script.src || 'defaultSrc.js';
        script.type = script.type || 'text/javascript';

        const deps = script.deps ? script.deps : [];
        deps.forEach(dep => {
            if (!dependencies[dep]) {
                throw new Error(`Dependency ${dep} not found`);
            }
        });

        if (script.critical) {
            scripts.sort((a, b) => dependencies[a.id] - dependencies[b.id]);
        }
    });

    const renderedScripts = scripts.slice(0, Math.min(scripts.length, maxScripts)).map(script => `
        <script id="${script.id}" src="${script.src}" type="${script.type}">
        </script>
    `).join('');

    if (scripts.length > maxScripts) {
        console.warn(`More than ${maxScripts} scripts provided. Consider increasing the limit or optimizing script loading.`);
    }

    return renderedScripts;
}
