public class DataProcessingService {
    private static final Logger LOG = LoggerFactory.getLogger(DataProcessingService.class);

    private boolean isRunning = true;
    private ScheduledExecutorService executor;

    public void start() {
        if (!isRunning) {
            LOG.info("Starting data processing service...");
            executor = Executors.newScheduledThreadPool(1);
            executor.scheduleAtFixedRate(() -> processData(), 0, 10, TimeUnit.SECONDS); // adjust processing interval here
            isRunning = true;
            LOG.info("Data processing service started.");
        }
    }

    public void stop() {
        if (isRunning) {
            LOG.info("Stopping data processing service...");
            executor.shutdown();
            while (!executor.isTerminated()) {
                try {
                    TimeUnit.MILLISECONDS.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            isRunning = false;
            LOG.info("Data processing service stopped.");
        }
    }

    public void pause() {
        if (isRunning) {
            LOG.info("Pausing data processing service...");
            executor.shutdownNow();
            while (!executor.isTerminated()) {
                try {
                    TimeUnit.MILLISECONDS.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            isRunning = false;
            LOG.info("Data processing service paused.");
        }
    }

    public void resume() {
        if (!isRunning) {
            LOG.info("Resuming data processing service...");
            executor = Executors.newScheduledThreadPool(1);
