function mergeStreams(streams, threshold) {
  let mergedBuffer = Buffer.alloc(0);
  let currentSize = 0;

  for (const stream of streams) {
    while (stream.length > 0) {
      const chunk = stream.slice(0, Math.min(stream.length, threshold - currentSize));
      mergedBuffer = Buffer.concat([mergedBuffer, chunk]);
      currentSize += chunk.length;
      if (currentSize >= threshold) {
        stream.copy(Buffer.alloc(0), 0, stream, 0, stream.length);
        currentSize = 0;
      }
    }
  }

  return mergedBuffer;
}
