function traverseDOM(root, options = {}) {
  const { filter } = options;
  const queue = [root];

  while (queue.length) {
    const node = queue.shift();

    if (node && node.nodeType === Node.ELEMENT_NODE) {
      const matchesFilter = filter(node);

      if (matchesFilter) {
        // Process the node
        processNode(node, options.data);

        // Add child nodes to the queue for processing
        Array.prototype.forEach.call(node.children, (child) => queue.push(child));
      } else {
        // Skip non-matching nodes and their children
        continue;
      }
    }
  }
}

function processNode(node, data) {
  const { metadata } = data;

  // Use the node's metadata to inform any processing or decisions
  if (metadata) {
    // For example, use the load time metadata to trigger a delayed operation
    setTimeout(() => {
      // Perform the delayed operation
    }, metadata.loadTime);
  }
}

function filter(node) {
  const { selector } = node;

  switch (selector.type) {
    case 'class':
      return hasClass(node, selector.value);
    case 'id':
      return hasId(node, selector.value);
    case 'attribute':
      return hasAttribute(node, selector.name, selector.value);
    default:
      return true; // Match all elements by default
  }
}

function hasClass(node, className) {
  return node.classList.contains(className);
}

function hasId(node, id) {
  return node.id === id;
}

function hasAttribute(node, name, value) {
  return node.getAttribute(name) === value;
}
