import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;

public class LogProcessor {

    public static void processLogs(List<String> logFilePaths) {
        Map<Path, AtomicLong> directoryCounts = new HashMap<>();
        long startTime = System.currentTimeMillis();

        for (String filePath : logFilePaths) {
            try {
                Path path = Paths.get(filePath);
                String dirPath = path.normalize().toString();
                if (!directoryCounts.containsKey(path)) {
                    directoryCounts.put(path, new AtomicLong(1));
                } else {
                    directoryCounts.get(path).incrementAndGet();
                }

                // Log the processing time for each file path
                long processingTime = System.currentTimeMillis() - startTime;
                System.out.println("Processing time for " + filePath + ": " + processingTime + "ms");
            } catch (Exception e) {
                // Handle exceptions and log errors
                System.out.println("Error processing log: " + e.getMessage());
            }
        }

        long endTime = System.currentTimeMillis();
        long totalProcessingTime = endTime - startTime;
        System.out.println("Total processing time: " + totalProcessingTime + "ms");
        System.out.println("Unique directories accessed: " + directoryCounts.size());

    }
}
