import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ConnectionPool {
    private final int poolSize;
    private final int maxConcurrentRequests;
    private final Map<InetSocketAddress, List<Connection>> connections;
    private final ExecutorService executorService;
    private final Selector selector;
    private final ServerSocketChannel serverSocketChannel;
    private final long healthCheckIntervalMs;
    private final int reconnectTimeoutMs;
    private final int backoffFactor;

    public ConnectionPool(int poolSize, int maxConcurrentRequests, int healthCheckIntervalMs, int reconnectTimeoutMs, int backoffFactor) {
        this.poolSize = poolSize;
        this.maxConcurrentRequests = maxConcurrentRequests;
        connections = new HashMap<>();
        executorService = Executors.newCachedThreadPool();
        selector = Selector.open();
        serverSocketChannel = ServerSocketChannel.open();

        // Initialize the connection pool
        for (int i = 0; i < poolSize; i++) {
            InetSocketAddress address = new InetSocketAddress("example.com", 8080);
            connections.computeIfAbsent(address, k -> new ArrayList<>()).add(new Connection(selector, serverSocketChannel));
        }

        // Start the health check thread
        executorService.submit(() -> {
            while (true) {
                try {
                    Thread.sleep(healthCheckIntervalMs);
                    for (Map.Entry<InetSocketAddress, List<Connection>> entry : connections.entrySet()) {
                        for (Connection connection : entry.getValue()) {
                            if (!connection.isHealthy()) {
                                // Reconnect and update the health status
                                connection.reconnect();
                            }
                        }
                    }
                } catch (IOException | InterruptedException e) {
                    // Handle errors
                }
            }
        });

        // Start the selector thread
        executorService.submit(() -> {
            while (true) {
                try {
                    selector.select();
                    for (SelectionKey key : selector.selectedKeys()) {
                        if (key.isValid() && key.isReadable()) {
                            Connection connection = (Connection) key.attachment();
                            connection.processRead();
                        }
                    }
                    selector.selectedKeys().clear();
                } catch (IOException e) {
                    // Handle errors
                }
            }
        });
    }

    public void startListening() throws IOException {
        serverSocketChannel.configureBlocking(false);
        SelectionKey key = serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
        key.attach(new Connection(selector));
    }

    private class Connection implements Runnable {
        private final Selector selector;
        private final ServerSocketChannel channel;
        private boolean healthy;

