import android.graphics.Bitmap;
import android.os.Build;
import android.os.Environment;
import android.util.Log;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class ThemeBitmapCache {
    private static final String TAG = "ThemeBitmapCache";
    private static final int MAX_CACHE_SIZE = 1024 * 1024; // 1MB

    private File cacheRootDir;
    private List<Bitmap> bitmaps = new CopyOnWriteArrayList<>();
    private Map<String, Bitmap> themeBitmaps = new HashMap<>();

    public ThemeBitmapCache(Context context) {
        cacheRootDir = getCacheRootDir(context);
        if (!cacheRootDir.exists()) {
            cacheRootDir.mkdirs();
        }
    }

    private File getCacheRootDir(Context context) {
        return new File(Environment.getExternalStoragePublicDirectory(
                Environment.DIRECTORY_DCIM), "theme_bitmaps");
    }

    public void putBitmap(String theme, Bitmap bitmap) {
        if (bitmap == null) return;
        try {
            String filePath = cacheRootDir.getAbsolutePath() + "/" + theme + ".png";
            bitmap.compress(Bitmap.CompressFormat.PNG, 100, new FileOutputStream(filePath));
            bitmaps.add(bitmap);
            themeBitmaps.put(theme, bitmap);
        } catch (IOException e) {
            Log.e(TAG, "Error putting bitmap: ", e);
        }
    }

    public Bitmap getBitmap(String theme) {
        return themeBitmaps.get(theme);
    }

    public void recycleBitmaps() {
        for (Bitmap bitmap : bitmaps) {
            if (!bitmap.isRecycled()) {
                bitmap.recycle();
            }
        }
        bitmaps.clear();
    }

    public void cleanUpCache() {
        File[] files = cacheRootDir.listFiles();
        for (File file : files) {
            if (file.isFile()) {
                file.delete();
            }
        }
    }

    public boolean isValidTheme(String theme) {
        return themeBitmaps.containsKey(theme);
    }

    public void invalidateTheme(String theme) {
        Bitmap bitmap = themeBitmaps.get(theme);
        if (bitmap != null) {
            bitmap.recycle();
            bitmaps.remove(bitmap);
            themeBitmaps.remove(theme);
        }
    }

    public void validateCache() {
        for (Map.Entry<String, Bitmap> entry : themeBitmaps.entrySet()) {
            String theme = entry.getKey();
            Bitmap bitmap = entry.getValue();
            if (!isValidBitmap(bitmap)) {
                invalidateTheme(theme);
            }
        }
    }

    private boolean isValidBitmap(Bitmap bitmap) {
        return bitmap != null && !bitmap.isRecycled();
    }

    public void switchTheme(String newTheme) {
        // fallback mechanism for seamless theme switching
        if (!isValidTheme(newTheme)) {
            newTheme = getDefaultTheme();
        }
        Bitmap newBitmap = getBitmap(newTheme);
        if (newBitmap == null) {
            // use default theme or display error message
        } else {
            // update UI with the new bitmap
        }
    }

    private String getDefaultTheme() {
        return "default_theme.png";
    }

    public void logCacheStats() {
        Log.d(TAG, "Cache size: " + bitmaps.size());
        Log.d(TAG, "Total cache size: " + cacheRootDir.length());
    }
}
