function authenticateUser($client_id, $client_secret, $redirect_uri) {
    // Initialize OAuth 2.0 client
    $client = new Google_Client();
    $client->setClientId($client_id);
    $client->setClientSecret($client_secret);
    $client->setRedirectUri($redirect_uri);

    // Authorize the client
    if (!isset($_GET['code'])) {
        header('Location: ' . $client->createAuthUrl());
        exit;
    }

    // Exchange authorization code for access token
    $token = $client->authenticate($_GET['code']);

    // Store access token securely in session variable
    $_SESSION['access_token'] = $token;

    // Retrieve user information using access token
    $user_info = json_decode($client->verifyIdToken(), true);

    return $user_info;
}
