import logging
from typing import Dict, List

def process_config_file(file_path: str, sort_criterion: str, metadata_fields: List[str]) -> None:
    logging.basicConfig(level=logging.INFO)
    logger = logging.getLogger(__name__)

    try:
        with open(file_path, 'r') as file:
            lines = [line.strip() for line in file.readlines()]

        if not lines:
            raise ValueError("File is empty")

        sorted_lines = sort_lines(lines, sort_criterion)

        extracted_metadata = extract_metadata(sorted_lines[-1], metadata_fields)

        logger.info(f"Processed {file_path} and extracted metadata: {extracted_metadata}")

    except FileNotFoundError as e:
        logger.error(f"Failed to open file {file_path}: {e}")
    except ValueError as e:
        logger.error(f"Invalid file contents: {e}")
    except Exception as e:
        logger.error(f"Unexpected error occurred: {e}")

def sort_lines(lines: List[str], criterion: str) -> List[str]:
    if criterion == "priority":
        return sorted(lines, key=lambda line: int(line.split(":")[1]))
    elif criterion == "timestamp":
        return sorted(lines, key=lambda line: line.split(" ")[0])
    else:
        raise ValueError(f"Invalid sorting criterion: {criterion}")

def extract_metadata(line: str, fields: List[str]) -> Dict[str, str]:
    metadata = {}
    for field in fields:
        value_start_idx = line.find(field + ":") + len(field) + 1
        value_end_idx = line.find(" ", value_start_idx)
        if value_end_idx == -1:
            value_end_idx = len(line)
        metadata[field] = line[value_start_idx:value_end_idx]
    return metadata
