typedef struct {
    int state;
    struct {
        int next;
    } *next_state;
} State;

State* construct_sublist(int* states, int num_states, State* fsa, int last_state, int max_size) {
    if (max_size == 0 || num_states > max_size)
        return NULL;

    int i, j = 0;
    State* sublist = (State*)malloc((num_states + 1) * sizeof(State));
    for (i = 0; i < num_states; i++) {
        if ((states[i] >= last_state) && (fsa[i].next != NULL)) {
            sublist[j].state = states[i];
            sublist[j++].next_state = &fsa[states[i]].next;
        }
    }

    sublist[j].state = 0; // sentinel state
    for (i = 0; i < j - 1; i++) {
        fsa[states[i]].next = &sublist[i];
    }

    if (j > 0) {
        sublist[j - 1].next_state->next = NULL;
    } else {
        free(sublist);
        return NULL;
    }

    return sublist;
}

