class OctreeNode {
public:
    enum class NodeType { Internal, Leaf };

    std::shared_ptr<OctreeNode> child[8];
    bool isLeaf;
    int capacity;
    int size;

    OctreeNode(int featureSize, bool isInternal) : isLeaf(false), capacity(featureSize), size(0) {
        if (isInternal) {
            for (int i = 0; i < 8; ++i) child[i] = nullptr;
        }
    }

    ~OctreeNode() {
        // Release child nodes
        for (auto& childNode : child) {
            if (childNode) childNode.reset();
        }
    }
};

class Octree {
public:
    std::shared_ptr<OctreeNode> root;
    int featureSize;
    int initialLeafNodes;
    int maxCapacity;
    bool threadSafe;

    Octree(int featureSize, int initialLeafNodes, int maxCapacity, bool threadSafe)
        : featureSize(featureSize), initialLeafNodes(initialLeafNodes), maxCapacity(maxCapacity), threadSafe(threadSafe) {
        root = std::make_shared<OctreeNode>(featureSize, true);
    }

    ~Octree() {
        // Release the tree
        if (root) root.reset();
    }
};

