struct Character {
    std::atomic<int> energy = 50;
    std::atomic<bool> cooldown = false;
    std::queue<std::function<void()>> attackHistory;

    void selectAttack(int attackId) {
        if (cooldown.load()) return; // Check for cooldown
        Attack attack = attacks[attackId];
        int energyCost = attack.energyCost;
        if (energy -= energyCost > 0) { // Check if character has enough energy
            // Simulate attack execution
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            energy += energyCost; // Refill energy
            cooldown.store(true); // Set cooldown
            attackHistory.push([this, attack]() {
                // Store attack in history for logging or analysis
                this->energy -= attack.energyCost;
                // Simulate cooldown
                std::this_thread::sleep_for(std::chrono::seconds(9));
                this->cooldown = false; // Reset cooldown
            });
        }
    }

    static const Attack attacks[] = {
        { "Lightning Bolt", 10 },
        { "Fireball", 20 },
        { "Earthquake", 30 },
        { "Healing Pulse", 15 }
    };

    std::mutex mutex;
    std::condition_variable cv;

    void runCharacterLoop() {
        while (true) {
            if (energy <= 0) break; // Check for character's energy depletion
            selectAttack(std::rand() % 4);
            // Wait until next attack is allowed
            cv.wait([this]() { return !cooldown.load(); });
        }
    }
};

int main() {
    std::atomic<int> numCharacters = 1000;
    std::vector<Character> characters(numCharacters);

    for (int i = 0; i < numCharacters; ++i) {
        characters[i].runCharacterLoop();
    }

    return 0;
}
