    }

    public void AddRange(int min, int max)
    {
        _intRanges.Add((min, max));
    }

    public void AddRange(double min, double max)
    {
        _doubleRanges.Add((min, max));
    }

    public float GetRandomFloat()
    {
        return (float)GetRandomValue(_floatRanges);
    }

    public float GetRandomFloatExclusive()
    {
        return (float)GetRandomValueExclusive(_floatRanges);
    }

    public int GetRandomInt()
    {
        return (int)GetRandomValue(_intRanges);
    }

    public int GetRandomIntExclusive()
    {
        return (int)GetRandomValueExclusive(_intRanges);
    }

    public double GetRandomDouble()
    {
        return GetRandomValue(_doubleRanges);
    }

    public double GetRandomDoubleExclusive()
    {
        return GetRandomValueExclusive(_doubleRanges);
    }

    private object GetRandomValue(IList<(float, float)> ranges)
    {
        Random rand = new Random();
        var minAndMax = ranges.Last();
        return rand.NextDouble() * (minAndMax.Item2 - minAndMax.Item1) + minAndMax.Item1;
    }

    private object GetRandomValueExclusive(IList<(float, float)> ranges)
    {
        Random rand = new Random();
        var minAndMax = ranges.Last();
        return rand.NextDouble() * (minAndMax.Item2 - minAndMax.Item1) + minAndMax.Item1;
    }

    public override string ToString()
    {
        return $"Float Ranges: {_floatRanges}\nInt Ranges: {_intRanges}\nDouble Ranges: {_doubleRanges}";
    }
