function customReduce(arr, initial, callback) {
  const concurrencyLimit = 10;
  const queue = [];
  let result = initial;

  function processChunk() {
    const chunkSize = Math.min(concurrencyLimit, arr.length);
    for (let i = 0; i < chunkSize; i++) {
      const num = arr.pop();
      if (!num) break;
      queue.push(num);
    }
    processQueue().then(() => {
      if (queue.length > 0) setTimeout(processChunk, 0);
    });
  }

  function processQueue() {
    return Promise.all(
      queue.map((num, i) => {
        const [acc, current, error, status] = callback(result, num, null, null);
        result = acc;
        if (error || !isFinite(result)) throw new Error('Invalid reduction');
        return Promise.resolve().then(() => queue.splice(i, 1));
      }),
      { maxConcurrency: concurrencyLimit }
    ).then(() => {
      return result;
    });
  }

  processChunk();
  return new Promise((resolve, reject) => {
    process.on('uncaughtException', (err) => {
      if (!reject) throw err;
      resolve(reject(err));
    });
    process.on('SIGINT', () => {
      reject(new Error('Operation interrupted'));
    });
  }).then((result) => resolve(result)).catch((error) => reject(error));
}
