#include <string.h>

typedef struct {
    int dependencies;
    char* source;
} Stage;

int init_pipeline(const char* config_file_path) {
    FILE* file = fopen(config_file_path, "r");
    if (file == NULL) return -1; // Failed to open the configuration file

    int num_stages = 0;
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    char* buffer = (char*)malloc((int)file_size + 1);
    fread(buffer, 1, file_size, file);
    fclose(file);

    char* token = strtok(buffer, ",");
    while (token != NULL) {
        Stage* stage = (Stage*)malloc(sizeof(Stage));
        // Initialize the stage's dependencies and source
        stage->dependencies = atoi(strtok(token, "("));
        stage->source = strdup(strtok(NULL, ")"));
        // Add the stage to the pipeline
        num_stages++;
    }
    free(buffer);

    return num_stages;
}
