const axios = require('axios');
const cheerio = require('cheerio');

class ElementCollector {
  constructor(apiUrl, cacheExpiration) {
    this.apiUrl = apiUrl;
    this.cacheExpiration = cacheExpiration;
    this.elementCache = {};
  }

  async collectElements(rootElement, selectors, sizeLimit, typeCriteria) {
    const promises = [];

    rootElement.querySelectorAll('iframe, frame').forEach(frame => {
      promises.push(this.traverseFrame(frame, selectors, sizeLimit, typeCriteria));
    });

    return Promise.all(promises).then(elements => elements.flat());
  }

  async traverseFrame(frame, selectors, sizeLimit, typeCriteria) {
    const { url } = frame.src;
    const iframePromise = axios.get(url);
    const cheerioFrame = await this.getCheerioFrame(iframePromise);

    return (await Promise.all(
      selectors.map(selector => {
        const elements = cheerioFrame.querySelectorAll(selector);
        return elements.filter(element => {
          if (this.elementCache[url] === undefined) {
            this.elementCache[url] = {};
          }
          const metadata = await this.getMetadata(element, sizeLimit, typeCriteria);
          if (!metadata || !metadata.size || !metadata.type.match(typeCriteria)) {
            return false;
          }
          this.elementCache[url][element.attr('id')] = metadata;
          return true;
        });
      })
    )).flat();
  }

  async getMetadata(element, sizeLimit, typeCriteria) {
    const { id } = element.attr('id');
    if (this.elementCache[id] !== undefined) {
      return this.elementCache[id];
    }
    try {
      const response = await axios.get(`${this.apiUrl}/metadata/${id}`);
      const metadata = response.data;
      if (metadata.size < sizeLimit && metadata.type.match(typeCriteria)) {
        return metadata;
      }
    } catch (error) {
      // Handle error
    }
    return null;
  }

  async getCheerioFrame(iframePromise) {
    const iframeResponse = await iframePromise;
    const cheerioFrame = await this.getCheerio(iframeResponse);
    return cheerioFrame;
  }

  async getCheerio(response) {
    const $ = cheerio.load(response.data);
    return $;
  }
}

module.exports = ElementCollector;
