void* process_file(void* args) {
    file_t* file = (file_t*)args;
    while(fgets(file->line, sizeof(file->line), file->file)) {
        // Process the line as needed
        // For example:
        char* token = strtok(file->line, ",");
        double sum = 0;
        int count = 1;
        for(int i = 1; ;i++) {
            token = strtok(NULL, ",");
            if(token == NULL) break;
            sum += atof(token);
            count++;
        }
        double avg = sum / (count - 1);
        // Print the processed line
        printf("%s,%f\n", file->line, avg);
    }
    fclose(file->file);
}

int main() {
    int num_files = 0;
    pthread_t threads[MAX_THREADS];
    file_t files[100]; // Assume max 100 files

    // Open and count the number of files
    FILE* file;
    while((file = fopen("file.txt", "r")) != NULL) {
        files[num_files].file = file;
        num_files++;
        if(num_files >= MAX_THREADS) break;
    }

    // Create a thread pool to process files concurrently
    pthread_create(&threads[0], NULL, process_file, &files[0]);
    for(int i = 1; i < num_files; i++) {
        pthread_create(&threads[i], NULL, process_file, &files[i]);
    }

    // Wait for all threads to finish
    for(int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
