typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
    unsigned char* hash;
} ImageMetaData;

int processImageFile(const char* filePath, const char* format, ImageMetaData** metaData, unsigned char** hash) {
    *metaData = (ImageMetaData*)malloc(sizeof(ImageMetaData));
    if (*metaData == NULL) return -1; // Out of memory

    FILE* file = fopen(filePath, "rb");
    if (file == NULL) return -2; // Failed to open file

    ImageMetaData* imageData = *metaData;
    unsigned char buffer[16]; // Buffer for reading image data
    size_t bytesRead;

    if (strcmp(format, "TIFF") == 0) {
        TIFF* tiff = TIFFOpen(filePath, "rb");
        if (tiff == NULL) return -3; // Failed to open TIFF file

        int bitsPerSample;
        uint16 samplesPerPixel;
        TIFFGetField(tiff, TIFF_FIELD_BITSPERSAMPLE, &bitsPerSample);
        TIFFGetField(tiff, TIFF_FIELD_SAMPLESPERPIXEL, &samplesPerPixel);

        imageData->bitsPerSample = bitsPerSample;
        imageData->samplesPerPixel = samplesPerPixel;

        // Read extra samples
        uint16 numExtraSamples;
        TIFFGetField(tiff, TIFF_FIELD_EXTRA SAMPLES, &numExtraSamples);
        imageData->extraSamples = numExtraSamples;

        // Compute SHA-256 hash of raw data
        SHA256_CTX sha256Context;
        SHA256_Init(&sha256Context);
        while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
            SHA256_Update(&sha256Context, buffer, bytesRead);
        }
        unsigned char* hashBytes = (unsigned char*)malloc(32); // SHA-256 hash
        SHA256_Final(hashBytes, &sha256Context);
        *hash = hashBytes;

        TIFFClose(tiff);
    } else if (strcmp(format, "JPEG") == 0) {
        // JPEG processing code goes here...
    } else if (strcmp(format, "PNG") == 0) {
        // PNG processing code goes here...
    } else {
        fclose(file); // Close file
        return -4; // Unknown format
    }

    fclose(file);
    return 0;
}
