char* modify_file_extension(const char* directory_path, const char* filename) {
    // Fetch latest version of file from metadata service
    const char* latest_version = get_latest_file_version(directory_path, filename);

    // Count consonants in the filename (excluding digits)
    int consonant_count = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (!isdigit((unsigned char)filename[i]) && !isspace((unsigned char)filename[i])) {
            if (!isalpha((unsigned char)filename[i]))
                continue;
            consonant_count += tolower((unsigned char)filename[i]) != 'a' &&
                               tolower((unsigned char)filename[i]) != 'e' &&
                               tolower((unsigned char)filename[i]) != 'i' &&
                               tolower((unsigned char)filename[i]) != 'o' &&
                               tolower((unsigned char)filename[i]) != 'u';
        }
    }

    // Check if the count exceeds the limit
    const int limit = 5; // Adjust this value as needed
    if (consonant_count > limit)
        return NULL;

    // Extract significant words from the filename
    char* words[1024]; // Adjust this size as needed
    char word[256];
    int word_count = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (!isdigit((unsigned char)filename[i]) && !isspace((unsigned char)filename[i])) {
            bool in_word = false;
            for (int j = 0; j < i; j++) {
                if (!isspace((unsigned char)filename[j]))
                    break;
                in_word = true;
            }
            if (!in_word)
                continue;
            sprintf(word, "%s", &filename[i]);
            words[word_count++] = strdup(word);
        }
    }

    // Derive the new file type from the first non-numeric character of each significant word
    char* new_extension = NULL;
    for (int i = 0; i < word_count; i++) {
        int j = 0;
        while ((words[i][j] >= 'a' && words[i][j] <= 'z') ||
               (words[i][j] >= 'A' && words[i][j] <= 'Z')) {
            if (!new_extension) {
                new_extension = strdup(&words[i][j]);
            } else {
                int len = strlen(new_extension);
                char* temp = malloc(len + 2);
                strcpy(temp, new_extension);
                free(new_extension);
                new_extension = realloc(temp, len + 2);
                sprintf(new_extension + len, "%c", words[i][j]);
            }
            j++;
        }
    }

    // Modify the file extension
    char* modified_filename = NULL;
    if (new_extension) {
        int len = strlen(latest_version) - strlen(filename) + strlen(new_extension);
        modified_filename = malloc(len + 1);
        sprintf(modified_filename, "%s.%s", latest_version, new_extension);
        free(new_extension);
    } else {
        modified_filename = strdup(latest_version);
    }

    return modified_filename;
}
