typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    unsigned char *iv;
} CipherContext;

CipherContext* init_aes_cipher(const char* password) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    // Set up the KDF
    const EVP_MD* md = EVP_get_md(EVP_sha256());
    unsigned char *derived_key;
    int derived_key_len = EVP_kdf_derive_bytes(md, password, strlen(password), 32, &derived_key);

    // Initialize AES context
    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    if (!ctx->cipher_ctx) {
        free(ctx);
        return NULL;
    }

    // Set up the AES-256-CBC cipher
    if (1 != EVP_CipherInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, derived_key, 32)) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        free(ctx);
        return NULL;
    }
    free(derived_key);

    // Set the IV length to 16 bytes
    ctx->iv = (unsigned char*)malloc(16);
    RAND_bytes(ctx->iv, 16);
    if (1 != EVP_CipherInit_ex(ctx->cipher_ctx, NULL, NULL, ctx->iv, 16)) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    // Set the cipher enabled
    if (1 != EVP_CipherStart(ctx->cipher_ctx)) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(CipherContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->cipher_ctx);
    free(ctx->iv);
    free(ctx);
}

// Theme Caching Mechanism

#include <png.h>

typedef struct {
    char *name;
    unsigned char *bitmap;
} Theme;

Theme* theme_cache[10];

void cache_theme(const char* filename) {
    // Check if the theme bitmap is recyclable
    for (int i = 0; i < 10; i++) {
        if (!theme_cache[i].name && !theme_cache[i].bitmap) {
            // Recycle the theme
            theme_cache[i].name = strdup(filename);
            Png *png = png_create_read(filename, NULL, NULL);
            unsigned char *data = (unsigned char*)malloc(png->width * png->height);
            png_read_file(png, data, 0);
            free(theme_cache[i].bitmap);
            theme_cache[i].bitmap = data;
            return;
        }
    }

    // Verify if a default theme directory is set
    if (!theme_cache[0].name) {
        theme_cache[0].name = strdup("default_theme");
        Png *png = png_create_read("default_theme.png", NULL, NULL);
        unsigned char *data = (unsigned char*)malloc(png->width * png->height);
        png_read_file(png, data, 0);
        free(theme_cache[0].bitmap);
        theme_cache[0].bitmap = data;
    }

    // Parse the PNG file
    Png *png = png_create_read(filename, NULL, NULL);
    unsigned char *data = (unsigned char*)malloc(png->width * png->height);
    png_read_file(png, data, 0);

    // Store it in the theme cache for rapid access
    int idx = -1;
    for (int i = 0; i < 10; i++) {
        if (!theme_cache[i].name && !theme_cache[i].bitmap) {
            idx = i;
            break;
        }
    }

    if (idx != -1) {
        theme_cache[idx].name = strdup(filename);
        theme_cache[idx].bitmap = data;
    } else {
        free(data);
    }
}
