#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>
#include <sys/resource.h>

#define MAX_CONCURRENT 15
#define LOG_FILE "command_log.txt"
#define MAX_RUNTIME 3600 // in seconds (1 hour)
#define RETRY_DELAY 30 // in seconds

int background_exec(char *cmd, int max_runtime, int attempt_limit) {
    if (getuid() == 0) {
        fprintf(stderr, "Warning: command executed with root privileges. Exiting.\n");
        return 0;
    }

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork failed");
        return 0;
    } else if (pid > 0) { // parent process
        int status;
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status)) {
            fprintf(stderr, "Command %d failed\n", pid);
            return 0;
        }
        return WEXITSTATUS(status);
    } else { // child process
        struct rlimit rl;
        getrlimit(RLIMIT_CORE, &rl);
        setrlimit(RLIMIT_CORE, &rl);

        if (setrlimit(RLIMIT_NOFILE, &(struct rlimit){.rlim_cur = 1024, .rlim_max = 1024})) {
            perror("RLIMIT_NOFILE failed");
            exit(1);
        }

        pid_t pids[MAX_CONCURRENT];
        int count = 0;
        if (count < MAX_CONCURRENT) {
            pids[count++] = pid;
        }

        while (1) {
            if (kill(pid, SIGCHLD)) {
                perror("kill failed");
                exit(1);
            }
            waitpid(pid, NULL, 0);

            char buffer[1024];
            FILE *log_file = fopen(LOG_FILE, "a+");
            fprintf(log_file, "%s\n", cmd);
            fclose(log_file);

            if (WEXITSTATUS(status) == 127 || WEXITSTATUS(status) == 1) {
                if (count < MAX_CONCURRENT) {
                    pids[count++] = fork();
                }
            } else {
                if (count > 0) {
                    for (int i = 0; i < count; i++) {
                        kill(pids[i], SIGCHLD);
                    }
                }
            }

            return WEXITSTATUS(status);
        }
    }
}
