public class WebApplicationService
{
    private readonly string _logFilePath;
    private readonly object _syncLock = new object();

    public void AddAndStartWebApp(string directoryPath, string appName)
    {
        if (!ValidateInputs(directoryPath, appName))
            return;

        var webConfigExist = File.Exists(Path.Combine(directoryPath, "web.config"));
        if (!webConfigExist)
            return;

        try
        {
            using (var process = new Process())
            {
                process.StartInfo.FileName = "dotnet";
                process.StartInfo.Arguments = $"run {appName}.dll";
                process.StartInfo.WorkingDirectory = directoryPath;
                process.Start();

                // Log operation to file
                File.AppendAllText(_logFilePath, $"Added and started web app '{appName}' in directory '{directoryPath}' at {DateTime.Now}\n");
            }
        }
        catch (Exception ex)
        {
            // Handle runtime errors or system failures
            File.AppendAllText(_logFilePath, $"Error adding and starting web app: {ex.Message} at {DateTime.Now}\n");
        }
    }

    private bool ValidateInputs(string directoryPath, string appName)
    {
        if (!Directory.Exists(directoryPath))
            return false;

        if (string.IsNullOrEmpty(appName) || !Directory.GetFiles(directoryPath).Any(f => f.Name.EndsWith($".{appName}.dll", StringComparison.OrdinalIgnoreCase))
            return false;

        return true;
    }
}
