    private static final long LOG_FILE_KEEP_ALIVE_TIME = 30 * 1000; // 30 seconds

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        Map<String, DiskSpaceCheckerTask> tasks = new HashMap<>();

        // Initialize tasks with servers and their corresponding disk space checking utilities
        tasks.put("server1", new DiskSpaceCheckerTask("server1", "df -h"));
        tasks.put("server2", new DiskSpaceCheckerTask("server2", "du -sh"));
        tasks.put("server3", new DiskSpaceCheckerTask("server3", "fsutil disk"));

        // Start the disk space checking process
        executor.submit(new DiskSpaceCheckerRunnable(tasks));
    }

    private static class DiskSpaceCheckerTask {
        private String serverName;
        private String diskSpaceCheckingUtility;

        public DiskSpaceCheckerTask(String serverName, String diskSpaceCheckingUtility) {
            this.serverName = serverName;
            this.diskSpaceCheckingUtility = diskSpaceCheckingUtility;
        }
    }

    private static class DiskSpaceCheckerRunnable implements Runnable {

        private Map<String, DiskSpaceCheckerTask> tasks;

        public DiskSpaceCheckerRunnable(Map<String, DiskSpaceCheckerTask> tasks) {
            this.tasks = tasks;
        }

        @Override
        public void run() {
            for (Map.Entry<String, DiskSpaceCheckerTask> entry : tasks.entrySet()) {
                String serverName = entry.getKey();
                DiskSpaceCheckerTask task = entry.getValue();

                // Check disk space and log results
                checkDiskSpaceAndLog(serverName, task.diskSpaceCheckingUtility);
            }
        }

        private void checkDiskSpaceAndLog(String serverName, String diskSpaceCheckingUtility) {
            while (true) {
                try {
                    Process process = Runtime.getRuntime().exec(diskSpaceCheckingUtility);
                    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    StringBuilder output = new StringBuilder();
                    String line;
                    while ((line = reader.readLine()) != null) {
                        output.append(line).append("\n");
                    }
                    // Log the disk space usage
                    logDiskSpaceUsage(serverName, output.toString());
                } catch (IOException e) {
                    // Handle utility not available or failed check
                } finally {
                    try {
                        process.waitFor();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }

                // Check if the disk space usage is low
                // ...
            }
        }

        private void logDiskSpaceUsage(String serverName, String output) {
            // Log to a central logging service using an asynchronous logger
            new AsyncLogger().log(serverName, output);
        }
    }

    private static class AsyncLogger {

        public void log(String serverName, String output) {
            // Log to the central logging service
        }
    }
}
