using System.Text;

public class DecryptAndVerifyMessage
{
    public string ProcessEncryptedMessage(byte[] encryptedMessage, byte[] ivHex, byte[] key)
    {
        try
        {
            // Ensure the IV is 16 bytes long (the default length for Triple DES)
            if (ivHex.Length != 32) throw new ArgumentException("IV must be a 16-byte hexadecimal-formatted value");

            // Ensure the key is exactly 24 bytes long (the expected length for this encryption algorithm and environment)
            if (key.Length != 24) throw new ArgumentException("Key must be exactly 24 bytes long");

            // Decrypt the message using Triple DES
            using (var tripleDes = TripleDESCryptoServiceProvider.Create())
            {
                tripleDes.Key = key;
                tripleDes.IV = Convert.FromHexString(ivHex);
                byte[] decryptedMessage = Decrypt(encryptedMessage, tripleDes);
                string message = Encoding.UTF8.GetString(decryptedMessage);

                // Deserialize the decrypted message to prevent potential attacks
                try
                {
                    // Implement object deserialization here (e.g., using JsonConvert.DeserializeObject)
                    // For demonstration purposes, simply return the decrypted message as a string
                    return message;
                }
                catch (Exception ex)
                {
                    // Handle deserialization exceptions to maintain system integrity
                    throw new InvalidOperationException("Failed to deserialize the decrypted message", ex);
                }
            }
        }
        catch (ArgumentException ex)
        {
            // Return an empty string on invalid input, ensuring graceful handling without affecting system-wide stability
            return string.Empty;
        }
        catch (CryptographicException ex)
        {
            // Catch and handle any cryptographic exceptions that may occur during the decryption process
            throw new InvalidOperationException("Failed to decrypt the message", ex);
        }
    }

    private byte[] Decrypt(byte[] encryptedMessage, TripleDESCryptoServiceProvider tripleDes)
    {
        using (var ms = new MemoryStream())
        {
            using (var cryptoStream = new CryptoStream(ms, tripleDes.CreateDecryptor()))
            {
                cryptoStream.Write(encryptedMessage, 0, encryptedMessage.Length);
                cryptoStream.FlushFinalBlock();
                return ms.ToArray();
            }
        }
    }
}
