    public class FileHashCalculator : IDisposable
    {
        private readonly string _cacheDirectory;
        private readonly int _maxCacheSizeInMB;
        private readonly ICachingStrategy _cachingStrategy;
        private readonly ILogger _logger;

        public FileHashCalculator(string cacheDirectory, int maxCacheSizeInMB, ICachingStrategy cachingStrategy, ILogger logger)
        {
            _cacheDirectory = cacheDirectory;
            _maxCacheSizeInMB = maxCacheSizeInMB;
            _cachingStrategy = cachingStrategy;
            _logger = logger;
        }

        public async Task ProcessFilesAsync(string[] filePaths, string directoryPath)
        {
            foreach (string filePath in filePaths)
            {
                if (!filePath.StartsWith(directoryPath))
                    continue;

                try
                {
                    using (FileStream fs = File.OpenRead(filePath))
                    {
                        SHA256CryptoServiceProvider sha256 = new SHA256CryptoServiceProvider();
                        byte[] hashBytes = sha256.ComputeHash(fs);
                        string hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                        await _cachingStrategy.AddToCacheAsync(filePath, hash);

                        if (_logger.IsEnabled(LogLevel.Debug))
                            _logger.LogDebug($"Processed file {filePath} with SHA-256 hash {hash}");
                    }
                }
                catch (IOException ex)
                {
                    _logger.LogError(ex, "Error processing file");
                }
            }
        }

        public void Dispose()
        {
            GC.SuppressFinalize(this);
        }
    }

    public interface ICachingStrategy
    {
        Task AddToCacheAsync(string filePath, string hash);
    }

    public class CacheMemoryStrategy : ICachingStrategy
    {
        private readonly Dictionary<string, string> _cache = new();
        private readonly int _maxSizeInBytes;

        public CacheMemoryStrategy(int maxSizeInBytes)
        {
            _maxSizeInBytes = maxSizeInBytes;
        }

        public async Task AddToCacheAsync(string filePath, string hash)
        {
            if (_cache.Count >= _maxSizeInBytes / 1024 / 1024) // in GB
                RemoveOldestEntry();

            _cache.Add(filePath, hash);
        }
    }

    public class CacheDiskStrategy : ICachingStrategy
    {
        private readonly string _diskCacheDirectory;
        private readonly int _maxSizeInGB;

        public CacheDiskStrategy(string diskCacheDirectory, int maxSizeInGB)
