using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public static class CryptoProcessor
{
    public static Task ProcessCiphertextsAsync(byte[][] ciphertexts, byte[] key, byte[] iv)
    {
        foreach (var ciphertext in ciphertexts)
        {
            try
            {
                var decryptedBytes = DecryptCiphertext(ciphertext, key, iv);
                var hmacSignature = ciphertext[ciphertext.Length - 32..];
                var plaintext = Encoding.UTF8.GetString(decryptedBytes);

                if (!VerifyHmacSignature(plaintext, hmacSignature, key))
                {
                    // invalid HMAC signature, skip this entry
                    continue;
                }

                // process the decrypted and verified plaintext here
            }
            catch (CryptographicException ex)
            {
                // decryption failure, log error and skip
                Console.WriteLine($"Decryption failed: {ex.Message}");
                continue;
            }
        }
    }

    private static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;

        using var decryptor = aes.CreateDecryptor();
        using var ms = new MemoryStream(ciphertext);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

        byte[] decryptedBytes = new byte[ciphertext.Length];
        cs.Read(decryptedBytes, 0, decryptedBytes.Length);

        return decryptedBytes;
    }

    private static bool VerifyHmacSignature(string plaintext, byte[] hmacSignature, byte[] key)
    {
        using var hmac = new HMACSHA256(key);
        byte[] signatureBytes = hmac.ComputeHash(Encoding.UTF8.GetBytes(plaintext));
        return AreByteArraysEqual(hmacSignature, signatureBytes);
    }

    private static bool AreByteArraysEqual(byte[] a, byte[] b)
    {
        if (a.Length != b.Length) return false;
        for (int i = 0; i < a.Length; i++)
            if (a[i] != b[i])
                return false;
        return true;
    }
}
