import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;

public List<MyCustomObject> processJsonString(String jsonString) {
    ObjectMapper mapper = new ObjectMapper();
    List<MyCustomObject> result = new ArrayList<>();

    try {
        JsonNode root = mapper.readTree(jsonString);

        for (Iterator<JsonNode> iterator = root.iterator(); iterator.hasNext(); ) {
            JsonNode node = iterator.next();

            if (node.isObject()) {
                MyCustomObject obj;
                try {
                    obj = mapper.treeToValue(node, MyCustomObject.class);
                    result.add(obj);
                } catch (JsonMappingException e) {
                    // Handle the exception
                    System.out.println("Error parsing JSON: " + e.getMessage());
                }
            }
        }
    } catch (IOException e) {
        // Handle the exception
        System.out.println("Error reading JSON: " + e.getMessage());
    }

    return result;
}
