const axios = require('axios');
const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');
const { Pool } = require('pg');
const { Queue } = require('bull');

class FileUploader {
  constructor({
    cloudStorageService,
    cachingLayer,
    backgroundQueue,
    dbPool,
  }) {
    this.cloudStorageService = cloudStorageService;
    this.cachingLayer = cachingLayer;
    this.backgroundQueue = backgroundQueue;
    this.dbPool = dbPool;
  }

  async processFileUrls(fileUrls) {
    const uploadsInFlight = new Set();
    const cachedUploads = {};

    for (const fileUrl of fileUrls) {
      if (!this.cachingLayer.has(fileUrl)) {
        await this.backgroundQueue.add({
          type: 'upload',
          url: fileUrl,
          callback: async ({ id, metadata }) => {
            const uploadedFile = await this.cloudStorageService.getUploadedFile(id);
            const publicUrl = await this.cloudStorageService.generatePublicURL(uploadedFile);

            // Update caching layer and database
            this.cachingLayer.set(fileUrl, publicUrl);
            await this.dbPool.query(`INSERT INTO files (url, metadata) VALUES ($1, $2) RETURNING *`, [fileUrl, metadata]);

            // Close the uploaded file session
            await this.cloudStorageService.closeUploadedFileSession(id);
          },
        });
      } else {
        const publicUrl = this.cachingLayer.get(fileUrl);
        if (publicUrl) {
          console.log(`File ${fileUrl} already uploaded. Public URL: ${publicUrl}`);
        }
      }
    }

    // Monitor and log upload progress
    await this.backgroundQueue.on('completed', (job) => {
      const { type, url } = job.data;
      if (type === 'upload') {
        console.log(`Upload completed for file ${url}`);
      }
    });

    await this.backgroundQueue.on('failed', (job) => {
      const { type, url } = job.data;
      if (type === 'upload') {
        console.error(`Upload failed for file ${url}`);
      }
    });
  }

  async getPublicUrl(fileUrl) {
    return this.cachingLayer.get(fileUrl);
  }
}

module.exports = FileUploader;
