const sanitizeHTML = (input) => {
  const escapeHtmlEntities = (str) =>
    str.replace(/&/g, '&amp;').replace(/>/g, '&gt;').replace(/</g, '&lt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#x27;');

  const sanitizeInput = (input) => {
    if (!input) return '';

    input = escapeHtmlEntities(input);
    // Sanitize HTML structure
    input = input.replace(/<(?!\/|javascript:)[^>]*>/gi, '');
    // Remove any malicious script tags
    input = input.replace(/<script[^>]*>|<\/script>/g, '');
    return input;
  };

  const generateHTML = (input) => {
    try {
      const htmlContent = sanitizeInput(input);
      // Fetch metadata from external API if necessary
      const apiResponse = await fetch('https://api.example.com/metadata');
      const metaData = await apiResponse.json();
      // Integrate fetched data into HTML content
      let finalHTML = '';
      for (const item of Object.keys(metaData)) {
        finalHTML += `<div>${item}: ${metaData[item]}</div>`;
      }
      return `${htmlContent}${finalHTML}`;
    } catch (error) {
      console.error('Error generating HTML:', error);
      // Provide meaningful feedback to the user
      alert('Failed to generate HTML. Please try again later.');
      return '';
    }
  };

  const getCustomOptions = () => ({
    sanitizeLevel: 'basic', // Options for sanitization level (basic, advanced)
    apiTimeout: 5000, // Timeout for API requests in milliseconds
    errorHandlingMode: 'silent' // Options for error handling mode (silent, alert)
  });

  const generateHTMLWithCustomOptions = (input, customOptions) => {
    const { sanitizeLevel, apiTimeout, errorHandlingMode } = customOptions;
    let finalHTML = '';
    try {
      const htmlContent = sanitizeInput(input);
      // Fetch metadata from external API if necessary
      await new Promise((resolve) => setTimeout(() => resolve(), apiTimeout));
      const metaData = await fetch('https://api.example.com/metadata').json();
      // Integrate fetched data into HTML content
      for (const item of Object.keys(metaData)) {
        finalHTML += `<div>${item}: ${metaData[item]}</div>`;
      }
      return `${htmlContent}${finalHTML}`;
    } catch (error) {
      if (errorHandlingMode === 'alert') {
        alert(`Error generating HTML: ${error}`);
      } else {
        console.error('Error generating HTML:', error);
      }
      return '';
    }
  };

  export { generateHTML, getCustomOptions, generateHTMLWithCustomOptions };
