        VertexProperties vp;
        vp.id = idDist(gen);
        vp.x = coordDist(gen);
        vp.y = coordDist(gen);
        add_vertex(vp, g);
    }

    for (int i = 0; i < numEdges; ++i) {
        int v1Index = random_device::entropy() % (numVertices - 1);
        int v2Index = random_device::entropy() % (numVertices - 1);
