use std::path::{Path, PathBuf};
use std::process;
use std::sync::mpsc;
use std::thread;

#[cfg(unix)]
extern crate unix_socket;

async fn create_directory(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = Path::new(dir_name);

    if !dir_path.exists() {
        match fs::create_dir_all(dir_path) {
            Ok(_) => {}
            Err(err) => {
                if err.kind() == std::io::ErrorKind::PermissionDenied {
                    eprintln!("Permission denied to create directory '{}'", dir_name);
                } else {
                    eprintln!("Failed to create directory '{}': {}", dir_name, err);
                }
                return Err(Box::new(err));
            }
        };
    }

    let mut env_vars = env::vars();
    for var in &["TEST_VAR", "TEST_VAR2"] {
        if let Some(val) = env_vars.get(var) {
            println!("Environment variable '{}' is set to '{}'", var, val);
        } else {
            println!("Environment variable '{}' is not set", var);
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let dir_name = "mydir";
    if create_directory(dir_name).await.is_err() {
        eprintln!("Failed to create directory '{}'", dir_name);
    } else {
        println!("Directory '{}' created successfully", dir_name);
    }

    Ok(())
}
