class FactoryRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, factory_func):
        self._registry[factory_func.__name__] = factory_func
        return self

    def get_factory(self, class_name):
        if class_name in self._registry:
            return self._registry[class_name]
        else:
            raise ValueError(f"No registered factory function for {class_name}")

class ObjectRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, obj_type):
        self._registry[obj_type.__name__] = obj_type
        return self

    def get_object(self, class_name):
        if class_name in self._registry:
            return self._registry[class_name]
        else:
            raise ValueError(f"No registered object type for {class_name}")

