class LazyLoader:
    def __init__(self, obj):
        self._obj = obj
        self._loaded = False

    def load(self):
        if not self._loaded:
            self._loaded = True
            return self._obj
        else:
            return self._obj

    def is_loaded(self):
        return self._loaded


class CustomObject:
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)


def main():
    factory_registry = FactoryRegistry()
    registry = ObjectRegistry()

    @factory_registry.register
    class PersonFactory:
        @classmethod
        def create(cls):
            return CustomObject(name="John", age=30)

    @registry.register
    class Person:
        pass

    # usage example
    person = factory_registry.get_factory("PersonFactory").create()
    print(person.name)  # John
    print(person.age)   # 30

if __name__ == "__main__":
    main()

