using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public class TemperatureManager
{
    private readonly Dictionary<string, List<TemperatureReading>> _readings = new();
    private readonly Dictionary<string, CachePolicy> _cachePolicies = new();
    private readonly ILogger _logger;
    private readonly HttpClient _httpClient;

    public TemperatureManager(ILogger logger)
    {
        _logger = logger;
        _httpClient = new HttpClient();
        InitializeCachePolicies();
    }

    public void AddReading(TemperatureReading reading, string location)
    {
        if (!_readings.TryGetValue(location, out var readings))
        {
            readings = new List<TemperatureReading>();
            _readings.Add(location, readings);
        }
        readings.Add(reading);
        CacheTemperatureReading(reading, location);
    }

    public double GetAverageTemperatureForMonth(string location, int month)
    {
        if (!_readings.TryGetValue(location, out var readings))
            return 0;

        return readings.Where(r => r.Date.Month == month).Average(r => r.Temperature);
    }

    public List<TemperatureReading> FilterReadingsByLocation(string location, bool includeLocalFiles = true)
    {
        if (includeLocalFiles && _readings.TryGetValue(location, out var readings))
            return readings;

        if (!includeLocalFiles)
            return new List<TemperatureReading>();

        try
        {
            string[] files = Directory.GetFiles("path_to_local_files");
            List<TemperatureReading> localReadings = files.Select(File.ReadAllBytes).Select(JsonSerializer.Deserialize<TemperatureReading>).ToList();
            _readings.Add(location, localReadings);
            return localReadings;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to read local temperature readings");
            return new List<TemperatureReading>();
        }
    }

    public async Task<List<TemperatureReading>> GetRemoteReadingsAsync(string location, int daysAgo)
    {
        try
        {
            string url = $"https://api.temperatureservice.com/{location}/{daysAgo}";
            HttpResponseMessage response = await _httpClient.GetAsync(url);
            if (response.IsSuccessStatusCode)
            {
                string responseBody = await response.Content.ReadAsStringAsync();
                return JsonSerializer.Deserialize<List<TemperatureReading>>(responseBody);
            }
            else
            {
                _logger.LogError($"Failed to retrieve remote temperature readings for {location}");
                return new List<TemperatureReading>();
            }
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to retrieve remote temperature readings");
            return new List<TemperatureReading>();
        }
    }

    private void CacheTemperatureReading(TemperatureReading reading, string location)
    {
        if (!_cachePolicies.TryGetValue(location, out var cachePolicy))
        {
            cachePolicy = new CachePolicy();
            _cachePolicies.Add(location, cachePolicy);
        }
        cachePolicy.Add(reading);
    }

    private void InitializeCachePolicies()
    {
        foreach (var policy in _cachePolicies.Values)
        {
            policy.EvictOldEntries(TimeSpan.FromHours(1));
        }
    }
}

public class TemperatureReading
{
    public DateTime Date { get; set; }
    public double Temperature { get; set; }
}

public enum CachePolicyEvictionStrategy
{
    LeastRecentlyUsed,
    FirstInFirstOut
}

public class CachePolicy
{
    private readonly Dictionary<TemperatureReading, DateTime> _readings = new();
    private readonly int _maxEntries;
    private readonly TimeSpan _evictionPeriod;

    public CachePolicy(int maxEntries, TimeSpan evictionPeriod)
    {
        _maxEntries = maxEntries;
        _evictionPeriod = evictionPeriod;
    }

    public void Add(TemperatureReading reading)
    {
        if (_readings.Count >= _maxEntries)
        {
            DateTime oldestEntry = _readings.Min(kvp => kvp.Value);
            _readings.Remove(oldestEntry);
        }
        _readings.Add(reading, DateTime.UtcNow);
    }

    public void EvictOldEntries(TimeSpan period)
    {
        DateTime cutoff = DateTime.UtcNow - period;
        foreach (var reading in _readings.Where(kvp => kvp.Value < cutoff))
        {
            _readings.Remove(reading);
        }
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}
