typedef struct {
    // ... other fields ...
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a doubly-linked list
void init_DoublyLinkedList(int num_elements) {
    // Initialize the head and tail of the list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Initialize the fields of the new element
        new_element->RX_UE_INFORMATION_TAG = rand();
        new_element->RNTI = rand();
        new_element->CRC_INDICATION_REL8_TAG.crc_flag = (rand() % 2);

        if (head == NULL) {
            head = new_element;
            tail = new_element;
        } else {
            tail->next = new_element;
            new_element->prev = tail;
            tail = new_element;
        }
    }

    // Periodically purge outdated entries from the list
    time_t current_time = time(NULL);
    for (NFAPI_CRC_INDICATION_PDU_T* node = head; node != NULL; node = node->next) {
        if (node->timestamp + 3600 < current_time) { // assume timestamp is in seconds
            NFAPI_CRC_INDICATION_PDU_T* prev_node = node->prev;
            NFAPI_CRC_INDICATION_PDU_T* next_node = node->next;

            if (prev_node != NULL) {
                prev_node->next = next_node;
            } else {
                head = next_node;
            }

            if (next_node != NULL) {
                next_node->prev = prev_node;
            } else {
                tail = prev_node;
            }

            free(node);
        }
    }

    // Ensure the list does not exceed a maximum size of 10,000 elements
    while (tail != NULL && (int)(tail - head) > 10000) {
        NFAPI_CRC_INDICATION_PDU_T* node = tail;
        tail = node->prev;
        free(node);
    }
}
