#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    int count;
    pthread_mutex_t lock;
} Records;

Records *init_records(int size) {
    Records *records = (Records *)malloc(sizeof(Records));
    records->count = 0;
    records->records = (Record *)calloc(size, sizeof(Record));
    pthread_mutex_init(&records->lock, NULL);
    return records;
}

int find(Records *records, int key) {
    Record *record = records->records;
    for (int i = 0; i < records->count; i++) {
        if (record[i].key == key) {
            pthread_mutex_unlock(&records->lock);
            return record[i].offset;
        }
        record++;
    }
    pthread_mutex_unlock(&records->lock);
    return -1;
}

void union_records(Records *records, int offset1, int offset2) {
    Record *record = records->records;
    for (int i = 0; i < records->count; i++) {
        if (record[i].offset == offset1) {
            record[i].key = -1;
            break;
        }
        if (record[i].offset == offset2) {
            record[i].key = -1;
            break;
        }
    }
}

int disjointness_check(Records *records, int time_start) {
    Record *record = records->records;
    long total_time = 0;
    int disjoint_count = 0;
    for (int i = 0; i < records->count; i++) {
        if (record[i].key == -1) continue;
        record++;
        pthread_mutex_lock(&records->lock);
        int offset = find(records, i);
        if (offset != -1) {
            union_records(records, offset, i);
            disjoint_count++;
        }
        pthread_mutex_unlock(&records->lock);
    }
    long time_end = millis();
    total_time += time_end - time_start;
    return disjoint_count, total_time;
}

long millis() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (tv.tv_sec * 1000) + (tv.tv_usec / 1000);
}

int main() {
    Records *records = init_records(10000);
    int disjoint_pairs = 0;
    long total_time = 0;
    for (int i = 0; i < 10; i++) {
        int start = millis();
        int count, time_taken = disjointness_check(records, start);
        disjoint_pairs += count;
        total_time += time_taken;
    }
    printf("Disjoint pairs: %d\n", disjoint_pairs);
    printf("Total time taken: %ld milliseconds\n", total_time);
    return 0;
}

