void compress_files(const char *directory_path, const char *extension, int algorithm) {
    DIR *dir = opendir(directory_path);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", directory_path);
        return;
    }

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }

        char file_path[1024];
        sprintf(file_path, "%s/%s", directory_path, ent->d_name);

        struct stat sb;
        if (stat(file_path, &sb) == -1) {
            printf("Error reading file: %s\n", file_path);
            continue;
        }

        if (S_ISDIR(sb.st_mode)) {
            compress_files(file_path, extension, algorithm);
        } else if (strcmp(ent->d_name + strlen(ent->d_name) - strlen(extension), extension) == 0) {
            // Compress the file using the specified algorithm
            // ...
            // For example:
            char compressed_file_path[1024];
            sprintf(compressed_file_path, "%s.%s.gz", directory_path, ent->d_name);
            rename(file_path, compressed_file_path);

            if (algorithm == 1) {
