#include <stdlib.h>
#include <string.h>

typedef struct {
    NFAPI_RX_FRAME_PDU_T frame;
    void *payload;
} FrameEntry;

typedef struct {
    int size;
    FrameEntry **entries;
    pthread_mutex_t mutex;
} DynamicFrameList;

DynamicFrameList* dynamic_frame_list_create() {
    DynamicFrameList* list = (DynamicFrameList*)malloc(sizeof(DynamicFrameList));
    list->size = 0;
    list->entries = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_frame_list_destroy(DynamicFrameList* list) {
    if (list == NULL) return;

    for (int i = 0; i < list->size; i++) {
        free(list->entries[i]->payload);
        free(list->entries[i]);
    }

    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void dynamic_frame_list_add(DynamicFrameList* list, NFAPI_RX_FRAME_PDU_T frame) {
    FrameEntry *entry = (FrameEntry*)malloc(sizeof(FrameEntry));
    entry->frame = frame;
    entry->payload = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->size == 0 || memcmp(&entry->frame, &list->entries[list->size - 1]->frame, sizeof(NFAPI_RX_FRAME_PDU_T)) != 0) {
        list->entries = realloc(list->entries, (list->size + 1) * sizeof(FrameEntry *));
        list->entries[list->size++] = entry;
    } else {
        // Update existing frame
        for (int i = 0; i < list->size; i++) {
            if (memcmp(&entry->frame, &list->entries[i]->frame, sizeof(NFAPI_RX_FRAME_PDU_T)) == 0) {
                free(list->entries[i]->payload);
                list->entries[i]->payload = entry->payload;
                break;
            }
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void dynamic_frame_list_remove(DynamicFrameList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->frame.rnti == rnti) {
            free(list->entries[i]->payload);
            free(list->entries[i]);

            // Shift elements
            for (int j = i + 1; j < list->size; j++) {
                list->entries[j - 1] = list->entries[j];
            }

            list->size--;
            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void dynamic_frame_list_update_payload(DynamicFrameList* list, uint16_t rnti, void *new_payload) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->frame.rnti == rnti) {
            free(list->entries[i]->payload);
            list->entries[i]->payload = new_payload;
            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}
