    int maxAllocations = 0;

    while (1) {
        // Allocate memory for arrays
        if ((offsetValues = malloc(sizeof(long) * size)) == NULL ||
            (keys = malloc(sizeof(int) * size)) == NULL) {
            break;  // Allocation failed, try again
        }

        // Initialize arrays
        for (int i = 0; i < size; i++) {
            offsetValues[i] = i;
            keys[i] = i % 10;  // Example initialization
        }

        maxAllocations++;
    }

    return malloc(sizeof(int) * maxAllocations);
}

void* allocateAndInitializeRecords(int count, int rangeSize) {
    record* records = NULL;

    while (1) {
        // Allocate memory for array of records
        if ((records = malloc(sizeof(record) * count)) == NULL) {
            break;  // Allocation failed, try again
