Record* records = NULL;
int record_count = 0;
int initial_capacity = 10;
int max_memory_usage = 1024 * 1024; // 1MB

void* reallocate_records(void* arg) {
    size_t current_size = sizeof(Record) * (record_count + 1);
    Record* new_records = realloc(records, current_size);
    if (!new_records) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    records = new_records;
    return NULL;
}

void add_record(int value) {
    pthread_mutex_lock(NULL); // assume lock-free implementation
    record_count++;
    if (record_count >= initial_capacity) {
        int* old_initial_capacity = &initial_capacity;
        initial_capacity += 10; // adjust capacity based on growth rate
        pthread_create(NULL, NULL, reallocate_records, old_initial_capacity);
    }
    records[record_count - 1].value = value;
    pthread_mutex_unlock(NULL);
}

int get_record_value(int index) {
    pthread_mutex_lock(NULL); // assume lock-free implementation
    if (index >= record_count) {
        printf("Index out of bounds.\n");
        return -1; // or handle it in a more sophisticated way
    }
    int value = records[index].value;
    pthread_mutex_unlock(NULL);
    return value;
}

int main() {
    pthread_t reallocator_thread;

    // Initialize the memory with the initial capacity
    pthread_create(&reallocator_thread, NULL, reallocate_records, NULL);

    while (1) {
        add_record(rand());
    }

    return 0;
}
