#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_BUCKET_SIZE 16
#define MAX_MEMORY_ALLOCATION 1024
#define LOAD_FACTOR_THRESHOLD 0.7

typedef struct {
    int integer;
    float floating_point;
    void* pointer;
} custom_data_t;

typedef struct {
    int key_length;
    char* key;
    custom_data_t value;
} entry_t;

typedef struct {
    int size;
    int capacity;
    pthread_mutex_t lock;
    entry_t** buckets;
    double total_memory_usage;
} hash_table_t;

hash_table_t* create_hash_table(int initial_bucket_size) {
    hash_table_t* table = (hash_table_t*)malloc(sizeof(hash_table_t));
    table->size = 0;
    table->capacity = INITIAL_BUCKET_SIZE;
    table->buckets = (entry_t**)malloc(table->capacity * sizeof(entry_t*));
    for (int i = 0; i < table->capacity; i++) {
        table->buckets[i] = NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    table->total_memory_usage = 0.0;
    return table;
}

void resize_hash_table(hash_table_t* table) {
    if (table->size > table->capacity * LOAD_FACTOR_THRESHOLD) {
        int new_capacity = table->capacity * 2;
        entry_t** new_buckets = (entry_t**)malloc(new_capacity * sizeof(entry_t*));
        for (int i = 0; i < new_capacity; i++) {
            new_buckets[i] = NULL;
        }
        for (int i = 0; i < table->capacity; i++) {
            entry_t* bucket = table->buckets[i];
            while (bucket) {
                int index = hash(bucket->key) % new_capacity;
                bucket->next = new_buckets[index];
                new_buckets[index] = bucket;
                bucket = bucket->next;
            }
        }
        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }
}

void* put(hash_table_t* table, char* key, void* value) {
    pthread_mutex_lock(&table->lock);
    int index = hash(key) % table->capacity;
    entry_t** bucket = &table->buckets[index];
    entry_t* entry = malloc(sizeof(entry_t));
    entry->key_length = strlen(key);
    entry->key = key;
    entry->value = *(custom_data_t*)value;
    entry->next = *bucket;
    *bucket = entry;
    table->size++;
    table->total_memory_usage += sizeof(custom_data_t) + key_length + sizeof(entry_t);
    if (table->total_memory_usage > MAX_MEMORY_ALLOCATION) {
        // Implement memory limit checking and graceful degradation strategy
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void get(hash_table_t* table, char* key, void* value) {
    pthread_mutex_lock(&table->lock);
    int index = hash(key) % table->capacity;
    entry_t** bucket = &table->buckets[index];
    entry_t* entry = *bucket;
    while (entry) {
        if (!strcmp(entry->key, key)) {
            *(custom_data_t*)value = entry->value;
            break;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->lock);
}

int hash(char* key) {
    // Implement a simple hash function
    int result = 0;
    for (int i = 0; i < strlen(key); i++) {
        result += key[i];
    }
    return result % table->capacity;
}
