void createAndPopulateNfarxList(int n, struct NFAPI_CRC_INDICATION_PDU_T **list) {
    sem_t *semaphore;
    semaphore = initializeSemaphore();

    for (int i = 0; i < n; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *pdu = (struct NFAPI_CRC_INDATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

        sem_wait(semaphore);
        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 200;
        pdu->CRCFLAG = rand() % 2; // 0 or 1

        sem_post(semaphore);

        (*list)[i] = pdu;
    }

    for (int i = 0; i < n; i++) {
        free((*list)[i]);
    }

    sem_close(semaphore);
}

sem_t *initializeSemaphore() {
    sem_t *semaphore;
    semaphore = sem_open("/my_semaphore", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, 1);

    if (semaphore == SEM_FAILED) {
        printf("Error creating semaphore\n");
        exit(-1);
    }

    return semaphore;
