#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char *filename;
    char *new_extension;
} FileItem;

int count_non_numeric_chars(const char *filename) {
    int count = 0;
    for (; *filename; filename++) {
        if (!isdigit(*filename))
            count++;
    }
    return count;
}

char *derive_file_type(const char *filename) {
    char *type = NULL;
    for (const char *p = filename; *p; p++) {
        while (*p && isspace(*p)) p++;
        while (*p && !isalpha(*p)) p++;
        if (*p) {
            type = strdup(p);
            break;
        }
    }
    return type;
}

char *create_new_extension(int count, char *type) {
    static const char *extensions[] = {"A", "TXT", "BIN", "PDF", "XML", "HTML"};
    int i;
    for (i = 0; i < sizeof(extensions) / sizeof(*extensions); i++) {
        if (!strncasecmp(type, extensions[i], strlen(extensions[i]))) {
            return strdup(extensions[i]);
        }
    }
    return NULL;
}

void process_file(char *filename) {
    int count = count_non_numeric_chars(filename);
    char *type = derive_file_type(filename);
    char *new_extension = create_new_extension(count, type ? type : "TXT");
    free(type);

    char *path = strdup(filename);
    char *ext = strrchr(path, '.');
    if (ext) {
        char *temp = ext;
        while (*temp && !isdigit(*temp)) temp++;
        if (*temp) {
            temp++;
            while (*temp && isdigit(*temp)) temp++;
            if (*temp) {
                int i = atoi(temp);
                sprintf(ext, ".%d", i + 1);
            }
        }
    } else {
        ext = strrchr(path, '/');
        if (ext) *ext++ = '\0';
    }

    strcat(strrchr(path, '.'), new_extension ? new_extension : "");
    free(new_extension);
    free(path);
}

void process_directory(const char *dir_path) {
    DIR *dir = opendir(dir_path);
    struct dirent *ent;
    while ((ent = readdir(dir))) {
        if (strcmp(ent->d_name, ".") && strcmp(ent->d_name, "..")) {
            char path[1024];
            sprintf(path, "%s/%s", dir_path, ent->d_name);
            process_file(path);
        }
    }
    closedir(dir);
}

int main() {
    process_directory("path_to_your_directory");
    return 0;
}
