            printf("Error: Invalid random number generated.\n");
            return;
        }
        random_numbers[i] = random_value;
    }

    // Check memory usage and adjust sizes if necessary
    size_t total_memory_usage = sizeof(long) * num_offset_values + sizeof(int) * num_offset_values + sizeof(record) * num_records;
    if (total_memory_usage > MEMORY_THRESHOLD) {
        int new_size = 2 * num_offset_values;
        while (new_size > total_memory_usage) {
            offset_values = realloc(offset_values, new_size * sizeof(long));
            keys = realloc(keys, new_size * sizeof(int));
            records = realloc(records, new_size * sizeof(record));
            new_size /= 2;
        }
    }

    // Deallocate memory when the function returns
    free(offset_values);
    free(keys);
    free(records);
    free(random_numbers);

    // Garbage collection strategy: reclaim memory from partially used data structures
    if (num_offset_values < num_records) {
        records = realloc(records, (num_offset_values + 1) * sizeof(record));
    } else {
        offset_values = realloc(offset_values, (num_records + 1) * sizeof(long));
    }
