    header->primaryKeyIndex = -1; // Default primary key index
    header->version = 0;

    // Step 3: Allocate memory for an array of column descriptors
    ColumnDescriptor** columns = (ColumnDescriptor**)malloc(numColumns * sizeof(ColumnDescriptor*));
    if (!columns) {
        free(header);
        return NULL;
    }

    // Step 4: Initialize and allocate memory for each column descriptor
    for (int i = 0; i < numColumns; i++) {
        ColumnDescriptor* column = (ColumnDescriptor*)malloc(sizeof(ColumnDescriptor));
        if (!column) {
            for (int j = 0; j < i; j++)
                free(columns[j]);
            free(columns);
            free(header);
            return NULL;
        }
        // Handle error: adjust column count and data sizes as needed
        // ...

        columns[i] = column;
    }

    // Step 5: Integrate with external dataset handling library (omitted for brevity)
    // ...

    // Step 6: Deallocate all allocated memory when the function returns
    for (int i = 0; i < numColumns; i++)
        free(columns[i]);
    free(columns);
    free(header);

    return header;
}
