NFAPI_CRC_INDICATION_PDU_T* create_array(int size) {
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return arr;
}

void* allocate_and_init_arrays(int size, int** offsets, long** keys) {
    *offsets = create_array(size);
    *keys = create_array(size);

    for (int i = 0; i < size; i++) {
        (*keys)[i] = rand();
        (*offsets)[i] = (long)(rand() / (RAND_MAX / (size - 1)));
    }
}

void resize_arrays(int* offsets, long* keys, int new_size) {
    if (new_size > MAX_CAPACITY) return;

    NFAPI_CRC_INDICATION_PDU_T* temp_offsets = create_array(new_size);
    NFAPI_CRC_INDICATION_PDU_T* temp_keys = create_array(new_size);

    for (int i = 0; i < new_size && i < *sizeof(*offsets); i++) {
        temp_offsets[i] = (*offsets)[i];
        temp_keys[i] = (*keys)[i];
    }

    free(*offsets);
    free(*keys);
    *offsets = temp_offsets;
    *keys = temp_keys;
