['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct value {
    float data;
    int ref_count;
} Value;

typedef struct node {
    pthread_mutex_t mutex;
    int num_values;
    Value **values;
    struct node *next;
} Node;

Node *node_list = NULL;
pthread_mutex_t node_list_mutex;

void create_node() {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->num_values = 0;
    new_node->values = NULL;
    new_node->next = node_list;
    pthread_mutex_lock(&node_list_mutex);
    if(node_list == NULL) {
        node_list = new_node;
    } else {
        Node *curr = node_list;
        while(curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
    pthread_mutex_unlock(&node_list_mutex);
}

void destroy_node(Node *node) {
    pthread_mutex_lock(&node_list_mutex);
    if(node == node_list) {
        node_list = node->next;
    } else {
        Node *curr = node_list;
        while(curr->next != NULL && curr->next != node) {
            curr = curr->next;
        }
        if(curr->next != NULL) {
            curr->next = node->next;
        }
    }
    pthread_mutex_unlock(&node_list_mutex);
}

void increment_value_refcount(Node *node, Value *value) {
    pthread_mutex_lock(&node->mutex);
    value->ref_count++;
    pthread_mutex_unlock(&node->mutex);
}

void decrement_value_refcount(Node *node, Value *value) {
    pthread_mutex_lock(&node->mutex);
    if(value->ref_count > 0) {
        value->ref_count--;
    }
    if(value->ref_count == 0) {
        // Clean up the value here
        free(value);
        node->num_values--;
        if(node->num_values == 0) {
            destroy_node(node);
        }
    }
    pthread_mutex_unlock(&node->mutex);
}

void print_value(Node *node, Value *value) {
    printf("Value: %f Ref Count: %d\n", value->data, value->ref_count);
}
