```c
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 50000
#define BUFFER_SIZE (MAX_NODES * sizeof(NFAPI_RRC_CTXT_CBACK_T))

typedef struct {
    NFAPI_RRC_CTXT_CBACK_T* nodes[MAX_NODES];
    int head;
    int tail;
    pthread_mutex_t lock;
} circular_list_t;

circular_list_t* init_circular_list() {
    circular_list_t* list = (circular_list_t*)malloc(sizeof(circular_list_t));
    list->head = 0;
    list->tail = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_at_head(circular_list_t* list, NFAPI_RRC_CTXT_CBACK_T* node) {
    if (list->head == 0) {
        list->nodes[0] = node;
    } else {
        memmove(&list->nodes[list->head-1], &list->nodes[list->head], sizeof(NFAPI_RRC_CTXT_CBACK_T*) * (MAX_NODES - list->head + 1));
        list->nodes[0] = node;
    }
    list->head = 1;
    if (list->tail == MAX_NODES - 1) {
        list->tail = 0;
    } else {
        list->tail++;
    }
}

void insert_at_tail(circular_list_t* list, NFAPI_RRC_CTXT_CBACK_T* node) {
    if (list->tail == 0) {
        list->nodes[0] = node;
    } else {
        memmove(&list->nodes[list->tail], &list->nodes[0], sizeof(NFAPI_RRC_CTXT_CBACK_T*) * list->tail);
        list->nodes[MAX_NODES - 1] = node;
    }
    list->tail = (list->tail + 1) % MAX_NODES;
}

void* iterate_list(void* data) {
    circular_list_t* list = (circular_list_t*)data;
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->head; i++) {
        // Perform operations on each node
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void delete_node(circular_list_t* list, NFAPI_RRC_CTXT_CBACK_T* node) {
    int i;
    for (i = 0; i < list->head; i++) {
        if (list->nodes[i] == node) {
            break;
        }
    }
    if (i >= list->head) return;

    memmove(&list->nodes[i], &list->nodes[i+1], sizeof(NFAPI_RRC_CTXT_CBACK_T*) * (list->head - i - 1));
    list->head = i;
    if (list->tail == i) {
        list->tail = 0;
    }
}

void free_circular_list(circular_list_t* list) {
    pthread_mutex_unlock(&list->lock);
    free(list);
}
```

Example of misuse:

```c
int main() {
    circular_list_t* list = init_circular_list();
    NFAPI_RRC_CTXT_CBACK_T* node1 = malloc(sizeof(NFAPI_RRC_CTXT_CBACK_T));
    NFAPI_RRC_CTXT_CBACK_T* node2 = malloc(sizeof(NFAPI_RRC_CTXT_CBACK_T));
    insert_at_head(list, node1);
    // This will lead to a memory leak because the nodes are not properly freed
    free(node1);  // Should be done after removing it from the list
    insert_at_tail(list, node2);
    delete_node(list, node2);
    return 0;
}
