// Function to manage encryption and decryption operations
void manage_cipher_operation(const char* input_data, int data_length, const char* cipher_mode, int key_size) {
    // Initialize the AES context
    EVP_CIPHER_CTX* ctx;
    if (!EVP_CIPHER_CTX_new(&ctx)) {
        printf("Failed to create AES context\n");
        return;
    }

    // Set the cipher mode and key size
    if (strcmp(cipher_mode, "CBC") == 0) {
        EVP_CIPHER_CTX_set_cipher(ctx, EVP_aes_256_cbc());
    } else if (strcmp(cipher_mode, "ECB") == 0) {
        EVP_CIPHER_CTX_set_cipher(ctx, EVP_aes_256_ecb());
    } else {
        printf("Unsupported cipher mode\n");
        return;
    }

    // Generate a random key
    unsigned char* key = (unsigned char*)malloc(key_size);
    RAND_bytes(key, key_size);

    // Encrypt or decrypt the input data
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, NULL) != 1) {
        printf("Failed to initialize AES encryption\n");
        return;
    }

    unsigned char* output = (unsigned char*)malloc(data_length);
    int out_len = 0;
    EVP_EncryptUpdate(ctx, output, &out_len, input_data, data_length);

    // Print the encrypted or decrypted data
    printf("Encrypted/decrypted data: ");
    for (int i = 0; i < out_len; i++) {
        printf("%02x", output[i]);
    }
    printf("\n");

    // Clean up memory and AES context
    EVP_CIPHER_CTX_free(ctx);
    free(key);
    free(output);
}
