#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <semaphore.h>

#define SEMAPHORE_COUNT 10
#define SEMAPHORE_INITIALIZER 5
#define MAX_SEMAPHORE_VALUE 100
#define MIN_SEMAPHORE_VALUE 0

typedef struct {
    sem_t* semaphore;
    int initial_value;
} semaphore_info;

semaphore_info semaphores[SEMAPHORE_COUNT];
sem_t log_sem;
int logging_enabled = 1;

void init_semaophores() {
    for (int i = 0; i < SEMAPHORE_COUNT; i++) {
        semaphores[i].initial_value = SEMAPHORE_INITIALIZER;
        sem_init(&semaphores[i].semaphore, 1, semaphores[i].initial_value);
    }
}

void create_semaphore(int index) {
    if (index >= SEMAPHORE_COUNT || index < 0) {
        perror("Invalid semaphore index");
        return;
    }
    semaphores[index].semaphore = sem_open((const char*)malloc(10), O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, SEMAPHORE_INITIALIZER);
    if (semaphores[index].semaphore == SEM_FAILED) {
        perror("Semaphore creation failed");
        return;
    }
}

void delete_semaphore(int index) {
    if (index >= SEMAPHORE_COUNT || index < 0) {
        perror("Invalid semaphore index");
        return;
    }
    sem_close(semaphores[index].semaphore);
    free((char*)sem_open((const char*)semaphores[index].semaphore, O_TRUNC));
}

void increment_semaphore(int index) {
    if (index >= SEMAPHORE_COUNT || index < 0) {
        perror("Invalid semaphore index");
        return;
    }
    int new_value = sem_getvalue(&semaphores[index].semaphore);
    if (new_value >= MAX_SEMAPHORE_VALUE || new_value <= MIN_SEMAPHORE_VALUE) {
        perror("Semaphore value out of range");
        return;
    }
    sem_post(&semaphores[index].semaphore);
}

void decrement_semaphore(int index) {
    if (index >= SEMAPHORE_COUNT || index < 0) {
        perror("Invalid semaphore index");
        return;
    }
    int new_value = sem_getvalue(&semaphores[index].semaphore);
    if (new_value <= MIN_SEMAPHORE_VALUE) {
        perror("Semaphore value underflow");
        return;
    }
    sem_wait(&semaphores[index].semaphore);
}

void log_operation(int operation, int index) {
    if (!logging_enabled) {
        return;
    }
    FILE* log_file = fopen("/var/log/semaphore.log", "a+");
    fprintf(log_file, "%s semaphore %d: %s\n", (operation == 0) ? "Created" : (operation == 1) ? "Deleted" : (operation == 2) ? "Incremented" : (operation == 3) ? "Decremented" , index);
    fclose(log_file);
}

int main() {
    init_semaophores();
    create_semaphore(0);
    increment_semaphore(0);
    decrement_semaphore(0);
    delete_semaphore(0);
    log_operation(1, 0);
    return 0;
}
