from kubernetes import client, config
from retrying import retry
from pyk8s import PyK8S

class DeploymentOrchestrator:
    def __init__(self, config_file, api_client_config):
        self.config_file = config_file
        self.api_client_config = api_client_config
        self.k8s_api = client.ApiClient()
        self.k8s_api.configuration.host = 'https://localhost:8443'
        self.k8s_api.configuration.ssl_verify = False

    def load_config(self):
        with open(self.config_file, 'r') as file:
            return yaml.safe_load(file)

    def deploy_app(self, config):
        try:
            # Create a new namespace
            namespace = client.V1Namespace(metadata=client.V1ObjectMeta(name='app-namespace'))
            self.k8s_api.create_namespaced_namespace(namespace, namespace.metadata.name)

            # Deploy the application
            deployment = client.V1Deployment(metadata=client.V1ObjectMeta(name='my-deployment'), 
                                               spec=client.V1DeploymentSpec replicas=3, 
                                               template=client.V1PodTemplateSpec labels={'app': 'my-app'})
            self.k8s_api.create_namespaced_deployment(namespace.metadata.name, deployment)

            # Scale the pods
            scale = client.V1Scale(targets=[client.V1ObjectFieldSelector(field_path='metadata.name')])
            self.k8s_api.patch_namespaced_scale(namespace.metadata.name, scale)

        except Exception as e:
            logging.error(f"Deployment failed: {e}")

    def roll_back(self):
        try:
            # Roll back the deployment
            self.k8s_api.delete_namespaced_deployment('my-deployment', namespace='app-namespace')

        except Exception as e:
            logging.error(f"Rollback failed: {e}")

    @retry(wait_fixed=10000, stop_max_attempt_number=5)
    def check_app_health(self):
        # Check the application health
        if not self.k8s_api.get_namespaced_pod('app-namespace', 'my-app').status.phase == 'Running':
            raise Exception("Application is not running")

    @retry(wait_fixed=10000, stop_max_attempt_number=5)
    def scale_app(self):
        # Scale the application based on CPU usage
        if self.k8s_api.get_namespaced_pod('app-namespace', 'my-app').spec.containers[0].resources.requests['cpu'] > 500:
            self.k8s_api.patch_namespaced_scale('app-namespace', client.V1Scale(targets=[client.V1ObjectFieldSelector(field_path='metadata.name')]))
        else:
            pass

    def run(self):
        config = self.load_config()

        try:
            if not yaml.validate(config, schema_url='#').error_string:
                # Deploy the application
                self.deploy_app(config)

                while True:
                    try:
                        self.check_app_health()
                    except Exception as e:
                        logging.error(f"Application health check failed: {e}")

                    self.scale_app()

            else:
                logging.error("Invalid configuration file")
        except Exception as e:
            logging.error(f"Script error: {e}")

        finally:
            try:
                # Roll back the deployment if any step fails
                self.roll_back()
            except Exception as e:
                logging.error(f"Rollback failed: {e}")

if __name__ == "__main__":
    config_file = 'config.yaml'
    api_client_config = client.Configuration(api_key=None, host='https://localhost:8443', ssl_verify=False)

    deployment_orchestrator = DeploymentOrchestrator(config_file, api_client_config)
    deployment_orchestrator.run()
