        ctx = EVP_CIPHER_CTX_new_by_name("AES-256-ECB");
    } else if (key_size == 256 && mode == CHACHA20_POLY1305) {
        ctx = EVP_CIPHER_CTX_new_by_name("CHACHA20-POLY1305");
    }

    // Perform key derivation using PBKDF2
    unsigned char derived_key[32];
    int derived_key_len;
