typedef struct {
    long transaction_id;
    time_t timestamp;
    unsigned int reference_count;
    item** items;
    size_t num_items;
} transaction;

transaction* allocate_transactions(size_t num_transactions) {
    transaction* transactions = (transaction*)malloc(num_transactions * sizeof(transaction));
    if (!transactions) {
        return NULL;  // Handle memory allocation failure
    }

    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i].num_items = 3;
        transactions[i].items = (item**)malloc(transactions[i].num_items * sizeof(item*));
        if (!transactions[i].items) {
            // Handle memory allocation failure
            free(transactions);
            return NULL;
        }

        for (size_t j = 0; j < transactions[i].num_items; ++j) {
            transactions[i].items[j] = (item*)malloc(sizeof(item));
            if (!transactions[i].items[j]) {
                // Handle memory allocation failure
                free(transactions);
                return NULL;
            }
        }

        transactions[i].timestamp = time(NULL);
    }

    return transactions;
}

void deallocate_transactions(transaction* transactions, size_t num_transactions) {
    for (size_t i = 0; i < num_transactions; ++i) {
        for (size_t j = 0; j < transactions[i].num_items; ++j) {
            free(transactions[i].items[j]);
        }
        free(transactions[i].items);
    }

    free(transactions);
}

transaction* allocate_item_array(size_t num_items) {
    item** items = (item**)malloc(num_items * sizeof(item*));
    if (!items) {
        return NULL;  // Handle memory allocation failure
    }

    for (size_t i = 0; i < num_items; ++i) {
        items[i] = (item*)malloc(sizeof(item));
        if (!items[i]) {
            free(items);
            return NULL;
        }
    }

    return items;
}

void deallocate_item_array(item** items, size_t num_items) {
    for (size_t i = 0; i < num_items; ++i) {
        free(items[i]);
    }
    free(items);
}
