```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure definition for each node in the linked list
typedef struct Node {
    int value;
    char label;
    struct Node* next;
} Node;

// Function to insert a new node at a specified position within the list
Node* insertNode(Node** head, int value, char label, int position) {
    // Create a new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = value;
    newNode->label = label;
    newNode->next = NULL;

    if (*head == NULL || position == 0) {
        // Insert at the beginning of the list
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        for (int i = 0; i < position - 1 && current != NULL; i++) {
            current = current->next;
        }
        if (current == NULL) {
            // Insert at the end of the list
            newNode->next = *head;
            *head = newNode;
        } else {
            newNode->next = current->next;
            current->next = newNode;
        }
    }

    return *head;
}

// Function to traverse the linked list and print node values and labels
void printList(Node* head) {
    while (head != NULL) {
        printf("Value: %d, Label: %c\n", head->value, head->label);
        head = head->next;
    }
}

int main() {
    // Initialize the linked list
    Node* head = NULL;

    // Insert nodes into the list
    head = insertNode(&head, 1, 'A', 0);
    head = insertNode(&head, 2, 'B', 1);
    head = insertNode(&head, 3, 'C', 2);

    // Print the linked list
    printList(head);

    return 0;
}
```

This C code demonstrates a dynamic linked list management system with functions to insert new nodes at specified positions and traverse the list to print node values and labels. The code implements thread-safe operations by creating a copy of the head pointer for each insertion operation, ensuring that the original head remains valid throughout the process.']

