#include <stdlib.h>
#include <pthread.h>

typedef struct {
    float value;
    int reference_count;
} Value;

typedef struct Node {
    pthread_mutex_t lock;
    int num_values;
    Value **values;
    pthread_sem_t semaphore;
    struct Node *next;
} Node;

Node *global_node_list = NULL;
pthread_mutex_t global_lock;

void initializeAndManageNodeList(int initial_semaphore_value) {
    if (pthread_semaphore_init(&semaphore, initial_semaphore_value) != 0) {
        // Handle semaphore initialization failure
        return;
    }

    pthread_mutex_init(&global_lock, NULL);
}

Node *create_node() {
    Node *node = malloc(sizeof(Node));
    node->num_values = 0;
    node->values = NULL;
    pthread_mutex_init(&node->lock, NULL);
    pthread_semaphore_init(&node->semaphore, 1);
    node->next = global_node_list;
    global_node_list = node;
}

void add_value_to_node(Node *node, Value *value) {
    pthread_mutex_lock(&node->lock);
    node->values = realloc(node->values, (node->num_values + 1) * sizeof(Value *));
    node->values[node->num_values] = value;
    node->num_values++;
    pthread_semaphore_post(&node->semaphore);
    pthread_mutex_unlock(&node->lock);
}

void remove_node(Node *node) {
    pthread_mutex_lock(&global_lock);
    if (node == global_node_list) {
        global_node_list = node->next;
    }

    Node *prev = NULL;
    Node *current = global_node_list;
    while (current != NULL && current != node) {
        prev = current;
        current = current->next;
    }

    if (current == node) {
        if (prev == NULL) {
            global_node_list = node->next;
        } else {
            prev->next = node->next;
        }
    }

    pthread_mutex_unlock(&global_lock);
}

void free_nodes() {
    Node *node = global_node_list;
    while (node != NULL) {
        Node *next = node->next;
        for (int i = 0; i < node->num_values; i++) {
            free(node->values[i]);
        }
        free(node->values);
        pthread_mutex_destroy(&node->lock);
        pthread_semaphore_destroy(&node->semaphore);
        free(node);
        node = next;
    }
}

void finalize() {
    free_nodes();
}
