typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
} node_t;

typedef struct {
    pthread_mutex_t lock;
    node_t* head;
    node_t* tail;
    size_t size;
    uint64_t hash[256];
} list_t;

list_t* initialize_list(size_t n) {
    list_t* list = (list_t*)malloc(sizeof(list_t));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    for (int i = 0; i < 256; i++) {
        list->hash[i] = -1;
    }

    return list;
}

void insert_at_head(list_t* list, NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) return;

    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = list->head;

    pthread_mutex_lock(&list->lock);

    if (list->head) {
        list->head->prev = &new_node->data;
    } else {
        list->tail = &new_node->data;
    }

    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void insert_at_tail(list_t* list, NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) return;

    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    list->tail->next = &new_node->data;
    list->tail = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void remove_node(list_t* list, node_t* node) {
    if (!node) return;

    pthread_mutex_lock(&list->lock);

    if (node == list->head) {
        list->head = node->next;
    } else if (node == list->tail) {
        list->tail = node->prev;
    }

    node->prev->next = node->next;
    node->next->prev = node->prev;

    free(node);

    pthread_mutex_unlock(&list->lock);
}

int get_node_by_rnti(list_t* list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);

    for (node_t* node = list->head; node; node = node->next) {
        if (node->data.rnti == rnti) {
            return 1;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int get_node_by_rx_ue_info(list_t* list, RX_UE_INFORMATION_TAG rx_ue_info) {
    pthread_mutex_lock(&list->lock);

    for (node_t* node = list->head; node; node = node->next) {
        if (node->data.rx_ue_info == rx_ue_info) {
            return 1;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}
