    $requests = 0;
    if (!isset($_SESSION['requests'])) {
        $_SESSION['requests'] = 0;
    }
    if (isset($_SERVER['REQUEST_TIME']) && ($_SERVER['REQUEST_TIME'] - $_SESSION['last_request_time']) > 60) {
        $_SESSION['requests'] = 1;
    } else {
        $requests = ++$_SESSION['requests'];
    }
    if ($requests >= 5) {
