            }
        }
        function cacheFileContents(filename) {
            const cache = {};
            try {
                const fileContent = fs.readFileSync(filename, 'utf8');
                const cachedVersion = Math.floor(Date.now() / 1000); // Unix timestamp in seconds
                cache[filename] = { content: fileContent, version: cachedVersion };
            } catch (err) {
                console.error('Error caching file contents:', err);
            }
        }
    }
}

