#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    char label[10];
} Record;

typedef struct Node {
    long* offsets;
    int* keys;
    Record** records;
    struct Node* next;
} Node;

Node* initRecords(int count, int min, int max, int labelLength) {
    if (count < 0 || min > max || labelLength > 10) {
        return NULL;
    }

    Node* head = NULL;
    Node* current = NULL;

    for (int i = 0; i < count; i++) {
        Record** records = malloc(sizeof(Record*) * count);
        int* keys = malloc(sizeof(int) * count);
        long* offsets = malloc(sizeof(long) * count);

        if (!records || !keys || !offsets) {
            for (int j = 0; j < i; j++) {
                free(records[j]);
                free(keys);
                free(offsets);
            }
            return NULL;
        }

        // Initialize record values and labels
        srand(time(NULL));
        for (int j = 0; j < count; j++) {
            keys[j] = rand() % (max - min + 1) + min;
            Record* record = malloc(sizeof(Record));
            if (!record) {
                for (int k = 0; k <= i; k++) {
                    free(records[k]);
                    free(keys);
                    free(offsets);
                }
                return NULL;
            }
            record->value = keys[j];
            sprintf(record->label, "Label %d", j + 1);

            records[j] = record;
        }

        Node* node = malloc(sizeof(Node));
        if (!node) {
            for (int k = 0; k <= i; k++) {
                free(records[k]);
                free(keys);
                free(offsets);
            }
            return NULL;
        }

        node->offsets = offsets;
        node->keys = keys;
        node->records = records;

        if (!head) {
            head = node;
            current = head;
        } else {
            current->next = node;
            current = node;
        }
    }

    return head;
}
