#include <stdlib.h>
#include <stdio.h>

typedef struct Item {
    int value;
    char label;
    struct Item* next;
} Item;

// Initialize the linked list with a dummy head
Item* initList() {
    Item* head = (Item*)malloc(sizeof(Item));
    head->value = 0;
    head->label = '\0';
    head->next = NULL;
    return head;
}

// Insert an item at a specified position in the linked list
void insertItem(Item** head, int value, char label, int position) {
    Item* newNode = (Item*)malloc(sizeof(Item));
    newNode->value = value;
    newNode->label = label;
    newNode->next = NULL;

    if (*head == NULL || position == 0) { // Insert at the head
        newNode->next = *head;
        *head = newNode;
    } else {
        Item* current = *head;
        for (int i = 0; i < position - 1 && current != NULL; i++) {
            current = current->next;
        }
        if (current == NULL) { // Insert at the end
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        } else {
            newNode->next = current->next;
            current->next = newNode;
        }
    }
}

// Print the linked list in a human-readable format
void printList(Item* head) {
    while (head != NULL) {
        printf("(%d, %c)\n", head->value, head->label);
        head = head->next;
    }
}
