#include <stdlib.h>
#include <string.h>

char* generate_identifier(char* url) {
    // Parse URL using liburllib (consider version compatibility)
    char* parsed_url = parse_url(url);

    if (!parsed_url) return NULL;

    // Extract protocol, host, path, and query parameters from the parsed URL
    char* protocol = extract_protocol(parsed_url);
    char* host = extract_host(parsed_url);
    char* path = extract_path(parsed_url);
    char* query_params = extract_query_params(parsed_url);

    // Generate unique identifier based on specified rules
    size_t id_len = 0;
    char* id = (char*)malloc(21); // Initialize with space for the longest possible ID

    if (protocol && host && path) {
        // Convert to lowercase and concatenate protocol, first character of host, and first three alphanumeric characters of path
        strcat(id,_tolower(protocol));
        id_len += strlen(_tolower(protocol));
        strcat(id, _tolower(host));
        id_len += strlen(_tolower(host)) - 1; // Subtract one for the colon (if present)
        size_t path_len = strlen(path);
        if (path_len < 3) {
            strcpy(id + id_len, path); // Use the entire path
        } else {
            strcat(id, _tolower(path));
            id_len += min(3, path_len);
        }
    }

    if (query_params) {
        // Extract first key of query string and append to identifier
        char* first_key = extract_first_query_key(query_params);
        if (first_key) {
            strcat(id + id_len, _tolower(first_key));
            id_len += strlen(_tolower(first_key));
        }
    }

    // Ensure the final identifier does not exceed 20 characters in length
    size_t remaining_chars = 20 - id_len;
    char* fragment = extract_fragment(parsed_url);
    if (fragment && strlen(fragment) <= remaining_chars) {
        strcat(id, _tolower(fragment));
    }

    // Free dynamically allocated strings and return the generated identifier
    free(parsed_url);
    free(protocol);
    free(host);
    free(path);
    free(query_params);
    free(first_key);
    free(fragment);

    return id;
}

// Helper functions to extract specific components from the parsed URL
char* extract_protocol(char* url) { ... }
char* extract_host(char* url) { ... }
char* extract_path(char* url) { ... }
char* extract_query_params(char* url) { ... }
char* extract_first_query_key(char* query_string) { ... }
char* extract_fragment(char* url) { ... }

// Helper function to convert a string to lowercase
char* _tolower(char* str) {
    for (int i = 0; str[i]; i++) {
        str[i] = tolower((unsigned char)str[i]);
    }
    return str;
}

// Helper function to calculate the minimum of two values
size_t min(size_t a, size_t b) {
    return (a < b) ? a : b;
}
