    public IActionResult UpdateResourceWithDirectory(int resourceId, [FromBody]XElement xmlPayload)
    {
        string directoryPath = Path.Combine(Environment.GetEnvironmentVariable("ParentDir"), xmlPayload.XPathSelectElement("//name").Value);
        if (!Directory.Exists(directoryPath))
        {
            Directory.CreateDirectory(directoryPath);
            Environment.SetEnvironmentVariable("CurrentDir", directoryPath);
        }
        else
        {
            Environment.SetEnvironmentVariable("CurrentDir", directoryPath);
        }

        return Ok(new Resource { Path = directoryPath });
    }

    [HttpDelete("api/resourcedirectory/{resourceId}")]
    public IActionResult DeleteResource(int resourceId)
    {
        string resourcePath = Environment.GetEnvironmentVariable("ParentDir");
        if (Directory.Delete(resourcePath, true))
        {
            Environment.SetEnvironmentVariable("CurrentDir", "default");
        }
        return Ok(new Resource { Path = "default" });
    }
}

public class Resource
{
    public string Path { get; set; }
}
