#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    float weight;
    char *string;
} record;

record* generateUserRecords(int n_offset_values, int n_keys, 
                            int n_weights, int n_strings, 
                            int max_records) {
    // Allocate and initialize arrays
    long* offsets = (long*)malloc(n_offset_values * sizeof(long));
    int* keys = (int*)malloc(n_keys * sizeof(int));
    float* weights = (float*)malloc(n_weights * sizeof(float));
    char** strings = (char**)malloc(n_strings * sizeof(char*));

    // Initialize arrays
    for (int i = 0; i < n_offset_values; i++) {
        offsets[i] = rand() % 100;
    }
    for (int i = 0; i < n_keys; i++) {
        keys[i] = rand() % 256;
    }
    for (int i = 0; i < n_weights; i++) {
        weights[i] = (float)rand() / RAND_MAX;
    }

    // Initialize strings
    for (int i = 0; i < n_strings; i++) {
        int str_len = rand() % 10 + 1;
        char* str = (char*)malloc(str_len * sizeof(char));
        for (int j = 0; j < str_len; j++) {
            str[j] = 'a' + rand() % 26;
        }
        strings[i] = str;
    }

    // Allocate and initialize records
    record* records = (record*)malloc(max_records * sizeof(record));
    for (int i = 0; i < max_records; i++) {
        records[i].offset = offsets[rand() % n_offset_values];
        records[i].key = keys[rand() % n_keys];
        records[i].weight = weights[rand() % n_weights];
        records[i].string = strings[rand() % n_strings];
    }

    // Deallocation
    for (int i = 0; i < n_strings; i++) {
        free(strings[i]);
    }
    free(strings);
    free(weights);
    free(keys);
    free(offsets);

    return records;
}
