} dataPoint;

void manageMemory(int matrixRows, int matrixCols, int numDataPoints) {
    // Allocate and initialize matrices
    double **matrix1 = (double **)malloc(matrixRows * sizeof(double *));
    for (int i = 0; i < matrixRows; i++) {
        matrix1[i] = (double *)malloc(matrixCols * sizeof(double));
    }

    char **matrix2 = (char **)malloc(matrixRows * sizeof(char *));
    for (int i = 0; i < matrixRows; i++) {
        matrix2[i] = (char *)malloc(matrixCols * sizeof(char));
    }

    // Allocate and initialize data points
    dataPoint *dataPoints = (dataPoint *)malloc(numDataPoints * sizeof(dataPoint));

    // Update data point values using linear transformation
    for (int i = 0; i < numDataPoints; i++) {
        int row = i / matrixCols;
