        double taxRate = rand() / (double)RAND_MAX * (taxRates[1] - taxRates[0]) + taxRates[0];
        double discountPercentage = rand() / (double)RAND_MAX * (discountPercentages[1] - discountPercentences[0]) + discountPercentences[0];

        // Calculate total order amount
        orders[i].amount = orderAmounts[i] * (1 - discountPercentage) * (1 + taxRate);

