        size_t totalMemoryUsage = sizeof(double) * numOrders + sizeof(char*) * numOrders + sizeof(struct tm) * numOrders + sizeof(product_category) * numOrders + sizeof(order) * numOrders;
        if (totalMemoryUsage > MAX_MEMORY_USAGE) {
