#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define HASH_TABLE_SIZE 1024
#define RECORD_FIELD_MAX 100
#define RECORD_FIELD_MIN 0

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    size_t size;
    size_t capacity;
    void** records;
    size_t* offsets;
    int* keys;
    pthread_cond_t cond;
} HashTable;

HashTable* hash_table_create(size_t initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = 0;
    table->capacity = initial_size;
    table->records = (void**)calloc(initial_size, sizeof(void*));
    table->offsets = (size_t*)calloc(initial_size, sizeof(size_t));
    table->keys = (int*)calloc(initial_size, sizeof(int));
    pthread_mutex_init(&table->mutex, NULL);
    pthread_cond_init(&table->cond, NULL);
    return table;
}

void hash_table_free(HashTable* table) {
    free(table->records);
    free(table->offsets);
    free(table->keys);
    pthread_mutex_destroy(&table->mutex);
    pthread_cond_destroy(&table->cond);
    free(table);
}

size_t hash_function(int key) {
    return key % HASH_TABLE_SIZE;
}

int main() {
    srand(time(NULL));
    HashTable* table = hash_table_create(HASH_TABLE_SIZE);

    size_t total_records = 0;

    while (total_records < MAX_RECORDS) {
        Record record;
        int key = rand() % INT_MAX;
        record.value = rand() % RECORD_FIELD_MAX + RECORD_FIELD_MIN;
        if (!insert_record(table, key, &record)) {
            break;
        }
        total_records++;
    }

    hash_table_free(table);

    return 0;
}
