<?php

function manageUserAccounts() {
    $data = $_POST;

    if (!isset($data['sub_action'])) {
        return json_encode(array('status' => 'error', 'message' => 'Invalid sub-action'));
    }

    switch ($data['sub_action']) {
        case 'create':
            createAccount($data);
            break;
        case 'update':
            updateAccount($data);
            break;
        case 'delete':
            deleteAccount($data);
            break;
        case 'get':
            getAccount($data);
            break;
        default:
            return json_encode(array('status' => 'error', 'message' => 'Invalid sub-action'));
    }
}

function createAccount($data) {
    if (!isset($data['name']) || strlen($data['name']) < 3) {
        return json_encode(array('status' => 'error', 'message' => 'Name must be at least 3 characters long'));
    }

    if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
        return json_encode(array('status' => 'error', 'message' => 'Invalid email format'));
    }

    if (strlen($data['password']) < 8) {
        return json_encode(array('status' => 'error', 'message' => 'Password must be at least 8 characters long'));
    }

    // Database operations
    $db = dbConnect();

    try {
        $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
        $stmt->execute(array(':name' => $data['name'], ':email' => $data['email'], ':password' => hash_password($data['password'])));

        // Environment management
        $dir = createDirectory();
        putenv('USER_ACCOUNTS_DIR=' . $dir);
    } catch (PDOException $e) {
        return json_encode(array('status' => 'error', 'message' => $e->getMessage()));
    }

    return json_encode(array('status' => 'success', 'message' => 'Account created successfully'));
}

function updateAccount($data) {
    // Database operations
    $db = dbConnect();

    try {
        $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
        $stmt->execute(array(':id' => $data['id'], ':name' => $data['name'], ':email' => $data['email'], ':password' => hash_password($data['password'])));
    } catch (PDOException $e) {
        return json_encode(array('status' => 'error', 'message' => $e->getMessage()));
    }

    return json_encode(array('status' => 'success', 'message' => 'Account updated successfully'));
}

function deleteAccount($data) {
    // Database operations
    $db = dbConnect();

    try {
        $stmt = $db->prepare("DELETE FROM users WHERE id = :id");
        $stmt->execute(array(':id' => $data['id']));

        // Environment management
        $dir = getEnvironmentVariable('USER_ACCOUNTS_DIR');
        if ($dir) {
            rmdir($dir);
        }
    } catch (PDOException $e) {
        return json_encode(array('status' => 'error', 'message' => $e->getMessage()));
    }

    return json_encode(array('status' => 'success', 'message' => 'Account deleted successfully'));
}

function getAccount($data) {
    // Database operations
    $db = dbConnect();

    try {
        $stmt = $db->prepare("SELECT * FROM users WHERE id = :id");
        $result = $stmt->execute(array(':id' => $data['id']));

        if ($row = $result->fetch()) {
            return json_encode(array('status' => 'success', 'message' => 'Account retrieved successfully', 'account' => $row));
        } else {
            return json_encode(array('status' => 'error', 'message' => 'Account not found'));
        }
    } catch (PDOException $e) {
        return json_encode(array('status' => 'error', 'message' => $e->getMessage()));
    }
}

