['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

#define MAX_PROFILES 1000
typedef struct {
    char *name;
    char *email;
    time_t birth_date;
} UserProfile;

UserProfile *profiles = NULL;
int profile_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_profile(char *name, char *email, time_t birth_date) {
    UserProfile *new_profile;
    pthread_mutex_lock(&mutex);
    if (profile_count >= MAX_PROFILES) {
        printf("Error: Maximum number of profiles reached.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_profile = malloc(sizeof(UserProfile));
    strcpy(new_profile->name, name);
    strcpy(new_profile->email, email);
    new_profile->birth_date = birth_date;
    if (profiles == NULL) {
        profiles = new_profile;
    } else {
        UserProfile *temp = profiles;
        while (temp != NULL) {
            temp = temp->next;
        }
        temp->next = new_profile;
    }
    profile_count++;
    pthread_mutex_unlock(&mutex);
}

void update_profile(char *email, char *name, time_t birth_date) {
    pthread_mutex_lock(&mutex);
    UserProfile *current = profiles;
    while (current != NULL) {
        if (strcmp(current->email, email) == 0) {
            strcpy(current->name, name);
            current->birth_date = birth_date;
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }
    printf("Error: Profile not found.\n");
    pthread_mutex_unlock(&mutex);
}

void get_profile(char *email) {
    pthread_mutex_lock(&mutex);
    UserProfile *current = profiles;
    while (current != NULL) {
        if (strcmp(current->email, email) == 0) {
            printf("Name: %s\nEmail: %s\nBirth Date: %ld\n", current->name, current->email, (long)current->birth_date);
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }
    printf("Error: Profile not found.\n");
    pthread_mutex_unlock(&mutex);
}

void export_profiles_to_json(char *filename) {
    json_object *json_profiles = json_object_new_object();
    pthread_mutex_lock(&mutex);
    UserProfile *current = profiles;
    while (current != NULL) {
        json_object *profile_obj = json_object_new_object();
        json_object_object_add(profile_obj, "name", json_string(current->name));
        json_object_object_add(profile_obj, "email", json_string(current->email));
        json_object_object_add(profile_obj, "birth_date", json_real((double)current->birth_date / 1000.0));
        json_object_array_add(json_profiles, "profiles", profile_obj);
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);

    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: Unable to open file for writing.\n");
        return;
    }
    json_object_to_file(fp, json_profiles);
    fclose(fp);
    json_object_free(json_profiles);
}

void free_profiles() {
    UserProfile *current = profiles;
    while (current != NULL) {
        UserProfile *next = current->next;
        free(current);
        current = next;
    }
    profiles = NULL;
    profile_count = 0;
}
