import java.util.concurrent.*;

public class ModularApplication {
    public static void main(String[] args) {
        // Batch processor configuration
        int batchSize = 100;
        long cacheClearIntervalMs = 5 * 60 * 1000; // Clear every 5 minutes

        // Service manager configuration
        int serviceStartDelayMs = 10 * 1000; // Start after 10 seconds
        int serviceStopDelayMs = 30 * 1000; // Stop after 30 seconds

        // Create the batch processor and service manager
        BatchProcessor batchProcessor = new BatchProcessor(batchSize);
        ServiceManager serviceManager = new ServiceManager(serviceStartDelayMs, serviceStopDelayMs);

        // Start the batch processor in a separate thread
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<?> batchProcessorFuture = executor.submit(batchProcessor::process);

        // Start the service manager in a separate thread
        executor.submit(() -> {
            while (true) {
                try {
                    Thread.sleep(serviceStartDelayMs);
                    serviceManager.startService();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
                try {
                    Thread.sleep(serviceStopDelayMs);
                    serviceManager.stopService();
                    // Publish notification to the event bus
                    EventBus.publish("service_stopped");
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        // Clear the cache periodically
        ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.scheduleAtFixedRate(() -> batchProcessor.clearCache(), 0, cacheClearIntervalMs / 1000, TimeUnit.MILLISECONDS);

        // Shut down the executor and event bus when the application is closed
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            executor.shutdownNow();
            scheduler.shutdownNow();
            EventBus.shutdown();
        }));
    }
}

