#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct {
    int integer;
    double precision;
    char* string;
} record_t;

record_t** records = NULL; // array of pointers to record structures
int num_records = 0; // number of allocated records

void update_record(int id, record_t* updated) {
    // find the record with matching ID
    for (int i = 0; i < num_records; i++) {
        if (records[i]->integer == id) {
            // update the record fields
            records[i]->integer = updated->integer;
            records[i]->precision = updated->precision;
            records[i]->string = updated->string;
            return;
        }
    }
}

record_t* get_record(int id) {
    // find the record with matching ID
    for (int i = 0; i < num_records; i++) {
        if (records[i]->integer == id) {
            return records[i];
        }
    }
    return NULL; // not found
}

void delete_record(int id) {
    // find the record with matching ID
    int idx = -1;
    for (int i = 0; i < num_records; i++) {
        if (records[i]->integer == id) {
            idx = i;
            break;
        }
    }
    if (idx != -1) {
        // remove the record and update the array
        free(records[idx]->string);
        free(records[idx]);
        memmove(&records[idx], &records[idx + 1], (num_records - idx - 1) * sizeof(record_t*));
        num_records--;
    }
}

void init_records() {
    if (!records) {
        // allocate initial records
        records = malloc(10 * sizeof(record_t**));
        for (int i = 0; i < 10; i++) {
            records[i] = malloc(sizeof(record_t));
            // initialize record fields with random values
            records[i]->integer = rand() % 100;
            records[i]->precision = (double)rand() / RAND_MAX;
            records[i]->string = malloc((rand() % 100) + 1);
            for (int j = 0; j < strlen(records[i]->string); j++) {
                records[i]->string[j] = 'a' + (rand() % 26);
            }
        }
    }
}

record_t* get_random_record() {
    int idx = rand() % num_records;
    return records[idx];
}
