void manage_memory(int num_offsets, int num_records, int max_value) {
    // Allocate and initialize arrays for offset values and keys
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    int* keys = (int*)malloc(num_offsets * sizeof(int));

    // Initialize arrays with zeros or default values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = 0;
        keys[i] = 0;
    }

    // Allocate and initialize array of record structures
    record* records = (record*)malloc(num_records * sizeof(record));

    // Initialize array with default values or zeros
    for (int i = 0; i < num_records; i++) {
        records[i].val = 0;
    }

    // Set random values in each record's int field
    for (int i = 0; i < num_records; i++) {
        records[i].val = rand() % max_value;
    }

    // Ensure total memory usage does not exceed predefined threshold
    size_t total_memory = sizeof(long) * num_offsets + sizeof(int) * num_offsets + sizeof(record) * num_records;
    if (total_memory > 1024*1024*10) { // adjust this value as needed
        // Dynamically adjust sizes of arrays and records to fit within the constraint
        num_offsets /= 2;
        num_records /= 2;
        offsets = realloc(offsets, sizeof(long) * num_offsets);
        keys = realloc(keys, sizeof(int) * num_offsets);
        records = realloc(records, sizeof(record) * num_records);
    }

    // Free allocated memory when the function is done
    free(offsets);
    free(keys);
    free(records);
}
