    for (int i = 0; i < size; i++) {
        records[i].key = rand() % 10000;
    }
    return records;
}

char* processDir(const char* dirPath, int maxRecs) {
    DIR* dir;
    struct dirent* ent;
    char path[1024], *newExt, *prevExt = NULL, *currExt;
    record* recs = initRecords(maxRecs);

    if ((dir = opendir(dirPath)) == NULL) {
        printf("Error opening directory: %s\n", dirPath);
        return NULL;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (ent->d_type != DT_REG) continue; // Only process files

        sprintf(path, "%s/%s", dirPath, ent->d_name);

        int nonNumChars = 0;
        char* p = ent->d_name;
        while (*p) {
            if (!isdigit(*p)) nonNumChars++;
            p++;
        }

        newExt = (char*)malloc((nonNumChars + 1) * sizeof(char));
        for (int i = 0; i < nonNumChars; i++) {
            newExt[i] = ent->d_name[i];
        }
        newExt[nonNumChars] = '\0';

        // Derive file type
        char* type = NULL;
        p = ent->d_name;
        while (*p) {
            if (!isalpha(*p)) continue; // Skip non-letter characters
            if (type == NULL) type = malloc(3 * sizeof(char));
            strcpy(type, "TXT");
            int i = 0;
            do {
                type[i++] = tolower(*p);
                p++;
            } while (*p && isalpha(*p));
            break;
        }
        if (!type[1]) free(type);

        // Normalize filename
        char* filename = (char*)malloc(strlen(ent->d_name) + 1 * sizeof(char));
        strcpy(filename, ent->d_name);
        p = filename;
        while (*p) {
            if (!isalnum(*p)) continue; // Skip non-alphanumeric characters
            p++;
        }
        *p = '\0';
        for (int i = 0; i < strlen(filename); i++) {
            if (!isalnum(filename[i])) break;
            filename[i] = tolower(filename[i]);
        }

        // Generate new extension
        currExt = malloc(strlen(newExt) + strlen(type) + 2 * sizeof(char));
        strcpy(currExt, newExt);
        strcat(currExt, type);

        if (prevExt) {
            char* prevNewExt = malloc(strlen(prevExt) + strlen(currExt) + 1 * sizeof(char));
            strcpy(prevNewExt, prevExt);
            strcat(prevNewExt, currExt);
            free(currExt);
            currExt = prevNewExt;
        } else currExt[0] = '\0';

        // Update records
        for (int i = 0; i < maxRecs; i++) {
            recs[i].key += i;
        }

        printf("Processed: %s\n", path);

        free(ent->d_name);
        free(newExt);
        free(type);
        free(filename);
        free(currExt);

        closedir(dir);
    }

    return currExt;
}

int main() {
    const char* dirPath = "/path/to/directory";
    int maxRecs = 1000;

    record* recs = initRecords(maxRecs);
    char* newExt = processDir(dirPath, maxRecs);

    printf("New extension: %s\n", newExt);

    // Add error handling and memory management for the list of filenames
    return 0;
}
