typedef struct {
    int *handles;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} connection_pool;

connection_pool* create_connection_pool(int initial_size) {
    connection_pool* pool = (connection_pool*)malloc(sizeof(connection_pool));
    pool->handles = (int*)calloc(initial_size, sizeof(int));
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void free_connection_pool(connection_pool* pool) {
    free(pool->handles);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}

int get_available_connection(connection_pool* pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        if (!pool->handles[i]) {
            return i;
        }
    }
    return -1;
}

void put_connection(connection_pool* pool, int connection_index) {
    pthread_mutex_lock(&pool->lock);
    pool->handles[connection_index] = 0;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
}

int get_connection(connection_pool* pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        if (!pool->handles[i]) {
            pool->handles[i] = 1;
            return i;
        }
    }
    return -1;
}

void release_connection(connection_pool* pool, int connection_index) {
    pthread_mutex_lock(&pool->lock);
    pool->handles[connection_index] = 0;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
}

