    if (total_memory_usage > 1024 * 1024 * 16) { // Threshold: 16MB
        // Dynamic adjustment of array sizes to fit within constraint
        int adjusted_size = (int)(size / 2.0);
        for (int i = 0; i < size; i++) {
            free(chars[i]);
        }
        free(chars);
        chars = (char**)realloc(chars, adjusted_size * sizeof(char*));
