// Function to manage dynamic memory allocation and initialization
int manage_memory(int offset_size, int key_size, int num_records, int max_value, int min_value) {
    // Allocate arrays for offsets and keys
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    // Allocate array of records
    record** records = allocate_records(num_records);

    // Set value of each record's int field to a random value within given range
    srand(time(NULL));  // Seed the random number generator efficiently
    for (int i = 0; i < num_records; i++) {
        records[i]->value = (rand() % (max_value - min_value + 1)) + min_value;
    }

    // Ensure total memory usage does not exceed predefined threshold
    if (offset_size * sizeof(long) + key_size * sizeof(int) + num_records * sizeof(record) > max_value) {
        // Dynamically adjust sizes of arrays and records to fit within constraint
        offset_size = max_value / sizeof(long);
        key_size = max_value / sizeof(int) - offset_size;
        num_records = (max_value - offset_size * sizeof(long) - key_size * sizeof(int)) / sizeof(record);

        // Reallocate arrays and records accordingly
        free(offsets);
        free(keys);
        offsets = (long*)malloc(num_records * sizeof(long));
        keys = (int*)malloc((num_records * 2) % max_value + num_records * sizeof(int));
        records = allocate_records(num_records);
    }

    // Deallocate memory when the function returns
    deallocate_node(NULL);  // NULL to avoid dangling pointer issues
    deallocate_records(records, num_records);

    return 0;
}
