    if (!offsets_file) return NULL;
    long* offsets = (long*)malloc(1000 * sizeof(long));  // Assume at most 1000 offsets
    int num_offsets = 0;
    while (fscanf(offsets_file, "%ld\n", &offsets[num_offsets]) == 1) {
        num_offsets++;
        if (num_offsets >= 1000) break;  // Stop reading when we reach the end of the file or our buffer is full
    }
    fclose(offsets_file);

    // Read unique 'int' keys from "keys.txt" and ensure they are unique within the allocated array
    FILE* keys_file = fopen("keys.txt", "r");
