#include <time.h>

typedef struct {
    int key;
    long offset;
} record_t;

record_t* generateRecords(int numRecords, int minKey, int maxKey, int minValue, int maxValue) {
    record_t *records = NULL;
    int *keys = NULL;
    long *offsets = NULL;

    srand(time(NULL)); // Seed the random number generator

    records = (record_t*)malloc(numRecords * sizeof(record_t));
    if (!records) {
        return NULL; // Handle allocation failure
    }

    keys = (int*)malloc(numRecords * sizeof(int));
    offsets = (long*)malloc(numRecords * sizeof(long));

    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
        records[i].offset = rand() % (maxValue - minValue + 1) + minValue;
    }

    free(keys);
    free(offsets);

    return records;
}
