Node* createSinglyLinkedList(int numNodes, const char* namespace) {
    Node** nodes = (Node**)malloc((numNodes + 1) * sizeof(Node*));
    nodes[0] = NULL; // sentinel node

    for (int i = 1; i <= numNodes; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));

        char id[256];
        sprintf(id, "%s-%d", namespace, i);
        node->identifier = strdup(id);

        node->timestamp = i;
        node->value = (double)i;

        nodes[i] = node;
    }

    return nodes;
}
