class SessionManager:
    def __init__(self, app):
        self.app = app
        self.session_interface = RedisSessionInterface(self.app)

    def get_session(self, request):
        return self.session_interface.open_session(request)

    def set_session(self, session_id, data):
        self.session_interface.save_session(session_id, data)

    def invalidate_session(self, session_id):
        self.session_interface.delete_session(session_id)

@app.before_request
def before_request():
    if 'session' in request:
        session = get_session(request)
        if session is None:
            return redirect(url_for('login'))
    else:
        session = SessionManager(app).get_session(request)
        if session is None:
            return redirect(url_for('login'))

@app.teardown_request
def teardown_request(exception):
    if 'session' in request:
        get_session(request).save()

if __name__ == '__main__':
    app.run(debug=True)

