        const fileContents = await getFileContent(filename);
        if (!fileContents) throw new Error(`File ${filename} not found`);
        const modifiedFilename = modifyExtension(filename, getModifiedExtension());
        await executeScript(modifiedFilename, fileContents);
        this.successfulExecutions++;
        return;
