// domTraverser.js
class DomTraverser {
  constructor(options = {}) {
    this.options = options;
    this.rootNode = null;
    this.traversalQueue = [];
    this.eventListeners = {};
    this.debounceTimeout = null;
  }

  traverse(rootNode) {
    this.rootNode = rootNode;
    this.traversalQueue.push({ node: rootNode, depth: 0 });
    while (this.traversalQueue.length > 0) {
      const current = this.traversalQueue.pop();
      if (current.node) {
        // apply filtering condition
        if (!this.applyFilter(current.node)) continue;

        // process the node
        this.processNode(current);

        // enqueue child nodes
        for (let i = 0; i < current.node.children.length; i++) {
          const child = current.node.children[i];
          this.traversalQueue.push({ node: child, depth: current.depth + 1 });
        }
      }
    }
  }

  applyFilter(node) {
    if (!this.options.filterCondition) return true;

    // implement custom filtering logic here
    // for example:
    if (node.classList.contains(this.options.filterCondition.className)) {
      return true;
    } else if (node.id === this.options.filterCondition.id) {
      return true;
    } else if (node.getAttribute(this.options.filterCondition.attributeName)) {
      return true;
    } else if (this.options.filterCondition.customProperty in node.dataset) {
      return true;
    }
    return false;
  }

  processNode(current) {
    // implement custom processing logic here
    // for example:
    const newNode = current.node.cloneNode(true);
    newNode.textContent = `Processed Node: ${current.node.nodeName}`;
    current.node.parentNode.replaceChild(newNode, current.node);
  }

  on(eventType, listener) {
    if (!this.eventListeners[eventType]) this.eventListeners[eventType] = [];
    this.eventListeners[eventType].push(listener);
  }

  off(eventType, listener) {
    if (this.eventListeners[eventType]) {
      const index = this.eventListeners[eventType].indexOf(listener);
      if (index >= 0) this.eventListeners[eventType].splice(index, 1);
    }
  }

  trigger(eventType, ...args) {
    if (this.eventListeners[eventType]) {
      for (let i = 0; i < this.eventListeners[eventType].length; i++) {
        this.eventListeners[eventType][i](...args);
      }
    }
  }

  debounce(func, delay) {
    let timeoutId;
    return (...args) => {
      if (timeoutId) clearTimeout(timeoutId);
      timeoutId = setTimeout(() => func.apply(this, args), delay);
    };
  }

  throttle(func, delay) {
    let lastCallTime;
    return (...args) => {
      const currentTime = Date.now();
      if (!lastCallTime || currentTime - lastCallTime >= delay) {
        func.apply(this, args);
        lastCallTime = currentTime;
      }
    };
  }

  pauseTraversal() {
    this.traversalQueue = [];
  }

  resumeTraversal() {
    this.traversalQueue.forEach((node) => node.node && this.traversalQueue.push(node));
  }
}
