#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    char* data;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t num_records;
} manager;

manager* manage_memory(size_t size) {
    manager* manager = (manager*)malloc(sizeof(manager));
    if (!manager) return NULL; // Out of memory

    manager->offsets = (long*)malloc(sizeof(long) * size);
    if (!manager->offsets) {
        free(manager);
        return NULL;
    }

    manager->keys = (int*)malloc(sizeof(int) * size);
    if (!manager->keys) {
        free((void*)manager->offsets);
        manager->offsets = NULL;
        return NULL;
    }

    manager->records = (record**)malloc(sizeof(record*) * size);
    if (!manager->records) {
        free((void*)manager->offsets);
        free((void*)manager->keys);
        manager->offsets = NULL;
        manager->keys = NULL;
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        manager->offsets[i] = i;
        manager->keys[i] = i + 1;

        record* record = (record*)malloc(sizeof(record));
        if (!record) {
            free((void*)manager->records);
            for (size_t j = 0; j < i; ++j) {
                free((void*)manager->records[j]->data);
                free((void*)manager->records[j]);
            }
            free((void*)manager->offsets);
            free((void*)manager->keys);
            manager->offsets = NULL;
            manager->keys = NULL;
            return NULL;
        }

        record->offset = i;
        record->key = i + 1;

        char* data = (char*)malloc(257); // 256 bytes for data and null terminator
        if (!data) {
            free((void*)record);
            free((void*)manager->records);
            for (size_t j = 0; j < i; ++j) {
                free((void*)manager->records[j]->data);
                free((void*)manager->records[j]);
            }
            free((void*)manager->offsets);
            free((void*)manager->keys);
            manager->offsets = NULL;
            manager->keys = NULL;
            return NULL;
        }

        sprintf(data, "record_%ld", i);

        record->data = data;

        manager->records[i] = record;
    }

    manager->num_records = size;

    return manager;
}

