['Here is a C function that manages memory for a doubly linked list:

```c
#include <stdlib.h>
#include <stdio.h>

typedef struct Node {
    int key;
    void* data;
    struct Node* next;
    struct Node* prev;
} node;

node* create_node(int key, void* data) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return NULL;
    new_node->key = key;
    new_node->data = data;
    new_node->next = new_node->prev = NULL;
    return new_node;
}

void insert_node(node** head, int key, void* data) {
    node* new_node = create_node(key, data);
    if (!new_node) return;

    if (*head == NULL || key < (*head)->key) {
        // Insert at the beginning
        new_node->next = *head;
        if (*head) (*head)->prev = new_node;
        *head = new_node;
    } else {
        node* current = *head;
        while (current && current->next && key > current->next->key)
            current = current->next;

        // Insert after the found node
        new_node->prev = current;
        new_node->next = current->next;
        if (current) current->next = new_node;
        else *head = new_node;
    }
}

void print_list(node* head, int direction) {
    node* current = head;
    while (current) {
        printf("Key: %d, Data: %p\n", current->key, current->data);
        if (direction == 0) { // Forward
            current = current->next;
        } else { // Reverse
            current = current->prev;
        }
    }
}

void free_list(node** head) {
    node* current = *head;
    while (current) {
        node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
