    logger* logger = (logger*)malloc(sizeof(logger));
    if (!logger) return NULL; // Memory allocation failed

    logger->values = (double*)malloc(size * sizeof(double));
    if (!logger->values) {
        free(logger);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        logger->values[i] = (i + 1.0) * 0.1;
    }

    logger->measurements = (measurement*)malloc(size * sizeof(measurement));
    if (!logger->measurements) {
        free(logger->values);
        free(logger);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        measurement* measurement = &logger->measurements[i];
        measurement->timestamp = time(NULL);
        measurement->value = logger->values[i];

        char buffer[64];
        sprintf(buffer, "Value: %.1f, Timestamp: %d", measurement->value, (int)measurement->timestamp);
        measurement->name = (char*)malloc(strlen(buffer) + 1);
        strcpy(measurement->name, buffer);
    }

    logger->size = size;
    return logger;
