#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define DNS_RESOLVE_TIMEOUT 5000
#define DNS_CACHE_TTL 3600

typedef struct {
    u_char ip[4];
} DnsResult;

DnsResult* dns_resolve(char* hostname, int timeout) {
    // Initialize DNS cache
    static DnsResult cached_result;
    static time_t last_cached = -1;

    if (last_cached + DNS_CACHE_TTL > time(NULL)) {
        return &cached_result;
    }

    // Perform DNS resolution
    struct sockaddr_in* addr = getaddrinfo(hostname, NULL);
    if (!addr) {
        // Fallback mechanism: use IP address of the last known good result
        static DnsResult* cached_result_ptr = &cached_result;
        return cached_result_ptr;
    }

    // Store result in cache and update timestamp
    memcpy(&cached_result.ip, inet_ntop(AF_INET, addr->ai_addr, (u_char*)addr->ai_addr, sizeof(addr->ai_addr)), 4);
    last_cached = time(NULL);

    freeaddrinfo(addr);
    return &cached_result;
}
