// Initialize a circularly linked list of NFAPI_RRC_CTXT_CBACK_T structures
void init_rrc_ctxt_list(NFAPI_RRC_CTXT_CBACK_T** list, size_t n) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    for (size_t i = 0; i < n; ++i) {
        NFAPI_RRC_CTXT_CBACK_T* node = malloc(sizeof(NFAPI_RRC_CTXT_CBACK_T));
        if (!node) {
            perror("Memory allocation failed");
            return;
        }

        // Ensure each CELL_ID is unique within the list
        while (1) {
            node->cell_id = rand() % 1000000; // or use a better random number generator
            bool cell_id_unique = true;
            for (size_t j = 0; j < i; ++j) {
                if (node->cell_id == list[j]->cell_id) {
                    cell_id_unique = false;
                    break;
                }
            }
            if (cell_id_unique)
                break;
        }

        node->pci = rand() % 100;
        node->rru_id = rand() % 100;

        // Dynamically allocate configuration settings
        node->config_settings = malloc(sizeof(int) * 10);
        if (!node->config_settings) {
            free(node);
            perror("Memory allocation failed");
            return;
        }

        // Insert the new node at the head of the list
        node->next = *list;
        *list = node;

        // Update the lock granularity to maintain performance under heavy load
        if (i % LOCK_GRANULARITY == 0) {
            pthread_mutex_unlock(&lock);
            pthread_cond_signal(&cond);
            pthread_mutex_lock(&lock);
        }
    }

    pthread_mutex_unlock(&lock);

    // Implement adaptive algorithms for dynamic memory pool size adjustment
    // Use caching strategies to minimize repeated memory access and improve lookup times
}

// Insert a new node at the head or tail of the list while maintaining order of unique CELL_IDs
void insert_node(NFAPI_RRC_CTXT_CBACK_T** list, NFAPI_RRC_CTXT_CBACK_T* node, bool is_head_insertion) {
    pthread_mutex_lock(&lock);
    if (is_head_insertion)
        node->next = *list;
    else {
        NFAPI_RRC_CTXT_CBACK_T* current = *list;
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&lock);
}

