class OctreeNode {
public:
    OctreeNode(size_t capacity) : data(new float[capacity]), count(0) {}

    ~OctreeNode() { delete[] data; }

    size_t capacity;
    std::unique_ptr<float[]> data;
    size_t count;

    void add(float value) {
        if (count < capacity) {
            data[count] = value;
            ++count;
        }
    }

    void clear() {
        count = 0;
    }
};

class Octree {
public:
    Octree(size_t featureSize, size_t numInitialLeafNodes, size_t maxDataCapacity, bool isThreadSafe = false)
        : root(new OctreeNode(numInitialLeafNodes)), maxCapacity(maxDataCapacity), threadSafe(isThreadSafe) {
        for (size_t i = 0; i < numInitialLeafNodes; ++i) {
            addLeafNode();
        }
    }

    ~Octree() { delete root; }

    void add(float value) {
        if (threadSafe) {
            std::lock_guard<std::mutex> lock(mutex);
            addRecursive(root.get(), value, 0);
        } else {
            addRecursive(root.get(), value, 0);
        }
    }

    void clear() {
        root->clear();
    }

private:
    void addRecursive(OctreeNode* node, float value, size_t depth) {
        if (node->count < node->capacity && node->count > 0) {
            for (size_t i = 0; i < 8; ++i) {
                size_t childIndex = (value >> (depth * 3)) & 7;
                if (childIndex >= node->data.size()) {
                    addLeafNode();
                }
                addRecursive(&node->data[childIndex], value, depth + 1);
            }
        } else {
            // Node is full or empty, so add a new leaf node
            addLeafNode();
            addRecursive(node, value, depth + 1);
        }
    }

