record_t* initializeRecords(int numRecords) {
    if (numRecords > 10000) {
        return NULL; // error: maximum limit exceeded
    }

    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));
    if (!records) {
        return NULL; // memory allocation failure
    }

    srand(time(NULL)); // initialize random number generator

    for (int i = 0; i < numRecords; i++) {
        records[i].offset = i;
        records[i].key = rand() % 100; // generate random key
        records[i].value = rand() % 100; // generate random value

        // allocate memory for offset and key pointers
        records[i].offset_ptr = (long*)malloc(sizeof(long));
        *records[i].offset_ptr = i;
        records[i].key_ptr = (int*)malloc(sizeof(int));
        *records[i].key_ptr = records[i].key;

        if (!records[i].offset_ptr || !records[i].key_ptr) {
            // handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(records[j].offset_ptr);
                free(records[j].key_ptr);
            }
            free(records);
            return NULL;
        }
    }

    return records;
}

void addRecord(record_t** records, int* numRecords) {
    if (*numRecords >= 10000) {
        // error: maximum limit exceeded
    }

    record_t* newRecord = (record_t*)malloc(sizeof(record_t));
    if (!newRecord) {
        // memory allocation failure
    }

    newRecord->offset = *numRecords;
    newRecord->key = rand() % 100; // generate random key
    newRecord->value = rand() % 100; // generate random value

    // allocate memory for offset and key pointers
    newRecord->offset_ptr = (long*)malloc(sizeof(long));
    *newRecord->offset_ptr = *numRecords;
    newRecord->key_ptr = (int*)malloc(sizeof(int));
    *newRecord->key_ptr = newRecord->key;

    if (!newRecord->offset_ptr || !newRecord->key_ptr) {
        // handle memory allocation failure
        free(newRecord);
        return;
    }

    (*records) = realloc(*records, (*numRecords + 1) * sizeof(record_t));
    (*records)[*numRecords] = *newRecord;

    free(newRecord);

    (*numRecords)++;
}

int getRecordValue(const record_t* record) {
    if (!record) {
        // error: invalid record
    }

    return record->value;
}

void serializeRecord(const record_t* record, char* buffer) {
    if (!record || !buffer) {
        // error: invalid record or buffer
    }

    sprintf(buffer, "{\"offset\":%ld,\"key\":%d,\"value\":%d}", record->offset, record->key, record->value);
}

void deserializeRecord(record_t* record, const char* buffer) {
    if (!record || !buffer) {
        // error: invalid record or buffer
    }

    sscanf(buffer, "{\"offset\":%ld,\"key\":%d,\"value\":%d}", &record->offset, &record->key, &record->value);
