typedef struct {
    char* str;
    int val;
} node;

node** create_nodes(int num_nodes) {
    node** nodes = (node**)malloc(num_nodes * sizeof(node*));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = (node*)malloc(sizeof(node));
        nodes[i]->str = NULL;
        nodes[i]->val = 0;
    }
    return nodes;
}

void free_nodes(node** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        if (nodes[i]->str != NULL)
            free(nodes[i]->str);
        free(nodes[i]);
    }
    free(nodes);
}

int hash_function(void* key, int table_size) {
    // implement a simple hash function
    return ((char*)key)[0] % table_size;
}

void insert_hash_table(node** nodes, node* new_node, int table_size) {
    int index = hash_function(&new_node->str[0], table_size);
    while (nodes[index] != NULL) {
        index = (index + 1) % table_size;
    }
    nodes[index] = new_node;
}

node* search_hash_table(node** nodes, char* target_str, int table_size) {
    int index = hash_function(target_str, table_size);
    while (nodes[index] != NULL && strcmp(nodes[index]->str, target_str) != 0) {
        index = (index + 1) % table_size;
    }
    return nodes[index];
}

void gc_nodes(node** nodes, int num_nodes) {
    // implement a simple garbage collector
    for (int i = 0; i < num_nodes; i++) {
        if (nodes[i]->str == NULL || strcmp(nodes[i]->str, "") == 0)
            free_nodes(&nodes[i], 1);
    }
}

void trim_memory(node** nodes, int* num_nodes) {
    int max_size = *num_nodes;
    for (int i = 0; i < max_size; i++) {
        if (nodes[i]->str == NULL || strcmp(nodes[i]->str, "") == 0)
            free(nodes[i]);
    }
    *num_nodes = max_size / 2; // dynamically adjust the size
}

void handle_error(char* message) {
    printf("Error: %s\n", message);
    exit(1);
}

int main() {
    int num_nodes = 10;
    node** nodes = create_nodes(num_nodes);

    // use the hash table, insert, search and gc

    trim_memory(nodes, &num_nodes);
    free_nodes(nodes, *num_nodes);

    return 0;
}
