#define MEMORY_THRESHOLD 1024*1024*10 // 10 MB
#define MAX_RECORDS 1000
#define OFFSET_ARRAY_SIZE 256
#define KEY_ARRAY_SIZE 256

typedef struct {
    int key;
} record_t;

void* dynamic_memory_allocation(int size, char type) {
    void* ptr = NULL;
    if (type == 'o') { // Offset array
        ptr = realloc(ptr, sizeof(long) * OFFSET_ARRAY_SIZE);
        for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
            ((long*)ptr)[i] = i;
        }
    } else if (type == 'k') { // Key array
        ptr = realloc(ptr, sizeof(int) * KEY_ARRAY_SIZE);
        for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
            ((int*)ptr)[i] = i;
        }
    } else if (type == 'r') { // Record array
        ptr = realloc(ptr, sizeof(record_t) * MAX_RECORDS);
        for (int i = 0; i < MAX_RECORDS; i++) {
            ((record_t*)ptr)[i].key = i;
        }
    }
    return ptr;
}

void* manage_memory(int offset_size, int key_size, int record_count) {
    void* mem_ptr = NULL;

    // Allocate and initialize offset array
    mem_ptr = dynamic_memory_allocation(offset_size, 'o');
    if (!mem_ptr) {
        printf("Offset array allocation failed.\n");
        return NULL;
    }

    // Allocate and initialize key array
    mem_ptr = dynamic_memory_allocation(key_size, 'k');
    if (!mem_ptr) {
        printf("Key array allocation failed.\n");
        free(mem_ptr);
        return NULL;
    }

    // Initialize record array
    mem_ptr = dynamic_memory_allocation(record_count, 'r');
    if (!mem_ptr) {
        printf("Record array allocation failed.\n");
        free(mem_ptr);
        return NULL;
    }

    return mem_ptr;
}

int main() {
    int offset_size = 256;
    int key_size = 256;
    int record_count = 1000;

    void* memory_ptr = manage_memory(offset_size, key_size, record_count);

    if (!memory_ptr) {
        printf("Memory allocation failed.\n");
    } else {
        printf("Memory allocated successfully.\n");
        free(memory_ptr);
    }

    return 0;
}
