// Function to manage dynamic memory allocation and initialization for the custom data structure
void* init_pipeline(int num_nodes, int max_memory) {
    // Initialize an array of node structures with the specified number of nodes
    Node** nodes = (Node**)malloc(num_nodes * sizeof(Node*));

    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = malloc(sizeof(Node));
        nodes[i]->next = NULL;
    }

    // Initialize an external library to manage dynamic memory pools
    void* pool = init_memory_pool(max_memory);

    return (void*)nodes;
}

// Function to insert a new node into the linked list, reusing existing nodes whenever possible
void insert_node(void* pipeline, Node* new_node) {
    // Traverse the linked list and find an existing node with available space
    Node** nodes = (Node**)pipeline;
    for (int i = 0; i < num_nodes; i++) {
        if (nodes[i]->next == NULL) {
            nodes[i]->next = new_node;
            break;
        }
    }
}

// Function to delete a node from the linked list, reusing freed memory whenever possible
void delete_node(void* pipeline, Node* node_to_delete) {
    // Traverse the linked list and find the node to be deleted
    Node** nodes = (Node**)pipeline;
    for (int i = 0; i < num_nodes; i++) {
        if (nodes[i]->next == node_to_delete) {
            nodes[i]->next = node_to_delete->next;
            break;
        }
    }

    // Free the deleted node and add it to a cache for reuse
    free(node_to_delete);
}

// Function to safely traverse and manipulate cyclic structures without causing infinite loops
void traverse_pipeline(void* pipeline) {
    Node** nodes = (Node**)pipeline;
    for (int i = 0; i < num_nodes; i++) {
        // Traverse the linked list while avoiding cycles
        Node* current = nodes[i];
        do {
            current = current->next;
        } while (current != nodes[i]);
    }
}

// Function to deallocate all allocated memory when the function returns, ensuring no memory leaks occur
void clean_up(void* pipeline) {
    // Deallocate all node structures and cache any freed memory for reuse
    Node** nodes = (Node**)pipeline;
    for (int i = 0; i < num_nodes; i++) {
        free(nodes[i]);
    }

    // Clean up the external library and deallocate any managed memory pools
    clean_up_memory_pool(pool);
}

