    while (1) {
        if ((size_t)(offsets[0] + keys[0]) > 1024 * 1024 * 64) { // Check for threshold
            printf("Memory usage exceeds threshold, adjusting sizes...\n");

            // Adjust array sizes to fit within the constraint
            offsets = realloc(offsets, sizeof(long*) * (size_t)(offsets[0] + keys[0]));
            keys = realloc(keys, sizeof(int) * (size_t)(offsets[0] + keys[0]));

            // Re-size record array
            for (int i = 0; i < num_records; i++) {
                records[i] = realloc(records[i], record_size);
            }
