void insert_node(node** head, int key, long offset) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->key = key;
    new_node->offset = offset;
    new_node->record = NULL;
    new_node->next = *head;
    *head = new_node;
}

void delete_node(node** head, int key) {
    node* current = *head;
    node* previous = NULL;
    while (current && current->key != key) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) return;
    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

void deallocate_nodes(node* head) {
    node* current = head;
    while (current != NULL) {
        node* next = current->next;
        free(current);
        current = next;
    }
}
