#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define a record structure with an int value and a pointer to a long key
typedef struct {
    int val;
    long* key;
} Record;

// Define the shared memory pool structure, including a hash map for fast lookups
typedef struct {
    Record** records;
    size_t capacity;
    pthread_mutex_t lock; // Thread-safe mutex for concurrent access
    pthread_hash_t* hashmap; // Hash map for fast record lookups
} SharedMemoryPool;

// Initialize the shared memory pool with a given initial capacity and hash map
SharedMemoryPool* init_shared_memory_pool(size_t initial_capacity, pthread_hash_t* hashmap) {
    SharedMemoryPool* pool = (SharedMemoryPool*)malloc(sizeof(SharedMemoryPool));
    pool->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);
    pool->hashmap = hashmap;
    return pool;
}

// Allocate and initialize a new record in the shared memory pool
void* allocate_record(SharedMemoryPool* pool) {
    Record** records = pool->records;
    size_t capacity = pool->capacity;

    // Check if the current capacity needs to be increased
    if (capacity >= (size_t)1 << 31) {
        // Re-allocate with a larger capacity, keeping existing records intact
        pool->records = (Record**)realloc(pool->records, ((size_t)1 << 32) * sizeof(Record*));
        pool->capacity = (size_t)1 << 32;
    }

    // Find the next available slot in the array and allocate a new record
    size_t i;
    for (i = 0; i < capacity; ++i) {
        if (!records[i]) break;
    }
    records[i] = (Record*)malloc(sizeof(Record));
    return records[i];
}

// Add a new record to the shared memory pool with a given key and value
void add_record_to_pool(SharedMemoryPool* pool, long key, int val) {
    Record** records = pool->records;
    pthread_hash_t* hashmap = pool->hashmap;

    // Find an available slot in the array or reallocate if necessary
    size_t i;
    for (i = 0; i < pool->capacity; ++i) {
        if (!records[i]) break;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->val = val;
    record->key = (long*)malloc(sizeof(long));

    // Insert the new record into the hash map
    pthread_hash_insert(hashmap, key, (void*)record);

    // Update the array with the new record and notify any waiting threads
    records[i] = record;
}

// Find a record by its key in the shared memory pool
Record* find_record_by_key(SharedMemoryPool* pool, long key) {
    pthread_hash_t* hashmap = pool->hashmap;

    // Perform a fast lookup in the hash map
    void* record_ptr = pthread_hash_search(hashmap, &key);
    if (record_ptr == NULL) return NULL; // Key not found

    Record* record = (Record*)record_ptr;
    return record;
}

// Free all allocated memory and resources when exiting the function
void exit_shared_memory_pool(SharedMemoryPool* pool) {
    Record** records = pool->records;

    // Release memory for each record
    size_t i;
    for (i = 0; i < pool->capacity; ++i) {
        if (!records[i]) continue;
        free(records[i]->key);
        free(records[i]);
    }

    // Free the hash map and its resources
    pthread_hash_destroy(pool->hashmap);

    // Release memory for the records array
    free(pool->records);

    // Clean up any remaining locks and resources
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
