Record** createRecords(int numRecords) {
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = NULL;
        records[i]->offset = -1;
        records[i]->key = -1;
        records[i]->access_count = 0;
    }
    return records;
}

void initRecords(long* offsets, int* keys, Record** records, int numOffsets, int numKeys) {
    for (int i = 0; i < numOffsets; i++) {
        records[i]->offset = offsets[i];
    }
    for (int i = 0; i < numKeys; i++) {
        for (int j = 0; j < numRecords; j++) {
            if (keys[i] == records[j]->key) {
                printf("Error: duplicate key found.\n");
                exit(1);
            }
        }
        records[i % numRecords]->key = keys[i];
    }
}

void setRecordValue(int key, int value, Record** records) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->key == key) {
            records[i]->value = (int*)malloc(sizeof(int));
            *records[i]->value = value;
            break;
        }
    }
}

void updateRecordValue(int key, int newValue, Record** records) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->key == key) {
            *records[i]->value = newValue;
            break;
        }
    }
}

long getRecordOffset(int key, Record** records) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->key == key) {
            return records[i]->offset;
        }
    }
    printf("Error: record not found.\n");
    exit(1);
}

void freeRecords(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->value != NULL) {
            free(records[i]->value);
        }
        free(records[i]);
    }
    free(records);
}
