#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    PENDING,
    RUNNING,
    COMPLETED
} status_t;

typedef struct task {
    int task_id;
    status_t status;
    char* description;
} task_t;

task_t* task_list = NULL;
size_t task_count = 0;

void add_task(int id, const char* desc) {
    task_t* new_task = (task_t*)malloc(sizeof(task_t));
    if (!new_task) return; // handle memory allocation failure
    new_task->task_id = id;
    new_task->status = PENDING;
    size_t len = strlen(desc);
    new_task->description = malloc(len + 1); // +1 for null-terminator
    if (!new_task->description) {
        free(new_task);
        return; // handle memory allocation failure
    }
    memcpy(new_task->description, desc, len);
    task_list = realloc(task_list, (task_count + 1) * sizeof(task_t));
    task_list[task_count++] = new_task;
}

void update_task_status(int id, status_t new_status) {
    for (size_t i = 0; i < task_count; i++) {
        if (task_list[i]->task_id == id) {
            task_list[i]->status = new_status;
            return;
        }
    }
}

void delete_task(int id) {
    for (size_t i = 0; i < task_count; i++) {
        if (task_list[i]->task_id == id) {
            free(task_list[i]->description);
            free(task_list[i]);
            task_list = realloc(task_list, --task_count * sizeof(task_t));
            return;
        }
    }
}

void cleanup_tasks() {
    for (size_t i = 0; i < task_count; i++) {
        if (task_list[i]->status == COMPLETED) {
            free(task_list[i]->description);
            free(task_list[i]);
            task_list = realloc(task_list, --task_count * sizeof(task_t));
        }
    }
}

void print_tasks() {
    for (size_t i = 0; i < task_count; i++) {
        printf("Task ID: %d, Status: %s, Description: %s\n",
               task_list[i]->task_id,
               task_list[i]->status == PENDING ? "Pending" :
               task_list[i]->status == RUNNING ? "Running" : "Completed",
               task_list[i]->description);
    }
}

void* thread_task(void* arg) {
    int tid = *(int*)arg;
    // perform some thread-specific task processing
    printf("Thread %d: Task processing completed.\n", tid);
    return NULL;
}

pthread_t create_thread(int id) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, thread_task, &id)) {
        perror("pthread_create");
        return (pthread_t){0}; // or handle the error
    }
    return thread;
}
