    // Validate input parameters
    if (numRows <= 0 || numCols <= 0 || count <= 0) {
        printf("Invalid parameter values. Aborting.\n");
        return;
    }

    // Allocate memory for matrices and data point array
    double** floatMatrix = malloc(numRows * sizeof(double*));
    char** charMatrix = malloc(numRows * sizeof(char*));
    dataPoint* dataPoints = malloc(count * sizeof(dataPoint));

    // Initialize matrices with zeros
    for (int i = 0; i < numRows; i++) {
        floatMatrix[i] = malloc(numCols * sizeof(double));
        charMatrix[i] = malloc(numCols * sizeof(char));
        memset(floatMatrix[i], 0, numCols * sizeof(double));
        memset(charMatrix[i], '\0', numCols * sizeof(char));
    }

    // Initialize data point array
    for (int i = 0; i < count; i++) {
        dataPoints[i].value = 0.0;
        dataPoints[i].identifier = '\0';
    }

    // Perform linear transformation on data points and update values
    for (int i = 0; i < count; i++) {
        int row = i / numCols;
        int col = i % numCols;
        double newValue = performLinearTransformation(row, col);
        if (newValue > MIN_VALUE && newValue < MAX_VALUE) {
            dataPoints[i].value = newValue;
        } else {
            printf("Value out of range. Adjusting.\n");
            // Handle value outside specified range
        }
    }

    // Deallocate memory upon return
    for (int i = 0; i < numRows; i++) {
        free(floatMatrix[i]);
        free(charMatrix[i]);
    }
    free(floatMatrix);
    free(charMatrix);
    free(dataPoints);
}
