ServiceClass* initializeService() {
    // Initialize a service class instance
    ServiceClass* service = (ServiceClass*) malloc(sizeof(ServiceClass));

    // Set up the service class for caching and concurrency control
    service->cache = initializeCache();
    service->mutex = pthread_mutex_init(NULL, NULL);

    return service;
}

