bool updateElementContent(ServiceClass* service, int pageSectionID, int elementID, char* htmlContent) {
    // Lock the mutex for concurrency control
    pthread_mutex_lock(service->mutex);

    // Check if the element is already cached
    ElementCacheEntry* entry = getServiceCacheEntry(service, pageSectionID, elementID);

    if (entry != NULL) {
        // Update the cached content if it's outdated or missing
        if (!isContentUpToDate(entry, htmlContent)) {
