    }

    // Define a custom random number generator using the RANDU library
    srand(time(NULL));  // Seed the random number generator

    // Allocate memory for a random number generator state
    int* rand_state = (int*)malloc(sizeof(int));
    *rand_state = 12345;  // Initialize the random number generator state

    // Define a function to generate random numbers using RANDU library
    int gen_rand(int min, int max) {
        int val;
        for (int i = 0; i < 4; i++) {
            val += ((rand_state[0] >> (i & 3)) & 1) << i;
            rand_state[0] >>= 1;
            if (!rand_state[0]) {
                rand_state[0] = *rand() | 0x80000000;
            }
        }
        return val % (max - min + 1) + min;
    }

    // Define a function to evaluate the quality of generated random numbers
    void eval_rand_quality(int num_samples, int min_val, int max_val) {
