#include <forward_list>
#include <string>
#include <algorithm>

void insertStringAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = list.begin();
    while (it != list.end()) {
        if (it->compare(target) == 0) {
            // found the target string
            list.insert_after(it++, insertion);
            return;
        }
        ++it;
    }
    // not found, insert at the end of the list
    list.insert_after(list.end(), insertion);
}
