    // Allocate and initialize arrays for offset values and keys
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    // Initialize the memory pool
    void* pool = malloc(1024);  // Initial pool size is 1KB

