    srand(time(NULL));  // Set the seed value

    // Use a loop to set the value of each record's int field to a random value
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;  // Generate a random integer between 0 and 99
    }

    // Monitor memory usage and adjust sizes if necessary
    size_t total_memory_usage = sizeof(long) * offset_size + sizeof(int) * key_size + sizeof(record_t) * num_records;
    if (total_memory_usage > 1024 * 1024 * 10) {  // Threshold is set to 10MB
        // Adjust sizes dynamically to fit within the constraint
        offset_size /= 2;  // Reduce the size of the offset array by half
        key_size /= 2;  // Reduce the size of the key array by half
        num_records /= 2;  // Reduce the number of records by half

        // Reallocate memory and reinitialize arrays
        free(offsets);
        offsets = (long*)malloc(offset_size * sizeof(long));
        for (int i = 0; i < offset_size; i++) {
            offsets[i] = -1;
        }

        free(keys);
        keys = (int*)malloc(key_size * sizeof(int));
        for (int i = 0; i < key_size; i++) {
            keys[i] = -1;
        }

        free(records);
        records = (record_t*)malloc(num_records * sizeof(record_t));
        for (int i = 0; i < num_records; i++) {
            records[i].value = -1;
        }
    }

    return pool;  // Return the memory pool
}
