// Define the maximum number of records
#define MAX_RECORDS 1000

// Define the maximum size for each record's int field
#define RECORD_INT_MAX 10000

// Define the maximum random number range
#define RANDOM_RANGE 100000

// Define the threshold for total memory usage
#define MEMORY_THRESHOLD (1024 * 1024) // 1MB

typedef struct {
    int value;
} Record;

void* my_malloc(size_t size) {
    return malloc(size);
}

void my_free(void* ptr) {
    free(ptr);
}

void manage_memory(int num_records, int** offsets, int** keys, Record** records) {
    size_t total_size = sizeof(long) * num_records + sizeof(int) * num_records + sizeof(Record) * num_records;
    while (total_size > MEMORY_THRESHOLD && num_records > 0) {
        // Resize arrays
        long* new_offsets = my_malloc(sizeof(long) * (num_records / 2));
        int* new_keys = my_malloc(sizeof(int) * (num_records / 2));
        Record* new_records = my_malloc(sizeof(Record) * (num_records / 2));

        // Copy existing data to new arrays
        memcpy(new_offsets, *offsets, sizeof(long) * (num_records / 2));
        memcpy(new_keys, *keys, sizeof(int) * (num_records / 2));
        for (int i = 0; i < num_records / 2; i++) {
            new_records[i].value = (*records)[i].value;
        }

        // Free old arrays
        my_free(*offsets);
        *offsets = new_offsets;

        my_free(*keys);
        *keys = new_keys;

        my_free(*records);
        *records = new_records;

        num_records /= 2;
    }
}

