// Define the record structure
typedef struct {
    int value;
} Record;

// Function to dynamically manage memory allocation and initialization
void* dynamic_memory_manager(int offset_size, int key_size, int num_records, int min_value, int max_value) {
    // Calculate the system-wide memory limit (e.g., 1 GB)
    size_t system_limit = 1024 * 1024 * 1024;

    // Allocate arrays for offset values and keys
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    // Initialize arrays if the allocation was successful
    if (offsets && keys) {
        // Set the value of each record's int field to a random value within the given range
        Record* records = (Record*)malloc(num_records * sizeof(Record));
        for (int i = 0; i < num_records; i++) {
            int value = rand() % (max_value - min_value + 1) + min_value;
            records[i].value = value;
        }

        // Monitor memory usage dynamically
        size_t total_memory_usage = sizeof(long) * offset_size + sizeof(int) * key_size + sizeof(Record) * num_records;
        while (total_memory_usage > system_limit * 0.7) {
            printf("Memory usage exceeded threshold! Pausing for user confirmation...\n");
            int confirm = getchar();
            if (confirm == 'y') {
                // Adjust memory allocation to fit within the constraint
                offset_size /= 2;
                key_size /= 2;
                num_records /= 2;
                total_memory_usage = sizeof(long) * offset_size + sizeof(int) * key_size + sizeof(Record) * num_records;
            } else {
                printf("Operation terminated. Deallocating memory...\n");
                // Deallocate all allocated memory
                free(offsets);
                free(keys);
                for (int i = 0; i < num_records; i++) {
                    free(&records[i]);
                }
                free(records);
                return NULL;
            }
        }

        // Handle potential errors during memory allocation or random number generation
        if (!offsets || !keys || !records) {
            printf("Error allocating memory. Log: ");
            for (int i = 0; i < num_records; i++) {
                printf("%d ", records[i].value);
            }
            printf("\n");
            return NULL;
        }

        // Deallocate all allocated memory when the function returns
        free(offsets);
        free(keys);
        for (int i = 0; i < num_records; i++) {
            free(&records[i]);
        }
        free(records);

        return records;
    } else {
        printf("Error allocating memory.\n");
        return NULL;
    }
}

// Example usage:
int main() {
    int offset_size = 100000, key_size = 50000, num_records = 200000;
    int min_value = 1, max_value = 10;

    Record* records = dynamic_memory_manager(offset_size, key_size, num_records, min_value, max_value);

    if (records) {
        for (int i = 0; i < num_records; i++) {
            printf("Record %d: %d\n", i, records[i].value);
        }
    }

    return 0;
}
