typedef struct {
    int value;
    char* str;
} record;

record* init_data(int size, int key_range, int value_range, int string_length_max) {
    // Calculate cache line boundary
    size_t alignment = sizeof(long);
    size_t aligned_size = (size * alignment + sizeof(long) - 1) / sizeof(long);

    long* offsets = aligned_alloc(alignment, aligned_size);
    int* keys = aligned_alloc(alignment, aligned_size);

    for (int i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = i % key_range;
    }

    // Initialize records
    record* data = (record*)malloc(size * sizeof(record));
    char** strings = (char**)malloc(size * sizeof(char*));

    for (int i = 0; i < size; i++) {
        data[i].value = rand() % value_range;
        strings[i] = (char*)malloc((rand() % string_length_max) + 1);
        sprintf(strings[i], "%d", data[i].value);
    }

    // Initialize random number generator
    srand(time(NULL));

    return data;
}

void free_data(record* data, int size) {
    for (int i = 0; i < size; i++) {
        free((char*)data[i].str);
    }
    free(data);
}
