#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define session structure
typedef struct {
    int id;
    char* key;
} Session;

// Define session cache structure
typedef struct {
    Session* sessions;
    size_t capacity;
    size_t used;
    time_t last_access[1000]; // assume max 1000 sessions in cache
    int policy; // 0 for LRU, 1 for TTL
    time_t ttl; // in seconds
} Cache;

// Function to initialize and manage session cache with given eviction policy and TTL
Cache* init_session_cache(int capacity, int policy, time_t ttl) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->sessions = (Session*)calloc(capacity, sizeof(Session));
    cache->capacity = capacity;
    cache->used = 0;
    for (int i = 0; i < capacity; i++) {
        cache->last_access[i] = time(NULL);
    }
    cache->policy = policy;
    cache->ttl = ttl;
    return cache;
}

// Function to add a session to the cache
void add_session(Cache* cache, int id, char* key) {
    // Check if there's room in the cache
    if (cache->used >= cache->capacity) {
        // Evict least recently used or expired sessions based on policy
        Session* evicted = NULL;
        time_t min_access = cache->last_access[0];
        int lru_idx = 0;
        for (int i = 1; i < cache->capacity; i++) {
            if ((cache->policy == 0 && cache->last_access[i] <= min_access) ||
                (cache->policy == 1 && time(NULL) - cache->last_access[i] > cache->ttl)) {
                min_access = cache->last_access[i];
                lru_idx = i;
                evicted = &cache->sessions[i];
            }
        }
        // Remove evicted session
        for (int i = lru_idx; i < cache->capacity - 1; i++) {
            cache->sessions[i] = cache->sessions[i + 1];
        }
        free(evicted->key);
        free(evicted);
        cache->used--;
    }

    // Add new session
    Session* new_session = (Session*)malloc(sizeof(Session));
    new_session->id = id;
    new_session->key = key;
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->last_access[i] == time(NULL)) {
            // Update access time
            cache->last_access[i] = time(NULL);
            cache->sessions[cache->used++] = new_session;
            return;
        }
    }
}

// Function to retrieve a session from the cache by ID
Session* get_session(Cache* cache, int id) {
    for (int i = 0; i < cache->used; i++) {
        if (cache->sessions[i]->id == id) {
            // Update access time
            cache->last_access[i] = time(NULL);
            return cache->sessions[i];
        }
    }
    return NULL;
}

// Function to remove a session from the cache by ID
void remove_session(Cache* cache, int id) {
    for (int i = 0; i < cache->used; i++) {
        if (cache->sessions[i]->id == id) {
            // Remove session
            Session* removed = cache->sessions[i];
            for (int j = i; j < cache->used - 1; j++) {
                cache->sessions[j] = cache->sessions[j + 1];
            }
            free(removed->key);
            free(removed);
            cache->used--;
            return;
        }
    }
}

// Function to clear expired sessions from the cache
void clear_expired_sessions(Cache* cache) {
    time_t now = time(NULL);
    for (int i = 0; i < cache->capacity; i++) {
        if ((cache->policy == 1 && now - cache->last_access[i] > cache->ttl)) {
            // Remove expired session
            Session* removed = &cache->sessions[i];
            for (int j = i; j < cache->used - 1; j++) {
                cache->sessions[j] = cache->sessions[j + 1];
            }
            free(removed->key);
            free(removed);
            cache->used--;
        }
    }
}

// Function to log cache operations
void log_cache_operation(Cache* cache, int operation) {
    // Open log file for appending
    FILE* log_file = fopen("session_cache.log", "a");
    if (log_file == NULL) {
        return;
    }

    time_t now = time(NULL);
    switch (operation) {
        case 0: // Add session
            fprintf(log_file, "%ld: Added session %d with key '%s'\n", now, cache->used, cache->sessions[cache->used - 1]->key);
            break;
        case 1: // Get session
            fprintf(log_file, "%ld: Retrieved session %d\n", now, operation);
            break;
        case 2: // Remove session
            fprintf(log_file, "%ld: Removed session %d\n", now, operation);
            break;
    }

    fclose(log_file);
}

int main() {
    Cache* cache = init_session_cache(1000, 1, 300); // initialize with capacity 1000, policy 1 (TTL), and TTL 300 seconds
    add_session(cache, 123, "example_key");
    Session* session = get_session(cache, 123);
    if (session != NULL) {
        log_cache_operation(cache, 0); // log addition
    } else {
        log_cache_operation(cache, 1); // log retrieval failure
    }
    remove_session(cache, 123);
    clear_expired_sessions(cache);
    return 0;
}

