    } else {
        newNode->next = *head;
        (*head)->prev = newNode;
        *head = newNode;
    }
}

// Insert a new node at the tail of the list
void insert_tail(Node** head, Node* newNode) {
    if (*head == NULL) {
        *head = newNode;
    } else {
        newNode->prev = (*head)->prev;
        (*head)->prev->next = newNode;
        newNode->next = *head;
        (*head)->prev = newNode;
    }
}

// Implement concurrency and synchronization mechanisms
pthread_mutex_t lock;

void insert_node(Node** head, Node* newNode) {
    pthread_mutex_lock(&lock);
    if (newNode == NULL)
        pthread_mutex_unlock(&lock);
    else {
        // Check for uniqueness of SRC_IP and DST_IP
        Node* current = *head;
        while (current != NULL && strcmp(current->stats.SRC_IP, newNode->stats.SRC_IP) &&
               strcmp(current->stats.DST_IP, newNode->stats.DST_IP)) {
            current = current->next;
        }
        if (current == NULL)
            insert_head(head, newNode);
        else
            // Handle duplicate SRC_IP and DST_IP combination gracefully
            pthread_mutex_unlock(&lock);

    }
}

void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%s -> %s\n", current->stats.SRC_IP, current->stats.DST_IP);
        current = current->next;
    }
}

int main() {
    Node* head = init_list();

    // Create and insert multiple nodes
    for (int i = 0; i < 5; i++) {
        TCP_CONNECTION_STATS stats;
        // Initialize stats structure with dummy values
        strcpy(stats.SRC_IP, "192.168.1.");
        sprintf(stats.DST_IP, "%d", i);
        stats.BYTES_SENT = i;
        stats.BYTES_RECEIVED = i * 2;

        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->stats = stats;
        newNode->prev = NULL;
        newNode->next = NULL;

        insert_node(&head, newNode);

        // Print the list
        print_list(head);
    }

    return 0;
}

