    for (int i = 0; i < num_entries; i++) {
        (*entries)[i] = (entry_t *)malloc(sizeof(entry_t));
    }

    // Populate entries with random values and check for duplicate keys
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        fscanf(fp, "%d %ld", &((*keys)[i]), &((*offsets)[i]));
        int random_value = rand() % 100;
        while (find_entry(*keys, num_entries, random_value) >= 0) {
            random_value = (random_value + 1) % 100;
        }
        (*entries)[i]->key = random_value;
    }

    fclose(fp);
    return 0;
}

// Helper function to find an entry with a given key
