        measurements[i].value = measurements[i].timestamp / 10.0;
        measurements[i].buffer = buffer;
    }

    // Set values for measurement fields and buffers
    for (int i = 0; i < measurementCount; i++) {
        timestamps[i] = measurements[i].timestamp;
        tags[i] = "measurement";
    }

    // Deallocate memory when the function returns
    aligned_free(timestamps);
    for (int i = 0; i < measurementCount; i++) {
        aligned_free(measurements[i].buffer);
    }
    aligned_free(measurements);

    if (myLibraryInitialized()) {
        // Clean up library resources after use
        myLibraryCleanup();
    }

    // Log memory usage and error occurrences for debugging purposes
    printf("Memory usage: %d bytes\n", timestampArraySize * sizeof(double) + measurementCount * sizeof(measurement));
}
