    FILE* file = fopen(file_path, "r");
    if (!file) {
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    *bundle_size = ftell(file);

    void* bundle = mmap(NULL, *bundle_size, PROT_READ | PROT_WRITE, MAP_SHARED, fileno(file), 0);
