typedef struct {
    float timestamp;
    char* identifier;
    EventType event_type;
} Event;

void initEventArrays(int size) {
    // Initialize three arrays with the given size
    float* timestamps = (float*) malloc(size * sizeof(float));
    char** identifiers = (char**) malloc(size * sizeof(char*));
    Event* events = (Event*) malloc(size * sizeof(Event));

    // Initialize array elements
    for (int i = 0; i < size; i++) {
        timestamps[i] = (float) i;
        identifiers[i] = (char*) malloc(strlen("event") + 1);
        strcpy(identifiers[i], "event");
        events[i].timestamp = timestamps[i];
        events[i].identifier = identifiers[i];

        // Hash identifier to determine event type
        int hash = 0;
        for (int j = 0; j < strlen(identifiers[i]); j++) {
            hash += identifiers[i][j];
        }
        if (hash % 3 == 0) {
            events[i].event_type = EVENT_TYPE_INFO;
        } else if (hash % 3 == 1) {
            events[i].event_type = EVENT_TYPE_WARNING;
        } else {
            events[i].event_type = EVENT_TYPE_ERROR;
        }
    }

    // Perform periodic status updates
    for (int i = 0; i < size; i++) {
        printf("Timestamp: %f, Identifier: %s, Event Type: %d\n", 
               timestamps[i], identifiers[i], events[i].event_type);
    }

    // Upload bulk data periodically
    for (int i = 0; i < size; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(events);

    // Release memory dynamically allocated
    free(timestamps);
}
