device* initialize_device(int num_sensors, int num_channels) {
    device* dev = (device*)malloc(sizeof(device));
    if (!dev) return NULL; // Handle memory allocation failure

    dev->sensors = (sensor_data**)calloc(num_sensors, sizeof(sensor_data*));
    if (!dev->sensors) {
        free(dev);
        return NULL;
    }

    dev->channels = (channel*)calloc(num_channels, sizeof(channel));
    if (!dev->channels) {
        for (int i = 0; i < num_sensors; i++) free(dev->sensors[i]);
        free(dev->sensors);
        free(dev);
        return NULL;
    }

    // Initialize sensor_data fields
    for (int i = 0; i < num_sensors; i++) {
        dev->sensors[i] = (sensor_data*)malloc(sizeof(sensor_data));
        if (!dev->sensors[i]) {
            while (i > 0) free(dev->sensors[--i]);
            for (int j = 0; j < num_channels; j++) free(dev->channels[j]);
            free(dev->channels);
            free(dev->sensors);
            free(dev);
            return NULL;
        }
    }

    // Initialize channel fields
    for (int i = 0; i < num_channels; i++) {
        dev->channels[i].data = dev->sensors;
        dev->channels[i].offset = i;
        // Apply custom mapping function to populate 'sensor_type' field
    }

    return dev;
}
