const require = require('require');
const blueslip = require('blueslip');
const parallel = require('parallel');

function runTests(moduleName, config) {
  const testFramework = require('test-framework');
  const testsToRun = [];

  try {
    const module = require(moduleName);
    const dependencies = Object.keys(module.dependencies);

    // Load dependencies and handle optional ones
    for (const dep of dependencies) {
      if (!module.dependencies[dep].required) continue;
      try {
        require(dep);
      } catch (err) {
        console.error(`Error loading dependency ${dep}: ${err}`);
        // Fallback mechanism: retry loading the dependency after a short delay
        setTimeout(() => {
          try {
            require(dep);
          } catch (err) {
            console.error(`Failed to load dependency ${dep} (2nd attempt): ${err}`);
          }
        }, 500);
      }
    }

    // Run tests in parallel and track performance metrics
    const testConcurrency = config.testConcurrency || 5;
    const maxTestConcurrency = config.maxConcurrency || 10;

    let totalExecutionTime = 0;
    for (const testName of Object.keys(module.tests)) {
      const testFunc = module.tests[testName];
      testsToRun.push(() => {
        try {
          blueslip.reset();
          testFramework.setup(); // Run setup method if available
          const startTime = process.hrtime()[0] * 1000000;
          testFunc();
          const executionTime = process.hrtime()[0] * 1000000 - startTime;
          totalExecutionTime += executionTime;
          console.log(`Test ${testName} completed in ${executionTime}ms`);
        } catch (err) {
          console.error(`Error running test ${testName}: ${err}`);
        }
      });
    }

    parallel(testsToRun, {
      concurrency: Math.min(maxTestConcurrency, testConcurrency),
      timeout: config.testTimeout || 30000,
    });

    // Log performance metrics and notify
    console.log(`Total execution time: ${totalExecutionTime}ms`);
    if (config.notify) {
      console.log('Tests completed successfully!');
    }
  } catch (err) {
    console.error(`Error running tests for module ${moduleName}: ${err}`);
  }
}

// Example usage:
const config = {
  testConcurrency: 5,
  maxConcurrency: 10,
  testTimeout: 30000,
  notify: true,
};

runTests('myModule', config);
