const { parse } = require('htmlparser2');
const fs = require('fs');

class DocumentProcessor {
  constructor() {
    this.cache = {};
    this.phaseRegex = /\b(hypothesis|methods|results|conclusions)\b/i;
    this.subcategoryRegex = /\b(methods\sdetails?|result\smeasurements?)\b/i;
  }

  async processDocument(path) {
    try {
      const html = await fs.promises.readFile(path, 'utf8');
      const doc = new DOMParser().parseFromString(html, 'text/html');
      const phases = {};

      const parser = new parse.DomHandler();
      const handler = new parse.Handler(parser);

      for (const section of doc.querySelectorAll('section')) {
        const text = section.textContent.trim();
        if (!text) continue;

        const phaseMatch = this.phaseRegex.exec(text);
        if (!phaseMatch) throw new Error(`Unknown phase: ${text}`);

        const phase = phaseMatch[1].toLowerCase();
        let subcategories = [];

        for (const paragraph of section.querySelectorAll('p')) {
          const text = paragraph.textContent.trim();
          if (!text) continue;

          const subcategoryMatch = this.subcategoryRegex.exec(text);
          if (!subcategoryMatch) throw new Error(`Unknown subcategory: ${text}`);

          const subcategory = subcategoryMatch[1].toLowerCase();

          subcategories.push({
            subcategory,
            text: text.replace(this.subcategoryRegex, '').trim(),
          });
        }

        phases[phase] ??= [];
        phases[phase].push(...subcategories);
      }

      // Handle caching
      if (this.cache[path]) {
        return this.cache[path];
      }

      for (const phase in phases) {
        this.cache[path][phase] = phases[phase];
      }

      return phases;
    } catch (error) {
