extern crate hyper;
extern crate tokio;
extern crate tokio-timer;

use hyper::{Client, Body};
use hyper::body::{BufMutReader, BufMutWriter};
use hyper::error::Error as HyperError;
use hyper::header::{HeaderMap, HeaderValue};
use hyper::method::Method;
use hyper::status::StatusCode;
use hyper::uri::{Scheme, Uri};

struct HttpApiClient {
    client: Client<hyper::client::HttpConnector>,
    connection_pool: tokio::sync::RwLock<Vec<tokio::net::TcpStream>>,
    rate_limiter: tokio::sync::Semaphore,
    timeout: u64,
    disable_certificate_validation: bool,
}

impl HttpApiClient {
    async fn new() -> Self {
        let client = Client::builder()
            .http_connector(hyper::client::HttpConnector::new())
            .build();

        let connection_pool = tokio::sync::RwLock::new(Vec::new());
        let rate_limiter = tokio::sync::Semaphore::new(5);
        let timeout = 5000;
        let disable_certificate_validation = false;

        HttpApiClient {
            client,
            connection_pool,
            rate_limiter,
            timeout,
            disable_certificate_validation,
        }
    }

    async fn request(&self, uri: &str, method: Method, headers: HeaderMap) -> Result<hyper::response::Response<Body>, HyperError> {
        self.rate_limiter.acquire().await.unwrap();

        let mut client = self.client.clone();
        if self.disable_certificate_validation {
            client = client.connector(hyper::client::HttpsConnector::new(None));
        }

        let request = Request::new(method, Uri::from_uri_string(uri)?)
            .headers(headers);

        match client.request(request).await {
            Ok(response) => {
                response.await?;
                self.rate_limiter.release();
                Ok(response)
            },
            Err(error) => {
                if error.is_timeout() {
                    // Retry with exponential backoff
                    tokio::timer::sleep(std::time::Duration::from_millis(500)).await;
                    self.request(uri, method, headers).await?
                } else {
                    self.rate_limiter.release();
                    Err(error)
                }
            },
        }
    }

    async fn get(&self, uri: &str) -> Result<hyper::response::Response<Body>, HyperError> {
        self.request(uri, Method::Get, HeaderMap::new()).await
    }

    async fn post(&self, uri: &str, body: Body) -> Result<hyper::response::Response<Body>, HyperError> {
        let headers = HeaderMap::from_pairs(("Content-Type", "application/json"));
        self.request(uri, Method::Post, headers).await
    }
}

struct Request<'a> {
    method: hyper::method::Method,
    uri: Uri<'a>,
    body: Body,
    headers: HeaderMap,
}

impl<'a> Request<'a> {
    fn new(method: hyper::method::Method, uri: Uri<'a>) -> Self {
        Request { 
            method, 
            uri, 
            body: Default::default(), 
            headers: HeaderMap::new() 
        }
    }

    fn headers(&self) -> &HeaderMap {
        &self.headers
    }
}
