#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the record structure containing a single int value
typedef struct {
    int val;
} record;

// Define the node structure representing a linked list element
typedef struct node {
    record *data;
    struct node *next, *prev;
} node;

// Function to manage dynamic memory allocation and initialization for the data structure
void* pipeline_manager(int num_records, int num_nodes) {
    // Initialize random seed
    srand(time(NULL));

    // Allocate a dynamic memory pool using an external library (e.g., jemalloc)
    void *pool = malloc_jemalloc(sizeof(record) * num_records);
    if (!pool) return NULL;

    // Initialize the linked list of nodes
    node *head = NULL;
    for (int i = 0; i < num_nodes; i++) {
        node *new_node = malloc_jemalloc(sizeof(node));
        if (!new_node) {
            free_jemalloc(pool);
            return NULL;
        }
        new_node->data = pool + (i * sizeof(record));
        new_node->next = head;
        new_node->prev = NULL;
        if (head) head->prev = &new_node->prev;
        head = &new_node->next;
    }

    // Initialize the first node as the list head
    head = new_node;

    return pool;
}

// Function to insert a new record into the linked list
void pipeline_insert(record *new_rec, node **head) {
    node *new_node = malloc_jemalloc(sizeof(node));
    if (!new_node) return;
    new_node->data = new_rec;
    new_node->next = *head;
    new_node->prev = NULL;
    if (*head) (*head)->prev = &new_node->prev;
    *head = &new_node->next;
}

// Function to delete a node from the linked list
void pipeline_delete(node **head, record **deleted_rec) {
    node *del_node = *head;
    if (!del_node) return;

    // Handle deletion of first node
    if (del_node == (*head)->prev) {
        *head = del_node->next;
        del_node->prev = NULL;
    } else {
        del_node->prev->next = del_node->next;
        if (del_node->next) del_node->next->prev = &del_node->prev->next;
    }

    *deleted_rec = del_node->data;
    free_jemalloc(del_node);
}

// Function to traverse the linked list and perform operations
void pipeline_traverse(node *head, void (*operation)(record *)) {
    node *current = head;
    while (current) {
        operation(current->data);
        current = current->next;
    }
}
