using System.Text;

public static string ProcessBatchOfMessages(byte[][] messages)
{
    for (int i = 0; i < 100 && i < messages.Length; i++)
    {
        byte[] messageBytes = messages[i];
        byte[] ivBytes = new byte[16]; // IV length is fixed at 16 bytes
        byte[] keyBytes = new byte[24]; // Key length is fixed at 24 bytes
        byte[] tagBytes = new byte[32]; // Tag length is fixed at 32 bytes

        if (messageBytes.Length < 48) // minimum required size for IV, key, and tag
            continue;

        Array.Copy(messageBytes, 0, ivBytes, 0, 16);
        Array.Copy(messageBytes, 16, keyBytes, 0, 24);
        Array.Copy(messageBytes, 40, tagBytes, 0, 32);

        if (ivBytes.Length != 16 || keyBytes.Length != 24 || tagBytes.Length != 32)
            continue;

        try
        {
            using (TripleDESCryptoServiceProvider crypto = new TripleDESCryptoServiceProvider())
            {
                crypto.Key = keyBytes;
                crypto.IV = ivBytes;

                using (MemoryStream ms = new MemoryStream())
                {
                    using (CryptoStream cs = new CryptoStream(ms, crypto.CreateDecryptor(), CryptoStreamMode.Write))
                    {
                        cs.Write(messageBytes, 16, messageBytes.Length - 48);
                    }

                    byte[] decryptedMessage = ms.ToArray();

                    if (decryptedMessage.Length > 0)
                    {
                        byte[] computedTag = SHA256.Create().ComputeHash(decryptedMessage);

                        if (computedTag.SequenceEqual(tagBytes))
                            return Encoding.UTF8.GetString(decryptedMessage);
                    }
                }
            }
        }
        catch
        {
            // handle exceptions gracefully and skip the message
        }

        // log warning and skip the message
    }

    return null;
}
