import java.io.*;
import java.net.*;
import java.util.*;
import java.nio.channels.*;

public class NetworkManager {
    private static final int MAX_CONCURRENT_CONNECTIONS = 10;
    private static final int CONNECTION_TIMEOUT = 3000; // milliseconds

    private Map<String, SocketChannel> connectionPool;
    private ExecutorService executor;

    public NetworkManager() {
        this.connectionPool = new HashMap<>();
        this.executor = Executors.newFixedThreadPool(MAX_CONCURRENT_CONNECTIONS);
    }

    public void connect(String serviceUrl) throws IOException {
        if (connectionPool.containsKey(serviceUrl)) {
            return; // already connected
        }

        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);

        try {
            InetSocketAddress address = new InetSocketAddress(serviceUrl, 80);
            channel.connect(address);
            connectionPool.put(serviceUrl, channel);
        } catch (IOException e) {
            // handle connection failure
            executor.execute(() -> reconnect(serviceUrl));
        }
    }

    public void disconnect(String serviceUrl) throws IOException {
        if (!connectionPool.containsKey(serviceUrl)) {
            return; // not connected
        }

        SocketChannel channel = connectionPool.remove(serviceUrl);
        channel.close();
    }

    private void reconnect(String serviceUrl) {
        try {
            connect(serviceUrl);
        } catch (IOException e) {
            // handle reconnection failure
        }
    }
}

