from cryptography.fernet import Fernet

def update_configurations(config_file_path, api_endpoint, api_key):
    with open(config_file_path, 'r') as file:
        config = json.load(file)

    response = requests.get(api_endpoint, headers={'API-Key': api_key})
    if response.status_code == 200:
        new_config = response.json()
        for key in new_config.keys():
            config[key] = new_config[key]

        with open(config_file_path, 'w') as file:
            json.dump(config, file)

        # encrypt sensitive information
        fernet = Fernet(api_key.encode())
        encrypted_data = fernet.encrypt(json.dumps(new_config).encode())
        with open('encrypted.txt', 'wb') as file:
            file.write(encrypted_data)

    else:
        print(f"Failed to retrieve configuration: {response.status_code}")
