using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly string _rootDirectory;
    private readonly string[] _allowedExtensions;
    private readonly int _maxConcurrentOperations;
    private readonly int _maxCacheAge;
    private readonly ILogService _logService;
    private readonly ICachedHashRepository _cachedHashRepository;

    public FileHasher(string rootDirectory, string[] allowedExtensions, int maxConcurrentOperations, int maxCacheAge, ILogService logService, ICachedHashRepository cachedHashRepository)
    {
        _rootDirectory = rootDirectory;
        _allowedExtensions = allowedExtensions;
        _maxConcurrentOperations = maxConcurrentOperations;
        _maxCacheAge = maxCacheAge;
        _logService = logService;
        _cachedHashRepository = cachedHashRepository;
    }

    public async Task ProcessFilesAsync(string directory, string algorithm)
    {
        var files = Directory.EnumerateFiles(directory, "*.*", SearchOption.AllDirectories);
        foreach (var file in files)
        {
            if (_allowedExtensions.Any(ext => Path.GetExtension(file).Equals(ext, StringComparison.OrdinalIgnoreCase)))
            {
                try
                {
                    using (var stream = File.OpenRead(file))
                    {
                        var hash = await CalculateHashAsync(stream, algorithm);
                        _logService.LogFileProcessed(file, stream.Length, hash);
                        _cachedHashRepository.SetHash(file, hash);
                    }
                }
                catch (IOException ex)
                {
                    _logService.LogError(ex.Message);
                }
            }
        }
    }

    private async Task<byte[]> CalculateHashAsync(Stream stream, string algorithm)
    {
        using (var algorithmProvider = GetAlgorithm(algorithm))
        {
            var hash = await Task.Run(() => HashStream(stream, algorithmProvider));
            return hash;
        }
    }

    private ICryptoServiceProvider GetAlgorithm(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "sha-256":
                return new SHA256CryptoServiceProvider();
            case "sha-512":
                return new SHA512CryptoServiceProvider();
            case "md5":
                return new MD5CryptoServiceProvider();
            default:
                throw new ArgumentException("Unsupported algorithm", nameof(algorithm));
        }
    }

    private byte[] HashStream(Stream stream, ICryptoServiceProvider provider)
    {
        using (var hash = provider.Create())
        {
            var buffer = new byte[stream.Length];
            await stream.ReadAsync(buffer, 0, buffer.Length);
            return hash.ComputeHash(buffer);
        }
    }
}
