function aggregateBytes(chunkSize, ...chunks) {
  if (chunkSize <= 0) throw new Error("Invalid chunk size");
  if (!Array.isArray(chunks)) throw new TypeError("Expected an array of chunks");

  const buffer = Buffer.alloc(0);
  let accumulatedChunks = 0;

  for (const chunk of chunks) {
    if (!Buffer.isBuffer(chunk)) continue;
    const chunkSizeActual = chunk.length;
    if (chunkSize !== chunkSizeActual)
      console.warn(`Chunk mismatch: expected ${chunkSize} bytes, got ${chunkSizeActual}`);

    buffer = Buffer.concat([buffer, chunk]);
    accumulatedChunks++;
  }

  return buffer;
}
