import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class DirectoryProcessor {
    private final ExecutorService executor = Executors.newCachedThreadPool();

    public Map<String, Long> processDirectoryPaths(String[] filePaths) throws IOException, InterruptedException {
        long startTime = System.currentTimeMillis();
        Map<String, Long> directoryCounts = new HashMap<>();

        for (String filePath : filePaths) {
            Path path = Paths.get(filePath);

            // Handle symbolic links
            if (!Files.isRegularFile(path)) {
                try {
                    path = Files.readSymbolicLink(path);
                } catch (IOException e) {
                    // Log error and skip processing
                    System.out.println("Error reading symbolic link: " + e.getMessage());
                    continue;
                }
            }

            String directoryPath = path.getParent().toString();

            // Update directory count
            if (!directoryCounts.containsKey(directoryPath)) {
                directoryCounts.put(directoryPath, 1L);
            } else {
                directoryCounts.put(directoryPath, directoryCounts.get(directoryPath) + 1);
            }
        }

        long endTime = System.currentTimeMillis();
        long processingTime = endTime - startTime;

        // Log processing time
        System.out.println("Processing Time: " + processingTime + "ms");

        return directoryCounts;
    }

    public void shutdown() {
        executor.shutdown();
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        DirectoryProcessor processor = new DirectoryProcessor();

        String[] filePaths = {"/path/to/file1", "/path/to/file2", "/path/to/subdir/file3"};
        Map<String, Long> directoryCounts = processor.processDirectoryPaths(filePaths);

        processor.shutdown();
    }
}
