import java.io.*;
import java.util.*;

public class SystemCommandExecutor {
    public static void main(String[] args) {
        String command = "your_command_here"; // replace with desired system command
        String directoryPath = "path_to_directory"; // replace with desired directory path
        boolean logToFile = true; // enable file logging if needed

        try (BufferedWriter writer = new BufferedWriter(new FileWriter("log.txt", true))) {
            executeCommand(command, directoryPath, logToFile, writer);
        } catch (IOException e) {
            System.out.println("Error while executing command or logging: " + e.getMessage());
        }
    }

    private static void executeCommand(String command, String directoryPath, boolean logToFile, Writer writer) throws IOException {
        File dir = new File(directoryPath);

        if (dir.exists()) {
            deleteDirectory(dir);
        }

        Process process = null;

        try {
            Runtime runtime = Runtime.getRuntime();
            process = runtime.exec(new String[] { "cd", directoryPath, "&&", command });

            if (logToFile) {
                writeOutput(process.getInputStream(), writer);
                writeError(process.getErrorStream(), writer);
            } else {
                System.out.println("Standard output: " + new BufferedReader(new InputStreamReader(process.getInputStream())).lines().reduce((acc, line) -> acc + line + "\n").orElse(""));
                System.out.println("Standard error: " + new BufferedReader(new InputStreamReader(process.getErrorStream())).lines().reduce((acc, line) -> acc + line + "\n").orElse(""));
            }

            int exitCode = process.waitFor();

            if (exitCode != 0) {
                System.out.println("Command execution failed with code " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            throw new IOException("Error while executing command: " + e.getMessage());
        } finally {
            if (process != null) {
                process.destroy();
            }
        }
    }

    private static void deleteDirectory(File directory) throws IOException {
        File[] files = directory.listFiles();

        if (files != null && files.length > 0) {
            for (File file : files) {
                if (file.isFile()) {
                    file.delete();
                } else if (file.isDirectory()) {
                    deleteDirectory(file);
                    file.delete();
                }
            }
        }

        directory.delete();
    }

    private static void writeOutput(InputStream in, Writer writer) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in))) {
            String line;

            while ((line = reader.readLine()) != null) {
                writer.write(line);
                writer.write("\n");
            }
        }
    }

    private static void writeError(InputStream in, Writer writer) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in))) {
            String line;

            while ((line = reader.readLine()) != null) {
                writer.write("Error: " + line);
                writer.write("\n");
            }
        }
    }
}
