['Here is the C code for managing a doubly linked list of TCP_CONNECTION_STATS structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    int bytes_sent;
    int bytes_received;
} TCP_CONNECTION_STATS;

// Define reader-writer lock structure
typedef pthread_rwlock_t lock_type;

// Define list node structure
typedef struct Node {
    TCP_CONNECTION_STATS stats;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the doubly linked list
typedef struct {
    Node* head;
    Node* tail;
    lock_type lock;
} List;

// Initialize the list
void init_list(List* list) {
    pthread_rwlock_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
}

// Add a new node at the head of the list
void add_head_node(List* list, TCP_CONNECTION_STATS stats) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->stats = stats;
    new_node->next = list->head;
    if (list->head != NULL)
        list->head->prev = &new_node->stats;
    else
        list->tail = &new_node->stats;
    list->head = &new_node->stats;
    pthread_rwlock_wrlock(&list->lock);
}

// Add a new node at the tail of the list
void add_tail_node(List* list, TCP_CONNECTION_STATS stats) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->stats = stats;
    new_node->prev = &list->tail->stats;
    new_node->next = NULL;
    if (list->tail != NULL)
        list->tail->next = &new_node->stats;
    else
        list->head = &new_node->stats;
    list->tail = &new_node->stats;
    pthread_rwlock_wrlock(&list->lock);
}

// Remove a node from the list
void remove_node(List* list, Node* node) {
    if (node->prev != NULL)
        node->prev->next = node->next;
    else
        list->head = node->next;

    if (node->next != NULL)
        node->next->prev = node->prev;
    else
        list->tail = node->prev;

    pthread_rwlock_unlock(&list->lock);
}

// Iterate over the list
void iterate_list(List* list, void (*callback)(TCP_CONNECTION_STATS*)) {
    Node* current = list->head;
    while (current != NULL) {
        callback(current->stats);
        current = current->next;
    }
}
