#include "memory_manager.h"
#include <stdlib.h>
#include <stdio.h>
#include <math.h>

typedef struct record {
    int value;
} record;

typedef struct node {
    struct node* next;
    struct node* prev;
} node;

void dynamic_allocation(int num_nodes, int max_records_per_node) {
    // Initialize memory pool
    memory_pool* mp = memory_manager_init();

    // Allocate nodes and initialize their pointers
    node** nodes = (node**)malloc(num_nodes * sizeof(node*));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = (node*)malloc(sizeof(node));
        nodes[i]->next = NULL;
        nodes[i]->prev = NULL;
    }

    // Initialize and populate records
    record** records = (record**)malloc(max_records_per_node * sizeof(record*));
    for (int i = 0; i < max_records_per_node; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = (rand() % 100) + 1;
    }

    // Implement cyclic linked list
    node* current = nodes[0];
    for (int i = 0; i < num_nodes - 1; i++) {
        current->next = nodes[i + 1];
        current->prev = &nodes[i]->next;
        current = current->next;
    }
    current->next = &nodes[0]; // Close the cycle

    // Implement insertion and deletion operations
    void insert_node(node* new_node, node** tail) {
        if (*tail == NULL) {
            *tail = new_node;
        } else {
            new_node->prev = *tail;
            (*tail)->next = new_node;
            *tail = new_node;
        }
    }

    void delete_node(node* node_to_delete) {
        if (node_to_delete->prev != NULL) {
            node_to_delete->prev->next = node_to_delete->next;
        } else {
            *tail = node_to_delete->next;
        }
        if (node_to_delete->next != NULL) {
            node_to_delete->next->prev = node_to_delete->prev;
        } else {
            *tail = node_to_delete->prev;
        }
    }

    // Perform batch processing
    void add_records(int num_records, record** new_records) {
        for (int i = 0; i < num_records; i++) {
            records[max_records_per_node - 1 + i] = new_records[i];
        }
    }

    void remove_records(int num_records) {
        for (int i = 0; i < num_records; i++) {
            free(records[max_records_per_node - 1 - i]);
        }
    }

    // Clean up and release memory
    memory_manager_free(mp);
    free(nodes);
    free(records);

    return;
}
