typedef struct Record {
    long identifier;
    int timestamp;
} Record;

typedef struct Node {
    Record* data;
    struct Node* next;
} Node;

void free_node(Node** head) {
    Node* current = *head;
    Node* next = NULL;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

Node* new_node(Record* data) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return NULL;

    node->data = data;
    node->next = NULL;
    return node;
}

void delete_node(Node** head, Record* data) {
    if (*head == NULL) return;

    if ((*head)->data == data) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }

    Node* current = *head;
    while (current->next != NULL) {
        if (current->next->data == data) {
            Node* temp = current->next;
            current->next = current->next->next;
            free(temp);
            return;
        }
        current = current->next;
    }
}

Node* insert_node(Node** head, Record* data) {
    Node* node = new_node(data);

    if (*head == NULL || (*head)->data->timestamp > data->timestamp) {
        node->next = *head;
        *head = node;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->data->timestamp <= data->timestamp)
            current = current->next;

        node->next = current->next;
        current->next = node;
    }

    return *head;
}

void free_all_nodes(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(&current);
        current = next;
    }
    *head = NULL;
}
