```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long identifier;
    int timestamp;
} Record;

// Define the node structure
typedef struct node {
    Record* record;
    struct node* next;
} Node;

// Function to create a new node with memory allocation
Node* newNode(Record* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;
    return node;
}

// Function to insert a new record into the linked list
void insertRecord(Node** head, Record* record) {
    Node* newNode = newNode(record);
    if (*head == NULL || (*head)->record->identifier > record->identifier) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next && current->next->record->identifier <= record->identifier) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to delete a record from the linked list
void deleteRecord(Node** head, long identifier) {
    Node* current = *head;
    Node* previous = NULL;
    while (current && current->record->identifier != identifier) {
        previous = current;
        current = current->next;
    }
    if (current) {
        if (previous)
            previous->next = current->next;
        else
            *head = current->next;
        free(current);
    }
}

// Function to garbage collect unused nodes and records
void garbageCollect(Node** head) {
    Node* current = *head;
    Node* nextNode;
    while (current) {
        nextNode = current->next;
        if (current->record->identifier == 0 || current->record->timestamp == 0) {
            // Node is unused, free it
            free(current);
            current = nextNode;
        } else {
            current = nextNode;
        }
    }
}

// Function to manage memory for multiple data structures
void* memoryManager(void* arg) {
    int* concurrentInserts = (int*)arg;
    while (*concurrentInserts > 0) {
        // Perform concurrent inserts
        Record records[10];
        for (int i = 0; i < 10 && *concurrentInserts > 0; i++) {
            records[i].identifier = rand();
            records[i].timestamp = time(NULL);
            insertRecord(&head, &records[i]);
            (*concurrentInserts)--;
        }
        // Perform concurrent deletes
        long identifiers[5];
        for (int i = 0; i < 5 && *concurrentInserts > 0; i++) {
            identifiers[i] = rand();
            deleteRecord(&head, identifiers[i]);
            (*concurrentInserts)--;
        }
        // Periodic garbage collection
        if (*concurrentInserts % 100 == 0)
            garbageCollect(&head);
    }
}

// Function to integrate with external logging service
void logMessage(char* message) {
    // Send log request to external logging service
    printf("%s\n", message);
}

int main() {
    pthread_t threads[10];
    int concurrentInserts = 100;
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, memoryManager, &concurrentInserts);
    }
    for (int i = 0; i < 10; i++)
        pthread_join(threads[i]);
    return 0;
}
