#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    long identifier;
    int timestamp;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

void init_node_array(Node** node_array, size_t capacity) {
    *node_array = (Node*)malloc(sizeof(Node) * capacity);
    for(size_t i = 0; i < capacity; ++i) {
        (*node_array)[i].next = NULL;
    }
}

void resize_node_array(Node** node_array, size_t new_capacity) {
    Node* new_array = (Node*)realloc(*node_array, sizeof(Node) * new_capacity);
    if(new_array == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    memset(new_array + (*node_array)->size, 0, sizeof(Node) * ((*node_array)->size - 1));
    for(size_t i = 0; i < (*node_array)->size; ++i) {
        if((*node_array)[i].next != NULL) {
            Node* temp = (*node_array)[i];
            for(size_t j = i + 1; j < (*node_array)->size; ++j) {
                temp->next = (*node_array)[j];
                (*node_array)[j] = NULL;
            }
            if(temp != NULL) {
                new_array[new_capacity - 1].next = temp;
            }
        }
    }
    free(*node_array);
    *node_array = new_array;
}

void insert_node(Node** node_array, size_t capacity, Record* record, int timestamp) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;
    new_node->timestamp = timestamp;
    if(*node_array == NULL || (*node_array)->size > 0) {
        new_node->next = *node_array;
        *node_array = new_node;
    } else if((*node_array)->next != NULL) {
        Node* temp = *node_array;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    } else {
        printf("Array is empty.\n");
        return;
    }
}

void delete_node(Node** node_array, size_t capacity, int timestamp) {
    Node* current = *node_array;
    Node* previous = NULL;
    while(current != NULL && current->timestamp <= timestamp) {
        previous = current;
        current = current->next;
    }
    if(current == NULL || (current->timestamp > timestamp && previous == NULL)) {
        printf("Node not found.\n");
        return;
    } else if(previous != NULL) {
        previous->next = current->next;
    } else {
        *node_array = current->next;
    }
    free(current);
}

void print_node_array(Node* node_array, size_t capacity) {
    for(size_t i = 0; i < capacity; ++i) {
        if(node_array[i].record != NULL) {
            printf("Identifier: %ld, Timestamp: %d\n", node_array[i].record->identifier, node_array[i].timestamp);
        }
    }
}

void print_node(Node* node) {
    while(node != NULL) {
        printf("Identifier: %ld, Timestamp: %d\n", node->record->identifier, node->timestamp);
        node = node->next;
    }
}
