    int size;
    int capacity;
    entry_t** entries;
    pthread_mutex_t mutex;
} store_t;

store_t* create_store() {
    store_t* store = (store_t*)malloc(sizeof(store_t));
    store->size = 0;
    store->capacity = MAX_ENTRIES / RESIZE_FACTOR;
    store->entries = (entry_t**)calloc(store->capacity, sizeof(entry_t*));
    pthread_mutex_init(&store->mutex, NULL);
    return store;
}

void destroy_store(store_t* store) {
    for (int i = 0; i < store->size; i++) {
        free(store->entries[i]->key);
        free(store->entries[i]);
    }
    free(store->entries);
    pthread_mutex_destroy(&store->mutex);
    free(store);
}

void resize_store(store_t* store) {
    int new_capacity = store->capacity * RESIZE_FACTOR;
    entry_t** new_entries = (entry_t**)realloc(store->entries, new_capacity * sizeof(entry_t*));
    if (!new_entries) {
        printf("Memory allocation failed\n");
        return;
    }
    store->capacity = new_capacity;
    store->entries = new_entries;
}

void add_entry(store_t* store, char* key, double value) {
    pthread_mutex_lock(&store->mutex);
    for (int i = 0; i < store->size; i++) {
        if (strcmp(store->entries[i]->key, key) == 0) {
            store->entries[i]->value = value;
            break;
        }
    }
    if (store->size == store->capacity) {
        resize_store(store);
    }
    entry_t* new_entry = (entry_t*)malloc(sizeof(entry_t));
    new_entry->key = strdup(key);
    new_entry->value = value;
    store->entries[store->size++] = new_entry;
    pthread_mutex_unlock(&store->mutex);
}

double get_value(store_t* store, char* key) {
    pthread_mutex_lock(&store->mutex);
    for (int i = 0; i < store->size; i++) {
        if (strcmp(store->entries[i]->key, key) == 0) {
            double value = store->entries[i]->value;
            pthread_mutex_unlock(&store->mutex);
            return value;
        }
    }
    pthread_mutex_unlock(&store->mutex);
    return -1.0; // Not found
