    if (!records) return NULL; // handle memory allocation failure

    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    int* keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
