    srand(time(NULL)); // initialize random seed
    for (int i = 0; i < n; i++) {
        offsets[i] = start + i * step;
        keys[i] = 0;
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
        records[i].status = rand() % 21 - 10; // random status value between -10 and 10
    }

    free(offsets);
    free(keys);

    return records;
}

