```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure for each item in the cache
typedef struct {
    char* key;
    double value;
    time_t timestamp;
} Item;

// Distributed cache structure
typedef struct {
    Item* items; // Array of items in the cache
    size_t capacity; // Maximum number of items the cache can hold
    size_t current_size; // Current number of items in the cache
    pthread_mutex_t lock; // Mutex for thread-safe operations
} Cache;

// Function to create a new cache with given capacity
Cache* create_cache(size_t capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->items = (Item*)calloc(capacity, sizeof(Item));
    cache->capacity = capacity;
    cache->current_size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Function to add an item to the cache
void cache_add(Cache* cache, char* key, double value) {
    Item new_item;
    new_item.key = key;
    new_item.value = value;
    time_t timestamp = time(NULL); // Current timestamp for expiration
    new_item.timestamp = timestamp;

    pthread_mutex_lock(&cache->lock);
    if (cache->current_size < cache->capacity) {
        cache->items[cache->current_size] = new_item;
        cache->current_size++;
    } else {
        printf("Cache is full. Cannot add new item.\n");
    }
    pthread_mutex_unlock(&cache->lock);
}

// Function to update an existing item in the cache
void cache_update(Cache* cache, char* key, double value) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->current_size; i++) {
        if (strcmp(cache->items[i].key, key) == 0) {
            cache->items[i].value = value;
            return;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Function to retrieve an item from the cache
double cache_get(Cache* cache, char* key) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->current_size; i++) {
        if (strcmp(cache->items[i].key, key) == 0) {
            double value = cache->items[i].value;
            pthread_mutex_unlock(&cache->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return -1.0; // Item not found
}

// Function to evict expired items from the cache
void cache_evict(Cache* cache) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->current_size; i++) {
        if (time(NULL) - cache->items[i].timestamp > 60) { // Item expired after 1 minute
            memmove(&cache->items[i], &cache->items[i + 1], (cache->current_size - i - 1) * sizeof(Item));
            cache->current_size--;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Function to resize the cache
void cache_resize(Cache* cache, size_t new_capacity) {
    if (new_capacity < cache->current_size) {
        printf("New capacity is less than current size. Cannot resize.\n");
        return;
    }

    Cache* new_cache = create_cache(new_capacity);
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->current_size; i++) {
        if (new_cache->current_size < new_cache->capacity) {
            new_cache->items[new_cache->current_size] = cache->items[i];
            new_cache->current_size++;
        } else {
            printf("New cache is full. Cannot resize.\n");
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }
    pthread_mutex_unlock(&cache->lock);

    // Replace the old cache with the new one
    Cache* old_cache = cache;
    cache = new_cache;
    free(old_cache->items);
    free(old_cache);
}

int main() {
    // Example usage:
    Cache* cache = create_cache(1000); // Create a cache with initial capacity of 1000

    cache_add(cache, "key1", 10.5);
    cache_add(cache, "key2", 20.7);

    double value = cache_get(cache, "key1");
    printf("Retrieved value: %f\n", value);

    // Update an existing item
    cache_update(cache, "key1", 15.3);

    // Evict expired items (simulate 1 minute passage of time)
    sleep(60);
    cache_evict(cache);

    // Resize the cache to have more capacity
    cache_resize(cache, 2000);

    return 0;
}
```

This code creates a distributed cache with an array of 'item' structures, each containing a unique 'char*' key, a 'double' value, and a timestamp for cache expiration. The functions `cache_add`, `cache_update`, and `cache_get` manage memory allocation and initialization for the data structure, ensuring thread-safe operations and efficient handling of concurrent read and write requests. The code also includes mechanisms to evict expired items and resize the cache when it reaches capacity.

Note that this is a basic implementation and may require further enhancements based on specific requirements or constraints.']

