    Node* head = (Node*) malloc(sizeof(Node));
    head->prev = NULL;
    head->next = NULL;
    return head;
}

// Function to insert a new node at the head or tail of the list
void insert_node(Node** head, Node** tail, TCP_CONNECTION_STATS stats) {
    // Acquire write lock for synchronization
    pthread_mutex_lock(&mutex);

    // Create a new node with given statistics
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->stats = stats;
    new_node->prev = NULL;
    new_node->next = *head;

    if (*head == NULL) {
        // Insert at the head of an empty list
        *head = new_node;
        *tail = new_node;
    } else {
        // Insert at the tail of a non-empty list
        (*tail)->next = new_node;
        new_node->prev = *tail;
        *tail = new_node;
    }

    // Release write lock for synchronization
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the doubly linked list
void* traverse_list(Node* head) {
    // Acquire read lock for concurrent access
    pthread_rwlock_rdlock(&rw_lock);

