        // Update LRU cache
        size_t i;
        for (i = 0; i < lru_cache.size; i++) {
            if (lru_cache.cache[i] == &current) {
                lru_cache.cache[i] = NULL;
                break;
            }
        }
        lru_cache.size--;

        current = current->next;
    }

    // Release read lock for concurrent access
    pthread_rwlock_unlock(&rw_lock);
}

// Function to manage LRU cache
void* manage_lru_cache(Node* node) {
    // Acquire write lock for synchronization
    pthread_mutex_lock(&mutex);

    size_t i;
    for (i = 0; i < lru_cache.size; i++) {
        if (lru_cache.cache[i] == &node) {
            break;
        }
    }

    if (i < lru_cache.size - 1) {
        // Update LRU cache
        size_t j;
        for (j = i; j < lru_cache.size - 1; j++) {
            lru_cache.cache[j] = lru_cache.cache[j + 1];
        }
    } else if (i == lru_cache.size - 1) {
        // Evict least recently used node
        free(lru_cache.cache[i]);
        lru_cache.size--;
    }

    // Release write lock for synchronization
    pthread_mutex_unlock(&mutex);
}

// Function to handle concurrent access and modification
