typedef struct {
    char* name;
    double size;
    struct Node** children;
    int child_count;
} Node;

Node* node_new(const char* name, double size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL; // handle memory allocation failure
    node->name = strdup(name);
    node->size = size;
    node->children = NULL;
    node->child_count = 0;
    return node;
}

void node_free(Node* node) {
    for (int i = 0; i < node->child_count; i++) {
        Node* child = node->children[i];
        free(child);
    }
    free(node->name);
    free(node);
}

Node* node_add_child(Node* parent, const char* name, double size) {
    Node* child = node_new(name, size);
    if (!child) return NULL; // handle memory allocation failure
    child->children = (struct Node**)realloc(parent->children, (parent->child_count + 1) * sizeof(struct Node*));
    if (!child->children) return NULL; // handle memory allocation failure
    parent->children[parent->child_count] = child;
    parent->child_count++;
    return child;
}

void node_remove_child(Node* parent, int index) {
    for (int i = index; i < parent->child_count - 1; i++) {
        Node* old_child = parent->children[i];
        Node* new_child = parent->children[i + 1];
        free(old_child);
        parent->children[i] = new_child;
    }
    free(parent->children[parent->child_count - 1]);
    parent->child_count--;
}

double node_get_size(Node* node) {
    double size = node->size;
    for (int i = 0; i < node->child_count; i++) {
        Node* child = node->children[i];
        size += node_get_size(child);
    }
    return size;
}

Node* node_find(Node* root, const char* name) {
    if (!root || !strcmp(root->name, name)) return root;
    for (int i = 0; i < root->child_count; i++) {
        Node* child = root->children[i];
        Node* found = node_find(child, name);
        if (found) return found;
    }
    return NULL;
}
