#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for each entry in the key-value store
typedef struct {
    char* key;
    double value;
} KVEntry;

// Define the hash table structure with separate chaining to handle collisions
typedef struct {
    int size; // Current size of the hash table
    int capacity; // Initial capacity of the hash table
    double loadFactor; // Desired load factor for the hash table (0.5 - 0.75)
    KVEntry** buckets; // Array of pointers to linked lists representing collisions
    pthread_mutex_t lock; // Mutex for thread safety
} HashTable;

// Function to create a new hash table with initial capacity and desired load factor
HashTable* createHashTable(int capacity, double loadFactor) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = 0;
    table->capacity = capacity;
    table->loadFactor = loadFactor;
    table->buckets = (KVEntry**)calloc(capacity, sizeof(KVEntry*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Function to resize the hash table based on the desired load factor
void resizeHashTable(HashTable* table) {
    int newCapacity = (int)(table->capacity * 2.5); // Grow by 50%
    KVEntry** newBuckets = (KVEntry**)calloc(newCapacity, sizeof(KVEntry*));
    for (int i = 0; i < table->capacity; i++) {
        KVEntry* currentBucket = table->buckets[i];
        while (currentBucket) {
            int index = hash_function(currentBucket->key, newCapacity);
            KVEntry* next = currentBucket;
            currentBucket = currentBucket->next;
            next->next = newBuckets[index];
            newBuckets[index] = next;
        }
    }
    free(table->buckets);
    table->buckets = newBuckets;
    table->capacity = newCapacity;
}

// Function to add a new entry to the hash table
void put(HashTable* table, char* key, double value) {
    int index = hash_function(key, table->capacity);
    KVEntry* entry = (KVEntry*)malloc(sizeof(KVEntry));
    entry->key = key;
    entry->value = value;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
}

// Function to update the value for a given key in the hash table
void update(HashTable* table, char* key, double newValue) {
    int index = hash_function(key, table->capacity);
    KVEntry* current = table->buckets[index];
    while (current) {
        if (strcmp(current->key, key) == 0) {
            current->value = newValue;
            return;
        }
        current = current->next;
    }
}

// Function to retrieve the value for a given key in the hash table
double get(HashTable* table, char* key) {
    int index = hash_function(key, table->capacity);
    KVEntry* current = table->buckets[index];
    while (current) {
        if (strcmp(current->key, key) == 0) {
            return current->value;
        }
        current = current->next;
    }
    return -1.0; // Key not found
}

// Function to periodically compact the hash table and reduce memory usage
void compactHashTable(HashTable* table) {
    int newCapacity = (int)(table->capacity * 0.5); // Shrink by 50%
    KVEntry** newBuckets = (KVEntry**)calloc(newCapacity, sizeof(KVEntry*));
    for (int i = 0; i < table->capacity; i++) {
        KVEntry* currentBucket = table->buckets[i];
        while (currentBucket) {
            int index = hash_function(currentBucket->key, newCapacity);
            KVEntry* next = currentBucket;
            currentBucket = currentBucket->next;
            next->next = newBuckets[index];
            newBuckets[index] = next;
        }
    }
    free(table->buckets);
    table->buckets = newBuckets;
    table->capacity = newCapacity;
}

// Function to handle network latency and prevent overload
void backpressure(HashTable* table) {
    // Implement a strategy to prevent overload when the system is under heavy load
}
