// Define the 'item' structure
typedef struct {
    char* name;
    double value;
    struct item* parent;
    int reference_count;
} item;

// Function to initialize and populate the collection with predefined items
void init_collection(item** root, int size) {
    // Initialize the root of the collection
    *root = (item*)malloc(sizeof(item));
    (*root)->name = "Root";
    (*root)->value = 0.0;
    (*root)->parent = NULL;
    (*root)->reference_count = 1;

    // Populate the collection with predefined items
    for (int i = 0; i < size; i++) {
        item* new_item = (item*)malloc(sizeof(item));
        new_item->name = "Item-%d"; // Replace with actual names
        new_item->value = (double)i;
        new_item->parent = *root;
        new_item->reference_count = 1;

        // Add the new item to the collection
        (*root)->reference_count++;
    }
}

// Function to add a new item to the collection
void add_item(item** root, char* name, double value) {
    // Create a new 'item' structure
    item* new_item = (item*)malloc(sizeof(item));
    new_item->name = name;
    new_item->value = value;
    new_item->parent = *root;
    new_item->reference_count = 1;

    // Update the reference count of the parent node
    (*root)->reference_count++;
}

// Function to find an item by name
item* find_item_by_name(item* root, char* name) {
    // Traverse the collection using a recursive function
    return traverse_collection(root, name);
}

// Recursive function to find an item by name
item* traverse_collection(item* node, char* name) {
    if (node == NULL || strcmp(node->name, name) == 0) {
        return node;
    }

    // Recursively search for the item in child nodes
    for (int i = 0; i < node->reference_count; i++) {
        item* found_node = traverse_collection((item*)node->parent, name);
        if (found_node != NULL) {
            return found_node;
        }
    }

    return NULL;
}

// Function to update the value of an item
void update_value(item* root, char* name, double new_value) {
    // Find the item by name
    item* target_item = find_item_by_name(root, name);

    if (target_item != NULL) {
        target_item->value = new_value;
    }
}

// Function to remove an item from the collection
void remove_item(item** root, char* name) {
    // Find the item by name
    item* target_item = find_item_by_name(*root, name);

    if (target_item != NULL) {
        // Decrement the reference count of the item
        target_item->reference_count--;

        // If the reference count drops to zero, free the item's resources
        if (target_item->reference_count == 0) {
            free(target_item);
        }
    }
}

// Function to safely traverse and manipulate the item hierarchy
item* traverse_hierarchy(item* node, char* name) {
    if (node == NULL || strcmp(node->name, name) == 0) {
        return node;
    }

    // Recursively search for the item in child nodes
    for (int i = 0; i < node->reference_count; i++) {
        item* found_node = traverse_hierarchy((item*)node->parent, name);
        if (found_node != NULL) {
            return found_node;
        }
    }

    return NULL;
}

// Function to print the collection
void print_collection(item* root) {
    // Traverse the collection using a recursive function
    traverse_collection_recursive(root);
}

// Recursive function to print the collection
void traverse_collection_recursive(item* node) {
    if (node == NULL) {
        return;
    }

    printf("Name: %s, Value: %f\n", node->name, node->value);

    // Recursively print child nodes
    for (int i = 0; i < node->reference_count; i++) {
        item* child_node = (item*)node->parent;
        traverse_collection_recursive(child_node);
    }
}

// Example usage:
int main() {
    int size = 5;
    item* root = NULL;

    init_collection(&root, size);

    // Add new items to the collection
    add_item(&root, "Item-1", 1.0);
    add_item(&root, "Item-2", 2.0);
    add_item(&root, "Item-3", 3.0);

    // Find and update an item's value
    update_value(root, "Item-1", 10.0);

    // Print the collection
    print_collection(root);

    // Remove an item from the collection
    remove_item(&root, "Item-2");

    return 0;
}

