#include <stdlib.h>
#include <stdio.h>

typedef struct Node {
    char* name;
    double size;
    struct Node** children;
    int childCount;
} Node;

void initNode(Node* node, const char* name, double size) {
    node->name = (char*)malloc(strlen(name) + 1);
    strcpy(node->name, name);
    node->size = size;
}

int addChild(Node* parent, Node* child) {
    parent->children = (Node**)realloc(parent->children, (parent->childCount + 1) * sizeof(Node*));
    if (!parent->children) return -1; // out of memory
    parent->children[parent->childCount++] = child;
    return 0; // success
}

void removeChild(Node* parent, Node* child) {
    int i;
    for (i = 0; i < parent->childCount; i++) {
        if (parent->children[i] == child) {
            memmove(&parent->children[i], &parent->children[i + 1], (parent->childCount - i - 1) * sizeof(Node*));
            parent->childCount--;
            free(child);
            return;
        }
    }
}

Node* findNode(Node* root, const char* name) {
    if (!root) return NULL; // not found
    if (strcmp(root->name, name) == 0) return root; // found
    int i;
    for (i = 0; i < root->childCount; i++) {
        Node* child = findNode(root->children[i], name);
        if (child) return child; // found in subtree
    }
    return NULL; // not found
}

double calculateSubtreeSize(Node* node) {
    double size = node->size;
    int i;
    for (i = 0; i < node->childCount; i++) {
        Node* child = node->children[i];
        size += calculateSubtreeSize(child);
    }
    return size;
}
