import os
import heapq
import logging
from collections import defaultdict
from hashlib import sha256

class Node:
    def __init__(self, value: str, weight: int):
        self.value = value
        self.weight = weight

class DynamicLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert(self, node: Node) -> None:
        if not self.head:
            self.head = self.tail = node
        else:
            current = self.head
            while current and current.weight <= node.weight:
                current = current.next
            node.next = current
            if not current:
                self.tail = node
            else:
                prev = self.tail
                self.tail = node
                self.tail.next = None
            heapq.heapify([(node.weight, node)])
            while self.size < 1000:  # adjust the threshold based on your needs
                new_node = heapq.heappop()
                if not new_node[1].next:
                    self.head = new_node[1]
                    break

    def delete(self) -> None:
        if not self.head:
            return
        prev = None
        current = self.head
        while current and current.next:
            prev = current
            current = current.next
        self.tail = prev
        if current:
            self.head = current.next
        else:
            self.head = None
        self.size -= 1

    def traverse(self) -> list:
        result = []
        current = self.head
        while current:
            result.append(current.value)
            current = current.next
        return result

class ConfigParser:
    def __init__(self, config_file: str):
        self.config_file = config_file
        self.config_data = {}

    def parse(self) -> None:
        with open(self.config_file, 'r') as file:
            for line in file:
                key, value = line.strip().split('=')
                if key not in self.config_data:
                    self.config_data[key] = []
                self.config_data[key].append((value, int(key)))

    def sort_config_entries(self) -> None:
        sorted_config_data = {}
        for key, value_list in self.config_data.items():
            sorted_value_list = sorted(value_list)
            sorted_config_data[key] = [value[0] for value in sorted_value_list]
        self.config_data = sorted_config_data

    def extract_sequence_number(self) -> int:
        last_entry = max(self.config_data.values(), key=lambda x: len(x))
        sequence_number = int(last_entry[-1][1])
        return sequence_number

class Logger:
    def __init__(self, log_file: str):
        self.log_file = log_file
        logging.basicConfig(filename=self.log_file, level=logging.INFO)

    def log_operation(self, message: str) -> None:
        logging.info(message)

# Example usage:

config_parser = ConfigParser('config.txt')
config_parser.parse()
config_parser.sort_config_entries()
sequence_number = config_parser.extract_sequence_number()

logger = Logger('log.txt')
logger.log_operation(f"Sequence number: {sequence_number}")

dynamic_linked_list = DynamicLinkedList()
dynamic_linked_list.insert(Node('value1', 1))
dynamic_linked_list.insert(Node('value2', 2))
dynamic_linked_list.traverse()  # ['value1', 'value2']

# Error handling:
try:
    # code that may raise an exception
except Exception as e:
    logger.log_operation(f"Error: {str(e)}")
