// Dynamic Linked List Management
typedef struct Node {
    char* string;
    int value;
} Node;

Node* createNode(char* str, int val) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->string = str;
    node->value = val;
    return node;
}

void insertNode(Node** headRef, char* str, int val) {
    Node* newNode = createNode(str, val);
    if (*headRef == NULL || strcmp(newNode->string, (*headRef)->string) < 0) {
        newNode->next = *headRef;
        *headRef = newNode;
    } else {
        Node* curr = *headRef;
        while (curr->next != NULL && strcmp(newNode->string, curr->next->string) > 0) {
            curr = curr->next;
        }
        newNode->next = curr->next;
        curr->next = newNode;
    }
}

void deleteNode(Node** headRef, char* str) {
    if (*headRef == NULL)
        return;

    Node* curr = *headRef;
    while (curr->next != NULL && strcmp(str, curr->next->string) < 0) {
        curr = curr->next;
    }
    if (curr->next != NULL && strcmp(str, curr->next->string) == 0) {
        Node* temp = curr->next;
        curr->next = curr->next->next;
        free(temp);
    }
}

void traverseList(Node* head) {
    while (head != NULL) {
        printf("%s - %d\n", head->string, head->value);
        head = head->next;
    }
}

