    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->size = size;
    hashTable->buckets = (Node**)malloc(size * sizeof(Node*));
    for (int i = 0; i < size; i++) {
        hashTable->buckets[i] = NULL;
    }
    return hashTable;
}

void insertIntoHashTable(HashTable* hashTable, char* str, int val) {
    int index = val % hashTable->size;
    Node* node = createNode(str, val);
    if (hashTable->buckets[index] == NULL || strcmp(node->string, hashTable->buckets[index]->string) < 0) {
        node->next = hashTable->buckets[index];
        hashTable->buckets[index] = node;
    } else {
        Node* curr = hashTable->buckets[index];
        while (curr->next != NULL && strcmp(node->string, curr->next->string) > 0) {
            curr = curr->next;
        }
        node->next = curr->next;
        curr->next = node;
    }
}

void deleteFromHashTable(HashTable* hashTable, char* str) {
    if (hashTable == NULL)
        return;

    int index = strlen(str) % hashTable->size;
    Node* curr = hashTable->buckets[index];
    while (curr != NULL && strcmp(str, curr->string) < 0) {
        curr = curr->next;
    }
    if (curr != NULL && strcmp(str, curr->string) == 0) {
        Node* temp = curr;
        curr = curr->next;
        free(temp);
    }
}

