// Define a custom hash table class
class NFAPIHashTable {
public:
    NFAPIHashTable(size_t initialSize) : size(initialSize), table(new pair<string, pair<string, string)>[initialSize]) {}

    ~NFAPIHashTable() { delete[] table; }

    void insert(const string& key, const string& value) {
        int index = hash(key) % size;
        if (table[index].first.empty()) {
            table[index] = make_pair(key, make_pair(value, nullptr));
        } else {
            pair<string, pair<string, string>>& entry = table[index];
            if (!entry.second.second && !entry.second.first.empty()) {
                entry.second.second = new pair<string, string>(value);
            } else {
                table[getNewIndex(index)] = make_pair(key, make_pair(value, nullptr));
            }
        }
    }

    void remove(const string& key) {
        int index = hash(key) % size;
        if (!table[index].first.empty()) {
            table[index] = pair<string, pair<string, string>>{};
        } else {
            for (int i = 0; i < size; ++i) {
                if (!table[i].first.empty() && table[i].first == key) {
                    table[i] = pair<string, pair<string, string>>{};
                }
            }
        }
    }

    string lookup(const string& key) {
        int index = hash(key) % size;
        if (table[index].first.empty()) return "";
        return table[index].second.first;
    }

private:
    size_t size;
    pair<string, pair<string, string>>* table;

    size_t hash(const string& key) const {
        size_t hashValue = 0;
        for (char c : key) {
            hashValue += static_cast<size_t>(c);
        }
        return hashValue % size;
    }

    int getNewIndex(int index) const {
        if (index + 1 < size) return index + 1;
        return hash("") % size;
    }
};

// Define a custom memory pool allocator class
class NFAPIAllocator {
public:
    NFAPIAllocator(size_t initialSize) : size(initialSize), memory(new char[size]) {}

    ~NFAPIAllocator() { delete[] memory; }

    void* allocate(size_t size) {
        for (size_t i = 0; i < size - 1; ++i) {
            if (memory[i] == '\0') {
                return &memory[i + 1];
            }
        }
        return nullptr;
    }

    void deallocate(void* ptr, size_t size) {
        char* address = static_cast<char*>(ptr);
        size_t offset = address - memory;
        for (size_t i = 0; i < size; ++i) {
            memory[offset + i] = '\0';
        }
    }

private:
    size_t size;
    char* memory;
};

