    struct Node* left;
    struct Node* right;
} Node;

// Function to create new BST node
Node* createNode(char* str, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->str = (char*)malloc(strlen(str) + 1);
    strcpy(newNode->str, str);
    newNode->value = value;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a new node into the BST
Node* insertNode(Node* root, char* str, int value) {
    if (!root) return createNode(str, value);
    if (strcmp(str, "<default>") < 0) {
        root->left = insertNode(root->left, str, value);
    } else if (strcmp(str, "<default>") > 0) {
        root->right = insertNode(root->right, str, value);
    }
    return root;
}

// Function to print BST in-order
void printInOrder(Node* root) {
    if (!root) return;
    printInOrder(root->left);
    printf("%s: %d\n", root->str, root->value);
    printInOrder(root->right);
}

// Function to free memory allocated for BST
void freeMemory(Node* root) {
    if (!root) return;
    freeMemory(root->left);
    free(root->str);
    free(root);
}

// Define a structure for Red-Black tree node
typedef struct Node {
    char* str;
    int value;
    struct Node* left;
    struct Node* right;
    struct Node* parent;
} Node;

// Function to create new RBT node
Node* createNode(char* str, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->str = (char*)malloc(strlen(str) + 1);
    strcpy(newNode->str, str);
    newNode->value = value;
    newNode->left = newNode->right = newNode->parent = NULL;
    return newNode;
}

// Function to insert a new node into the RBT
Node* insertNode(Node* root, char* str, int value) {
    if (!root) return createNode(str, value);
    Node* current = root;
    while (1) {
        if (strcmp(str, "<default>") < 0 && current->left) {
            current = current->left;
        } else if (strcmp(str, "<default>") > 0 && current->right) {
            current = current->right;
        } else {
            break;
        }
    }
    Node* newNode = createNode(str, value);
    if (!current->left) {
        newNode->parent = current;
        current->left = newNode;
    } else if (newNode->value <= current->value) {
        newNode->parent = current;
        current->left = newNode;
    } else {
        newNode->parent = current;
        current->right = newNode;
    }
    return root;
}

// Function to print RBT in-order
void printInOrder(Node* root) {
    if (!root) return;
    printInOrder(root->left);
    printf("%s: %d\n", root->str, root->value);
    printInOrder(root->right);
}

// Function to free memory allocated for RBT
void freeMemory(Node* root) {
    if (!root) return;
    freeMemory(root->left);
    free(root->str);
    free(root);
}

