#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct for the node of binary search tree
typedef struct Node {
    int key;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create new node with given key
Node* newNode(int key) {
    Node* temp = (Node*)malloc(sizeof(Node));
    temp->key = key;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

// Function for inserting a key in the binary search tree
void insertNode(Node** root, int key) {
    if (*root == NULL) {
        *root = newNode(key);
    } else if (key < (*root)->key) {
        insertNode(&((*root)->left), key);
    } else if (key > (*root)->key) {
        insertNode(&((*root)->right), key);
    }
}

// Function to search a key in the binary search tree
Node* searchNode(Node* root, int key) {
    if (root == NULL || root->key == key)
        return root;
    if (root->key > key)
        return searchNode(root->left, key);
    return searchNode(root->right, key);
}

// Define a struct for the node of red-black tree
typedef struct RBTNode {
    int key;
    struct RBTNode* left;
    struct RBTNode* right;
    struct RBTNode* parent;
} RBTNode;

// Function to create new node with given key
RBTNode* newRBTNode(int key) {
    RBTNode* temp = (RBTNode*)malloc(sizeof(RBTNode));
    temp->key = key;
    temp->left = NULL;
    temp->right = NULL;
    temp->parent = NULL;
    return temp;
}

// Function for inserting a key in the red-black tree
void insertRBTNode(RBTNode** root, int key) {
    RBTNode* newNode = newRBTNode(key);
    if (*root == NULL)
        *root = newNode;
    else {
        RBTNode* current = *root;
        while (1) {
            if (newNode->key < current->key) {
                if (current->left == NULL) {
                    newNode->parent = current;
                    current->left = newNode;
                    break;
                }
                current = current->left;
            } else {
                if (current->right == NULL) {
                    newNode->parent = current;
                    current->right = newNode;
                    break;
                }
                current = current->right;
            }
        }
    }
}

// Function to search a key in the red-black tree
RBTNode* searchRBTNode(RBTNode* root, int key) {
    if (root == NULL || root->key == key)
        return root;
    if (root->key > key)
        return searchRBTNode(root->left, key);
    return searchRBTNode(root->right, key);
}
