// Define a structure for Project objects
typedef struct {
    int project_id;
    double budget;
    char* start_date;
    char* status;
} Project;

// Function to manage the dynamic list of projects
Project** project_list = NULL; // Initialize an empty array
int project_count = 0;         // Initialize project count

void add_project(Project* new_project) {
    // Allocate memory for a new entry in the project list
    Project** new_entry = (Project**)malloc(sizeof(Project*));

    // Copy the new project data into the newly allocated space
    *new_entry = new_project;

    // Add the new entry to the existing project list
    if (project_list == NULL) {
        project_list = &new_entry; // Initialize the array with the new entry
    } else {
        // Find the last element in the current list and append the new entry after it
        Project** prev_last = project_list;
        while (*prev_last != NULL && (*prev_last + 1) != NULL) {
            prev_last = &((*prev_last + 1));
        }
        *prev_last = new_entry; // Update the last element to point to the new entry
    }

    project_count++;
}

void update_project(int project_id, Project* updated_project) {
    for (int i = 0; i < project_count; i++) {
        if (project_list[i]->project_id == project_id) {
            // Update the existing project with the new data
            project_list[i] = updated_project;
            return;
        }
    }
}

void remove_project(int project_id) {
    for (int i = 0; i < project_count; i++) {
        if (project_list[i]->project_id == project_id) {
            // Shift all subsequent projects up by one position to fill the gap
            Project** temp = project_list + i + 1;
            while (*temp != NULL && *temp + 1 != NULL) {
                *temp = *(temp + 1);
                temp++;
            }

            // Release memory for the removed project
            free(project_list[i]);
            project_list[i] = NULL; // Set the last element to null

            // Update the project list's length
            project_count--;
            return;
        }
    }
}

// Serialize the project list to a file (JSON format)
void serialize_projects(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        return; // Unable to write to the file
    }

    fprintf(file, "{\"projects\": [");
    for (int i = 0; i < project_count; i++) {
        fprintf(file, "{\"project_id\": %d, \"budget\": %.2f, \"start_date\": \"%s\", \"status\": \"%s\"},",
                project_list[i]->project_id,
                project_list[i]->budget,
                project_list[i]->start_date,
                project_list[i]->status);
    }
    fprintf(file, "]}");

    fclose(file);
}

// Deserialize the project list from a file (JSON format)
void deserialize_projects(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return; // Unable to read from the file
    }

    Project** new_project_list = NULL;
    int new_project_count = 0;

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Parse JSON data into a new project structure
        Project* new_project = malloc(sizeof(Project));
        sscanf(buffer, "{\"project_id\": %d, \"budget\": %.2f, \"start_date\": \"%s\", \"status\": \"%s\"}",
               &new_project->project_id,
               &new_project->budget,
               new_project->start_date,
               new_project->status);

        // Add the new project to the list
        add_project(new_project);
    }

    fclose(file);
}
