#include <openssl/chacha.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>

EVP_CIPHER_CTX* unified_cipher_config(const char *mode, const int key_size, const char *password, const unsigned char *salt, const int iterations) {
    EVP_CIPHER_CTX *cipher_ctx = OPENSSL_malloc(sizeof(EVP_CIPHER_CTX));
    if (!cipher_ctx) {
        ERR_error_fp(stderr, "Memory allocation failed.");
        return NULL;
    }

    // Select the encryption algorithm based on mode and key size
    EVP_CIPHER *cipher;
    switch (mode[0]) {
        case 'E':
            switch (key_size) {
                case 128:
                    cipher = EVP_aes_128_ecb();
                    break;
                case 192:
                    cipher = EVP_aes_192_ecb();
                    break;
                case 256:
                    cipher = EVP_aes_256_ecb();
                    break;
                default:
                    ERR_error_fp(stderr, "Invalid key size.");
                    OPENSSL_free(cipher_ctx);
                    return NULL;
            }
            break;
        case 'C':
            switch (key_size) {
                case 128:
                    cipher = EVP_aes_128_cbc();
                    break;
                case 192:
                    cipher = EVP_aes_192_cbc();
                    break;
                case 256:
                    cipher = EVP_aes_256_cbc();
                    break;
                default:
                    ERR_error_fp(stderr, "Invalid key size.");
                    OPENSSL_free(cipher_ctx);
                    return NULL;
            }
            break;
        case 'G':
            switch (key_size) {
                case 128:
                    cipher = EVP_chacha_20_gcm();
                    break;
                case 192:
                    cipher = EVP_chacha_20_192_gcm();
                    break;
                case 256:
                    cipher = EVP_chacha_20_256_gcm();
                    break;
                default:
                    ERR_error_fp(stderr, "Invalid key size.");
                    OPENSSL_free(cipher_ctx);
                    return NULL;
            }
            break;
        default:
            ERR_error_fp(stderr, "Invalid mode.");
            OPENSSL_free(cipher_ctx);
            return NULL;
    }

    // Initialize the cipher context
    if (!EVP_CIPHER_CTX_init(cipher_ctx)) {
        ERR_error_fp(stderr, "Cipher initialization failed.");
        OPENSSL_free(cipher_ctx);
        return NULL;
    }

    // Set the cipher mode and key size
    EVP_CIPHER_CTX_set_cipher(cipher_ctx, cipher);

    // Key derivation using PBKDF2
    unsigned char *derived_key = PBKDF2(password, salt, iterations, key_size/8, 0);
    if (!derived_key) {
        ERR_error_fp(stderr, "Key derivation failed.");
        OPENSSL_free(cipher_ctx);
        return NULL;
    }

    // Set the derived key in the cipher context
    EVP_CIPHER_CTX_set_key_length(cipher_ctx, key_size);

    // Check integrity using HMAC-SHA256
    unsigned char *mac = HMAC_sha256(password, salt, iterations, key_size/8, 0);
    if (!mac) {
        ERR_error_fp(stderr, "HMAC calculation failed.");
        OPENSSL_free(cipher_ctx);
        return NULL;
    }

    // Set the MAC in the cipher context
    EVP_CIPHER_CTX_set_mac(cipher_ctx, mac);

    return cipher_ctx;
}
