#include <pthread.h>

#define MAX_ID_LENGTH 64
#define MIN_ID_LENGTH 8
#define NUM_THREADS 4
#define ID_ALPHABET_SIZE 52

typedef struct node {
    long* data;
    int key;
} Node;

Node* create_node_array(int num_nodes) {
    Node* nodes = (Node*) malloc(num_nodes * sizeof(Node));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].data = (long*) malloc(MAX_ID_LENGTH + 1);
        nodes[i].key = i;
    }
    return nodes;
}

void generate_id(Node* node, int length) {
    char* id = (char*) node->data;
    for (int i = 0; i < length; i++) {
        if (rand() % 2) { // 50% chance of uppercase
            id[i] = 'A' + rand() % ID_ALPHABET_SIZE;
        } else {
            id[i] = 'a' + rand() % ID_ALPHABET_SIZE;
        }
    }
    id[length] = '\0';
}

void* generate_id_thread(void* arg) {
    Node* node = (Node*) arg;
    int length = MIN_ID_LENGTH + rand() % (MAX_ID_LENGTH - MIN_ID_LENGTH);
    generate_id(node, length);
    return NULL;
}

int main() {
    int num_nodes = 1000; // adjust this for your use case
    Node* nodes = create_node_array(num_nodes);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        Node* node = &nodes[i * (num_nodes / NUM_THREADS)];
        pthread_create(&threads[i], NULL, generate_id_thread, node);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Release allocated resources
    for (int i = 0; i < num_nodes; i++) {
        free(nodes[i].data);
    }
    free(nodes);

    return 0;
}
