typedef enum {
    TYPE_A,
    TYPE_B
} EntryType;

typedef struct {
    void* data;
    unsigned int size;
    EntryType type;
} Entry;

Entry* create_entry_array(int count) {
    Entry* entries = (Entry*)malloc(count * sizeof(Entry));

    if (!entries) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        Entry entry;

        // Randomly determine the size within a specified range
        int min_size = 1024;
        int max_size = 1048576;
        int size = rand() % (max_size - min_size) + min_size;

        // Ensure sufficient memory for data allocation
        size_t available_memory = sysconf(_SC_PAGE_SIZE) * sysconf(_SC_PHYS_PAGES);
        if (size > available_memory / count)
            size = (int)(available_memory / count);

        entry.data = malloc(size);
        entry.size = size;
        entry.type = TYPE_A; // or TYPE_B

        if (!entry.data) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
    }

    for (int i = 0; i < count; i++) {
        Entry* entry = &entries[i];

        // Populate the data pointer with a unique sequence of random bytes
        srand(time(NULL) + i);
        char* byte = (char*)entry->data;
        for (unsigned int j = 0; j < entry->size; j++)
            byte[j] = (char)(rand() % 256);
    }

    return entries;
}

void free_entry_array(Entry* entries, int count) {
    for (int i = 0; i < count; i++) {
        Entry* entry = &entries[i];

        if (entry->data)
            free(entry->data);
    }

    free(entries);
}
