#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256
#define MIN_KEY_LENGTH 1
#define INITIAL_LIST_SIZE 1000

typedef struct {
    double value;
    char* key;
    int ref_count;
} entry_t;

entry_t** entries = NULL;
int list_size = 0;
int allocated_entries = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_entry(entry_t* e, const char* str) {
    pthread_mutex_lock(&lock);
    if (str != NULL && strlen(str) >= MIN_KEY_LENGTH && strlen(str) <= MAX_KEY_LENGTH) {
        int len = strlen(str);
        e->key = malloc(len + 1);
        memcpy(e->key, str, len);
        e->key[len] = '\0';
    } else {
        e->key = NULL;
    }
    pthread_mutex_unlock(&lock);
}

void* generate_key(void* arg) {
    char* format = (char*)arg;
    size_t len = strlen(format);

    char* buffer = malloc(len + 1);
    int i, j;

    for (i = 0; i < len; i++) {
        if (format[i] == '%') {
            int digit_count = format[i+1] - '0';
            int letter_count = format[i+2] - '0';

            for (j = 0; j < digit_count; j++) {
                buffer[buffer_length++] = '0' + rand() % 10;
            }

            for (j = 0; j < letter_count; j++) {
                buffer[buffer_length++] = 'a' + rand() % 26;
            }
        } else {
            buffer[buffer_length++] = format[i];
        }
    }

    buffer[buffer_length] = '\0';
    return buffer;
}

void* populate_keys(void* arg) {
    size_t i;

    for (i = 0; i < allocated_entries; i++) {
        if (!entries[i]->key) {
            char* key = generate_key(arg);
            initialize_entry(&entries[i][0], key);
            free(key);
        }
    }

    return NULL;
}

void* create_list(size_t size) {
    pthread_mutex_lock(&lock);

    entries = (entry_t**)malloc(sizeof(entry_t*) * size);
    list_size = size;
    allocated_entries = size;

    for (int i = 0; i < size; i++) {
        entries[i] = (entry_t*)malloc(sizeof(entry_t));
        entries[i]->value = 0.0;
        entries[i]->ref_count = 1;
        entries[i]->key = NULL;
    }

    pthread_mutex_unlock(&lock);

    return NULL;
}

void free_list() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < list_size; i++) {
        if (entries[i]->key) {
            free(entries[i]->key);
        }
        free(entries[i]);
    }

    free(entries);

    pthread_mutex_unlock(&lock);
}

entry_t* find_entry(const char* key) {
    pthread_mutex_lock(&lock);

    entry_t* result = NULL;

    for (int i = 0; i < list_size; i++) {
        if (strcmp(entries[i]->key, key) == 0) {
            entries[i]->ref_count++;
            result = &entries[i][0];
            break;
        }
    }

    pthread_mutex_unlock(&lock);

    return result;
}

void release_entry(entry_t* e) {
    pthread_mutex_lock(&lock);

    if (e->key) {
        free(e->key);
    }
    e->ref_count--;
    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));

    size_t list_size = INITIAL_LIST_SIZE;
    create_list(list_size);

    // Populate keys with a format string
    char* format = "%d%a";
    void* thread_arg = format;

    pthread_create(NULL, NULL, populate_keys, thread_arg);
    pthread_join(*thread_arg, NULL);

    // Example usage:
    entry_t* e1 = find_entry("key1");
    if (e1) {
        printf("%f - %s\n", e1->value, e1->key);
        release_entry(e1);
    }

    free_list();

    return 0;
}
