typedef struct {
    long* offset;
    int key;
} Record;

typedef struct {
    Record** records;
    int capacity;
    int size;
} DynamicList;

void initializeDynamicList(DynamicList* list, int capacity) {
    list->records = (Record**)malloc(capacity * sizeof(Record*));
    list->capacity = capacity;
    list->size = 0;
}

void insertRecord(DynamicList* list, Record record) {
    if (list->size == list->capacity) {
        // resize the list
        int newCapacity = list->capacity * 2;
        Record** newRecords = (Record**)realloc(list->records, newCapacity * sizeof(Record*));
        list->capacity = newCapacity;
        list->records = newRecords;
    }
    list->records[list->size] = &record;
    list->size++;
}

void deleteRecord(DynamicList* list, int key) {
    for (int i = 0; i < list->size; i++) {
        if (list->records[i]->key == key) {
            free(list->records[i]->offset);
            free(list->records[i]);
            Record** newRecords = (Record**)malloc((list->size - 1) * sizeof(Record*));
            int j = 0;
            for (int k = 0; k < list->size; k++) {
                if (k != i) {
                    newRecords[j] = list->records[k];
                    j++;
                }
            }
            free(list->records);
            list->records = newRecords;
            list->size--;
            return;
        }
    }
}

void resizeList(DynamicList* list, int capacity) {
    int newCapacity = capacity * 2;
    Record** newRecords = (Record**)realloc(list->records, newCapacity * sizeof(Record*));
    list->capacity = newCapacity;
    list->records = newRecords;
}
