    }
    printf("Random number distribution: \n");
    // Run statistical tests or generate histograms here

    // Ensure total memory usage does not exceed a predefined threshold
    int total_memory_usage = *offset_values_size + *keys_size + *records_num * sizeof(record_t);
    if (total_memory_usage > 1000000) {
        printf("Error: Total memory usage exceeded the threshold.\n");
    } else {
        printf("Total memory usage within the threshold.\n");
    }

    // Implement a sophisticated memory management strategy
    int current_offset_values_size = *offset_values_size;
    int current_keys_size = *keys_size;
    int current_records_num = *records_num;

    while (total_memory_usage > 1000000) {
        // Dynamically adjust array and record sizes to fit within the constraint
        current_offset_values_size /= 2;
        current_keys_size /= 2;
        current_records_num /= 2;

        // Re-allocate arrays with new sizes
        offset_values = (long*)realloc(offset_values, current_offset_values_size * sizeof(long));
        keys = (int*)realloc(keys, current_keys_size * sizeof(int));
        records = (record_t*)realloc(records, current_records_num * sizeof(record_t));

        // Initialize arrays with random values and buffer initialized to empty string
        for (int i = 0; i < current_offset_values_size; i++) {
            offset_values[i] = i;
        }
        for (int i = 0; i < current_keys_size; i++) {
            keys[i] = i;
        }
        for (int i = 0; i < current_records_num; i++) {
            records[i].value = rand() % (max - min + 1) + min;
            strcpy(records[i].buffer, "");
        }

        // Test quality of generated random numbers
        test_values = (int*)malloc(current_records_num * sizeof(int));
        for (int i = 0; i < current_records_num; i++) {
            test_values[i] = records[i].value;
        }
        printf("Random number distribution: \n");
        // Run statistical tests or generate histograms here

        total_memory_usage = current_offset_values_size + current_keys_size + current_records_num * sizeof(record_t);
