void init_hash_table(HashTable* hash_table, int initial_size) {
    hash_table->size = initial_size;
    hash_table->buckets = (Node**)malloc(initial_size * sizeof(Node*));
    for (int i = 0; i < initial_size; i++) {
        hash_table->buckets[i] = NULL;
    }
}

// Implement dynamic memory allocation and initialization
void hash_table_insert(HashTable* hash_table, int key, char* value) {
    int index = key % hash_table->size;
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->value = value;
    node->next = hash_table->buckets[index];
    hash_table->buckets[index] = node;

    // Resize the hash table if necessary
    int load_factor = 0.75; // adjust this value to balance between memory usage and performance
    if (hash_table->size * load_factor > hash_table->size) {
        hash_table->size *= 2;
        Node** new_buckets = (Node**)malloc(hash_table->size * sizeof(Node*));
        for (int i = 0; i < hash_table->size; i++) {
            new_buckets[i] = NULL;
        }
        for (int i = 0; i < initial_size; i++) {
            Node* current = hash_table->buckets[i];
            while (current) {
                int new_index = current->key % hash_table->size;
                if (!new_buckets[new_index]) {
                    new_buckets[new_index] = current;
                } else {
                    Node* next = current->next;
                    while (next) {
                        int next_index = next->key % hash_table->size;
                        if (!new_buckets[next_index]) {
                            new_buckets[next_index] = next;
                        } else {
                            next->next = new_buckets[next_index];
                            new_buckets[next_index] = next;
                        }
                        next = next->next;
                    }
                }
                current = current->next;
            }
        }
        free(hash_table->buckets);
        hash_table->buckets = new_buckets;
    }
}

