```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for key-value pairs
typedef struct {
    int id;
    char* string;
    double value;
} KVPair;

// Define the structure for the hash table
typedef struct {
    KVPair** buckets;
    int capacity;
    int size;
    int loadFactor;
    pthread_mutex_t mutex; // Mutex for thread safety
} HashTable;

// Function to initialize a new hash table with the given capacity and load factor
HashTable* createHashTable(int capacity, int loadFactor) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (KVPair**)calloc(capacity, sizeof(KVPair*));
    table->capacity = capacity;
    table->size = 0;
    table->loadFactor = loadFactor;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Function to insert a new key-value pair into the hash table
void insertHashTable(HashTable* table, int id, char* string, double value) {
    pthread_mutex_lock(&table->mutex); // Lock before insertion

    int index = id % table->capacity; // Calculate the bucket index using the hash function
    KVPair* pair = (KVPair*)malloc(sizeof(KVPair));
    pair->id = id;
    pair->string = string;
    pair->value = value;

    if (table->size / table->capacity > table->loadFactor) { // Check if the load factor exceeds the threshold
        resizeHashTable(table); // Resize the hash table if necessary
    }

    table->buckets[index] = pair; // Insert the new key-value pair into the bucket
    table->size++;

    pthread_mutex_unlock(&table->mutex); // Unlock after insertion
}

// Function to retrieve a key-value pair from the hash table
KVPair* getHashTable(HashTable* table, int id) {
    pthread_mutex_lock(&table->mutex); // Lock before retrieval

    int index = id % table->capacity; // Calculate the bucket index using the hash function

    KVPair* pair = table->buckets[index];
    while (pair != NULL && pair->id != id) {
        pair = pair->next;
    }

    pthread_mutex_unlock(&table->mutex); // Unlock after retrieval
    return pair;
}

// Function to resize the hash table based on real-time performance metrics
void resizeHashTable(HashTable* table) {
    int newCapacity = 2 * table->capacity; // Double the current capacity for resizing

    KVPair** oldBuckets = table->buckets;
    table->buckets = (KVPair**)calloc(newCapacity, sizeof(KVPair*));
    table->capacity = newCapacity;

    for (int i = 0; i < table->capacity; i++) {
        KVPair* pair = oldBuckets[i];
        while (pair != NULL) {
            int newIndex = pair->id % newCapacity;
            if (table->buckets[newIndex] == NULL) {
                table->buckets[newIndex] = pair;
            } else {
                pair->next = table->buckets[newIndex];
                table->buckets[newIndex] = pair;
            }
            pair = pair->next;
        }
    }

    free(oldBuckets);
}

// Function to log all operations performed on the hash table
void logHashTable(HashTable* table, int level) {
    // Implement logging mechanism here based on the given requirements
}
