```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <error.h>

// Define a structure to hold an int value
typedef struct {
    int value;
} record;

// Function to manage dynamic memory allocation and initialization
record** allocate_and_init_data_structures(int num_offsets, int num_keys, int num_records) {
    // Initialize error handling variables
    int* errors = NULL;
    size_t total_memory = 0;

    // Allocate memory for offset values array
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error allocating memory for offset values\n");
        return NULL;
    }
    total_memory += num_offsets * sizeof(long);

    // Initialize the offset values array
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i; // Initialize with default value
    }

    // Allocate memory for key values array
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error allocating memory for key values\n");
        free(offsets); // Deallocate previously allocated memory
        return NULL;
    }
    total_memory += num_keys * sizeof(int);

    // Initialize the key values array
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i; // Initialize with default value
    }

    // Allocate and initialize record structures array
    record** records = (record**)malloc(num_records * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Error allocating memory for record structures\n");
        free(offsets); // Deallocate previously allocated memory
        free(keys);
        return NULL;
    }
    total_memory += num_records * sizeof(record*);

    // Initialize the record structures array
    for (int i = 0; i < num_records; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Error allocating memory for record structure\n");
            free(offsets); // Deallocate previously allocated memory
            free(keys);
            for (int j = 0; j < i; j++) {
                free(records[j]); // Free the records array
            }
            return NULL;
        }
    }

    // Initialize the record structures array
    for (int i = 0; i < num_records; i++) {
        records[i]->value = rand() % 100; // Randomly initialize the record's int value
    }

    // Ensure total memory usage does not exceed a predefined threshold
    if (total_memory > THRESHOLD) {
        // Dynamically adjust array sizes to fit within the constraint
        num_offsets *= 2;
        num_keys *= 2;
        num_records *= 2;

        offsets = (long*)realloc(offsets, num_offsets * sizeof(long));
        keys = (int*)realloc(keys, num_keys * sizeof(int));
        records = (record**)realloc(records, num_records * sizeof(record*));

        for (int i = 0; i < num_records; i++) {
            records[i] = (record*)realloc(records[i], sizeof(record));
        }
    }

    return records;
}

// Function to deallocate all allocated memory
void deallocate_data_structures(record** records, int num_records) {
    // Deallocate record structures array
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);

    // Deallocate key values array
    free(keys);

    // Deallocate offset values array
    free(offsets);
}

// Example usage:
int main() {
    int num_offsets = 100;
    int num_keys = 50;
    int num_records = 200;

    record** records = allocate_and_init_data_structures(num_offsets, num_keys, num_records);

    // Use the allocated data structures...

    deallocate_data_structures(records, num_records);
}
