#include <math.h>

typedef struct {
    int timestamp;
    float reading;
    char tag;
} sensorData;

int processSensorData(int sensorCount, int recordCount, int threshold, float mean, float stddev) {
    // Allocate and initialize arrays
    float* readings = (float*)malloc(sensorCount * sizeof(float));
    char* tags = (char*)malloc(sensorCount * sizeof(char));

    for (int i = 0; i < sensorCount; i++) {
        readings[i] = (rand() / (float)RAND_MAX) * stddev + mean;
        tags[i] = 'A' + (i % 26);
    }

    // Allocate and initialize array of sensorData structures
    sensorData* data = (sensorData*)malloc(recordCount * sizeof(sensorData));

    for (int i = 0; i < recordCount; i++) {
        data[i].timestamp = i;
        data[i].reading = readings[rand() % sensorCount];
        data[i].tag = tags[rand() % sensorCount];
    }

    // Process sensor data stream
    float maxReading = -INFINITY;
    int maxTimestamp = -1;

    for (int i = 0; i < recordCount; i++) {
        if (data[i].reading > threshold) {
            // Filter out invalid readings
            continue;
        }
        // Apply moving average filter over last 10 samples
        float sum = 0.0;
        int count = 0;

        for (int j = Math.max(0, i - 9); j <= i; j++) {
            sum += data[j].reading;
            count++;
        }

        if (count > 0) {
            data[i].reading = sum / count;
        }
    }

    // Calculate performance metrics
    float avgReading = 0.0;

    for (int i = 0; i < recordCount; i++) {
        avgReading += data[i].reading;
    }

    printf("Average reading: %f\n", avgReading / recordCount);

    // Return maximum absolute value of sensor readings and corresponding timestamp
    float maxAbs = -INFINITY;

    for (int i = 0; i < recordCount; i++) {
        if (abs(data[i].reading) > maxAbs) {
            maxAbs = abs(data[i].reading);
            maxTimestamp = data[i].timestamp;
        }
    }

    printf("Maximum absolute value: %f at timestamp %d\n", maxAbs, maxTimestamp);

    // Deallocate memory
    free(readings);
    free(tags);
    free(data);

    return 0;
}
