int update_node(Node** head, int index, union {char *string; int number;} data) {
    if (*head == NULL || index < 0)
        return -1;

    Node* current = *head;
    for (int i = 0; i < index && current->next != NULL; i++)
        current = current->next;

    if (current->next == NULL)
        return -2;

    current->data = data;
    return 1;
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next = NULL;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}
