#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    union {
        char *string;
        int number;
    } value;
    struct node *next;
} Node;

Node *head = NULL;
Node *tail = NULL;
int size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_node(Node **head, Node **tail, Node *new_node) {
    pthread_mutex_lock(&lock);
    if (*head == NULL) {
        *head = new_node;
        *tail = new_node;
    } else {
        (*tail)->next = new_node;
        *tail = new_node;
    }
    size++;
    pthread_mutex_unlock(&lock);
}

void update_node(Node **head, Node **tail, int index, union { char *string; int number; } value) {
    pthread_mutex_lock(&lock);
    if (index < 0 || index >= size) {
        printf("Invalid node index for update.\n");
        return;
    }
    Node *node = (*head);
    for (int i = 0; i < index; i++) {
        node = node->next;
    }
    node->value.value = value;
    pthread_mutex_unlock(&lock);
}

void free_list(Node **head) {
    Node *curr = *head;
    Node *next;
    while (curr != NULL) {
        next = curr->next;
        free(curr);
        curr = next;
    }
    *head = NULL;
    size = 0;
}

int main() {
    // Example usage
    add_node(&head, &tail, malloc(sizeof(Node)));
    ((Node *)tail)->value.string = "Hello";
    add_node(&head, &tail, malloc(sizeof(Node)));
    ((Node *)tail)->value.number = 123;

    update_node(&head, &tail, 1, (union { char *string; int number; }){"World", 0});

    free_list(&head);

    return 0;
}
