        return NULL; // or handle error in a more meaningful way
    }

    // Allocate array of long integers for offsets
    long* offsets = malloc(num_records * sizeof(long));
    if (!offsets) return NULL;

    // Calculate the number of half-records
    int num_halfRecords = num_records / 2;
    if (num_halfRecords == 0) num_halfRecords = 1; // to avoid divide by zero

    // Allocate array of int keys for indexing specific records
    int* keys = malloc(num_halfRecords * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Calculate the total number of records including half-records
    int total_records = num_records + num_halfRecords;

    // Allocate array of struct record with size equal to total records
    record* rec_array = malloc(total_records * sizeof(record));
    if (!rec_array) {
        free(offsets);
        free(keys);
        return NULL;
