typedef struct {
    int key;
    long offset;
} Record;

Record* createRecords(int numRecords, int start, int end) {
    if (start > end) {
        fprintf(stderr, "Error: Start value must be less than or equal to end value.\n");
        return NULL;
    }

    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % (end - start + 1) + start;
        records[i].offset = rand() % (1000000 - 1 + 1) + 1;
    }

    return records;
}

void freeRecords(Record* records, int numRecords) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    int numRecords = 50000;
    int start = 0;
    int end = 100;

    Record* records = createRecords(numRecords, start, end);

    // Use the records

    freeRecords(records, numRecords);

    return 0;
}
