public class DistributedCache {
    private static final ObjectMapper mapper = new ObjectMapper(new Jaxb2JsonConfig().disableDefaultTyping());
    private static final ConcurrentHashMap<String, CustomObject> cache = new ConcurrentHashMap<>();
    private static AtomicInteger hitCount = new AtomicInteger(0);
    private static AtomicInteger missCount = new AtomicInteger(0);

    public static void initCache() {
        List<CustomObject> sampleData = new ArrayList<>();
        for (int i = 0; i < 1000; i++) {
            CustomObject obj = new CustomObject("key" + i, Math.random(), new ArrayList<String>());
            for (int j = 0; j < 10; j++) {
                obj.getList().add(String.valueOf(j));
            }
            sampleData.add(obj);
        }
        for (CustomObject obj : sampleData) {
            cache.put(obj.getKey(), obj);
        }
    }

    public static void main(String[] args) throws Exception {
        initCache();

        // Simulate concurrent access
        Thread thread1 = new Thread(() -> {
            for (int i = 0; i < 100; i++) {
                String key = "key" + (i % 10);
                CustomObject obj = cache.get(key);
                if (obj != null) {
                    hitCount.incrementAndGet();
                } else {
                    missCount.incrementAndGet();
                }
            }
        });
        thread1.start();

        Thread thread2 = new Thread(() -> {
            for (int i = 0; i < 100; i++) {
                String key = "key" + (i % 10);
                CustomObject obj = cache.get(key);
                if (obj != null) {
                    hitCount.incrementAndGet();
                } else {
                    missCount.incrementAndGet();
                }
            }
        });
        thread2.start();

        // Monitor and log metrics
        System.out.println("Cache Hit Rate: " + (double) hitCount.get() / (hitCount.get() + missCount.get()));
        System.out.println("Cache Miss Rate: " + (double) missCount.get() / (hitCount.get() + missCount.get()));

        // Test serialization and deserialization
        CustomObject obj = cache.get("key0");
        String json = mapper.writeValueAsString(obj);
        CustomObject deserializedObj = mapper.readValue(json, CustomObject.class);

        System.out.println("Serialization and Deserialization OK!");
    }
}
