#define RECORD_SIZE sizeof(record)
#define ALIGNMENT 16
#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

thread_local unsigned long random_seed = time(NULL);

void* alloc_aligned(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) return NULL;

    size_t offset = (size_t)ptr % ALIGNMENT;
    ptr = (void*)((size_t)ptr + ALIGNMENT - offset);
    return ptr;
}

void dealloc_aligned(void* ptr, size_t size) {
    size_t offset = ((size_t)ptr) % ALIGNMENT;
    ptr = (void*)((size_t)ptr - ALIGNMENT + offset);

    free(ptr);
}

record* alloc_records(int count) {
    record* records = NULL;

    if (count > 0) {
        size_t total_size = RECORD_SIZE * count;
        void* ptr = malloc(total_size);
        if (!ptr) return NULL;

        int i;
        for (i = 0; i < count - ((total_size + ALIGNMENT - 1) / ALIGNMENT); i++) {
            records = (record*)(((size_t)records + ALIGNMENT) % total_size);
            *records++ = (record){i};
        }

        dealloc_aligned(ptr, total_size);
    }

    return records;
}

int main() {
    int num_records = 100;
    int array_size = 10;

    record* records = alloc_records(num_records);

    for (int i = 0; i < num_records; i++) {
        printf("Record %d: %d\n", i, records[i].value);
    }

    dealloc_aligned(records, RECORD_SIZE * num_records);

    return 0;
}

