struct mem_pool {
    void* base;
    size_t size;
    void** blocks;
};

struct mem_pool* mp = NULL;

void* alloc(size_t size) {
    if (!mp) {
        mp = malloc(sizeof(struct mem_pool));
        mp->base = malloc(MAX_MEMORY_LIMIT);
        mp->size = MAX_MEMORY_LIMIT;
        mp->blocks = (void**)malloc((MAX_MEMORY_LIMIT / RECORD_SIZE + 1) * sizeof(void*));
        for (int i = 0; i < MAX_MEMORY_LIMIT / RECORD_SIZE + 1; i++)
            mp->blocks[i] = mp->base + i * RECORD_SIZE;
    }
    return mp->base + size;
}

void free_all() {
    if (mp) {
        free(mp->base);
        free(mp->blocks);
        free(mp);
        mp = NULL;
    }
}

