void* allocate_and_init(int size, int num_records) {
    // Allocate and initialize arrays for offset values and keys
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc((size + 7) / 8 * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize offset array with custom padding strategy
    for (int i = 0; i < size; i++) {
        offsets[i] = (i % 16 ? i * 16 + 15 : i * 16);
    }

    // Allocate and initialize array of record structures
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));

    if (!records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
