#include <stdlib.h>
#include <stdio.h>

// Define a node structure containing a double value and a pointer to the next node.
typedef struct Node {
    double value;
    struct Node* next;
} Node;

// Function to manage memory allocation and initialization for a linked list of nodes.
Node* initialize_list(int num_nodes) {
    Node* head = NULL; // Initialize the head of the list to NULL
    Node** tail = &head; // Create a pointer to the tail of the list

    // Dynamically allocate memory for each node
    for (int i = 0; i < num_nodes; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed. Exiting.\n");
            return NULL;
        }
        new_node->value = 0.0; // Initialize the node's value to 0.0
        *tail = new_node; // Update the tail of the list
        tail = &((*tail)->next); // Move the tail pointer to the next node
    }

    return head;
}

// Function to insert a new node at the head or tail of the list.
void insert_node(Node** head, Node* new_node) {
    if (!(*head)) { // If the list is empty, insert at the head
        *new_node = (*head);
        *head = new_node;
    } else { // Insert at the tail
        Node* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to delete a node from the list.
void delete_node(Node** head, Node* node_to_delete) {
    if (*head == node_to_delete) { // If the node is at the head
        *head = node_to_delete->next;
    } else { // Find the node and update the previous node's next pointer
        Node* current = *head;
        while (current->next && current->next != node_to_delete) {
            current = current->next;
        }
        if (current->next == node_to_delete) {
            current->next = node_to_delete->next;
        } else { // The node is not found in the list
            printf("Node not found. Exiting.\n");
            return;
        }
    }
}

// Function to free all allocated memory upon completion.
void finalize_list(Node* head) {
    Node* current = head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
}
