#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    double value;
    struct node* next;
} Node;

Node* linkedListInit(int numNodes) {
    if (numNodes <= 0)
        return NULL;

    Node* head = (Node*)malloc(sizeof(Node));
    Node* tail = head;
    for (int i = 1; i < numNodes; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->next = NULL;
        tail->next = newNode;
        tail = newNode;
    }
    return head;
}

void linkedListFree(Node* head) {
    Node* temp = head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
}

Node* linkedListInsertHead(Node* head, double value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = value;
    newNode->next = head;
    return newNode;
}

Node* linkedListInsertTail(Node* tail, double value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = value;
    newNode->next = NULL;
    tail->next = newNode;
    return newNode;
}

void linkedListDeleteHead(Node** headRef) {
    if (*headRef == NULL)
        return;

    Node* temp = *headRef;
    *headRef = (*headRef)->next;
    free(temp);
}

void linkedListDeleteTail(Node** tailRef, Node** headRef) {
    if (*tailRef == NULL || *headRef == NULL)
        return;

    Node* prev = *headRef;
    while (prev->next != *tailRef)
        prev = prev->next;
    free(*tailRef);
    *tailRef = prev->next;
}

void linkedListMonitor(Node* head, int numNodes) {
    printf("Linked List Status: \n");
    printf("Head: %p\n", head);
    printf("Tail: %p\n", getTail(head));
    printf("Number of Nodes: %d\n", numNodes);
    printf("Memory Usage: %lu bytes\n", sizeof(Node) * numNodes);
}

Node* getTail(Node* head) {
    Node* temp = head;
    while (temp->next != NULL)
        temp = temp->next;
    return temp;
}
