DataStruct* init_data_struct(int num_nodes) {
    DataStruct* data = (DataStruct*)malloc(sizeof(DataStruct));
    data->size = num_nodes;
    data->nodes = (Node**)calloc(num_nodes, sizeof(Node*));
    data->htEntries = (HTEntry**)calloc(100, sizeof(HTEntry*)); // Initialize with a default capacity
    pthread_mutex_init(&data->mutex, NULL);
    return data;
}

// Function to implement thread-safe linked list traversal
