    entry->node = node;
    entry->next = data->htEntries[index];
    data->htEntries[index] = entry;
}

// Function to resize the hash table
void resize_ht_table(DataStruct* data) {
    int new_capacity = data->htEntries[0]->next == NULL ? 100 : (int)(data->htEntries[0]->next->node->value * 2);
    HTEntry** new_entries = (HTEntry**)realloc(data->htEntries, sizeof(HTEntry*) * new_capacity);
    for (int i = 0; i < data->size; i++) {
        if (data->htEntries[i] != NULL) {
            Node* current = data->htEntries[i]->node;
            while (current != NULL) {
                int index = hash_function(current->value, data);
                HTEntry* entry = new_entries[index];
                while (entry->next != NULL) {
                    entry = entry->next;
                }
                entry->next = current;
                current = current->next;
            }
        }
    }
    free(data->htEntries);
    data->htEntries = new_entries;
}

// Function to optimize memory usage by reusing memory blocks that are freed
