// Structure to hold an integer record
typedef struct {
    int value;
} record;

void manageMemory(int* offsetSize, int* keySize, int* numRecords) {
    // Parameters for dynamic memory allocation and initialization
    int threshold = 10000; // Initial allocation exceeds this value will trigger reallocation
    int initialOffsetSize = *offsetSize;
    int initialKeySize = *keySize;
    int initialNumRecords = *numRecords;

    // Allocate memory for offset array and key array
    long* offsets = (long*)malloc(initialOffsetSize * sizeof(long));
    if (!offsets) {
        printf("Failed to allocate memory for offsets.\n");
        exit(1);
    }

    int* keys = (int*)malloc(initialKeySize * sizeof(int));
    if (!keys) {
        printf("Failed to allocate memory for keys.\n");
        exit(1);
    }

    // Initialize arrays
    for (int i = 0; i < initialOffsetSize; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < initialKeySize; i++) {
        keys[i] = i;
    }

    // Allocate memory for record array and initialize records
    record* records = (record*)malloc(initialNumRecords * sizeof(record));
    if (!records) {
        printf("Failed to allocate memory for records.\n");
        exit(1);
    }
    srand(time(NULL)); // Initialize random number generator with current time
    for (int i = 0; i < initialNumRecords; i++) {
        records[i].value = rand() % 100; // Set random value within range [0, 100]
    }

    // Monitor and log memory usage statistics
    printf("Maximum memory usage: %.2f MB\n", (*offsetSize + *keySize + *numRecords) / (1024.0));
    printf("Current memory usage: %.2f MB\n", sizeof(long) + sizeof(int) + initialNumRecords * sizeof(record) / (1024.0));

    // Deallocate allocated memory
    free(offsets);
