    // Allocate memory for offsets structures
    offsets* offsets_ptr = (offsets*)malloc(n * sizeof(offsets));
    if (!offsets_ptr) return 1; // Error: unable to allocate memory for offsets

    // Initialize each offsets structure's value to zero
