    keys* keys_ptr = (keys*)malloc(m * sizeof(keys));
    if (!keys_ptr) return 2; // Error: unable to allocate memory for keys

    // Initialize each keys structure's key to a random value between 0 and 100
    for (int i = 0; i < m; i++) {
