#include <stdlib.h>
#include <stdio.h>

typedef enum {
    COLUMN_DOUBLE,
    COLUMN_CHAR,
    COLUMN_TABLE
} ColumnType;

typedef struct column {
    void* value;
    ColumnType type;
    struct column* next;
} Column;

typedef struct row {
    Column** columns;
    int numColumns;
    struct row* next;
} Row;

typedef struct table {
    Row** rows;
    int numRows;
    struct table* next;
} Table;

Table* initTable(int numRows) {
    Table* table = (Table*)malloc(sizeof(Table));
    table->rows = (Row**)calloc(numRows, sizeof(Row*));
    table->numRows = numRows;
    return table;
}

Row* initRow() {
    Row* row = (Row*)malloc(sizeof(Row));
    row->columns = NULL;
    row->next = NULL;
    return row;
}

Column* initColumn(ColumnType type) {
    Column* column = (Column*)malloc(sizeof(Column));
    column->value = NULL;
    column->type = type;
    column->next = NULL;
    return column;
}

void freeTable(Table* table) {
    for(int i = 0; i < table->numRows; i++) {
        Row* row = table->rows[i];
        while(row != NULL) {
            Column* column = row->columns[0];
            while(column != NULL) {
                if(column->type == COLUMN_DOUBLE || column->type == COLUMN_CHAR) {
                    free(column->value);
                } else {
                    Table* subTable = (Table*)column->value;
                    freeSubTable(subTable);
                }
                Column* temp = column;
                column = column->next;
                free(temp);
            }
            row->columns = NULL;
            Row* tempRow = row;
            row = row->next;
            free(tempRow);
        }
    }
    free(table->rows);
    free(table);
}

void freeSubTable(Table* table) {
    for(int i = 0; i < table->numRows; i++) {
        Row* row = table->rows[i];
        while(row != NULL) {
            Column* column = row->columns[0];
            while(column != NULL) {
                if(column->type == COLUMN_DOUBLE || column->type == COLUMN_CHAR) {
                    free(column->value);
                } else {
                    Table* subTable = (Table*)column->value;
                    freeSubTable(subTable);
                }
                Column* temp = column;
                column = column->next;
                free(temp);
            }
            row->columns = NULL;
            Row* tempRow = row;
            row = row->next;
            free(tempRow);
        }
    }
    free(table->rows);
    free(table);
}

void printTable(Table* table) {
    for(int i = 0; i < table->numRows; i++) {
        Row* row = table->rows[i];
        printf("Row %d:\n", i);
        for(int j = 0; j < row->numColumns; j++) {
            Column* column = row->columns[j];
            if(column->type == COLUMN_DOUBLE) {
                printf("Column %d: %f\n", j, *(double*)column->value);
            } else if(column->type == COLUMN_CHAR) {
                printf("Column %d: %s\n", j, (char*)column->value);
            } else {
                printSubTable((Table*)column->value);
            }
        }
    }
}

void printSubTable(Table* table) {
    for(int i = 0; i < table->numRows; i++) {
        Row* row = table->rows[i];
        printf("Row %d:\n", i);
        for(int j = 0; j < row->numColumns; j++) {
            Column* column = row->columns[j];
            if(column->type == COLUMN_DOUBLE) {
                printf("Column %d: %f\n", j, *(double*)column->value);
            } else if(column->type == COLUMN_CHAR) {
                printf("Column %d: %s\n", j, (char*)column->value);
            } else {
                printSubTable((Table*)column->value);
            }
        }
    }
}

int main() {
    Table* table = initTable(2);
    for(int i = 0; i < table->numRows; i++) {
        Row* row = initRow();
        table->rows[i] = row;
        // Add columns to the row
        row->columns = (Column**)calloc(3, sizeof(Column*));
        row->numColumns = 3;
        for(int j = 0; j < 3; j++) {
            if(j == 0) {
                row->columns[j] = initColumn(COLUMN_DOUBLE);
                *(double*)row->columns[j]->value = i + 1.5;
            } else if(j == 1) {
                row->columns[j] = initColumn(COLUMN_CHAR);
                (char*)row->columns[j]->value = "Hello";
            } else {
                Table* subTable = initTable(3);
                for(int k = 0; k < subTable->numRows; k++) {
                    Row* subRow = initRow();
                    subTable->rows[k] = subRow;
                    // Add columns to the sub-row
                    subRow->columns = (Column**)calloc(2, sizeof(Column*));
                    subRow->numColumns = 2;
                    for(int l = 0; l < 2; l++) {
                        if(l == 0) {
                            subRow->columns[l] = initColumn(COLUMN_DOUBLE);
                            *(double*)subRow->columns[l]->value = k + 1.5;
                        } else {
                            subRow->columns[l] = initColumn(COLUMN_CHAR);
                            (char*)subRow->columns[l]->value = "Goodbye";
                        }
                    }
                }
                row->columns[j] = initColumn(COLUMN_TABLE);
                row->columns[j]->value = subTable;
            }
        }
    }
    printTable(table);
    freeTable(table);
    return 0;
}

