#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* key;
    void* value;
} entry;

typedef struct {
    entry** buckets;
    int size;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} hash_table;

void* hash_table_init(int initial_capacity) {
    // Initialize the hash table with initial buckets
    hash_table* table = malloc(sizeof(hash_table));
    table->buckets = (entry**)malloc(initial_capacity * sizeof(entry*));
    for (int i = 0; i < initial_capacity; i++) {
        table->buckets[i] = NULL;
    }
    table->size = 0;
    table->capacity = initial_capacity;
    pthread_mutex_init(&table->mutex, NULL);
    pthread_cond_init(&table->cond, NULL);

    return table;
}

void hash_table_free(hash_table* table) {
    // Free the allocated memory
    for (int i = 0; i < table->capacity; i++) {
        free(table->buckets[i]);
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
    pthread_cond_destroy(&table->cond);

    free(table);
}

void hash_table_resize(hash_table* table, int new_capacity) {
    // Resize the buckets array and rehash all entries
    entry** new_buckets = (entry**)malloc(new_capacity * sizeof(entry*));
    for (int i = 0; i < new_capacity; i++) {
        new_buckets[i] = NULL;
    }

    pthread_mutex_lock(&table->mutex);
    for (int i = 0; i < table->capacity; i++) {
        entry* entry = table->buckets[i];
        while (entry != NULL) {
            int index = hash(entry->key, new_capacity) % new_capacity;
            if (new_buckets[index] == NULL) {
                new_buckets[index] = entry;
            } else {
                // Rehash the entry
                entry = entry->next;
            }
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;

    pthread_mutex_unlock(&table->mutex);
}

int hash_table_insert(hash_table* table, char* key, void* value) {
    // Calculate the index for the given key
    int index = hash(key, table->capacity) % table->capacity;
    entry* entry = (entry*)malloc(sizeof(entry));
    entry->key = key;
    entry->value = value;

    pthread_mutex_lock(&table->mutex);
    if (table->buckets[index] == NULL) {
        table->buckets[index] = entry;
    } else {
        // Hash collision, find the next available slot
        entry* prev = table->buckets[index];
        while (prev->next != NULL) {
            prev = prev->next;
        }
        prev->next = entry;
    }

    table->size++;
    pthread_mutex_unlock(&table->mutex);

    if (table->size > 0.75 * table->capacity) {
        // Resize the hash table
        int new_capacity = table->capacity * 2 + 1;
        hash_table_resize(table, new_capacity);
    }

    return 0;
}

void* hash_table_get(hash_table* table, char* key) {
    // Calculate the index for the given key
    int index = hash(key, table->capacity) % table->capacity;

    pthread_mutex_lock(&table->mutex);
    entry* entry = table->buckets[index];
    while (entry != NULL && strcmp(entry->key, key) != 0) {
        entry = entry->next;
    }
    if (entry == NULL || entry->value == NULL) {
        // Not found or value is null
        pthread_mutex_unlock(&table->mutex);
        return NULL;
    }

    pthread_mutex_unlock(&table->mutex);

    return entry->value;
}

int hash(const char* key, int capacity) {
    // Implement a simple hash function using the Djb2 algorithm
    unsigned long hash = 5381;
    const char* p = (const char*)key;
    while (*p != '\0') {
        hash = ((hash << 5) + *p) % capacity;
        p++;
    }
    return (int)hash;
}
