LinkedList* initLinkedList(int initialSize) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    // Allocate memory for initial nodes
    Node** nodes = (Node**)malloc(initialSize * sizeof(Node*));
    for (int i = 0; i < initialSize; i++) {
        nodes[i] = NULL;
    }
    list->nodes = nodes;
    return list;
}

// Function to insert a new node at the end of the linked list
void insertNode(LinkedList* list, double value, void* userData) {
    // Check if the list needs to be resized
    if (list->size == list->head->nodes->length) {
        // Resize the list by allocating more memory for nodes
        Node** newNodes = (Node**)malloc(list->head->nodes->length * 2 * sizeof(Node*));
        memcpy(newNodes, list->head->nodes, list->head->nodes->length * sizeof(Node*));
        free(list->head->nodes);
        list->head->nodes = newNodes;
    }

    // Create a new node and add it to the end of the list
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = value;
    newNode->userData = userData;
    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;
}

// Function to remove a node from the linked list
void removeNode(LinkedList* list, Node* node) {
    // Update the head and tail pointers if necessary
    if (node == list->head) {
        list->head = node->next;
    }
    if (node == list->tail) {
        list->tail = node->prev;
    }

    // Free the memory allocated for the node
    free(node);
}

// Function to traverse the linked list and process each node
void traverseLinkedList(LinkedList* list, void (*processNode)(Node*)) {
    Node* current = list->head;
    while (current) {
        processNode(current);
        current = current->next;
    }
}
