// Initialize an AES-256-CBC cipher with a given password
void* init_aes_cipher(const char* password, int password_len) {
    // Create the encryption key using a KDF instead of SHA-1
    unsigned char key[32];
    EVP_BytesToKey(EVP_aes_256_cbc(), NULL, (unsigned char*)password, password, password_len, 64, key, sizeof(key));

    // Initialize the AES cipher context
    void* cipher_ctx = EVP_CipherInit(EVP_aes_256_cbc(), key, 32);
    if (!cipher_ctx) {
        return NULL;
    }

    // Set the IV length to 16 bytes and the key length to 32 bytes
    EVP_CIPHER_CTX_set_iv_length(cipher_ctx, 16);
    EVP_CIPHER_CTX_set_key_length(cipher_ctx, 32);

    return cipher_ctx;
}

// Clean up the AES cipher context when it is no longer needed
void cleanup_aes_cipher(void* cipher_ctx) {
    if (cipher_ctx) {
        EVP_CipherFinalize((EVP_CIPHER_CTX*)cipher_ctx);
        OPENSSL_free(cipher_ctx);
    }
}

