pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && size > 0) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void* my_realloc(void* ptr, size_t size) {
    void* new_ptr = realloc(ptr, size);
    if (new_ptr == NULL && size > 0) {
        printf("Re-allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    free(ptr);
    return new_ptr;
}

void grow_arrays() {
    pthread_mutex_lock(&mutex);

    // Grow arrays
    current_size *= growth_rate;

    if (current_size > max_size) {
        max_size = current_size;
    }

    records = my_realloc(records, sizeof(record_t) * current_size);
    offsets = my_realloc(offsets, sizeof(long) * current_size);
    keys = my_realloc(keys, sizeof(int) * current_size);

    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize arrays
    records = my_malloc(sizeof(record_t) * PREALLOCATE);
    offsets = my_malloc(sizeof(long) * PREALLOCATE);
    keys = my_malloc(sizeof(int) * PREALLOCATE);

    for (uint32_t i = 0; i < PREALLOCATE; i++) {
        // Initialize data
        records[i].val = rand();
        offsets[i] = i;
        keys[i] = i;
    }

    while (1) {
        grow_arrays();
        printf("Current size: %u\n", current_size);
        sleep(2);  // Pause for 2 seconds
    }
}
