    if (!container) return NULL; // Allocation failed

    container->values = (double*)calloc(num_values, sizeof(double));
    if (!container->values) return NULL; // Allocation failed
    container->ids = (unsigned short*)calloc(num_ids, sizeof(unsigned short));
    if (!container->ids) return NULL; // Allocation failed
    container->entries = (data_entry**)calloc(num_ids, sizeof(data_entry*));
    if (!container->entries) return NULL; // Allocation failed

    for (int i = 0; i < num_ids; i++) {
        data_entry* entry = (data_entry*)malloc(sizeof(data_entry));
        if (!entry) return NULL; // Allocation failed
        container->entries[i] = entry;
        srand((unsigned int)i); // Initialize random number generator
        entry->value = (int)((double)rand() / RAND_MAX * (range_end - range_start + 1)) + range_start;
        entry->status = ' '; // Default status is whitespace
        clock_gettime(CLOCK_REALTIME, &entry->timestamp);
    }

    return container;
}
