#include <string.h>

typedef struct node {
    char *key;
    int value;
} Node;

typedef struct hash_table {
    Node **buckets;
    int size;
    int threshold;
} HashTable;

Node* create_node(const char* key, int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = strdup(key);
    node->value = value;
    return node;
}

int hash_function(const char* key, int table_size) {
    unsigned long hash = 0;
    for(int i = 0; i < strlen(key); i++) {
        hash = (hash * 31 + key[i]) % table_size;
    }
    return hash;
}

void resize_hash_table(HashTable* table, int new_size) {
    HashTable* new_table = (HashTable*)malloc(sizeof(HashTable));
    new_table->size = new_size;
    new_table->threshold = (int)(new_size * 0.7);
    new_table->buckets = (Node**)calloc(new_size, sizeof(Node*));

    for(int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while(node) {
            int index = hash_function(node->key, new_size);
            node->next = new_table->buckets[index];
            new_table->buckets[index] = node;
            node = node->next;
        }
    }

    free(table->buckets);
    *table = *new_table;
}

void insert_node(HashTable* table, const char* key, int value) {
    int index = hash_function(key, table->size);
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = strdup(key);
    node->value = value;

    if(table->buckets[index] == NULL) {
        table->buckets[index] = node;
    } else {
        Node* current = table->buckets[index];
        while(current->next) {
            current = current->next;
        }
        current->next = node;
    }

    if(table->size * 0.7 <= ++table->threshold) {
        resize_hash_table(table, table->size * 2);
    }
}

int main() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = 16;
    table->threshold = 11;
    table->buckets = (Node**)calloc(table->size, sizeof(Node*));

    insert_node(table, "key1", 1);
    insert_node(table, "key2", 2);
    // Add more nodes here...

    return 0;
}
