#include "random_library.h"

typedef struct {
    int value;
    char status;
    double timestamp;
} data_entry;

void initialize_data_container(int* array_size, int* range_start, int* range_end, int* threshold) {
    // Initialize memory pool allocator
    size_t initial_allocation = 1024 * 1024; // 1 MB
    void* memory_pool = malloc(initial_allocation);
    if (!memory_pool) {
        printf("Memory allocation failed. Exiting.\n");
        return;
    }

    // Dynamic array of double precision floating-point numbers
    int num_arrays = *array_size;
    double** arrays = (double**)malloc(num_arrays * sizeof(double*));
    for (int i = 0; i < num_arrays; i++) {
        arrays[i] = (double*)malloc(initial_allocation / num_arrays);
    }

    // Array of unsigned short identifiers
    unsigned short** ids = (unsigned short**)malloc(*array_size * sizeof(unsigned short*));
    for (int i = 0; i < *array_size; i++) {
        ids[i] = (unsigned short*)malloc(initial_allocation / (*array_size));
    }

    // Array of data_entry pointers
    data_entry** entries = (data_entry**)malloc(*array_size * sizeof(data_entry*));
    for (int i = 0; i < *array_size; i++) {
        entries[i] = (data_entry*)malloc(initial_allocation / (*array_size));
        entries[i]->value = rand() % (*range_end - *range_start + 1) + *range_start;
        entries[i]->status = 'A';
        entries[i]->timestamp = ((double)rand()) / RAND_MAX;
    }

    // Arrays for long offset values and int keys
    size_t max_offset = initial_allocation / sizeof(long);
    long** offsets = (long**)malloc(max_offset * sizeof(long*));
    for (int i = 0; i < max_offset; i++) {
        offsets[i] = (long*)malloc(initial_allocation / max_offset);
    }

    int** keys = (int**)malloc(max_offset * sizeof(int*));
    for (int i = 0; i < max_offset; i++) {
        keys[i] = (int*)malloc(initial_allocation / max_offset);
    }

    // Array of record structures
    size_t max_records = initial_allocation / sizeof(int);
    int** records = (int**)malloc(max_records * sizeof(int*));
    for (int i = 0; i < max_records; i++) {
        records[i] = (int*)malloc(initial_allocation / max_records);
    }

    // Initialize memory profiler
    size_t current_memory_usage = 0;
    size_t total_memory_allocation = 0;

    // Main loop
    while (1) {
        // Resize arrays and records based on threshold
        if (current_memory_usage > *threshold) {
            // Resize arrays
            for (int i = 0; i < num_arrays; i++) {
                arrays[i] = realloc(arrays[i], initial_allocation / (*array_size));
            }

            // Resize offset values and int keys
            max_offset = current_memory_usage;
            offsets = realloc(offsets, max_offset * sizeof(long*));
            for (int i = 0; i < max_offset; i++) {
                offsets[i] = realloc(offsets[i], initial_allocation / max_offset);
            }

            // Resize record structures
            max_records = current_memory_usage;
            records = realloc(records, max_records * sizeof(int*));
            for (int i = 0; i < max_records; i++) {
                records[i] = realloc(records[i], initial_allocation / max_records);
            }
        }

        // Perform garbage collection
        size_t reclaimed_memory = 0;
        for (int i = 0; i < num_arrays; i++) {
            free(arrays[i]);
        }
        for (int i = 0; i < *array_size; i++) {
            free(ids[i]);
        }
        for (int i = 0; i < *array_size; i++) {
            free(entries[i]);
        }
        for (int i = 0; i < max_offset; i++) {
            free(offsets[i]);
        }
        for (int i = 0; i < max_records; i++) {
            free(records[i]);
        }

        // Update memory profiler
        current_memory_usage -= reclaimed_memory;
        total_memory_allocation -= initial_allocation;

        printf("Memory usage: %zu bytes\n", current_memory_usage);
    }
}
