// Define the structure for an entry
typedef struct {
    char* key;
    double value;
} Entry;

// Define the node structure for the BST
typedef struct Node {
    Entry data;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new node with given entry
Node* createNode(Entry e) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = e;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Function to compare two entries based on their keys
int compareEntries(const Entry* e1, const Entry* e2) {
    return strcmp(e1->key, e2->key);
}

// Function to insert an entry into the BST while maintaining balance
Node* insertNode(Node* root, Entry newEntry) {
    if (root == NULL) {
        return createNode(newEntry);
    }

    int comparison = compareEntries(&newEntry, &root->data);

    if (comparison < 0) {
        root->left = insertNode(root->left, newEntry);
    } else if (comparison > 0) {
        root->right = insertNode(root->right, newEntry);
    } else { // Duplicate key found
        // Handle duplicate keys by storing multiple values for each key
        // For this example, we'll simply append the new value to the existing list
        Entry* entryList = (Entry*)realloc(root->data.key, sizeof(Entry));
        if (!entryList) {
            printf("Memory error\n");
            exit(1);
        }
        root->data.key = entryList;
        entryList[root->data.value] = newEntry.value;
    }

    // Update the balance factor and rebalance if necessary
    int balanceFactor = getHeight(root->left) - getHeight(root->right);

    if (balanceFactor > 1) {
        if (getHeight(root->left->left) >= getHeight(root->left->right)) {
            return rotateRight(root);
        } else {
            root->left = rotateLeft(root->left);
            return rotateRight(root);
        }
    } else if (balanceFactor < -1) {
        if (getHeight(root->right->right) >= getHeight(root->right->left)) {
            return rotateLeft(root);
        } else {
            root->right = rotateRight(root->right);
            return rotateLeft(root);
        }
    }

    return root;
}

// Function to rotate the BST to the right
Node* rotateRight(Node* node) {
    Node* temp = node->left;
    node->left = temp->right;
    temp->right = node;

    return temp;
}

// Function to rotate the BST to the left
Node* rotateLeft(Node* node) {
    Node* temp = node->right;
    node->right = temp->left;
    temp->left = node;

    return temp;
}

// Function to get the height of a subtree
int getHeight(Node* node) {
    if (node == NULL) {
        return 0;
    }
    return 1 + maxHeight(node->left, node->right);
}

// Recursive function to find the maximum height of a subtree
int maxHeight(Node* left, Node* right) {
    if (left == NULL && right == NULL) {
        return 0;
    } else if (left == NULL) {
        return getHeight(right);
    } else if (right == NULL) {
        return getHeight(left);
    }
    return 1 + (getHeight(left) > getHeight(right)) ? getHeight(left) : getHeight(right);
}

// Function to search for an entry in the BST
Entry* findEntry(Node* root, char* key) {
    if (root == NULL) {
        return NULL;
    }

    int comparison = compareEntries(&root->data, &createNode((Entry){key, 0}));

    if (comparison < 0) {
        return findEntry(root->left, key);
    } else if (comparison > 0) {
        return findEntry(root->right, key);
    } else { // Key found
        // Handle duplicate keys by returning the first entry with this key
        return &root->data;
    }
}

// Function to print the contents of the BST
void printBST(Node* root) {
    if (root == NULL) {
        printf("Empty BST\n");
        return;
    }

    printf("Printing BST...\n");

    // Traverse the BST in-order and print the entries
    traverseInOrder(root);
}

// Recursive function to traverse the BST in-order
void traverseInOrder(Node* node) {
    if (node == NULL) {
        return;
    }
    traverseInOrder(node->left);
    printf("%s, %f\n", node->data.key, node->data.value);
    traverseInOrder(node->right);
}

int main() {
    // Create a new BST
    Node* root = NULL;

    // Insert some entries into the BST
    Entry entry1 = {"key1", 10.0};
    Entry entry2 = {"key2", 20.0};
    Entry entry3 = {"key1", 30.0};  // Duplicate key

    root = insertNode(root, entry1);
    root = insertNode(root, entry2);
    root = insertNode(root, entry3);

    // Print the contents of the BST
    printBST(root);

    return 0;
}
