#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    void* value;
    time_t timestamp;
    int reference_count;
} cache_entry;

typedef struct {
    int size;
    int capacity;
    cache_entry** entries;
} hash_table;

hash_table* init_hash_table(int size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->size = size;
    table->capacity = 1;
    table->entries = (cache_entry**)calloc(size, sizeof(cache_entry*));
    return table;
}

void resize_hash_table(hash_table* table) {
    int new_size = table->size * 2;
    cache_entry** new_entries = (cache_entry**)realloc(table->entries, new_size * sizeof(cache_entry*));
    for (int i = 0; i < table->size; i++) {
        new_entries[i] = table->entries[i];
    }
    free(table->entries);
    table->entries = new_entries;
    table->size = new_size;
}

void insert_cache_entry(hash_table* table, char* key, void* value) {
    int hash = custom_hash_function(key);
    cache_entry* entry = (cache_entry*)malloc(sizeof(cache_entry));
    entry->key = strdup(key);
    entry->value = value;
    entry->timestamp = time(NULL);
    entry->reference_count = 1;

    if (table->entries[hash]) {
        // Update existing entry
        table->entries[hash]->reference_count++;
    } else {
        // New entry
        table->entries[hash] = entry;
    }
}

void* get_cache_entry(hash_table* table, char* key) {
    int hash = custom_hash_function(key);
    cache_entry* entry = table->entries[hash];
    if (entry) {
        entry->reference_count--;
        return entry->value;
    } else {
        return NULL;
    }
}

void evict_lru_entry(hash_table* table, int max_capacity) {
    int least_recently_used = -1;
    time_t earliest_timestamp = time(NULL);

    for (int i = 0; i < table->size; i++) {
        cache_entry* entry = table->entries[i];
        if (entry && entry->timestamp > earliest_timestamp) {
            earliest_timestamp = entry->timestamp;
            least_recently_used = i;
        }
    }

    if (least_recently_used != -1) {
        free(table->entries[least_recently_used]);
        table->entries[least_recently_used] = NULL;
    }

    // Rebalance the hash table
    for (int i = 0; i < table->size; i++) {
        cache_entry* entry = table->entries[i];
        if (!entry) {
            continue;
        }
        int new_hash = custom_hash_function(entry->key);
        if (new_hash != i) {
            entry->timestamp = time(NULL); // Update timestamp
            table->entries[new_hash] = entry;
            table->entries[i] = NULL;
            break; // Found a suitable replacement
        }
    }

    // Resizing the hash table if necessary
    int current_size = 0;
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i]) {
            current_size++;
        } else {
            break;
        }
    }
    if (current_size > max_capacity) {
        resize_hash_table(table);
    }
}

void clear_cache(hash_table* table) {
    for (int i = 0; i < table->size; i++) {
        cache_entry* entry = table->entries[i];
        if (!entry) {
            continue;
        }
        free(entry->key);
        free(entry);
    }
    free(table->entries);
}

int custom_hash_function(char* key) {
