#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the maximum length of a unique identifier string
#define MAX_IDENTIFIER_LENGTH 256

// Define the record structure
typedef struct {
    int value;
    char* identifier;
} Record;

// Function to manage dynamic memory allocation and initialization
void manageMemory(int arraySize, int recordCount, int maxIdentifierLength, int minValue, int maxValue) {
    // Allocate arrays for offset values and keys
    long* offsets = alignedAlloc(arraySize * sizeof(long));
    int* keys = alignedAlloc(arraySize * sizeof(int));

    // Initialize arrays with dummy values
    for (int i = 0; i < arraySize; i++) {
        offsets[i] = -1;
        keys[i] = -1;
    }

    // Allocate and initialize array of record structures
    Record* records = alignedAlloc(recordCount * sizeof(Record));
    for (int i = 0; i < recordCount; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].identifier = malloc(maxIdentifierLength);
        sprintf(records[i].identifier, "%d", records[i].value);
    }

    // Print allocated memory usage
    printf("Allocated memory: %ld bytes\n", (long)(sizeof(long) * arraySize + sizeof(int) * arraySize + sizeof(Record) * recordCount));

    // Deallocate all allocated memory when the function returns
    atExit();
}

// Function to allocate memory aligned to cache line boundaries
void* alignedAlloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Function to deallocate all allocated memory when the function returns
void atExit() {
    free((long*)offsets);
    free(keys);
    for (int i = 0; i < recordCount; i++) {
        free(records[i].identifier);
    }
    free(records);
}
