#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

struct data {
    int integer;
    double decimal;
    char* string;
};

typedef struct node {
    struct data value;
    struct node* next;
    struct node* prev;
} Node;

Node* create_node(int integer, double decimal, char* string) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->value.integer = integer;
    new_node->value.decimal = decimal;
    new_node->value.string = string;
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

void insert_at_position(Node** head, int position, Node* node) {
    if (position == 0) {
        node->next = *head;
        (*head)->prev = node;
        *head = node;
    } else {
        Node* current = *head;
        for (int i = 0; i < position - 1; i++) {
            current = current->next;
        }
        node->next = current->next;
        node->prev = current;
        if (node->next) node->next->prev = node;
        else (*head)->next = node;
        current->next = node;
    }
}

void traverse_list(Node* head, void (*operation)(struct data*)) {
    Node* current = head;
    while (current != NULL) {
        operation(&current->value);
        current = current->next;
    }
}

void sort_list(Node** head, int (*comparator)(const struct data*, const struct data*)) {
    Node* current = *head;
    Node* previous = NULL;
    while (current != NULL) {
        previous = current;
        current = current->next;
    }

    for (Node* i = *head; i != NULL; i = i->next) {
        for (Node* j = i->next; j != NULL; j = j->next) {
            if (comparator(&i->value, &j->value) > 0) {
                struct data temp;
                temp.integer = i->value.integer;
                temp.decimal = i->value.decimal;
                temp.string = i->value.string;

                i->value.integer = j->value.integer;
                i->value.decimal = j->value.decimal;
                i->value.string = j->value.string;

                j->value.integer = temp.integer;
                j->value.decimal = temp.decimal;
                j->value.string = temp.string;
            }
        }
    }
}

int comparator(const struct data* a, const struct data* b) {
    return (a->integer > b->integer)? 1 : ((b->integer > a->integer)? -1 : 0);
}
