    *head = (Node*)malloc(sizeof(Node));
    if (!*head) return; // Handle memory allocation failure
    (*head)->data.value = 0;
    (*head)->data.score = 0.0;
    (*tail = (*head))->prev = NULL;
    for (int i = 1; i < size; i++) {
        Node* node = create_node((struct_data){i, 0.0});
        if (!node) return; // Handle memory allocation failure
        node->next = (*tail);
        node->prev = (*tail);
        (*tail)->next = node;
        (*head)->prev = &node;
    }
}

