    if (!new_node) return; // Handle memory allocation failure

    if (index == 0) {
        new_node->next = (*head);
        new_node->prev = NULL;
        (*head)->prev = &new_node;
        *head = new_node;
    } else if (index == 10) {
        new_node->prev = (*tail);
        new_node->next = NULL;
        (*tail)->next = &new_node;
        *tail = new_node;
