    char CRC_INDICATION_REL8_TAG[4]; // assuming 4 bytes for CRC flag
    time_t timestamp; // to track outdated entries
} nfaapi_crc_indication_pdu_t;

// Define the doubly-linked list structure
typedef struct {
    nfaapi_crc_indication_pdu_t* head;
    nfaapi_crc_indication_pdu_t* tail;
    int size;
