// Function to initialize and manage the data structures
crc_indication_list_t* init_crc_indication_list(int max_size) {
    crc_indication_list_t* list = (crc_indication_list_t*)malloc(sizeof(crc_indication_list_t));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    return list;
