// Function to add a new record to the list
void add_crc_indication_record(crc_indication_list_t* list, int key, long offset) {
    nfaapi_crc_indication_pdu_t* node = (nfaapi_crc_indication_pdu_t*)malloc(sizeof(nfaapi_crc_indication_pdu_t));
    node->RX_UE_INFORMATION_TAG = key;
    node->RNTI = rand(); // generate a random RNTI
    srand(time(NULL)); // ensure randomness
    for (int i = 0; i < 4; i++) {
        node->CRC_INDICATION_REL8_TAG[i] = (char)(rand() % 256); // generate a random CRC flag
    }
    node->timestamp = time(NULL);

    if (list->size == 0) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }

    list->size++;
}

// Function to remove outdated entries from the list
void purge_crc_indication_records(crc_indication_list_t* list, int max_size) {
    while (list->size > max_size) {
        nfaapi_crc_indication_pdu_t* node = list->head;
        if (node != NULL) {
            free(node);
            list->head = node->next;
            if (list->head == NULL)
                list->tail = NULL;
        }
        list->size--;
    }
}

// Function to traverse the list
void traverse_crc_indication_records(crc_indication_list_t* list) {
    nfaapi_crc_indication_pdu_t* node = list->head;
    while (node != NULL) {
        // perform operations on each record
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %s\n", node->RX_UE_INFORMATION_TAG, node->RNTI, node->CRC_INDICATION_REL8_TAG);
        node = node->next;
    }
}

// Function to free the data structures
