#include <sys/stat.h>
#include <dirent.h>

typedef struct {
    int field1;
    int field2;
    int field3;
} Record;

void process_directory(const char *dir_path) {
    DIR *dp;
    struct dirent *ent;
    dp = opendir(dir_path);
    if (dp == NULL)
        return;

    srand(time(NULL));
    long *offsets = malloc(10000 * sizeof(long));
    int *keys = malloc(10000 * sizeof(int));
    Record **records = malloc(10000 * sizeof(Record *));
    for (int i = 0; i < 10000; i++) {
        records[i] = malloc(sizeof(Record));
        (*records[i]).field1 = rand() % 100;
        (*records[i]).field2 = rand() % 200;
        (*records[i]).field3 = rand() % 300;
    }

    while ((ent = readdir(dp)) != NULL) {
        char filename[256];
        int num_non_numeric = 0;
        for (int i = 0; i < strlen(ent->d_name); i++) {
            if (!isdigit(ent->d_name[i])) num_non_numeric++;
        }
        int file_type_offset = 0;
        for (char *p = ent->d_name; *p && !isdigit(*p); p++)
            file_type_offset = (int) (p - ent->d_name);

        char new_extension[9];
        if (file_type_offset > 0) {
            strcpy(new_extension, &ent->d_name[file_type_offset]);
            for (int i = strlen(new_extension) - 1; i >= 0 && !isdigit(new_extension[i]); i--) {
                new_extension[i] = '\0';
                break;
            }
        } else
            strcpy(new_extension, "DAT");

        // Trim whitespace and leading special characters
        int new_length = 0;
        for (int i = 0; i < strlen(ent->d_name); i++) {
            if (!isspace(ent->d_name[i]) && !ispunct(ent->d_name[i]))
                ent->d_name[new_length++] = ent->d_name[i];
        }
        ent->d_name[new_length] = '\0';

        // Update checksum
        int checksum = 0;
        for (int i = 0; i < strlen(ent->d_name); i++)
            checksum += (int) ent->d_name[i];

        // Generate unique identifier
        char id[9];
        sprintf(id, "%x", checksum);
        strcpy(&ent->d_name[file_type_offset], id);

        // Update performance monitoring system
        int total_files = 0;
        int avg_processing_time = 0;

        printf("File processed: %s\n", ent->d_name);

        closedir(dp);
    }

    free(offsets);
    free(keys);
    for (int i = 0; i < 10000; i++) {
        free(records[i]);
        records[i] = NULL;
    }
    free(records);
}
