// Define a custom memory pool-based linked list class
class MemoryPoolLinkedList : public DoublyLinkedList {
private:
    MemoryPool memory_pool;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void insert(Record& record) {
        std::unique_lock<std::mutex> lock(mutex);
        Node* node = (Node*)memory_pool.allocate(sizeof(Node));
        if (!node) {
            // Handle allocation failure
        }
        node->record = record;
        node->prev = nullptr;
        node->next = head_;
        if (head_) {
            head_->prev = &node->record;
        } else {
            tail_ = &node->record;
        }
        head_ = node;
        lock.unlock();
        cv.notify_one();
    }

    void remove(Record& record) {
        std::unique_lock<std::mutex> lock(mutex);
        Node* current = head_;
        while (current) {
            if (&current->record == &record) {
                if (current->prev) {
                    current->prev->next = current->next;
                } else {
                    head_ = current->next;
                }
                if (current->next) {
                    current->next->prev = current->prev;
                } else {
                    tail_ = current->prev;
                }
                memory_pool.deallocate(current, sizeof(Node));
                break;
            }
            current = current->next;
        }
    }

private:
    Node* head_;
    Node* tail_;
};

