        auto it = map_.find(key);
        if (it == map_.end()) {
            map_[key] = Value{key, offset};
        }
    }

    Value get(int key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = map_.find(key);
        if (it != map_.end()) {
