        level = SEV_INFO;
    } else if (strcmp(tokens[2], "WARNING") == 0) {
        level = SEV_WARNING;
    } else if (strcmp(tokens[2], "ERROR") == 0) {
        level = SEV_ERROR;
    } else if (strcmp(tokens[2], "CRITICAL") == 0) {
        level = SEV_CRITICAL;
    }

    // Normalize message
    int len = strlen(line);
    char* msg = (char*)malloc(len + 1);
    strcpy(msg, line);
    msg[len] = '\0';
    msg = strtok_r(msg, " ", &line);

    // Check for invalid characters and provide feedback
    if (strchr(msg, '<') || strchr(msg, '>') || strchr(msg, '|')) {
        fprintf(stderr, "Invalid message: %s\n", msg);
        free(event);
        return;
