#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    char* id;
} Record;

Record* recordCollection = NULL;
size_t capacity = 0;
size_t size = 0;

void* malloc_or_die(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_or_die(void* ptr, size_t size) {
    if (free(ptr) != 0) {
        perror("free");
        exit(EXIT_FAILURE);
    }
}

Record* recordCollection_create(size_t numRecords, int minKey, int maxKey, size_t idLength) {
    Record* newRecs = malloc_or_die(numRecords * sizeof(Record));
    if (!newRecs) return NULL;

    for (size_t i = 0; i < numRecords; ++i) {
        Record* rec = &newRecs[i];
        rec->key = rand() % (maxKey - minKey + 1) + minKey;
        rec->id = malloc_or_die(idLength * sizeof(char));
        if (!rec->id) return NULL;

        memset(rec->id, '\0', idLength);
    }

    capacity = numRecords;
    size = numRecords;
    recordCollection = newRecs;
    return recordCollection;
}

void recordCollection_insert(Record* rec) {
    if (size >= capacity) {
        capacity *= 2;
        Record* newRecs = realloc_or_die(recordCollection, capacity * sizeof(Record));
        if (!newRecs) return;

        size_t i;
        for (i = 0; i < size; ++i) {
            newRecs[i] = recordCollection[i];
        }
        memset(&newRecs[size], '\0', capacity - size);
    }

    recordCollection[size++] = *rec;
}

Record* recordCollection_lookup(int key, char** id) {
    for (size_t i = 0; i < size; ++i) {
        if (recordCollection[i].key == key) {
            *id = recordCollection[i].id;
            return &recordCollection[i];
        }
    }

    return NULL;
}

void recordCollection_free() {
    for (size_t i = 0; i < size; ++i) {
        free_or_die(recordCollection[i].id, sizeof(char));
    }

    free_or_die(recordCollection, capacity * sizeof(Record));
}
