UserProfile** manage_user_profiles(size_t initial_size, size_t max_username_len, int min_rating, int max_rating) {
    // Allocate memory for the initial number of profiles
    UserProfile** profiles = (UserProfile**)malloc(initial_size * sizeof(UserProfile*));

    if (!profiles) return NULL;  // Handle out-of-memory error

    // Initialize each profile with default values
    for (size_t i = 0; i < initial_size; ++i) {
        profiles[i] = malloc(sizeof(UserProfile));
        if (!profiles[i]) return NULL;  // Handle out-of-memory error

        // Initialize rating and review count for the profile
        RatingStats stats;
        stats.rating = rand() % (max_rating - min_rating + 1) + min_rating;
        stats.review_count = rand();

        profiles[i]->user_id = i;
        strcpy(profiles[i]->username, "User");
        profiles[i]->stats = stats;
    }

    return profiles;
}

// Function to retrieve a user profile by ID
UserProfile* get_user_profile(UserProfile** profiles, size_t num_profiles, int target_id) {
    // Iterate over the array of user profiles
    for (size_t i = 0; i < num_profiles; ++i) {
        if (profiles[i]->user_id == target_id)
            return profiles[i];
    }
    return NULL;  // Profile not found
}

// Function to update a user profile's rating and review count
void update_user_profile(UserProfile** profiles, size_t num_profiles, int target_id, int new_rating, size_t new_review_count) {
    // Iterate over the array of user profiles
    for (size_t i = 0; i < num_profiles; ++i) {
        if (profiles[i]->user_id == target_id) {
            profiles[i]->stats.rating = new_rating;
            profiles[i]->stats.review_count = new_review_count;
            return;
        }
    }
}

// Function to free memory allocated for the user profile collection
void free_user_profiles(UserProfile** profiles, size_t num_profiles) {
    // Free each profile and then the array of profiles itself
    for (size_t i = 0; i < num_profiles; ++i)
        free(profiles[i]);
    free(profiles);
}
