typedef struct Record {
    int key;
    char* identifier;
} Record;

Record** manageRecordCollection(int numRecords, int minKey, int maxKey, int maxIdentifierLength) {
    Record** recordCollection = (Record**)malloc(sizeof(Record*) * numRecords);

    for(int i = 0; i < numRecords; i++) {
        recordCollection[i] = (Record*)malloc(sizeof(Record));
        recordCollection[i]->key = rand() % (maxKey - minKey + 1) + minKey;

        char* identifier = (char*)malloc((maxIdentifierLength+1)*sizeof(char));
        sprintf(identifier, "ID-%d", i);
        recordCollection[i]->identifier = identifier;
    }

    for(int i = 0; i < numRecords; i++) {
        MD5_CTX md5ctx;
        MD5_Init(&md5ctx);
        MD5_Update(&md5ctx, recordCollection[i]->identifier, strlen(recordCollection[i]->identifier));
        unsigned char* hashBytes = (unsigned char*)malloc(16 * sizeof(char));
        MD5_Final(hashBytes, &md5ctx);

        // Print the record key and identifier along with its MD5 hash
        printf("Record Key: %d\nIdentifier: %s\nMD5 Hash: ", recordCollection[i]->key, recordCollection[i]->identifier);
        for(int j = 0; j < 16; j++) {
            printf("%02x", hashBytes[j]);
        }
        free(hashBytes);
    }

    return recordCollection;
}
