// Define a function to allocate and initialize arrays for offset values and keys
void* init_arrays(int size, pthread_mutex_t* mutex) {
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));

    // Initialize the arrays with zeros
    memset(offsets, 0, size * sizeof(long));
    memset(keys, 0, size * sizeof(int));

    return malloc(sizeof(record) * size);
}

// Define a function to deallocate memory for arrays and records
void dealloc_memory(void* offsets, void* keys, void* records) {
    free((long*)offsets);
    free((int*)keys);
    free(records);
}

// Define the main function that manages dynamic memory allocation and initialization
void* manage_memory(int offset_size, int key_size, int record_count, pthread_mutex_t* mutex) {
    // Initialize arrays for offset values and keys
    void* array_ptr = init_arrays(offset_size, mutex);

    // Initialize an array of records
    record* records = (record*)array_ptr;
    memset(records, 0, record_count * sizeof(record));

