#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1000
#define MAX_RECORDS 5000
#define MEMORY_THRESHOLD (MAX_ARRAY_SIZE * sizeof(long) + MAX_RECORDS * sizeof(record))
#define RANDOM_RANGE 100

typedef struct {
    int value;
} record;

void manageMemory(int arraySize, int recordCount) {
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    // Allocate and initialize arrays
    if (arraySize > 0 && arraySize <= MAX_ARRAY_SIZE) {
        offsets = (long*)malloc(arraySize * sizeof(long));
        keys = (int*)malloc(arraySize * sizeof(int));

        if (!offsets || !keys) {
            printf("Memory allocation failed for arrays.\n");
            return;
        }
    } else {
        arraySize = (arraySize > 0 && arraySize <= MAX_ARRAY_SIZE) ? arraySize : MAX_ARRAY_SIZE;
        offsets = (long*)malloc(arraySize * sizeof(long));
        keys = (int*)malloc(arraySize * sizeof(int));

        if (!offsets || !keys) {
            printf("Memory allocation failed for arrays.\n");
            return;
        }
    }

    // Initialize arrays
    for (int i = 0; i < arraySize; i++) {
        offsets[i] = i * sizeof(long);
        keys[i] = i % RANDOM_RANGE;
    }

    // Calculate total memory usage and adjust allocations if necessary
    size_t totalMemoryUsage = (arraySize * sizeof(long) + arraySize * sizeof(int)) + (recordCount * sizeof(record));
    if (totalMemoryUsage > MEMORY_THRESHOLD) {
        printf("Total memory usage exceeds threshold. Adjusting allocations.\n");

        // Adjust array sizes to fit within the constraint
        int adjustedArraySize = (int)(MEMORY_THRESHOLD / (sizeof(long) + sizeof(int))) - 1;
        offsets = (long*)realloc(offsets, adjustedArraySize * sizeof(long));
        keys = (int*)realloc(keys, adjustedArraySize * sizeof(int));

        // Adjust record count to fit within the constraint
