#include <time.h>

typedef struct {
    int value;
} record;

record* initArraysAndRecords(int size, int numRecords) {
    // Initialize arrays for offset values and keys
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));

    // Initialize array of records
    record* records = (record*)malloc(numRecords * sizeof(record));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        offsets[i] = i * (size + 1);
        keys[i] = i % size;
    }

    // Initialize record values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100;
    }

    return records;
}

void manageMemory(record* records, int numRecords) {
    int totalMemUsage = sizeof(long) * size + sizeof(int) * size + sizeof(record) * numRecords;

    if (totalMemUsage > 1024 * 1024 * 10) { // Threshold for memory usage
        printf("Memory pressure detected. Adjusting sizes...\n");

        // Dynamically adjust array and record sizes to fit within the constraint
        size = (size + 1) / 2;
        numRecords = (numRecords + 1) / 2;

        free(offsets);
        free(keys);
        free(records);

        offsets = (long*)malloc(size * sizeof(long));
        keys = (int*)malloc(size * sizeof(int));
        records = (record*)malloc(numRecords * sizeof(record));
    }
}
