// Function to allocate and initialize a binary search tree (BST)
void* bst_init(int nodes) {
    // Allocate memory for the BST structure
    void* bst = malloc(sizeof(struct BST));
    if (!bst) return NULL;

    // Initialize the BST with the given number of nodes
    struct Node** nodes_array = calloc(nodes, sizeof(struct Node*));
    if (!nodes_array) {
        free(bst);
        return NULL;
    }

    for (int i = 0; i < nodes; i++) {
        nodes_array[i] = malloc(sizeof(struct Node));
        if (!nodes_array[i]) {
            for (int j = 0; j < i; j++)
                free(nodes_array[j]);
            free(bst);
            free(nodes_array);
            return NULL;
        }
    }

    // Initialize the BST structure
    ((struct BST*)bst)->nodes = nodes;
    ((struct BST*)bst)->root = nodes_array[0];
    ((struct BST*)bst)->size = 1;

    return bst;
}

