// Enum for cache state
enum cache_state { CACHE_IN_USE, CACHE_INVALIDATED };

// Function suite to manage dynamic memory allocation and initialization
void* init_cache_suite() {
    // Initialize hash table with initial capacity
    uint64_t* hash_table = (uint64_t*)malloc(1024 * sizeof(uint64_t));
    size_t hash_capacity = 1024;

    // Allocate and initialize cache records array
    cache_record* cache_records = (cache_record*)malloc(1000 * sizeof(cache_record));
    for (int i = 0; i < 1000; i++) {
        cache_records[i].tags = (uint32_t*)malloc(5000 * sizeof(uint32_t));
        cache_records[i].timestamps = (time_t*)malloc(30 * sizeof(time_t));

        // Initialize timestamp and tag values
        for (int j = 0; j < 30; j++) {
            cache_records[i].timestamps[j] = time(NULL) - (j % 60) * 60;
        }
        for (int j = 0; j < 5000; j++) {
            cache_records[i].tags[j] = rand() % 5000 + 1;
        }
    }

    // Initialize linked list of cache entries
    struct node* head = NULL;
    struct node* current = NULL;

    // Allocate and initialize cache entry structures
    for (int i = 0; i < 1000; i++) {
        cache_entry* entry = (cache_entry*)malloc(sizeof(cache_entry));
        if (!head) {
            head = entry;
            current = head;
        } else {
            current->next = entry;
            current = entry;
        }
    }

    // Initialize hash table with initial values
    for (int i = 0; i < 1024; i++) {
        hash_table[i] = rand() % 1000000 + 1;
    }

    return cache_records;
}

void cleanup_cache_suite(void* cache_suite) {
    // Deallocate cache records array and its contents
    for (int i = 0; i < 1000; i++) {
        free(cache_suite->cache_records[i].tags);
        free(cache_suite->cache_records[i].timestamps);
    }

    // Deallocate linked list of cache entries
    struct node* current = head;
    while (current) {
        struct node* next = current->next;
        free(current);
        current = next;
    }

    // Deallocate hash table
    for (int i = 0; i < 1024; i++) {
        free(&cache_suite->hash_table[i]);
    }
}

