typedef struct metadata {
    time_t last_update;
    int active;
    int reference_count;
} Metadata;

typedef struct item {
    int integer;
    double value;
    struct item* next;
    Metadata* metadata;
} Item;

Item* create_linked_list(int num_nodes) {
    srand(time(NULL));

    // Define a list of unique names
    const char** names = {"Alice", "Bob", "Charlie", "David", "Emily"};
    int num_names = sizeof(names)/sizeof(names[0]);

    Item* head = NULL;
    for (int i = 0; i < num_nodes; i++) {
        Item* new_node = malloc(sizeof(Item));
        new_node->integer = rand() % 100;
        new_node->value = (double)rand() / RAND_MAX;

        // Ensure uniqueness of the string names
        int name_index;
        for (name_index = 0; name_index < num_names; name_index++) {
            if (rand() % 2 == 0) {
                break;
            }
        }
        new_node->metadata = malloc(sizeof(Metadata));
        strcpy(new_node->metadata->last_update, names[name_index]);

        // Initialize metadata fields
        new_node->metadata->active = 1;
        new_node->metadata->reference_count = 0;

        if (head == NULL) {
            head = new_node;
        } else {
            Item* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    return head;
}
