Graph* init_graph(int num_frames, void (*log_func)(const char*), int (*compress_func)(int), void* (*malloc_func)(size_t), void (*free_func)(void*, size_t)) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->head = NULL;
    graph->tail = NULL;
    graph->num_frames = num_frames;
    graph->log_func = log_func;
    graph->compress_func = compress_func;
    graph->malloc_func = malloc_func;
    graph->free_func = free_func;
    return graph;
}

// Function to insert a new frame into the graph
void insert_frame(Graph* graph, int pixel_values, int resolution, long timestamp) {
    FrameNode* new_node = (FrameNode*)graph->malloc_func(sizeof(FrameNode));
    new_node->pixel_values = pixel_values;
    new_node->resolution = resolution;
    new_node->timestamp = timestamp;

    if (graph->head == NULL) {
        graph->head = new_node;
        graph->tail = new_node;
    } else {
        FrameNode* curr_tail = graph->tail;
        new_node->prev_frame = curr_tail;
        curr_tail->next_frame = new_node;
        graph->tail = new_node;
    }
}

// Function to delete a frame from the graph
void delete_frame(Graph* graph, int index) {
    if (index < 0 || index >= graph->num_frames)
        return; // Handle error

    FrameNode* curr = graph->head;
    for (int i = 0; i < index; i++) {
        curr = curr->next_frame;
    }

    if (curr == NULL)
        return; // Handle error

    if (index == 0) {
        graph->head = curr->next_frame;
    } else {
        FrameNode* prev_node = graph->head;
        for (int i = 0; i < index - 1; i++) {
            prev_node = prev_node->next_frame;
        }
        prev_node->next_frame = curr->next_frame;
    }

    if (index == graph->num_frames - 1) {
        graph->tail = curr->prev_frame;
    } else {
        FrameNode* next_node = curr->next_frame;
        curr->prev_frame->next_frame = next_node;
    }
}

// Function to traverse the graph
void traverse_graph(Graph* graph, void (*func)(FrameNode*)) {
    FrameNode* curr = graph->head;
    while (curr != NULL) {
        func(curr);
        curr = curr->next_frame;
    }
}

// Function to compress metadata for a frame
int compress_metadata(FrameNode* node) {
