// Function to manage dynamic memory allocation and initialization
void init_data_structures(int num_offsets, int num_records, size_t max_memory_usage) {
    // Allocate and initialize arrays for offset values and keys
    long* offsets = NULL;
    int* keys = NULL;
    int capacity = 0;

    while (capacity < num_offsets) {
        if ((void*)(&offsets + capacity) >= &keys[num_offsets]) {
            // Resize the arrays to accommodate more elements
            long* new_offsets = my_malloc((num_offsets + capacity) * sizeof(long));
            int* new_keys = my_malloc((num_offsets + capacity) * sizeof(int));

            if (!new_offsets || !new_keys) {
                // Handle memory allocation failure
                printf("Memory allocation failed\n");
                return;
            }

            memcpy(new_offsets, offsets, capacity * sizeof(long));
            memcpy(new_keys, keys, capacity * sizeof(int));

            my_free(offsets);
            my_free(keys);

            offsets = new_offsets;
            keys = new_keys;

            num_offsets += capacity;
        } else {
            // Allocate initial memory for arrays
            if (!offsets) {
                offsets = my_malloc(num_offsets * sizeof(long));
                keys = my_malloc(num_offsets * sizeof(int));

                if (!offsets || !keys) {
                    // Handle memory allocation failure
                    printf("Memory allocation failed\n");
                    return;
                }
            }

            capacity += num_offsets;
        }
    }

    // Initialize arrays with random values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 100;
    }

    // Allocate and initialize array of record structures
    record* records = NULL;
    capacity = 0;

    while (capacity < num_records) {
        if ((void*)(&records + capacity) >= &keys[num_offsets]) {
            // Resize the arrays to accommodate more elements
            record* new_records = my_malloc((num_records + capacity) * sizeof(record));

            if (!new_records) {
                // Handle memory allocation failure
                printf("Memory allocation failed\n");
                return;
            }

            my_free(records);

            records = new_records;
            num_records += capacity;
        } else {
            // Allocate initial memory for arrays
            if (!records) {
                records = my_malloc(num_records * sizeof(record));

                if (!records) {
                    // Handle memory allocation failure
                    printf("Memory allocation failed\n");
                    return;
                }
            }

            capacity += num_records;
        }
    }

    // Initialize record structures with random values and strings
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
        char* string = my_malloc(10);
        sprintf(string, "%c", 'a' + rand() % 26);

        records[i].string = string;
    }
}
