#include <fcntl.h>

// Define structure for record
typedef struct {
    int key;
    char* str;
} Record;

// Function to process input from text file and manage memory dynamically
void process_input(char* filename) {
    // Open file
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        printf("Error opening file\n");
        return;
    }

    // Read file line by line
    char line[1024];
    while (1) {
        read(fd, line, sizeof(line));
        if (line[strlen(line) - 1] == '\n') break;

        // Split line into offset and key
        long offset = atol(strtok(line, " "));
        int key = atoi(strtok(NULL, " "));

        // Allocate memory for arrays
        long* offsets = (long*) aligned_alloc(sizeof(long), sizeof(long) * 2);
        int* keys = (int*) aligned_alloc(sizeof(int), sizeof(int) * 2);

        // Initialize arrays
        offsets[0] = offset;
        offsets[1] = offset + 1;
        keys[0] = key;
        keys[1] = key;

        // Allocate memory for record structures
        Record* records = (Record*) aligned_alloc(sizeof(Record), sizeof(Record) * 2);

        // Initialize record structures
        for (int i = 0; i < 2; i++) {
            int random_int = rand() % 100;
            char* str = (char*) malloc(rand() % 50 + 1);
            sprintf(str, "%d", random_int);
            records[i].key = key;
            records[i].str = str;
        }
    }

    // Close file
    close(fd);

    // Print arrays and record structures
    for (int i = 0; i < 2; i++) {
        printf("Offset: %ld, Key: %d\n", offsets[i], keys[i]);
        printf("Record: key=%d, str='%s'\n", records[i].key, records[i].str);
    }

    // Free memory
    free(offsets);
    free(keys);
    for (int i = 0; i < 2; i++) {
        free(records[i].str);
    }
    free(records);

    return;
}

int main() {
    process_input("input.txt");
    return 0;
}
