    size_t total_size = sizeof(long) * num_records + sizeof(int) * num_records;

    // Align total size to cache line boundary (assuming 64-byte cache lines)
    size_t aligned_size = ((total_size + 63) / 64) * 64;

    // Allocate memory for two arrays
