    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    int offset_size = 1000;
    int key_size = 500;

    long* offsets = (long*)my_malloc(offset_size * sizeof(long));
    int* keys = (int*)my_malloc(key_size * sizeof(int));

    // Initialize the arrays
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = i;
    }

    int record_count = 100;

    record* records = (record*)my_malloc(record_count * sizeof(record));

    // Initialize and sort the records
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % 1000;
    }
    qsort(records, record_count, sizeof(record), (int(*)(const void*, const void*))compareTo);

    return 0;
}

int compareTo(const void* a, const void* b) {
    record* rec_a = (record*)a;
    record* rec_b = (record*)b;

    if (rec_a->value < rec_b->value) {
        return -1;
    } else if (rec_a->value > rec_b->value) {
        return 1;
    } else {
        return 0;
    }
}
