        generated_values[i] = rand() / (double)RAND_MAX;
    }

    // Simulate production environment
    int threshold = 1024 * 1024 * 10; // 10MB threshold
    size_t total_memory = sizeof(long) * size + sizeof(int) * size + sizeof(double) * size + sizeof(char*) * size;
    if (total_memory > threshold) {
        // Dynamically adjust array sizes to stay within the threshold
        size /= 2;
        offsets = realloc(offsets, size * sizeof(long));
        keys = realloc(keys, size * sizeof(int));
        values = realloc(values, size * sizeof(double));
