void manage_memory(int matrix_rows, int matrix_cols_float, int matrix_cols_double,
                   int num_vectors, int max_vector_length) {
    // Allocate and initialize float matrix
    float **float_matrix = (float **)malloc(matrix_rows * sizeof(float *));
    for (int i = 0; i < matrix_rows; i++) {
        float_matrix[i] = (float *)malloc(matrix_cols_float * sizeof(float));
        memset(float_matrix[i], 0, matrix_cols_float * sizeof(float));
    }

    // Allocate and initialize double matrix
    double **double_matrix = (double **)malloc(matrix_rows * sizeof(double *));
    for (int i = 0; i < matrix_rows; i++) {
        double_matrix[i] = (double *)malloc(matrix_cols_double * sizeof(double));
        memset(double_matrix[i], 0, matrix_cols_double * sizeof(double));
    }

    // Allocate memory for and initialize vector structures
    struct vector **vectors = (struct vector **)malloc(num_vectors * sizeof(struct vector *));
    for (int i = 0; i < num_vectors; i++) {
        vectors[i] = (struct vector *)malloc(sizeof(struct vector));
        vectors[i]->strings = (char **)malloc(max_vector_length * sizeof(char *));
        for (int j = 0; j < max_vector_length; j++) {
            vectors[i]->strings[j] = (char *)malloc(1024 * sizeof(char)); // reserve space for strings
        }
    }

    // Populate each vector with randomly generated char strings
    srand(time(NULL)); // seed random generator
    for (int i = 0; i < num_vectors; i++) {
        for (int j = 0; j < max_vector_length; j++) {
            int string_len = rand() % 10 + 1; // generate random length between 1 and 10
            char *random_string = generate_random_string(string_len);
            vectors[i]->strings[j] = random_string;
        }
    }

    // Check total memory usage and adjust if necessary
    size_t total_memory_usage = calculate_total_memory_usage(float_matrix, double_matrix, vectors);
    if (total_memory_usage > MEMORY_THRESHOLD) {
        // dynamically adjust sizes of matrices and vectors to fit within constraint
        float_matrix = resize_matrix(float_matrix, matrix_rows, matrix_cols_float);
        double_matrix = resize_matrix(double_matrix, matrix_rows, matrix_cols_double);
        vectors = resize_vector_array(vectors, num_vectors, max_vector_length);
    }

    // Free allocated memory
    for (int i = 0; i < matrix_rows; i++) {
        free(float_matrix[i]);
        free(double_matrix[i]);
    }
    free(float_matrix);
    free(double_matrix);

    for (int i = 0; i < num_vectors; i++) {
        for (int j = 0; j < max_vector_length; j++) {
            free(vectors[i]->strings[j]);
        }
        free(vectors[i]->strings);
