    srand(time(NULL));
    Record* head = NULL;
    for (int i = 0; i < numRecords; i++) {
        Record* record = (Record*) malloc(sizeof(Record));
        if (!head) {
            head = record;
        } else {
            record->next = head;
            head = record;
        }
        record->key = rand() % 100;
        record->numOffsets = rand() % 10 + 1;
        record->value = 0;
        record->offsets = (long*) malloc(record->numOffsets * sizeof(long));
        for (int j = 0; j < record->numOffsets; j++) {
            long offset = rand() % 1000000;
            while (j > 0 && offset == record->offsets[j-1]) {
                offset = rand() % 1000000;
            }
            record->offsets[j] = offset;
        }
    }
    return head;
}

void freeCollection(Record* head) {
    Record* current = head;
    Record* next;
    while (current != NULL) {
        next = current->next;
        for (int i = 0; i < current->numOffsets; i++) {
            free((void*) &current->offsets[i]);
        }
        free(current);
        current = next;
    }
}

