Record* create_record(int key, int value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->offsets = NULL;
    new_record->offset_count = 0;
    return new_record;
}

// Function to populate offset values with random numbers
void populate_offsets(Record* record, int min_offset, int max_offset) {
    if (record->offsets != NULL) {
        free(record->offsets);
    }
    record->offsets = (long*)malloc((record->offset_count + 1) * sizeof(long));
    for (int i = 0; i < record->offset_count; i++) {
        record->offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
    }
}

// Function to free memory allocated for records
void free_record(Record* record) {
    if (record->offsets != NULL) {
        free(record->offsets);
    }
    free(record);
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    Record* new_record = create_record(1, 0);

    populate_offsets(new_record, -10000, 10000);

    printf("Record key: %d\n", new_record->key);
    printf("Record value: %d\n", new_record->value);
    for (int i = 0; i < new_record->offset_count; i++) {
        printf("Offset %d: %ld\n", i, new_record->offsets[i]);
    }

    free_record(new_record);

    return 0;
}
