    char* start;
    char* end;
} MemoryPool;

// Define function to create a new memory pool
MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->size = size;
    pool->start = (char*)malloc(size);
    pool->end = pool->start + size;
    return pool;
}

// Define function to allocate memory from the pool
void* malloc_from_pool(MemoryPool* pool, size_t size) {
    void* ptr = (void*)((char*)pool->start + (rand() % (pool->size - size)));
    // Check if allocation is within bounds of the pool
    if ((size_t)(ptr - (char*)pool->start) > pool->size || (size_t)(ptr - (char*)pool->end) < 0) {
        printf("Allocation out of bounds!\n");
        return NULL;
    }
    return ptr;
}

// Define function to free memory from the pool
void free_from_pool(MemoryPool* pool, void* ptr) {
    // Check if deallocation is within bounds of the pool
    size_t ptr_offset = (size_t)(ptr - (char*)pool->start);
    if (ptr_offset > pool->size || ptr_offset < 0) {
        printf("Deallocation out of bounds!\n");
        return;
    }
    // Update the end pointer to mark the deallocated memory
    pool->end = ptr;
}

