// Define a hash function using the djb2 algorithm
unsigned long hash(const char* key, unsigned long table_size) {
    unsigned long hash = 5381;
    while (*key) {
        hash = ((hash << 5) + hash) ^ *key++;
    }
    return hash % table_size;
}

// Define a custom memory pool for managing dynamically allocated objects
typedef struct MemoryPool {
    void** entries;
    size_t capacity;
    size_t used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->entries = (void**)malloc(capacity * sizeof(void*));
    pool->capacity = capacity;
    pool->used = 0;
    return pool;
}

void free_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->used; i++) {
        free(pool->entries[i]);
    }
    free(pool->entries);
    free(pool);
}

// Define a hash table with dynamic resizing
