// Define a structure for the key-value pair
typedef struct {
    int id;
    char* string;
    struct kv_pair* next;
} kv_pair;

// Define a structure for the hash table
typedef struct {
    unsigned long long size;
    int capacity;
    kv_pair** buckets;
} hash_table;

// Function to create a new key-value pair
kv_pair* kv_pair_create(int id, char* string) {
    kv_pair* pair = (kv_pair*)malloc(sizeof(kv_pair));
    pair->id = id;
    pair->string = (char*)malloc(strlen(string) + 1);
    strcpy(pair->string, string);
    pair->next = NULL;
    return pair;
}

// Function to create a new hash table
hash_table* hash_table_create(int capacity) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->size = 0;
    table->capacity = capacity;
    table->buckets = (kv_pair**)calloc(capacity, sizeof(kv_pair*));
    return table;
}

// Function to insert a key-value pair into the hash table
void hash_table_insert(hash_table* table, kv_pair* pair) {
    unsigned long long index = pair->id % table->capacity;
    if(table->buckets[index] == NULL) {
        table->buckets[index] = (kv_pair*)malloc(sizeof(kv_pair));
        *table->buckets[index] = *pair;
    } else {
        kv_pair* current = table->buckets[index];
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = pair;
    }
}

// Function to retrieve a key-value pair from the hash table
kv_pair* hash_table_get(hash_table* table, char* string) {
    unsigned long long index = strlen(string);
    while(index < table->capacity && table->buckets[index] == NULL) {
        index++;
    }
    if(table->buckets[index] != NULL) {
        kv_pair* current = table->buckets[index];
        while(current->next != NULL) {
            if(strcmp(current->string, string) == 0) {
                return current;
            }
            current = current->next;
        }
        if(strcmp(current->string, string) == 0) {
            return current;
        }
    }
    return NULL;
}

// Function to delete a key-value pair from the hash table
void hash_table_delete(hash_table* table, char* string) {
    unsigned long long index = strlen(string);
    while(index < table->capacity && table->buckets[index] == NULL) {
        index++;
    }
    if(table->buckets[index] != NULL) {
        kv_pair* current = table->buckets[index];
        kv_pair* previous = NULL;
        while(current->next != NULL) {
            if(strcmp(current->string, string) == 0) {
                if(previous == NULL) {
                    table->buckets[index] = current->next;
                } else {
                    previous->next = current->next;
                }
                free(current);
                return;
            }
            previous = current;
            current = current->next;
        }
        if(strcmp(current->string, string) == 0) {
            if(previous == NULL) {
                table->buckets[index] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
        }
    }
}

// Define a structure for the bloom filter
typedef struct {
    unsigned long long size;
    int capacity;
    unsigned char* bits;
} bloom_filter;

// Function to create a new bloom filter
bloom_filter* bloom_filter_create(int capacity) {
    bloom_filter* filter = (bloom_filter*)malloc(sizeof(bloom_filter));
    filter->size = 0;
    filter->capacity = capacity;
    filter->bits = (unsigned char*)calloc(capacity, sizeof(unsigned char));
    return filter;
}

// Function to set a bit in the bloom filter
void bloom_filter_set_bit(bloom_filter* filter, unsigned long long index) {
    if(index < filter->capacity) {
        filter->bits[index] = 1;
    }
}

// Function to test membership for a key in the bloom filter
int bloom_filter_test_membership(bloom_filter* filter, char* string) {
    unsigned long long hash = strlen(string);
    int result = 0;
    while(hash < filter->capacity && !filter->bits[hash]) {
        hash++;
    }
    if(hash >= filter->capacity || filter->bits[hash]) {
        return 1; // Membership tested
    } else {
        return 0; // No membership found
    }
}

