    ser->format = format;
    ser->data = (char*)malloc(strlen(data) + 1);
    strcpy(ser->data, data);
    return ser;
}

// Function to deserialize key-value pairs
void serialization_deserialize(char* serialized_data) {
    // Deserialize logic here
}

