    kv_pair* pair = kv_pair_create(1, "hello");
    hash_table_insert(table, pair);
    kv_pair* retrieved = hash_table_get(table, "hello");
    if(retrieved != NULL) {
        printf("Retrieved key-value pair: %d - %s\n", retrieved->id, retrieved->string);
    } else {
        printf("Key not found\n");
    }
    hash_table_delete(table, "hello");
    bloom_filter* filter = bloom_filter_create(1000);
    bloom_filter_set_bit(filter, 500);
    int result = bloom_filter_test_membership(filter, "hello");
    if(result == 1) {
        printf("Membership tested: %s is in the bloom filter\n", "hello");
    } else {
        printf("%s is not in the bloom filter\n", "hello");
    }
    serialization* ser = serialization_create(0, "key-value pair data");
    serialization_deserialize(ser->data);
    return 0;
}
