#include <iostream>
#include <vector>
#include <map>
#include <random>

using namespace std;

class Character {
public:
    Character(int energy) : energy_(energy), cooldown_(0) {}
    int attack() {
        if (cooldown_ > 0) return -1; // Attack is on cooldown
        energy_ -= getAttackCost();
        cooldown_ = 9; // Set cooldown period
        return 1; // Successful attack
    }
    int getEnergy() const { return energy_; }
    void setEnergy(int energy) { energy_ = energy; }

private:
    int energy_;
    int cooldown_;

    int getAttackCost() {
        static vector<int> costs = {10, 20, 25, 30}; // Predefined attack costs
        random_device rd;
        mt19937 gen(rd());
        uniform_int_distribution<> dist(0, costs.size() - 1);
        return costs[dist(gen)];
    }
};

class CharacterPool {
public:
    void addCharacter(int energy) { characters_.emplace_back(energy); }
    int getEnergy(size_t index) const { return characters_[index].getEnergy(); }
    int attack(size_t index) { return characters_[index].attack(); }

private:
    vector<Character> characters_;
};

class RNG {
public:
    RNG(int seed, string distributionType) : seed_(seed), dist_(distributionType) {}
    int generate() {
        static random_device rd;
        mt19937 gen(rd());
        uniform_int_distribution<> dist(0, 100); // Uniform distribution between 0 and 100

        if (dist_ == "normal") {
            normal_distribution<> nd(mean_, stddev_);
            return nd(gen);
        } else {
            return dist(gen);
        }
    }

private:
    int seed_;
    string dist_;
    double mean_ = 50, stddev_ = 10; // Default normal distribution parameters
};

class MemoryPool {
public:
    void resize(int capacity) { data_.reserve(capacity); }
    template <typename T>
    void push(T&& item) { data_.emplace_back(forward<T>(item)); }

private:
    vector<void*> data_;
};
