Record* init_records(int initial_size) {
    int i;
    Record* records = (Record*)malloc(initial_size * sizeof(Record));
    for(i = 0; i < initial_size; i++) {
        records[i].offset = rand_long();
        records[i].key = rand_int(-1000000, 1000000);
        strcpy(records[i].identifier, "");
    }
    return records;
}

void resize_records(Record** records, int old_size, int new_size) {
    Record* temp = (Record*)malloc(new_size * sizeof(Record));
    memcpy(temp, *records, old_size * sizeof(Record));
    free(*records);
    *records = temp;
}

int search_record(Record* records, int size, int key) {
    int i;
    for(i = 0; i < size; i++) {
        if(records[i].key == key)
            return i;
    }
    return -1;
}

void free_records(Record** records, int size) {
    free(*records);
    *records = NULL;
}

int main() {
    // Example usage:
    int initial_size = 1000;
    Record* records = init_records(initial_size);

    // Insert some records
    for(int i = 0; i < 5000; i++) {
        // Check if the record already exists
        int index = search_record(records, initial_size, i);
        if(index == -1) {
            // If not, add a new record
            resize_records(&records, initial_size, initial_size + 1000);
            records[initial_size].offset = rand_long();
            records[initial_size].key = i;
            strcpy(records[initial_size].identifier, "record");
            initial_size += 1000;
        }
    }

    // Free the memory when done
    free_records(&records, initial_size);

    return 0;
}
