    int* keys = (int*)malloc(size * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Initialize records array
    record* records = (record*)malloc(size * sizeof(record));
    srand(time(NULL)); // seed random number generator

    for (int i = 0; i < size; i++) {
        records[i].value = rand() % maxRange;
    }

    return records;
}

void deallocateArraysAndRecords(record* records, long* offsets, int* keys) {
    free(records);
    free(offsets);
    free(keys);
}

void logMemoryUsage(const char* message, size_t memoryUsed) {
    // Implement logging mechanism here
    printf("%s: Memory usage = %zu bytes\n", message, memoryUsed);
}

record* manageDynamicMemoryAllocation(int arraySize, int recordCount, int maxRange) {
    record* records;
    long* offsets;
    int* keys;

    size_t totalMemoryUsage = 0;
    size_t initialMemoryUsage = arraySize * sizeof(long) + arraySize * sizeof(int);

    if (initialMemoryUsage > 1024 * 1024 * 10) { // adjust threshold as needed
        // Handle memory usage exceeding the limit
        arraySize /= 2; // reduce array sizes to half

        // Initialize arrays with reduced size
        offsets = (long*)malloc(arraySize * sizeof(long));
        keys = (int*)malloc(arraySize * sizeof(int));

        for (int i = 0; i < arraySize; i++) {
            offsets[i] = i;
            keys[i] = i;
        }

        // Initialize records with reduced size
        records = (record*)malloc(arraySize * sizeof(record));
        srand(time(NULL)); // seed random number generator

        for (int i = 0; i < arraySize; i++) {
            records[i].value = rand() % maxRange;
        }
    } else {
        // Allocate memory as initially planned
        offsets = (long*)malloc(arraySize * sizeof(long));
        keys = (int*)malloc(arraySize * sizeof(int));

        for (int i = 0; i < arraySize; i++) {
            offsets[i] = i;
            keys[i] = i;
        }

        // Initialize records with full size
        records = initializeArraysAndRecords(arraySize, maxRange);
    }

    totalMemoryUsage += initialMemoryUsage + arraySize * sizeof(record);

    logMemoryUsage("Initialization", totalMemoryUsage);

    // Set record values to random numbers within the specified range
    for (int i = 0; i < recordCount; i++) {
        records[i].value = rand() % maxRange;
    }

    logMemoryUsage("Random number generation", totalMemoryUsage + arraySize * sizeof(record));

    deallocateArraysAndRecords(records, offsets, keys);

    return NULL;
}
