// Node structure definition
typedef struct {
    int key;
    double *value;
} node;

// List structure definition
typedef struct {
    node **nodes;
    int size;
    int capacity;
} list;

// Initialize a new empty list
list* newList() {
    list* l = (list*)malloc(sizeof(list));
    l->size = 0;
    l->capacity = 2; // Initial capacity
    l->nodes = (node**)malloc(l->capacity * sizeof(node*));
    return l;
}

// Insert a new node into the list, ensuring no duplicates based on key value
void insertNode(list* l, int key, double value) {
    if (l->size == l->capacity) {
        // Resize the array when it reaches capacity
        l->nodes = (node**)realloc(l->nodes, (l->capacity *= 2) * sizeof(node*));
    }
    for (int i = 0; i < l->size; i++) {
        if (l->nodes[i]->key == key) {
            // Update the value if a duplicate node is found
            free(l->nodes[i]->value);
            l->nodes[i]->value = malloc(sizeof(double));
            *l->nodes[i]->value = value;
            return;
        }
    }
    // Create a new node and add it to the list
    node* newNode = (node*)malloc(sizeof(node));
    newNode->key = key;
    newNode->value = malloc(sizeof(double));
    *newNode->value = value;
    l->nodes[l->size++] = newNode;
}

// Traverse the list and print all key-value pairs
void printList(list* l) {
    for (int i = 0; i < l->size; i++) {
        printf("%d: %f\n", l->nodes[i]->key, *(l->nodes[i]->value));
    }
}

// Free memory allocated by the list and its nodes
void freeList(list* l) {
    for (int i = 0; i < l->size; i++) {
        free(l->nodes[i]->value);
        free(l->nodes[i]);
    }
    free(l->nodes);
    free(l);
}
