#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for node
typedef struct {
    int key;
    double* value;
} Node;

// Define the structure for list
typedef struct {
    Node** nodes;
    int size;
    pthread_mutex_t mutex;
} List;

// Function to create a new list
List* newList() {
    List* list = (List*)malloc(sizeof(List));
    list->nodes = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to insert a node into the list
void insertNode(List* list, int key, double value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->key = key;
    newNode->value = &value;

    pthread_mutex_lock(&list->mutex);

    // Double the size of the array if it's full
    if (list->size == list->nodes != NULL && list->nodes[0] != NULL) {
        int newSize = 2 * list->size;
        Node** newNodes = (Node**)realloc(list->nodes, newSize * sizeof(Node*));
        for (int i = list->size; i < newSize; i++) {
            newNodes[i] = NULL;
        }
        list->nodes = newNodes;
    }

    // Add the new node to the end of the array
    if (list->size == 0) {
        list->nodes = (Node**)malloc(sizeof(Node*));
    } else {
        Node** temp = (Node**)realloc(list->nodes, (list->size + 1) * sizeof(Node*));
        list->nodes = temp;
    }
    list->nodes[list->size] = newNode;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

// Function to delete a node from the list
void deleteNode(List* list, int key) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size; i++) {
        if (list->nodes[i]->key == key) {
            free(list->nodes[i]);
            for (int j = i + 1; j < list->size; j++) {
                list->nodes[j - 1] = list->nodes[j];
            }
            list->size--;
            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to reverse the list
void reverseList(List* list) {
    int start = 0;
    int end = list->size - 1;

    for (int i = 0; i < list->size / 2; i++) {
        Node* temp = list->nodes[start];
        list->nodes[start] = list->nodes[end];
        list->nodes[end] = temp;

        start++;
        end--;
    }
}

// Function to find the median value of all 'value' fields
double findMedian(List* list) {
    double values[list->size];

    for (int i = 0; i < list->size; i++) {
        values[i] = *(list->nodes[i]->value);
    }

    qsort(values, list->size, sizeof(double), NULL);

    if (list->size % 2 == 0) {
        return (values[list->size / 2 - 1] + values[list->size / 2]) / 2.0;
    } else {
        return values[list->size / 2];
    }
}

// Function to print all 'key-value' pairs in sorted order
void printList(List* list) {
    for (int i = 0; i < list->size; i++) {
        printf("%d: %f\n", list->nodes[i]->key, *(list->nodes[i]->value));
    }
}

// Function to compact the list periodically
void compactList(List* list) {
    // Implementation left out for brevity. This could involve moving nodes around in memory,
    // freeing up unused space, and so on.
}
