    long* offsets = (long*)malloc((num_offsets + 1) * sizeof(long));

    if (!offsets) {
        return; // Handle error: Memory allocation failed
    }

    // Initialize an array of int keys, where the number of keys is half the number of offset values, rounded down
    int* keys = (int*)malloc((num_offsets / 2 + 1) * sizeof(int));

    if (!keys) {
        free(offsets);
        return; // Handle error: Memory allocation failed
    }

    // Allocate memory for an array of record structures
    record_t* records = (record_t*)malloc(num_offsets * sizeof(record_t));

    if (!records) {
        free(offsets);
        free(keys);
        return; // Handle error: Memory allocation failed
    }

