typedef struct {
    int key;
    long offset;
    double timestamp;
} record;

record* allocate_records(int num_records, int seed);
void free_records(record** records);

record* allocate_records(int num_records, int seed) {
    if (seed == 0)
        srand(time(NULL));
    else
        srand(seed);

    record* records = (record*)malloc(num_records * sizeof(record));

    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].key = i;
        records[i].offset = rand() % ((1 << 31) - 1);
        records[i].timestamp = time(NULL);
    }

    return records;
}

void free_records(record** records) {
    if (!records || !*records)
        return;

    for (int i = 0; i < (*records)->size; i++) {
