                record->timestamp = time(NULL);
                // Insert the record into the linked list
                Node *new_node = (Node *)malloc(sizeof(Node));
                new_node->record = record;
                if(head == NULL) {
                    head = new_node;
                    tail = new_node;
                } else {
                    tail->next = new_node;
                    tail = new_node;
                }
            }
        }

        // Process the records
        for(Node *node = head; node != NULL; node = node->next) {
            printf("%d %ld\n", node->record->value, (long)node->record->timestamp);
            free(node->record);
