typedef struct {
    char* key;
    double value;
} Entry;

Entry** entries = NULL; // dynamic array of entry pointers
int numEntries = 0; // current number of entries
int capacity = 10; // initial allocation size

// lock for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(int newSize) {
    Entry** newEntries;

    if ((newEntries = realloc(entries, newSize * sizeof(Entry*))) == NULL) {
        printf("Error allocating memory.\n");
        return NULL;
    }

    entries = newEntries;

    // initialize newly allocated space with null pointers
    for (int i = numEntries; i < newSize; i++) {
        entries[i] = NULL;
    }

    return entries;
}

void* reallocateIfNeeded(int newSize) {
    if (newSize > capacity) {
        Entry** newEntries = allocateMemory(newSize);
        if (newEntries == NULL)
            return NULL;

        // copy contents from old array to the new one
        for (int i = 0; i < capacity; i++) {
            if (entries[i] != NULL) {
                entries[i]->key = strndup(entries[i]->key, strlen(entries[i]->key));
                newEntries[i] = entries[i];
            } else {
                newEntries[i] = NULL;
            }
        }

        free(entries);
        entries = newEntries;
        capacity = newSize;
    }

    return entries;
}

void populateEntries() {
    for (int i = 0; i < numEntries; i++) {
        Entry* entry = &entries[i][0];
        double value = i * 2.5 + 10.0; // calculated result based on index

        if (value > 100) {
            value = 100;
        } else if (value < -50) {
            value = -50;
        }

        entry->value = value;
    }
}

void printEntries() {
    for (int i = 0; i < numEntries; i++) {
        Entry* entry = &entries[i][0];
        printf("Key: %s, Value: %.2f\n", entry->key, entry->value);
    }
}

void* iterateAndPrint(void* arg) {
    int threadID = *(int*)arg;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < numEntries; i++) {
        Entry* entry = &entries[i][0];

        printf("Thread %d: Key - %s, Value - %.2f\n", threadID, entry->key, entry->value);
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    // allocate initial memory
    entries = (Entry**)malloc(capacity * sizeof(Entry*));

    for (int i = 0; i < capacity; i++) {
        entries[i] = (Entry*)malloc(sizeof(Entry));
        entries[i]->key = strndup("Key", 4);
    }

    numEntries = capacity;

    // populate the entries
    populateEntries();

    // iterate and print the entries concurrently from multiple threads
    pthread_t threads[5];
    int threadIDs[] = {0, 1, 2, 3, 4};

    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, iterateAndPrint, &threadIDs[i]) != 0) {
            printf("Error creating thread.\n");
            return -1;
        }
    }

    // wait for all threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
