    pthread_mutex_t lock;
} mem_pool_t;

// Function to initialize a random number generator
int init_rng();

// Function to generate a random integer within a specified range
int rng(int min, int max);

// Function to initialize record values with random integers
void init_record(record_t* rec, int min, int max);

