        keys = my_malloc(sizeof(int) * count);
    }

    if (!keys) {
        printf("Memory allocation failed for key array.\n");
        return NULL;
    }

    // initialize keys with random values
    srand(time(NULL));
    int i;
    for (i = 0; i < count; i++) {
        keys[i] = rand() % RANDOM_RANGE;
    }
    return keys;
}

