// Define a structure to represent nodes in the tree
typedef struct Node {
    char* data;
    struct Node* next;
} Node;

// Function to create and initialize a node with given data
Node* createNode(char* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        return NULL; // Handle memory allocation error
    }
    newNode->data = (char*)malloc(strlen(data) + 1);
    strcpy(newNode->data, data);
    newNode->next = NULL;
    return newNode;
}

// Function to populate nodes with unique substrings from the input string
void populateNodes(char* str, int numNodes, Node** nodes) {
    char* pstr = str;
    for (int i = 0; i < numNodes; i++) {
        int len = rand() % strlen(pstr) + 1;
        char* subStr = (char*)malloc(len);
        strncpy(subStr, pstr, len);
        subStr[len] = '\0';
        nodes[i] = createNode(subStr);
    }
}

// Function to perform depth-first traversal and record path lengths
void traverse(Node* root, int* pathLengths) {
    if (!root) return;
    int length = 1;
    Node* current = root;
    while (current->next) {
        current = current->next;
        length++;
    }
    *pathLengths += length;
}

// Function to manage memory and deallocate all allocated resources
void freeMemory(Node** nodes, int numNodes) {
    for (int i = 0; i < numNodes; i++) {
        if (nodes[i]) {
            free(nodes[i]->data);
            free(nodes[i]);
        }
    }
}

// Main function to demonstrate the dynamic memory management and traversal
int main() {
    char* inputStr = "This is a sample string for testing";
    int numNodes = 10; // Adjust the number of nodes based on performance requirements
    Node* nodes[numNodes];

    // Allocate and initialize nodes, populate them with unique substrings
    populateNodes(inputStr, numNodes, nodes);

    // Perform depth-first traversal to record path lengths
    int totalLength = 0;
    for (int i = 0; i < numNodes; i++) {
        traverse(nodes[i], &totalLength);
    }

    // Deallocate all allocated memory
    freeMemory(nodes, numNodes);

    printf("Total length of the tree: %d\n", totalLength);

    return 0;
}
