void traverse_tree(Node* root, int* path_lengths) {
    if (root == NULL) {
        return;
    }
    // Perform DFS traversal and update path lengths
    int current_path_length = 0;
    Node* current_node = root;
    while (current_node != NULL) {
        current_path_length++;
        current_node = current_node->next;
    }
    *path_lengths = current_path_length;
}

