typedef struct node {
    char* string;
    int weight;
    float score;
} Node;

Node* newNode(char* str, int w, float s) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->string = strdup(str);
    new_node->weight = w;
    new_node->score = s;
    return new_node;
}

void insert_node(Node** head, char* str, int w, float s) {
    Node* new_node = newNode(str, w, s);

    if (*head == NULL || (*head)->weight < w) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->weight <= w)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_node(Node** head, int w) {
    if (*head == NULL || (*head)->weight != w)
        return;

    Node* temp = *head;
    *head = (*head)->next;
    free(temp);
}

int main() {
    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100);

    int num_records = 10;  // Number of records to create
    int record_size = sizeof(struct record);
    struct record* records = (struct record*)malloc(num_records * record_size);

