        records[i].offset = dis(gen);
        records[i].key = i;
        records[i].value = (double)i / 10.0;

        // Allocate memory for the string and initialize it
        char* str = (char*)malloc(20 * sizeof(char));
        sprintf(str, "Record %d", i);

        records[i].string = str;
    }

    return 0;
}
