void manage_memory(int* double_array_size, int* char_array_size, int* element_array_size,
                    float* min_value, float* max_value, int* threshold) {
    // Allocate arrays
    double* doubles = (double*)malloc(*double_array_size * sizeof(double));
    char** chars = (char**)malloc(*char_array_size * sizeof(char*));
    element_t** elements = (element_t**)malloc(*element_array_size * sizeof(element_t*));

    // Initialize arrays
    for (int i = 0; i < *double_array_size; i++) {
        doubles[i] = rand() / (float)RAND_MAX;
    }
    for (int i = 0; i < *char_array_size; i++) {
        chars[i] = (char*)malloc(strlen("fixed_string") + 1);
        strcpy(chars[i], "fixed_string");
    }
    for (int i = 0; i < *element_array_size; i++) {
        elements[i] = (element_t*)malloc(sizeof(element_t));
        elements[i]->value = lerp(*min_value, *max_value, rand() / (float)RAND_MAX);
        elements[i]->flag = elements[i]->value > 0.5;
    }

    // Manage memory
    if (sizeof(double) * *double_array_size + sizeof(char*) * *char_array_size +
        sizeof(element_t*) * *element_array_size > *threshold) {
        int proportional_reduction = 2; // adjust this value based on your needs
        *double_array_size /= proportional_reduction;
        *char_array_size /= proportional_reduction;
        *element_array_size /= proportional_reduction;

        free(doubles);
        doubles = (double*)malloc(*double_array_size * sizeof(double));
        for (int i = 0; i < *double_array_size; i++) {
            doubles[i] = rand() / (float)RAND_MAX;
        }

        for (int i = 0; i < *char_array_size; i++) {
            free(chars[i]);
            chars[i] = (char*)malloc(strlen("fixed_string") + 1);
            strcpy(chars[i], "fixed_string");
        }

        for (int i = 0; i < *element_array_size; i++) {
            free(elements[i]);
            elements[i] = (element_t*)malloc(sizeof(element_t));
            elements[i]->value = lerp(*min_value, *max_value, rand() / (float)RAND_MAX);
            elements[i]->flag = elements[i]->value > 0.5;
        }
    }

    // Deallocate memory
    for (int i = 0; i < *char_array_size; i++) {
        free(chars[i]);
    }
    free(chars);

    for (int i = 0; i < *element_array_size; i++) {
        free(elements[i]);
    }
    free(elements);
    free(doubles);
}

float lerp(float min_value, float max_value, float x) {
    return min_value + (max_value - min_value) * x;
}
