void* manage_memory_and_cipher(size_t offset_size, size_t key_size, const char* password) {
    // Define maximum allowed size for arrays
    const size_t MAX_SIZE = 1024;

    // Check if sizes exceed the limit
    if (offset_size > MAX_SIZE || key_size > MAX_SIZE) {
        return NULL; // Handle error: allocation exceeds the limit
    }

