    EVP_CIPHER_CTX* ctx;
    if (!(ctx = EVP_CipherInit(EVP_aes_256_cbc(), NULL, NULL))) {
        return NULL; // Handle error: initialization failed
    }

    unsigned char password_hash[SHA1_DIGEST_LENGTH];
    SHA1((const uint8_t*)password, strlen(password), password_hash);

    if (!EVP_SemyourInit(ctx, password_hash)) {
        return NULL; // Handle error: key derivation failed
    }

    // Set IV length and key length
    EVP_CIPHER_CTX_set_iv_len(ctx, 16);
    EVP_CIPHER_CTX_set_key_len(ctx, 32);

    ctx = EVP_CipherStart(ctx); // Enable the cipher

    // Return a pointer to the cipher context
    return (void*)ctx;
}

