ComplexNode* init_complex_node_list(int size) {
    // Initialize list with a specified size and maximum allowed size
    int max_allowed_size = 1000; // Adjust according to your needs
    int node_size = sizeof(ComplexNode);

    if (size > max_allowed_size) {
        size = max_allowed_size;
    }

    ComplexNode* head = NULL;
    for (int i = 0; i < size; i++) {
        ComplexNode* new_node = malloc(node_size);
        if (!new_node) {
            // Handle memory allocation failure
            printf("Memory allocation failed. Reducing list size.\n");
            break;
        }

        // Initialize node index and set next node to NULL
        new_node->index = i;
        new_node->next = head ? head : NULL;
        new_node->prev = (head && i > 0) ? head->prev : NULL;

        if (!head) {
            head = new_node;
        } else if (!new_node->next) {
            // Set last node's prev to the previous one
            ComplexNode* temp = head;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = new_node;
            new_node->prev = temp;
        } else {
            head->next = new_node;
            new_node->prev = head;
            head = new_node;
        }
    }

    return head;
}

void free_complex_node_list(ComplexNode* head) {
    ComplexNode* current = head;
    while (current) {
        ComplexNode* temp = current->next;
        free(current);
        current = temp;
    }
}
