        doubles[i] = i;
    }
    for (int i = 0; i < num_char; i++) {
        chars[i] = (char*)malloc(strlen("hello") + 1);
        strcpy(chars[i], "hello");
    }
    for (int i = 0; i < num_point; i++) {
        points[i].x = i;
        points[i].y = i;
    }

    // Calculate the total memory usage
    int total_memory = sizeof(double) * num_double + sizeof(char*) * num_char + sizeof(point) * num_point;

    // Check if the threshold is exceeded and adjust sizes accordingly
    while (total_memory > MEMORY_THRESHOLD) {
        if (num_double > 0) {
            num_double /= 2;
            doubles = (double*)realloc(doubles, num_double * sizeof(double));
        }
        if (num_char > 0) {
            for (int i = 0; i < num_char; i++) {
                free(chars[i]);
            }
            num_char /= 2;
            chars = (char**)realloc(chars, num_char * sizeof(char*));
            for (int i = 0; i < num_char; i++) {
                chars[i] = (char*)malloc(strlen("hello") + 1);
                strcpy(chars[i], "hello");
            }
        }
        if (num_point > 0) {
            points = (point*)realloc(points, num_point / 2 * sizeof(point));
        }

        total_memory = sizeof(double) * num_double + sizeof(char*) * num_char + sizeof(point) * num_point;
    }

    // Allocate memory for and initialize records
    record* records = (record*)malloc(num_records * sizeof(record));

    // Initialize records
    for (int i = 0; i < num_records; i++) {
        records[i].value = i;
        records[i].str = chars[i % num_char];
        records[i].pt = points[i % num_point];
    }

    // Deallocate memory when the function returns
    free(doubles);
    for (int i = 0; i < num_char; i++) {
        free(chars[i]);
    }
    free(chars);
    free(points);
    free(records);

    return;
}

