// Structure for a record
typedef struct {
    int value;
} Record;

// Hash table structure
typedef struct {
    int* keys;
    long* offsets;
    Record** records;
    int size;
    int load_factor;
} HashTable;

// Function to initialize and manage memory for the hash table
HashTable* initialize_hash_table(int size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->load_factor = 0.75; // optimal load factor

    ht->keys = (int*)calloc(size, sizeof(int));
    ht->offsets = (long*)calloc(size, sizeof(long));

    ht->records = (Record**)calloc(size, sizeof(Record*));

    for (int i = 0; i < size; i++) {
        ht->records[i] = (Record*)malloc(sizeof(Record));
    }

    return ht;
}

// Function to insert a record into the hash table
void insert_record(HashTable* ht, int key, Record* record) {
    int index = key % ht->size;

    // Handle collision by linear probing
    while (ht->keys[index] != 0 && ht->keys[index] != key) {
        index = (index + 1) % ht->size;
    }

    ht->keys[index] = key;
    ht->offsets[index] = record;

    // Update load factor
    ht->load_factor += (record->value > 0 ? 1 : -1);
}

// Function to retrieve a record from the hash table
Record* get_record(HashTable* ht, int key) {
    int index = key % ht->size;

    while (ht->keys[index] != 0 && ht->keys[index] != key) {
        index = (index + 1) % ht->size;
    }

    return ht->offsets[index];
}

// Function to serialize the hash table to a file
void serialize(HashTable* ht, FILE* file) {
    // Serialize keys and offsets
    for (int i = 0; i < ht->size; i++) {
        fwrite(&ht->keys[i], sizeof(int), 1, file);
        fwrite(&ht->offsets[i], sizeof(long), 1, file);
    }

    // Serialize records
    for (int i = 0; i < ht->size; i++) {
        Record* record = ht->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
    }
}

// Function to deserialize the hash table from a file
HashTable* deserialize(FILE* file) {
    HashTable* ht = initialize_hash_table(16); // initial size

    // Deserialize keys and offsets
    for (int i = 0; i < ht->size; i++) {
        fread(&ht->keys[i], sizeof(int), 1, file);
        fread(&ht->offsets[i], sizeof(long), 1, file);
    }

    // Deserialize records
    for (int i = 0; i < ht->size; i++) {
        Record* record = ht->records[i];
        fread(&record->value, sizeof(int), 1, file);
    }

    return ht;
}

// Function to read initial key-value pairs from a CSV file
void read_csv_file(HashTable* ht, FILE* file) {
    char line[256];

    while (fgets(line, 255, file)) {
        int key = atoi(strtok(line, ","));
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = atoi(strtok(NULL, ","));

        insert_record(ht, key, record);
    }
}

int main() {
    // Initialize hash table with initial size
    HashTable* ht = initialize_hash_table(16);

    // Read initial key-value pairs from CSV file
    FILE* csv_file = fopen("data.csv", "r");
    read_csv_file(ht, csv_file);
    fclose(csv_file);

    // Serialize the hash table to a file
    FILE* serialize_file = fopen("serialized_data.bin", "wb");
    serialize(ht, serialize_file);
    fclose(serialize_file);

    return 0;
}
