#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a record
typedef struct {
    int value;
    char data;
} Record;

// Hash table node structure
typedef struct {
    Record *record;
    int key;
    struct {
        void* next;
    } collision;
} Node;

// Hash table structure
typedef struct {
    Node **table;
    int size;
    int capacity;
    int load_factor;
    pthread_mutex_t mutex;
} HashTable;

// Function to initialize and allocate memory for a hash table
HashTable* init_hash_table(int initial_size, int max_load_factor) {
    // Allocate memory for the hash table
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    // Set the initial size and capacity of the hash table
    table->size = initial_size;
    table->capacity = initial_size;
    table->load_factor = max_load_factor;

    // Initialize the mutex for thread safety
    pthread_mutex_init(&table->mutex, NULL);

    return table;
}

// Function to insert a record into the hash table
void insert_record(HashTable *table, int key, Record *record) {
    // Calculate the index of the bucket using the hash function
    unsigned long index = key % table->capacity;

    // Lock the mutex for thread safety
    pthread_mutex_lock(&table->mutex);

    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_unlock(&table->mutex);
        return;
    }

    node->record = record;
    node->key = key;

    // Handle collisions by chaining
    Node *current = table->table[index];
    while (current) {
        current = current->collision.next;
    }
    node->collision.next = current;
    table->table[index] = node;

    // Update the load factor and resize if necessary
    int load_factor = table->size / table->capacity;
    if (load_factor > 0.5 && table->size < 10000) {
        table->size *= 2;
        table->capacity *= 2;
        table->table = (Node**)realloc(table->table, table->capacity * sizeof(Node*));
        for (int i = 0; i < table->size; i++) {
            if (!table->table[i]) continue;
            Node *node = table->table[i];
            while (node) {
                node = node->collision.next;
                current = node;
            }
        }
    }

    pthread_mutex_unlock(&table->mutex);
}

// Function to deserialize the hash table from a file
HashTable* deserialize_hash_table(const char *filename, int *initial_size, int *max_load_factor) {
    // Open the file for reading
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    // Read the initial size and maximum load factor from the file
    fread(initial_size, sizeof(int), 1, file);
    fread(max_load_factor, sizeof(int), 1, file);

    // Allocate memory for the hash table
    HashTable *table = init_hash_table(*initial_size, *max_load_factor);
    if (!table) {
        fclose(file);
        return NULL;
    }

    // Read and insert records from the file into the hash table
    while (1) {
        int key;
        fread(&key, sizeof(int), 1, file);
        if (feof(file)) break;
        Record record;
        fread(&record.value, sizeof(int), 1, file);
        fread(&record.data, sizeof(char), 1, file);
        insert_record(table, key, &record);
    }

    fclose(file);
    return table;
}

// Function to serialize the hash table to a file
void serialize_hash_table(const HashTable *table, const char *filename) {
    // Open the file for writing
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    // Write the initial size and maximum load factor to the file
    fwrite(&table->size, sizeof(int), 1, file);
    fwrite(&table->load_factor, sizeof(int), 1, file);

    // Serialize records from the hash table into the file
    Node *node = NULL;
    for (int i = 0; i < table->capacity; i++) {
        node = table->table[i];
        while (node) {
            fwrite(&node->key, sizeof(int), 1, file);
            Record record = *(Record*)node->record;
            fwrite(&record.value, sizeof(int), 1, file);
            fwrite(&record.data, sizeof(char), 1, file);
            node = node->collision.next;
        }
    }

    fclose(file);
}

int main() {
    // Initialize the hash table
    HashTable *table = init_hash_table(1000, 0.5);

    // Insert records into the hash table
    for (int i = 0; i < 10000; i++) {
        Record record;
        record.value = i;
        record.data = 'a' + i % 26;
        insert_record(table, i, &record);
    }

    // Serialize the hash table to a file
    serialize_hash_table(table, "hash_table.ser");

    // Deserialize the hash table from the file
    HashTable *deserialized_table = deserialize_hash_table("hash_table.ser", &initial_size, &max_load_factor);

    return 0;
}

