    fwrite(offsets, sizeof(long), arraySize, file);
    fwrite(keys, sizeof(int), arraySize, file);
    for (int i = 0; i < recordCount; i++) {
        fwrite(&records[i].key, sizeof(int), 1, file);
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].timestamp, sizeof(time_t), 1, file);
        char* identifier = records[i].identifier;
        size_t len = strlen(identifier);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(identifier, 1, len + 1, file);
