import ctypes
from threading import Lock
from functools import lru_cache

class MemoryAllocator:
    def __init__(self, cache_size):
        self.cache_size = cache_size
        self.memory_pool = {}
        self.lock = Lock()

    @lru_cache(maxsize=1000)
    def allocate(self, size):
        with self.lock:
            if size not in self.memory_pool:
                self.memory_pool[size] = []
            if len(self.memory_pool[size]) < self.cache_size:
                return ctypes.create_string_buffer(size).cast(ctypes.POINTER(ctypes.c_char))
            else:
                raise MemoryError("Cache is full")

    def deallocate(self, buffer):
        with self.lock:
            for size in reversed(sorted(self.memory_pool)):
                if buffer in self.memory_pool[size]:
                    del self.memory_pool[size][self.memory_pool[size].index(buffer)]
                    return
            raise ValueError("Invalid buffer")

