void* manage_memory(int size, int keys_size, int records_size) {
    // Dynamic array for long offset values
    long** offsets = (long**)malloc(keys_size * sizeof(long*));
    for (int i = 0; i < keys_size; i++) {
        offsets[i] = (long*)malloc(size);
    }

    // Dynamic array for int keys
    int** keys = (int**)malloc(keys_size * sizeof(int*));
    for (int i = 0; i < keys_size; i++) {
        keys[i] = (int*)malloc(size);
    }

    // Array of record structures
    record** records = (record**)malloc(records_size * sizeof(record*));
    for (int i = 0; i < records_size; i++) {
        records[i] = (record*)malloc(sizeof(record));
    }

    return (void*)keys;
}

void manage_memory_reallocation(void* ptr, int size, int new_size) {
    // Get the original type
    if (ptr == (void*)NULL) {
        printf("Error: attempting to reallocate NULL pointer.\n");
        return;
    }
    int* keys = (int*)ptr;

    // Resize arrays
    long** offsets = (long**)malloc(new_size * sizeof(long*));
    for (int i = 0; i < new_size; i++) {
        offsets[i] = (long*)malloc(size);
    }

    int** keys_reallocation = (int**)malloc(new_size * sizeof(int*));
    for (int i = 0; i < new_size; i++) {
        keys_reallocation[i] = (int*)malloc(size);
    }

    record** records_reallocation = (record**)malloc(new_size * sizeof(record*));
    for (int i = 0; i < new_size; i++) {
        records_reallocation[i] = (record*)malloc(sizeof(record));
    }

    // Copy data to new arrays
    for (int i = 0; i < size; i++) {
        keys[i] = keys_reallocation[i];
        for (int j = 0; j < keys_size; j++) {
            offsets[j][i] = offsets_reallocation[j][i];
        }
        for (int k = 0; k < records_size; k++) {
            records[k]->val = records_reallocation[k]->val;
        }
    }

    // Free old arrays
    free(offsets);
    free(keys);
    free(records);

    return;
}

void* generate_random_numbers(int size, int seed) {
    srand(seed);

    int* random_numbers = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
