    size_t total_mem = sizeof(double) * arr_size1 + sizeof(char) * (arr_size2 + 1) + 
                        sizeof(struct { int i; float f; }) * arr_size3 + sizeof(measurement) * measure_count;

    // Check if the total memory exceeds the threshold
    if (total_mem > 1024*1024*10) {
        // Dynamically adjust sizes to fit within the constraint
        size_t adjusted_arr_sizes[3] = {arr_size1, arr_size2, arr_size3};

        for (int i = 0; i < 3; i++) {
            while (sizeof(double) * adjusted_arr_sizes[i] + sizeof(char) * (adjusted_arr_sizes[i] + 1) + 
                   sizeof(struct { int i; float f; }) * adjusted_arr_sizes[i] > 1024*1024*10 - total_mem) {
                adjusted_arr_sizes[i]--;
            }
        }

        // Recalculate the total memory required
        total_mem = sizeof(double) * adjusted_arr_sizes[0] + sizeof(char) * (adjusted_arr_sizes[0] + 1) + 
                   sizeof(struct { int i; float f; }) * adjusted_arr_sizes[1] + sizeof(measurement) * measure_count;
    }

