typedef struct {
    int key;
    int value;
    int status; // 0: inactive, 1: active
} record_t;

// Function to dynamically allocate memory for and initialize an array of records
record_t* generateRecords(int size, int minKey, int maxKey, int minValue, int maxValue) {
    record_t* records = NULL;
    int i;

    // Check if the allocation failed
    if (size <= 0 || (records = (record_t*)malloc(size * sizeof(record_t))) == NULL) {
        printf("Memory allocation failure: %s\n", strerror(errno));
        return NULL; // Fallback mechanism to notify the caller of insufficient resources
    }

    // Initialize records with unique keys and random values within specified ranges
    for (i = 0; i < size; i++) {
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].status = 0; // Inactive by default
    }

    // Return the allocated and initialized array of records
    return records;
}

// Function to deallocate memory for an array of records
void freeRecords(record_t* records, int size) {
    if (records != NULL) {
        free(records);
    }
}
