#define RECORD_STRUCT int

void manage_memory(int size1, int size2, int record_count) {
    long* offset_array = NULL;
    int* key_array = NULL;
    RECORD_STRUCT** record_array = NULL;

    // Initialize memory pool
    void* memory_pool = malloc(size1 * sizeof(long));
    if (!memory_pool) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Allocate and initialize offset and key arrays
    offset_array = (long*)memory_pool;
    key_array = (int*)((char*)offset_array + size1);

    for (int i = 0; i < size1; i++) {
        *(offset_array + i) = i * sizeof(long);
    }

    for (int i = 0; i < size2; i++) {
        *(key_array + i) = i;
    }

    // Allocate and initialize record array
    memory_pool = malloc(size2 * sizeof(RECORD_STRUCT*));
    if (!memory_pool) {
        printf("Memory allocation failed.\n");
        return;
    }

    record_array = (RECORD_STRUCT**)(memory_pool);

    for (int i = 0; i < size2; i++) {
        *(record_array + i) = malloc(sizeof(RECORD_STRUCT));
        if (!*(record_array + i)) {
            printf("Memory allocation failed.\n");
            return;
        }

        *((*(record_array + i))) = i;
    }

    // Integrate with external library for generating random numbers
    srand(time(NULL));

    int total_memory_usage = (size1 * sizeof(long) + size2 * sizeof(int)) + record_count * sizeof(RECORD_STRUCT);

    if (total_memory_usage > THRESHOLD) {
        // Adjust array sizes to fit within the constraint
        size1 -= (size1 / 4);
        size2 -= (size2 / 4);
        record_count = (record_count / 4);

        void* new_memory_pool = malloc(size1 * sizeof(long));
        if (!new_memory_pool) {
            printf("Memory allocation failed.\n");
            return;
        }

        offset_array = (long*)new_memory_pool;

        memory_pool = malloc(size2 * sizeof(int));
        if (!memory_pool) {
            printf("Memory allocation failed.\n");
            return;
        }

        key_array = (int*)memory_pool;

        memory_pool = realloc(record_array, record_count * sizeof(RECORD_STRUCT*));
        if (!memory_pool) {
            printf("Memory reallocation failed.\n");
            return;
        }

        record_array = (RECORD_STRUCT**)(memory_pool);

        // Compact memory segments
        void* start = offset_array;
        void* end = key_array + size2;

        while ((void*)end < (void*)record_array) {
            memmove(start, end, sizeof(int));
            end = (void*)start + size1;
        }

        free(new_memory_pool);
    }

    // Test random number generator quality
