    std::vector<int> keys;
    long offsets[1024];

    void start() {
        // Start data collection
        std::thread collectorThread([this]() {
            while (true) {
                // Simulate data collection
                for (int i = 0; i < 100; i++) {
                    records.push_back({i});
                    keys.push_back(i);
                    offsets[i] = i;
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                }
            }
