            isRunning = true;
            std::thread serviceThread([this]() {
                while (isRunning) {
                    // Simulate service operations
                    for (int i = 0; i < 100; i++) {
                        // Randomly pause or resume the service
                        if (randomNumberGenerator.generate() % 2 == 0) {
