    long int** offsets = (long int**)dynamic_malloc(sizeof(long int*) * 10000);
    int** keys = (int**)dynamic_malloc(sizeof(int*) * 10000);
    record** records = (record**)dynamic_malloc(sizeof(record*) * 10000);

