        offsets[i] = (long int*)dynamic_malloc(sizeof(long int));
        keys[i] = (int*)dynamic_malloc(sizeof(int));
        records[i] = (record*)dynamic_malloc(sizeof(record));

        *offsets[i] = random_long(1, INT_MAX);
        *keys[i] = random_int();
        (*records[i]).val = random_long();

        // Dynamic resizing and garbage collection
        if ((int)sizeof(long int) + (int)sizeof(int) + sizeof(record) > 1024 * 1024 * 10) {
            dynamic_free(*offsets);
            dynamic_free(*keys);
            dynamic_free(*records);

            offsets = (long int**)dynamic_malloc(sizeof(long int*) * 5000);
            keys = (int**)dynamic_malloc(sizeof(int*) * 5000);
            records = (record**)dynamic_malloc(sizeof(record*) * 5000);

            for (int j = 0; j < 5000; j++) {
