                keys[j] = (int*)dynamic_malloc(sizeof(int));
                records[j] = (record*)dynamic_malloc(sizeof(record));

                *offsets[j] = random_long(1, INT_MAX);
                *keys[j] = random_int();
                (*records[j]).val = random_long();
            }
        }

        // Compression and encryption
        char buffer[1024];
        int len = sprintf(buffer, "Record %d: Offset = 0x%lX, Key = %d, Value = 0x%X", i, *offsets[i], *keys[i], (*records[i]).val);

        // File I/O and compression
        FILE* file = fopen("data.bin", "wb");
        fwrite(buffer, sizeof(char), len, file);
        fclose(file);

        // Asynchronous processing
        pthread_t thread;
        pthread_create(&thread, NULL, process_data, &file);

        return 0;
    }

    return 0;
}

// Thread function for asynchronous processing
void* process_data(void* ptr) {
    FILE* file = (FILE*)ptr;

    while (!feof(file)) {
        char buffer[1024];
        int len = fread(buffer, sizeof(char), 1024, file);

        // Compression and encryption
        unsigned char compressed[len + 1];
        int compressed_len = compress((void*)buffer, len, compressed);
        FILE* encrypted_file = fopen("encrypted_data.bin", "wb");
        fwrite(compressed, sizeof(unsigned char), compressed_len, encrypted_file);
        fclose(encrypted_file);

        return NULL;
    }
}
