#include <time.h>

// Structure definition for a record
typedef struct {
    int key;
    int value;
} Record;

// Function to manage memory for dynamic collection of records
void* allocateMemory(int size) {
    void* ptr = malloc(size);
    if (ptr == NULL && size > 0) {
        // If allocation fails, try allocating a larger block
        ptr = valloc(size);
    }
    return ptr;
}

// Function to initialize and populate record structures
int initializeRecords(Record** records, int numRecords, FILE* config) {
    srand(time(NULL));

    int i;
    for (i = 0; i < numRecords; i++) {
        Record* record = (Record*)allocateMemory(sizeof(Record));
        if (!record) return -1;

        record->key = rand() % 21000 - 10000;
        record->value = rand() % 21000 - 10000;

        (*records)++;  // Increment the pointer
    }

    return i;  // Return the number of records initialized
}

// Function to print the contents of a record structure
void printRecord(const Record* record) {
    printf("Key: %d, Value: %d\n", record->key, record->value);
}

int main(int argc, char** argv) {
    FILE* config = fopen(argv[1], "r");  // Open the configuration file

    if (config == NULL || fseek(config, 0, SEEK_END) != 0) {
        printf("Error opening or reading configuration file!\n");
        return -1;
    }

    int numRecords = atoi(fread(NULL, 1, sizeof(int), config));

    Record* records = NULL;  // Initialize the record structure pointer

    if (initializeRecords(&records, numRecords, config) < 0) {
        printf("Error initializing records!\n");
        return -1;
    }

    fclose(config);

    // Print the contents of each record
    int i;
    for (i = 0; i < numRecords; i++) {
        printRecord(&records[i]);
    }

    // Persist the data to disk in binary format
    FILE* output = fopen(argv[2], "wb");

    if (!output) {
        printf("Error opening output file!\n");
        return -1;
    }

    fwrite(records, sizeof(Record), numRecords, output);

    fclose(output);

    // Free the memory allocated for records
    free(records);

    return 0;
}

