void manageMemory(int numPeople, int numActivities) {
    // Create an array of 'person' objects
    Person** people = (Person**)malloc(numPeople * sizeof(Person));

    // Randomly assign ages within a specified range for each person
    srand(time(NULL));
    for (int i = 0; i < numPeople; i++) {
        people[i]->age = rand() % 100 + 1;
    }

    // Set the status based on certain conditions (e.g., age > 30)
    for (int i = 0; i < numPeople; i++) {
        if (people[i]->age > 30) {
            people[i]->status = INACTIVE;
        } else {
            people[i]->status = ACTIVE;
        }
    }

    // Create an array of 'activity' structures
    Activity* activities = (Activity*)malloc(numActivities * sizeof(Activity));

    // Assign random person and date for each activity
    for (int i = 0; i < numActivities; i++) {
        people[i]->person->name = "Person Name"; // Update with actual name data
        activities[i].date = time(NULL) - rand() % 86400;
        activities[i].person = people[rand() % numPeople];
