```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 50000
#define MAX_STRING_LENGTH 100
#define MAX_NESTED_DATA_SIZE 1024 // sizeof(float) * 16 + sizeof(int)
#define FILE_NAME_MAX_LENGTH 256

typedef struct {
    double d;
    char str[MAX_STRING_LENGTH];
    struct nested_data {
        float values[16];
        int i;
    } nd;
} record;

record* records = NULL;
int num_records = 0;

// Function to randomly generate a record
record* generate_record() {
    record* r = (record*)malloc(sizeof(record));
    if (!r) return NULL; // Handle allocation failure

    r->d = (double)(rand() / (RAND_MAX + 1.0)) * 2000000 - 1000000;
    srand(time(NULL)); // Ensure randomness
    for (int i = 0; i < MAX_STRING_LENGTH; i++) {
        r->str[i] = (char)(rand() % 26); // Random characters for string
        if (r->str[i] == '\0') break;
    }
    strcpy(r->str, r->str);

    r->nd.values[0] = (float)(rand() / (RAND_MAX + 1.0)) * 200 - 100;
    r->nd.i = rand() % 2;

    return r;
}

// Function to filter records based on integer and float ranges
record* filter_records(int min_int, int max_int, float min_float, float max_float) {
    record* filtered_records = NULL;
    int num_filtered = 0;

    for (int i = 0; i < num_records; i++) {
        record* r = &records[i];
        if ((r->nd.i >= min_int && r->nd.i <= max_int) &&
            (r->nd.values[0] >= min_float && r->nd.values[0] <= max_float)) {
            filtered_records = realloc(filtered_records, sizeof(record*) * (num_filtered + 1));
            filtered_records[num_filtered++] = r;
        }
    }

    return filtered_records;
}

// Function to filter records based on string substring
record* filter_records_by_string(const char* substring) {
    record* filtered_records = NULL;
    int num_filtered = 0;

    for (int i = 0; i < num_records; i++) {
        record* r = &records[i];
        if (strstr(r->str, substring)) {
            filtered_records = realloc(filtered_records, sizeof(record*) * (num_filtered + 1));
            filtered_records[num_filtered++] = r;
        }
    }

    return filtered_records;
}

// Function to write records to a binary file
void write_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return; // Handle file opening failure

    for (int i = 0; i < num_records; i++) {
        record* r = &records[i];
        fwrite(&r->d, sizeof(double), 1, file);
        fwrite(r->str, strlen(r->str) + 1, 1, file); // Include null-terminator
        fwrite(&r->nd.values, sizeof(float), 16, file);
        fwrite(&r->nd.i, sizeof(int), 1, file);
    }

    fclose(file);
}

// Function to read records from a binary file
void read_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return; // Handle file opening failure

    record* temp_records = NULL;
    int num_read = 0;

    while (1) {
        double d;
        char str[MAX_STRING_LENGTH];
        float values[16];
        int i;

        fread(&d, sizeof(double), 1, file);
        fread(str, MAX_STRING_LENGTH + 1, 1, file); // Include null-terminator
        fread(values, sizeof(float), 16, file);
        fread(&i, sizeof(int), 1, file);

        if (ferror(file)) break; // End of file or error

        temp_records = realloc(temp_records, sizeof(record*) * (num_read + 1));
        temp_records[num_read++] = malloc(sizeof(record));
        ((record*)temp_records[num_read - 1])->d = d;
        strcpy(((record*)temp_records[num_read - 1])->str, str);
        memcpy(((record*)temp_records[num_read - 1])->nd.values, values, sizeof(float) * 16);
        ((record*)temp_records[num_read - 1])->nd.i = i;
    }

    num_records = num_read;

    // Free temporary records
    for (int i = 0; i < num_read; i++) {
        free(temp_records[i]);
    }
    free(temp_records);

    fclose(file);
}

// Function to handle file existence and prompting
void prompt_file_existence(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file) {
        printf("File '%s' already exists. Do you want to overwrite it? (y/n): ", filename);
        char response[2];
        fgets(response, 2, stdin);

        if (response[0] == 'n') {
            printf("Operation aborted.\n");
            exit(1);
        }

        fclose(file); // Close existing file
    }
}

int main() {
    srand(time(NULL)); // Ensure randomness

    records = NULL;
    num_records = 0;

    for (int i = 0; i < MAX_RECORDS; i++) {
        record* r = generate_record();
        if (!r) break; // Handle allocation failure
        records = realloc(records, sizeof(record*) * (num_records + 1));
        records[num_records++] = r;
    }

    printf("Records generated: %d\n", num_records);

    prompt_file_existence("records.bin");

    write_to_file("records.bin");

    return 0;
}
```
This code provides the basic functionality for managing a dynamic collection of `record` structures, including random generation, filtering, and persistence to disk. It also handles file existence and prompting for user input. Note that this is just one possible implementation, and you may want to modify it based on your specific requirements or constraints.']

