    FILE* config_file = fopen(config_file_path, "r");
    fscanf(config_file, "%d %ld", &num_offsets, &max_offset);
    fclose(config_file);

    long* offset_array = (long*)malloc(num_offsets * sizeof(long));
    int* key_array = (int*)malloc(num_offsets * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < num_offsets; i++) {
        offset_array[i] = rand() % max_offset;
        key_array[i] = i;
    }

    record* records = NULL;

    // Allocate memory for and initialize an array of record structures
