    fscanf(config_file, "%d", &num_records);

    if (num_records > 0) {
        size_t total_size = sizeof(record) * num_records;
        records = mmap(NULL, total_size, PROT_READ | PROT_WRITE,
                MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        for (int i = 0; i < num_records; i++) {
            ((record*)records)[i].val = rand() % 100; // Set random value
        }
    }

    // Handle concurrent access to data structures
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    void* shared_data = mmap(NULL, sizeof(long) + sizeof(int), PROT_READ | PROT_WRITE,
            MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    long* shared_offset_array = (long*)shared_data;
    int* shared_key_array = ((int*)shared_data) + num_offsets;

    // Persist data to disk in binary format
    FILE* output_file = fopen(output_file_name, "wb");
    fwrite(offset_array, sizeof(long), num_offsets, output_file);
    fwrite(key_array, sizeof(int), num_offsets, output_file);
    if (records) {
        fwrite(records, sizeof(record), num_records, output_file);
    }
    fclose(output_file);

    // Clean up
    munmap(records, total_size);
    free(offset_array);
    free(key_array);
}
