                // Calculate MD5 hash
                for (int j = 0; j < 16; j++) {
                    buffer[j] = result[j];
                }
                char* str = (char*)malloc(17);
                memcpy(str, buffer, 16);
                str[16] = '\0';
                printf("Record %d: %s\n", k + 1, str);

                totalMemUsed += sizeof(record);
            }
        }
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    for (int i = 0; i < numRecords; i++) {
        free((char*)&records[i]);
    }
    free(records);
