void* record_manager(void** data, int* count, int max_count) {
    // Initialize the record array with a fixed-size buffer for strings
    record_t* records = (record_t*)malloc(RECORD_MAX * sizeof(record_t));
    int record_index = 0;

    // Function to merge incoming data with existing records
    void merge_record(void** new_data, int new_count) {
        // Merge the incoming data into the existing records array
        for (int i = 0; i < new_count; i++) {
            record_t* new_rec = (record_t*)malloc(sizeof(record_t));
            strcpy(new_rec->timestamp_str, ((char**)new_data)[i]);
            new_rec->status_code = atoi(((char**)new_data)[i + 1]);
            new_rec->monetary_value = atof(((char**)new_data)[i + 2]);

            // Insert the merged record into the records array
            records[record_index++] = *new_rec;
            free(new_rec);
        }
    }

    // Mechanism to efficiently merge incoming data with existing records, ensuring minimal memory reallocation and efficient data insertion
    void process_new_data(void** new_data, int new_count) {
