            record_index += new_count;
        } else {
            // Handle the case where the records array needs to be reallocated
        }
    }

    // Age-based pruning strategy to automatically remove records that exceed a specified age threshold
    void prune_records(int age_threshold) {
        int i = 0;
        while (i < record_index) {
            if (records[i].timestamp < (time(NULL) - age_threshold)) {
                free(&records[i]);
                // Shift the remaining records down to fill the gap
                for (; i < record_index - 1; i++) {
                    records[i] = records[i + 1];
                }
                record_index--;
            } else {
                i++;
            }
        }
    }

    // Thread-safe data structure to ensure concurrent access from multiple threads without data corruption or race conditions
    void* lock;
    void init_lock(void) {
        lock = (void*)malloc(sizeof(pthread_mutex_t));
        pthread_mutex_init((pthread_mutex_t*)lock, NULL);
    }
    void acquire_lock(void) {
        pthread_mutex_lock((pthread_mutex_t*)lock);
    }
    void release_lock(void) {
        pthread_mutex_unlock((pthread_mutex_t*)lock);
    }

