    for (i = 0; i < MAX_RECORDS && (*num_records <= MAX_SIZE); i++) {
        if (!(*offsets)) *offsets = init_offsets(i);
        if (!(*keys)) *keys = init_keys(i);

        if (records) free(records);
        records = realloc(records, (i + 1) * sizeof(record));
        if (!records) return;

        for (int j = 0; j < i; j++) {
            records[j].offset += RAND_RANGE;
            records[j].key++;
        }
    }

    *num_records = i;
