#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_MAX 1000
#define BUFFER_SIZE 100
#define MAX_AGE 3600 // one hour in seconds
#define PRUNE_THRESHOLD 500 // records to prune when memory pressure detected
#define BACKPRESSURE_THRESHOLD 80 // percentage buffer full before backpressure

typedef struct {
    long timestamp;
    int status_code;
    double monetary_value;
} record_t;

record_t *records = NULL;
int record_count = 0;
int buffer_size = BUFFER_SIZE;
int buffer_full = 0;
int prune_interval = 30; // seconds
double total_monetary_value = 0.0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void *buffer[RECORD_MAX];
int buffer_head = 0;
int buffer_tail = 0;

void merge_records(record_t *new_record) {
    pthread_mutex_lock(&lock);

    if (record_count < RECORD_MAX) {
        records[record_count] = *new_record;
        record_count++;

        total_monetary_value += new_record->monetary_value;
    } else {
        buffer[buffer_head] = malloc(sizeof(record_t));
        memcpy(buffer[buffer_head], new_record, sizeof(record_t));
        buffer_head = (buffer_head + 1) % RECORD_MAX;

        if (buffer_head == buffer_tail) {
            buffer_full = 1;
        }
    }

    pthread_mutex_unlock(&lock);
}

void prune_records() {
    pthread_mutex_lock(&lock);

    int i, num_pruned = 0;

    for (i = 0; i < record_count; i++) {
        if ((time(NULL) - records[i].timestamp) > prune_interval * 2) {
            free(&records[i]);
            record_count--;
            total_monetary_value -= records[i].monetary_value;
            num_pruned++;

            if (num_pruned >= PRUNE_THRESHOLD) {
                break;
            }
        } else {
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void *worker_thread(void *arg) {
    record_t new_record;
    int backpressure_level = 0;

    while (1) {
        // wait for new records
        pthread_cond_wait(&cond, &lock);

        if (buffer_full && buffer_head == buffer_tail) {
            backpressure_level = (buffer_full ? BACKPRESSURE_THRESHOLD : 0);

            while (backpressure_level > 0) {
                // signal upstream components to slow down
                printf("Backpressure level: %d%%\n", backpressure_level);

                // wait for data flow reduction
                usleep(100000 * (BACKPRESSURE_THRESHOLD - backpressure_level));

                backpressure_level--;
            }
        } else if (!buffer_full && buffer_tail == buffer_head) {
            // buffer is empty, notify upstream components to speed up
            printf("Buffer is full, notify upstream components to speed up\n");

            // signal upstream components
            pthread_cond_signal(&cond);
        }

        while (buffer_full && buffer_head != buffer_tail) {
            merge_records(buffer[buffer_tail]);
            buffer_tail = (buffer_tail + 1) % RECORD_MAX;
        }

        prune_records();
    }

    return NULL;
}

void start_threads() {
    pthread_t threads[RECORD_MAX / 2];

    for (int i = 0; i < RECORD_MAX / 2; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, NULL) != 0) {
            printf("Failed to create thread\n");
        }
    }
}

void stop_threads() {
    pthread_t threads[RECORD_MAX / 2];

    for (int i = 0; i < RECORD_MAX / 2; i++) {
        if (pthread_kill(threads[i], 0) == 0) {
            pthread_join(threads[i], NULL);
        }
    }
}

int main() {
    start_threads();

    // process records from external data pipeline
    while (1) {
        record_t new_record;
        // read new record from pipeline

        merge_records(&new_record);

        if (buffer_full && buffer_head == buffer_tail) {
            backpressure_level = BACKPRESSURE_THRESHOLD;

            while (backpressure_level > 0) {
                // signal upstream components to slow down
                printf("Backpressure level: %d%%\n", backpressure_level);

                // wait for data flow reduction
                usleep(100000 * (BACKPRESSURE_THRESHOLD - backpressure_level));

                backpressure_level--;
            }
        } else if (!buffer_full && buffer_tail == buffer_head) {
            // buffer is empty, notify upstream components to speed up
            printf("Buffer is full, notify upstream components to speed up\n");

            // signal upstream components
            pthread_cond_signal(&cond);
        }
    }

    stop_threads();

    return 0;
}
