#include <stdlib.h>
#include <stdio.h>
#include <random>

// Define the node and item structures
typedef struct {
    int* items;
    int size;
} Node;

typedef struct {
    int value;
} Item;

Node* createNodes(int numNodes, int itemsPerNode) {
    // Calculate total memory needed for nodes and items
    size_t totalMemNeeded = sizeof(Node) * numNodes + sizeof(Item) * numNodes * itemsPerNode;

    if (totalMemNeeded > MEMORY_THRESHOLD) {
        // Adjust node and item sizes to fit within the constraint
        numNodes = (int)sqrt((double)MEMORY_THRESHOLD / sizeof(Node));
        itemsPerNode = (int)sqrt((double)(MEMORY_THRESHOLD - sizeof(Node) * numNodes) / sizeof(Item));
    }

    Node* nodes = (Node*)malloc(numNodes * sizeof(Node));
    for (int i = 0; i < numNodes; i++) {
        nodes[i].items = (Item*)malloc(itemsPerNode * sizeof(Item));
    }

    return nodes;
}

void initItems(Node* nodes, int numNodes, int itemsPerNode) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100);

    for (int i = 0; i < numNodes; i++) {
        for (int j = 0; j < itemsPerNode; j++) {
            nodes[i].items[j].value = dis(gen);
        }
    }
}

void traverseNodes(Node* nodes, int numNodes, callbackFunc cb) {
    // Traverse nodes and items concurrently
    std::vector<std::thread> threads;
    for (int i = 0; i < numNodes; i++) {
        threads.emplace_back([this, &nodes, i, cb]() {
            for (int j = 0; j < nodes[i].size; j++) {
                cb(nodes[i].items[j]);
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }
}

void freeNodes(Node* nodes, int numNodes) {
    // Deallocate memory safely
    for (int i = 0; i < numNodes; i++) {
        if (nodes[i].items) {
            free(nodes[i].items);
        }
    }

    if (nodes) {
        free(nodes);
    }
}
