node* init_list(int num_nodes, size_t max_memory_usage) {
    // Calculate the maximum memory required based on the number of nodes
    size_t total_memory = sizeof(node) * num_nodes + strlen("") * (num_nodes - 1);

    if (total_memory > max_memory_usage) {
        // Optimize the linked list structure to fit within the constraint
        node* new_head = NULL;
        for (int i = 0; i < num_nodes / 2; i++) {
            node* temp = malloc(sizeof(node));
            temp->data = malloc(strlen("") * sizeof(char));
            strcpy(temp->data, "");
            temp->value = 0;
            temp->next = new_head;
            new_head = temp;
        }

        // Update the linked list to ensure proper termination
        for (node* current = new_head; current != NULL; current = current->next) {
            if (current->next == NULL) {
                free(current->data);
                break;
            }
        }

        return new_head;
    } else {
        // Initialize the linked list as usual
        node* head = malloc(sizeof(node));
        for (int i = 0; i < num_nodes; i++) {
