        temp->data = malloc(strlen("") * sizeof(char));
        strcpy(temp->data, "");
        temp->value = 0;
        temp->next = NULL;
        pthread_mutex_lock(&lock);
        if (head == NULL) {
            head = temp;
        } else {
            node* current = head;
            while (current != NULL) {
                current = current->next;
            }
            current->next = temp;
        }
        pthread_mutex_unlock(&lock);
