#include <stdlib.h>
#include <string.h>

typedef struct {
    char* str;
    int64_t timestamp;
} Entry;

typedef struct {
    Entry** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Collection;

Collection* collection_init(size_t initial_capacity) {
    Collection* coll = malloc(sizeof(Collection));
    coll->entries = malloc(initial_capacity * sizeof(Entry*));
    coll->capacity = initial_capacity;
    coll->size = 0;
    pthread_mutex_init(&coll->lock, NULL);
    return coll;
}

void collection_free(Collection* coll) {
    for (size_t i = 0; i < coll->size; i++) {
        free(coll->entries[i]->str);
        free(coll->entries[i]);
    }
    free(coll->entries);
    pthread_mutex_destroy(&coll->lock);
    free(coll);
}

void collection_add(Collection* coll, const char* str) {
    Entry* entry = malloc(sizeof(Entry));
    entry->str = strdup(str);
    entry->timestamp = time(NULL);

    if (coll->size >= coll->capacity / 2) {
        // Double the capacity
        Collection* new_coll = collection_init(coll->capacity * 2);
        for (size_t i = 0; i < coll->size; i++) {
            new_coll->entries[i] = coll->entries[i];
        }
        free(coll->entries);
        coll->entries = new_coll->entries;
        coll->capacity = new_coll->capacity;
        coll->size = new_coll->size;
        collection_free(new_coll);
    }

    coll->entries[coll->size++] = entry;
}

int64_t collection_get_timestamp(Collection* coll, size_t index) {
    pthread_mutex_lock(&coll->lock);
    int64_t timestamp = coll->entries[index]->timestamp;
    pthread_mutex_unlock(&coll->lock);
    return timestamp;
}

void collection_update_timestamp(Collection* coll, size_t index) {
    pthread_mutex_lock(&coll->lock);
    coll->entries[index]->timestamp = time(NULL);
    pthread_mutex_unlock(&coll->lock);
}
