#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

#define MAX_NODES 1000
#define MEMORY_THRESHOLD 1024*1024*10 // 10MB threshold

typedef struct node {
    char* string;
    int weight;
    float value;
} Node;

typedef struct data {
    Node* node;
    float field;
} Data;

void initArrays(long** offsets, int** keys, float** weights, int size) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *weights = (float*)malloc(size * sizeof(float));
}

Node* newNode(char* str, int weight, float value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->string = str;
    node->weight = weight;
    node->value = value;
    return node;
}

void insertNode(Node** nodes, char* str, int weight, float value) {
    // Find the correct position to insert the new node
    Node* newNode = newNode(str, weight, value);
    for (int i = 0; i < *nodes; i++) {
        if (newNode->weight <= (*nodes)[i]->weight) {
            break;
        }
    }

    // Insert the new node at the correct position
    for (int i = *nodes; i > i; i--) {
        (*nodes)[i] = (*nodes)[i-1];
    }
    (*nodes)[i] = newNode;

    (*nodes)++;
}

void deallocArrays(long* offsets, int* keys, float* weights, int size) {
    free(offsets);
    free(keys);
    free(weights);
}

int main() {
    // Initialize arrays
    long* offsets;
    int* keys;
    float* weights;
    initArrays(&offsets, &keys, &weights, MAX_NODES);

    // Initialize linked list
    Node* nodes = 0;

    // Example usage: insert nodes into the linked list
    for (int i = 0; i < 10; i++) {
        char str[i+1];
        sprintf(str, "Node %d", i);
        insertNode(&nodes, str, i, (float)i/100.0);
    }

    // Populate data structures
    Data* data = (Data*)malloc(MAX_NODES * sizeof(Data));
    for (int i = 0; i < nodes; i++) {
        Node* node = nodes[i];
        data[i].node = node;
        data[i].field = node->value + 1.0f;
    }

    // Deallocate memory
    deallocArrays(offsets, keys, weights, MAX_NODES);

    return 0;
}
