#include <stdlib.h>
#include <string.h>

typedef struct {
    char* str;
    int val;
} node;

node* linked_list_new(int num_nodes) {
    // Initialize the head of the linked list
    node* head = (node*) malloc(sizeof(node));
    head->str = NULL;
    head->val = 0;

    // Initialize the tail of the linked list
    node* tail = head;

    for (int i = 1; i < num_nodes; i++) {
        node* new_node = (node*) malloc(sizeof(node));
        new_node->str = NULL;
        new_node->val = 0;

        tail->next = new_node;
        tail = new_node;
    }

    return head;
}

void linked_list_free(node* head) {
    // Free the nodes
    node* current = head;
    while (current != NULL) {
        node* next = current->next;
        free(current);
        current = next;
    }
}

node* linked_list_insert_after(node* prev_node, char* str, int val) {
    // Create a new node
    node* new_node = (node*) malloc(sizeof(node));
    new_node->str = str;
    new_node->val = val;

    // Link the new node to the previous node
    new_node->next = prev_node->next;
    prev_node->next = new_node;

    return new_node;
}

void linked_list_remove(node* target) {
    if (target == NULL) return;

    // Find the previous node in the list
    node* prev_node = NULL;
    node* current = head;
    while (current != NULL && current != target) {
        prev_node = current;
        current = current->next;
    }

    // Remove the target node from the list
    if (target == head) {
        head = target->next;
    } else {
        prev_node->next = target->next;
    }

    free(target);
}

int linked_list_search(node* head, char* str) {
    node* current = head;
    while (current != NULL) {
        if (strcmp(current->str, str) == 0) return current->val;
        current = current->next;
    }
    return -1;
}
