#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int key;
    struct node* value;
    struct node* next;
} Node;

Node* head = NULL;

// Function to insert a new node at the beginning of the list
void insert(int key, void* value) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->key = key;
    newNode->value = (Node*) value;
    newNode->next = head;
    head = newNode;
}

// Function to delete a node with a given key from the list
void delete(int key) {
    if (head == NULL)
        return;

    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL)
        return;

    if (previous == NULL)
        head = current->next;
    else
        previous->next = current->next;

    free(current);
}

// Function to print the key-value pairs of all nodes in the list
void traverse() {
    Node* current = head;
    while (current != NULL) {
        printf("Key: %d, Value: %p\n", current->key, current->value);
        current = current->next;
    }
}

// Function to serialize the linked list to a file
void serialize(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL)
        return;

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current, sizeof(Node), 1, file);
        current = current->next;
    }

    fclose(file);
}

// Function to deserialize the linked list from a file
void deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL)
        return;

    Node* node = NULL;
    while (fread(&node, sizeof(Node), 1, file) == 1) {
        insert(node->key, node);
    }

    fclose(file);
}

// Function to reverse the order of nodes in the list
void reverse() {
    Node* current = head;
    Node* previous = NULL;
    Node* next = NULL;

    while (current != NULL) {
        next = current->next;
        current->next = previous;
        previous = current;
        current = next;
    }

    head = previous;
}

// Function to lock the list for concurrent access
void lock() {
    // Use a mutex or semaphore for thread safety
}

// Function to unlock the list after concurrent access
void unlock() {
    // Use a mutex or semaphore for thread safety
}
