```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct node {
    int key;
    void* value;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void insert(int key, void* value) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->key = key;
    newNode->value = value;
    newNode->next = head;
    pthread_mutex_lock(&mutex);
    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&mutex);
}

void delete(int key) {
    Node** nodeptr = &head;
    Node* current = *nodeptr;
    while (current != NULL && current->key != key) {
        nodeptr = &current->next;
        current = current->next;
    }
    if (current == NULL) return; // Key not found
    *nodeptr = current->next;
    free(current);
}

void* traverse() {
    Node* current = head;
    while (current != NULL) {
        printf("%d: %p\n", current->key, current->value);
        current = current->next;
    }
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    // Create and insert nodes
    for (int i = 0; i < 10000; i++) {
        insert(i, &i); // Just a placeholder value
    }

    // Run concurrent traversal
    pthread_create(&thread1, NULL, traverse, NULL);
    pthread_create(&thread2, NULL, traverse, NULL);

    // Delete nodes
    for (int i = 0; i < 10000 / 2; i++) {
        delete(i); // Just a placeholder key
    }

    return 0;
}
