} record;

// Function to allocate and initialize arrays with LRU strategy
record* alloc_and_init_arrays(int offset_size, int key_size, int num_records) {
    // Calculate the total memory required for arrays
    size_t total_memory = (offset_size * sizeof(long)) + (key_size * sizeof(int));

    if (total_memory > 0.5 * getrlimit(RLIMIT_AS).rlim_cur) {
        printf("Error: Total memory exceeds 50% of system-wide limit.\n");
        return NULL;
    }

    // Allocate memory for offset and key arrays
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        printf("Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays with LRU strategy
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i * sizeof(long);
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = i % num_records;
    }

    // Allocate memory for record array
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize record array with random values
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
    }

    // Sort records based on int value in ascending order
    qsort(records, num_records, sizeof(record), compare);

    return records;
}

// Function to sort record array using comparison function
int compare(const void* a, const void* b) {
    record* ra = (record*)a;
    record* rb = (record*)b;

    if (ra->value < rb->value)
        return -1;
    else if (ra->value > rb->value)
        return 1;
    else
        return 0;
}

// Function to deallocate all allocated memory
void dealloc_all_memory(record* records, long* offsets, int* keys) {
    free(records);
    free(offsets);
    free(keys);
}

int main() {
    // Example usage: Allocate and initialize arrays with LRU strategy
    record* records = alloc_and_init_arrays(100, 200, 500);

    if (!records) {
        printf("Error allocating memory.\n");
        return -1;
    }

    // Verify the integrity of the data after decryption using a provided checksum function
    int checksum = calculate_checksum(records);

