    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

void myFree(void* ptr) {
    free(ptr);
}

int manageMemory(int n, int m) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long* longArray = (long*)myMalloc(n * sizeof(long));
    if (!longArray) return -1;

    for (int i = 0; i < n; i++) {
        longArray[i] = i;
    }

    record* recordArray = (record*)myMalloc(m * sizeof(record));
    if (!recordArray) {
        myFree(longArray);
        return -2;
    }

    srand(time(NULL));

    for (int i = 0; i < m; i++) {
        recordArray[i].value = rand() % 1000 + 1;
        recordArray[i].linkedLong = &longArray[i];
    }

    pthread_mutex_lock(&mutex);
    // Simulating a scenario where the application experiences 
    // a sudden increase in load
    int newM = m * 2;
    long* newLongArray = (long*)myMalloc(newM * sizeof(long));
    if (!newLongArray) {
        myFree(recordArray);
        pthread_mutex_unlock(&mutex);
        return -3;
    }

    for (int i = m; i < newM; i++) {
        newLongArray[i] = i;
    }

    record* newRecordArray = (record*)myMalloc(newM * sizeof(record));
    if (!newRecordArray) {
        myFree(recordArray);
        myFree(longArray);
        pthread_mutex_unlock(&mutex);
        return -4;
    }

    for (int i = 0; i < newM; i++) {
        newRecordArray[i].value = rand() % 1000 + 1;
        newRecordArray[i].linkedLong = &newLongArray[i];
    }

    pthread_mutex_unlock(&mutex);

    // Now, deallocate the memory
    myFree(longArray);
    myFree(recordArray);
    myFree(newLongArray);
    myFree(newRecordArray);
    return 0;
}

int main() {
    int n = 1000000; // Example value for testing purposes
    int m = 50000;   // Example value for testing purposes

    manageMemory(n, m);

    return 0;
}
