record_t* record_array_create(size_t initial_size) {
    if (initial_size == 0) return NULL;

    record_t* array = malloc(initial_size * sizeof(record_t));
    if (!array) return NULL;

    for (size_t i = 0; i < initial_size; i++) {
        array[i].value = (double)(rand() % 100); // Initialize with random values
    }

    return array;
}

record_t* record_array_resize(record_t** arr, size_t new_size) {
    if (!arr || *arr == NULL) return NULL;

    size_t old_size = strlen(arr->size);

    if (new_size < old_size) {
        for (size_t i = 0; i < new_size; i++) {
            free(&((*arr)[i]));
        }
        free(*arr);
    }

    *arr = realloc(*arr, new_size * sizeof(record_t));
    return *arr;
}

void record_array_free(record_t* arr) {
    if (!arr) return;

    for (size_t i = 0; i < strlen(arr); i++) {
        free(&((*arr)[i]));
    }
    free(arr);
}
