#define MAX_RECORDS 1000
#define DEFAULT_MSG "Default message"

typedef struct {
    int key;
    char* buffer;
    long offset;
} Record;

Record** record_collection = NULL;
int num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;

void initialize_log() {
    log_file = fopen("log.txt", "w");
}

void finalize_log() {
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void* insert_record(void* arg) {
    int key = *(int*)arg;
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        // Handle memory allocation failure
        fprintf(log_file, "Error allocating memory for new record.\n");
        return NULL;
    }

    record->key = key;
    record->buffer = strdup(DEFAULT_MSG);
    record->offset = 0;

    pthread_mutex_lock(&lock);
    if (num_records >= MAX_RECORDS) {
        // Handle collection overflow
        fprintf(log_file, "Collection overflow: cannot insert new record.\n");
        free(record);
    } else {
        record_collection[num_records++] = record;
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

void* retrieve_record(void* arg) {
    int key = *(int*)arg;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        if (record_collection[i]->key == key) {
            // Found the record
            break;
        }
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

void free_records() {
    for (int i = 0; i < num_records; i++) {
        free(record_collection[i]->buffer);
        free(record_collection[i]);
    }

    free(record_collection);
}
