    srand(time(NULL));

    // Allocate memory for records array
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        return NULL;  // Handle memory allocation failure
    }

    // Check if the total memory usage exceeds the specified limit
