        return NULL;
    }

    int i;
    for (i = 0; i < num_records; i++) {
        // Initialize record with input values
        records[i].offset = offsets[0][i];
        records[i].key = keys[0][i];
        records[i].tag = tags[0][i];

        // Generate random double value within a given range
        double min_value = 1.0;  // Set the minimum and maximum values as needed
        double max_value = 100.0;
        records[i].value = (double)(rand() / (RAND_MAX / (max_value - min_value))) + min_value;

        // Check for duplicate keys
        int j;
        for (j = 0; j < i; j++) {
            if (records[j].key == records[i].key) {
                // Handle duplicate key: either log an error or modify behavior as needed
                // For demonstration purposes, skip the record with a duplicate key
                break;
            }
        }
        if (j != i) {
            return NULL;  // Return an error for duplicate keys
        }
    }

    // Integrate with external logging system to log successful creation of each record
