void prune_connections() {
    pthread_mutex_lock(&lock);
    long now = time(NULL);
    for (int i = 0; i < node_count; i++) {
        if ((now - nodes[i]->last_active_timestamp > prune_threshold) &&
            (nodes[i]->established_time + prune_interval < now)) {
            free(nodes[i]);
            --node_count;
            --i;
        }
    }
    pthread_mutex_unlock(&lock);
}

void update_cache(long timestamp) {
    // cache update logic here
}

void add_node(TCP_CONNECTION_STATS* node) {
    if (node_count >= MAX_NODES) {
        printf("Error: maximum number of nodes reached\n");
        return;
    }

    pthread_mutex_lock(&lock);

    if (cache_hit_rate > 0) {
        if ((timestamp - cache_last_accessed) < LOCK_TIMEOUT) {
            // cache hit
            node->config_settings = nodes[cache_hit_rate - 1]->config_settings;
            ++cache_hit_rate;
        } else {
            // cache miss
            int i = 0;
            for (i = 0; i < node_count; i++) {
                if ((timestamp - nodes[i]->last_active_timestamp) > prune_threshold) break;
            }
            if (i >= node_count) {
                printf("Error: no available nodes to prune\n");
                return;
            }
            free(nodes[i]);
            --node_count;

            // re-add the pruned node
            node->config_settings = (void*)malloc(sizeof(void*));
            nodes[node_count] = node;
            ++node_count;
        }
    }

    pthread_mutex_unlock(&lock);
}

