// Function to manage dynamic memory allocation and initialization
void* manageMemory(size_t offsetCapacity, size_t keyCapacity, size_t recordCount) {
    // Allocate arrays for offsets and keys
    long* offsets = (long*)malloc(offsetCapacity * sizeof(long));
    int* keys = (int*)malloc(keyCapacity * sizeof(int));

    // Initialize the arrays with some default values
    for (size_t i = 0; i < offsetCapacity; i++) {
        offsets[i] = i;
    }
    for (size_t i = 0; i < keyCapacity; i++) {
        keys[i] = i;
    }

    // Allocate array of record structures
    Record* records = (Record*)malloc(recordCount * sizeof(Record));

    // Initialize the records with some default values
    for (size_t i = 0; i < recordCount; i++) {
        records[i].value = i;
    }

    // Set the value of each record's int field to a random value within a given range
    int min = 1, max = 100;
    srand(time(NULL));
    for (size_t i = 0; i < recordCount; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }

    // Ensure the total memory usage does not exceed a predefined threshold
    size_t totalBytes = offsetCapacity * sizeof(long) + keyCapacity * sizeof(int) + recordCount * sizeof(Record);
    if (totalBytes > (size_t)(1024 * 1024)) { // Assuming 1MB as the threshold
        // Dynamically adjust the sizes of arrays and records to fit within the constraint
        size_t newOffsetCapacity = offsetCapacity / 2;
        size_t newKeyCapacity = keyCapacity / 2;
        size_t newRecordCount = recordCount / 2;

        free(offsets);
        free(keys);
        free(records);

        offsets = (long*)malloc(newOffsetCapacity * sizeof(long));
        keys = (int*)malloc(newKeyCapacity * sizeof(int));
        records = (Record*)malloc(newRecordCount * sizeof(Record));

        // Reinitialize the arrays and records
        for (size_t i = 0; i < newOffsetCapacity; i++) {
            offsets[i] = i;
        }
        for (size_t i = 0; i < newKeyCapacity; i++) {
            keys[i] = i;
        }
        for (size_t i = 0; i < newRecordCount; i++) {
            records[i].value = i;
        }

        // Continue with the random number generation and record initialization
    }

    return (void*)records;
}
