#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <logging-lib.h>

typedef struct {
    long offset;
    int key;
    char* buffer;
} dataItem;

void init_data_item(dataItem** items, int n) {
    for (int i = 0; i < n; i++) {
        (*items)[i].offset = i;
        (*items)[i].key = i % 10;

        size_t max_size = 1024; // predefined maximum buffer size
        (*items)[i].buffer = malloc(max_size);
        if (!(*items)[i].buffer) {
            logging_lib_log_error("Memory allocation failed for dataItem %d", i);
            continue;
        }

        strcpy((*items)[i].buffer, "default_value");
    }
}

void free_data_item(dataItem** items, int n) {
    for (int i = 0; i < n; i++) {
        if ((*items)[i].buffer) {
            free((*items)[i].buffer);
            (*items)[i].buffer = NULL;
        }
    }
}

void log_memory_usage(dataItem* items, int n) {
    logging_lib_log_info("Memory usage: %lu bytes", sizeof(*items) * n);

    for (int i = 0; i < n; i++) {
        size_t buffer_size = strlen(items[i].buffer);
        logging_lib_log_info("DataItem %d: offset %ld, key %d, buffer size %zu bytes", i, items[i].offset, items[i].key, buffer_size);
    }

    int largest_sizes[3] = {0};
    for (int i = 0; i < n; i++) {
        size_t buffer_size = strlen(items[i].buffer);
        if (i < 3) {
            largest_sizes[i] = buffer_size;
        } else if (buffer_size > largest_sizes[2]) {
            int k = 0;
            for (; k < 3; k++) {
                if (largest_sizes[k] >= buffer_size) break;
            }
            largest_sizes[k - 1] = buffer_size;
        }
    }

    logging_lib_log_info("Top three largest dataItem structures: %zu, %zu, %zu bytes", largest_sizes[0], largest_sizes[1], largest_sizes[2]);
}

int main() {
