Event* events = NULL;
int capacity = 0;
int size = 0;

void initEvents() {
    if (size == 0) {
        capacity = 1024;
        size = 0;
        events = (Event*)malloc(capacity * sizeof(Event));
    }
}

void resizeArray() {
    int newCapacity = capacity * 2;
    Event* newEvents = (Event*)realloc(events, newCapacity * sizeof(Event));

    if (newEvents == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    events = newEvents;
    capacity = newCapacity;
}

void addEvent() {
    if (size >= capacity) {
        resizeArray();
    }

    Event* event = &events[size];
    event->timestamp = time(NULL);
    event->id = size + 1;

    size++;
}

void deallocEvents() {
    free(events);
}
