    data_point* new_point = (data_point*)malloc(sizeof(data_point));
    if (!new_point) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize structure with random values
    srand(time(NULL));
    new_point->timestamp = time(NULL);
    new_point->sensor_id = rand() % 1000; // Unique sensor ID within the collection
    new_point->value = (double)rand() / RAND_MAX;

    // Validate device name and truncate if necessary
    char temp[MAX_DEVICE_NAME_LENGTH + 1];
    fgets(temp, sizeof(temp), stdin);
    if (strlen(temp) > MAX_DEVICE_NAME_LENGTH) {
        printf("Device name truncated to %d characters.\n", MAX_DEVICE_NAME_LENGTH);
        strcpy(new_point->device_name, temp);
    } else {
        strcpy(new_point->device_name, temp);
    }

    // Check for duplicate sensor ID
    int found = 0;
    *head = new_point;
    data_point* current = *head;
    while (current && !found) {
        if (new_point->sensor_id == current->sensor_id) {
            free(new_point);
            return NULL; // Sensor ID already exists, cannot add
        }
        current = current->next;
    }

    new_point->next = current;

    return new_point;
}

int main() {
    data_point* head = NULL;
    int num_points = 0;

    while (1) {
        printf("Enter the number of points to add: ");
        scanf("%d", &num_points);

        for (int i = 0; i < num_points; i++) {
            add_data_point(&head, 1);
        }

        // Periodically free and reallocate memory
        if (num_points % 100 == 0) {
            data_point* temp = head;
            while (temp) {
                data_point* next = temp->next;
                free(temp);
                temp = next;
