class Event {
public:
    std::string timestamp;
    std::string event_type;
    std::string source_id;
    int priority;
    std::map<std::string, std::string> metadata;

    Event(const std::string& ts, const std::string& et, const std::string& sid, int pr, const std::map<std::string, std::string>& md = {}) :
        timestamp(ts), event_type(et), source_id(sid), priority(pr), metadata(md) {}
};

class EventCollection {
private:
    std::vector<Event> events;
    std::mutex mtx;

public:
    void addEvent(const Event& e) {
        std::lock_guard<std::mutex> lock(mtx);
        events.push_back(e);
    }

    Event getEvent(size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index < events.size()) {
            return events[index];
        } else {
            throw std::out_of_range("Index out of range");
        }
    }

    void removeEvent(size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index < events.size()) {
            events.erase(events.begin() + index);
        } else {
            throw std::out_of_range("Index out of range");
        }
    }
};

