void create_records(int num_records, int max_offsets_per_record, int offset_range) {
    srand(time(NULL)); // Initialize random number generator with current time as seed

    struct Record* records = (struct Record*)malloc(num_records * sizeof(struct Record));
    if (!records) {
        printf("Memory allocation failed for records.\n");
        return;
    }

    long* offsets = (long*)malloc(num_records * max_offsets_per_record * sizeof(long));
    if (!offsets) {
        free(records);
        printf("Memory allocation failed for offsets.\n");
        return;
    }

    int i;
    for (i = 0; i < num_records; i++) {
        records[i].key = rand() % 100 + 1; // Random key within the range [1, 100]
        records[i].offsets = &offsets[i * max_offsets_per_record];
        for (int j = 0; j < max_offsets_per_record; j++) {
            records[i].offsets[j] = rand() % offset_range + 1;
        }
    }

    printf("Records created with keys and offsets:\n");
    for (i = 0; i < num_records; i++) {
        printf("Record %d: key = %d, offsets = {", i, records[i].key);
        for (int j = 0; j < max_offsets_per_record; j++) {
            printf("%ld ", records[i].offsets[j]);
        }
        printf("}\n");
    }

    free(offsets);
    free(records);
}
