// Define a linked list node structure
typedef struct Node {
    char* line;
    struct Node* next;
} Node;

// Function to create a new linked list node and allocate memory for the node's contents
Node* newNode(char* line) {
    Node* node = my_malloc(sizeof(Node));
    node->line = my_malloc(strlen(line) + 1);
    strcpy(node->line, line);
    node->next = NULL;
    return node;
}

// Function to process command-line arguments and input files
void process_args(int argc, char** argv) {
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "--directory") == 0) {
            // Process directory option
        } else if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--compression") == 0) {
            // Process compression option
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            // Process output format option
        } else {
            char* filename = argv[i];
            // Read and process each input file line by line
            Node* head = NULL;
            Record* records = (Record*) my_malloc(sizeof(Record));
            for (int j = 1; j < argc - i; j++) {
                FILE* file = fopen(filename, "r");
                if (!file) {
                    perror(filename);
                    continue;
                }
                while (fgets(line, sizeof(line), file)) {
                    Node* node = newNode(line);
                    // Add the new node to the linked list
                    if (!head) {
                        head = node;
                    } else {
                        Node* curr = head;
                        while (curr->next) {
                            curr = curr->next;
                        }
                        curr->next = node;
                    }
                }
                fclose(file);
                // Process each record and store it in the array
                Record* curr_record = records;
                for (Node* node = head; node; node = node->next) {
                    Record new_record;
                    // Initialize the record's ID and timestamp
                    new_record.id = j;
                    new_record.timestamp = time(NULL);
                    // Add the new record to the array
                    curr_record->id = new_record.id;
                    curr_record->timestamp = new_record.timestamp;
                    curr_record++;
                }
            }
        }
    }
}

int main(int argc, char** argv) {
    process_args(argc, argv);
    return 0;
}
