    srand(time(NULL));

    void* memory = malloc(size);

    if (memory == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Clear the allocated memory to prevent any potential issues
    memset(memory, 0, size);

    return memory;
}

void dealloc_memory(void** memptrs, int n) {
    for (int i = 0; i < n; i++) {
        if (*memptrs != NULL) {
            free(*memptrs);
            *memptrs = NULL;
        }
    }
}

record* init_records(int count, size_t record_size) {
    record* records = (record*)malloc(count * sizeof(record));

    // Initialize the timestamp for each record
    for (int i = 0; i < count; i++) {
        records[i].timestamp = time(NULL);
    }

    return records;
}

void* init_offsets(int count, size_t offset_size) {
    void* offsets = malloc(count * sizeof(long));

    // Initialize the random long offset values
    for (int i = 0; i < count; i++) {
        long val = rand() % 1000000000;
        *(long*)offsets + i = val;
    }

    return offsets;
}

void* init_keys(int count, size_t key_size) {
    void* keys = malloc(count * sizeof(int));

    // Initialize the int keys
    for (int i = 0; i < count; i++) {
        *(int*)keys + i = i;
    }

    return keys;
}

void manage_memory(size_t max_memory, int record_count) {
    size_t total_size = record_count * sizeof(record) + record_count * sizeof(long) + record_count * sizeof(int);

    if (total_size > max_memory) {
        printf("Total memory usage exceeds the maximum limit.\n");

        // Dynamically adjust sizes to prevent overflow
        record_count /= 2;

        while ((total_size = record_count * sizeof(record) + record_count * sizeof(long) + record_count * sizeof(int)) > max_memory) {
            record_count /= 2;
        }
    }

    void* records = init_records(record_count, sizeof(record));
    void* offsets = init_offsets(record_count, sizeof(long));
    void* keys = init_keys(record_count, sizeof(int));

    // Deallocate memory upon function return
    dealloc_memory(&records, 1);
    dealloc_memory(&offsets, 1);
    dealloc_memory(&keys, 1);
}

int main() {
    size_t max_memory = 10000000;
    int record_count = 1000000;

    manage_memory(max_memory, record_count);

    return 0;
}
