#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structure for 'offset' values
typedef struct {
    long offset;
} Offset;

// Define structure for 'record' components
typedef struct {
    int key;
    Offset *offset;
} Record;

// Function to initialize and allocate memory for records
Record* initRecords(int size) {
    Record *records = (Record *)malloc(size * sizeof(Record));
    if (!records) return NULL; // Handle allocation failure

    srand(time(NULL)); // Initialize random number generator with current time
    for (int i = 0; i < size; i++) {
        records[i].key = i;
        records[i].offset = &((Offset *)malloc(sizeof(Offset)))[i];
        if (!records[i].offset) return NULL; // Handle allocation failure

        // Initialize 'offset' values with random values
        records[i].offset->offset = rand() % 1000000;
    }
    return records;
}

// Function to reset the state of 'record' structures without reallocating memory
void resetRecords(Record *records, int size) {
    for (int i = 0; i < size; i++) {
        records[i].key = -1; // Mark as un-initialized
        records[i].offset->offset = 0;
    }
}

// Function to access 'offset' values associated with each 'record' structure
const Offset* getOffset(Record *records, int index) {
    if (index >= records && !records[index].offset) return NULL; // Handle out-of-bounds or uninitialized record
    return &records[index].offset;
}

// Free allocated memory for records and their 'offset' values
void freeRecords(Record *records, int size) {
    for (int i = 0; i < size; i++) {
        if (!records[i].offset) continue; // Ignore uninitialized or unallocated 'record'
        free(records[i].offset);
    }
    free(records);
}
