#define HUMIDITY_RANGE 80
#define TOLERANCE 1.0

typedef struct {
    float temperature;
    int humidity;
} sensor_data;

sensor_data* create_sensor_data(int count) {
    if(count > MAX_RECORDS) {
        printf("Error: Maximum number of records exceeded.\n");
        return NULL;
    }

    sensor_data* data = (sensor_data*)malloc(count * sizeof(sensor_data));

    if(data == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for(int i = 0; i < count; i++) {
        data[i].temperature = rand() / (float)RAND_MAX * TEMPERATURE_RANGE;
        data[i].humidity = rand() % HUMIDITY_RANGE;

        // Ensure no two records have the same temperature value within tolerance
        while(i > 0 && fabs(data[i].temperature - data[i-1].temperature) < TOLERANCE) {
            data[i].temperature += rand() / (float)RAND_MAX * TEMPERATURE_RANGE;
            data[i].humidity = rand() % HUMIDITY_RANGE;
        }
    }

    return data;
}

void free_sensor_data(sensor_data* data, int count) {
    if(data != NULL) {
        free(data);
    }
}
