```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

void my_realloc(void* ptr, size_t newSize) {
    void* newPtr = realloc(ptr, newSize);
    if (!newPtr) {
        printf("Re-allocation failed\n");
        exit(1);
    }
    return;
}

void manageMemory(int capacity, int numRecords) {
    long* offsets = my_malloc(capacity * sizeof(long));
    int* keys = my_malloc(capacity * sizeof(int));

    record* records = my_malloc(numRecords * sizeof(record));

    // Initialize arrays and records
    for (int i = 0; i < capacity; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100; // Random value between 0 and 99
    }

    int totalBytes = capacity * sizeof(long) + capacity * sizeof(int) + numRecords * sizeof(record);

    if (totalBytes > 1024 * 1024 * 10) {
        // Dynamic adjustment of array sizes and records to fit within the constraint
        capacity = (int)(1024 * 1024 * 10 / (capacity * sizeof(long) + capacity * sizeof(int) + numRecords * sizeof(record)));
        offsets = my_realloc(offsets, capacity * sizeof(long));
        keys = my_realloc(keys, capacity * sizeof(int));

        records = my_realloc(records, capacity * sizeof(record));
    }

    // Testing the quality of generated random numbers
    int passedTests = 0;
    for (int i = 0; i < numRecords; i++) {
        if (records[i].value >= 0 && records[i].value <= 99) {
            passedTests++;
        }
    }
    printf("Random number generation quality: %d/%d tests passed\n", passedTests, numRecords);

    // Deallocate memory when the function returns
    my_free(offsets);
    my_free(keys);
    my_free(records);
}

int main() {
    int capacity = 1000;
    int numRecords = 500;

    srand(time(NULL)); // Seed random number generator

    manageMemory(capacity, numRecords);

    return 0;
}
