#include <time.h>

typedef struct {
    int value;
} record_t;

void manage_memory(int num_records, int max_offset, int range_start, int range_end) {
    // Initialize arrays with initial capacity
    long* offsets = (long*)malloc(1024 * sizeof(long));
    int* keys = (int*)malloc(1024 * sizeof(int));

    // Dynamic resizing for arrays
    while (sizeof(*offsets) + sizeof(*keys) >= 65536) {
        // Double the initial capacity
        long* temp_offsets = (long*)realloc(offsets, 2048 * sizeof(long));
        int* temp_keys = (int*)realloc(keys, 2048 * sizeof(int));
        offsets = temp_offsets;
        keys = temp_keys;
    }

    // Initialize array of record structures
    record_t** records = (record_t**)malloc(num_records * sizeof(record_t*));

    // Dynamic resizing for records
    while ((num_records * sizeof(record_t)) >= 65536) {
        // Double the initial capacity
        record_t** temp_records = (record_t**)realloc(records, num_records * 2 * sizeof(record_t*));
        records = temp_records;
        num_records *= 2;
    }

    for (int i = 0; i < num_records; i++) {
        // Initialize record structure
        records[i] = (record_t*)malloc(sizeof(record_t));
        records[i]->value = rand() % (range_end - range_start + 1) + range_start;
    }

    // Ensure total memory usage does not exceed threshold
    while ((sizeof(*offsets) + sizeof(*keys) + num_records * sizeof(record_t)) > max_offset) {
        if (num_records > 0) {
            free(records[--num_records]);
        }
        offsets = (long*)realloc(offsets, (num_records + 1) * sizeof(long));
        keys = (int*)realloc(keys, (num_records + 1) * sizeof(int));
    }

    // Free memory
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);
}
