typedef struct {
    size_t capacity;
    void** memory;
    size_t freeIndex;
} MemoryPoolAllocator;

// Custom memory pool allocator function
void* my_malloc(size_t size) {
    // Allocate and initialize the memory pool
    static MemoryPoolAllocator mp = {0, NULL, 0};
    if (!mp.memory || mp.freeIndex == 0) {
        mp.capacity = (size_t)1 << 20;
        mp.memory = (void**)malloc(mp.capacity * sizeof(void*));
        mp.freeIndex = mp.capacity;
    }
    // Return allocated memory
    return *(--mp.freeIndex);
}

// Custom random number generator function
int my_random(int min, int max) {
    // Initialize the random number generator
    static RandomGenerator rg = {1};
    // Generate a random number based on the seed and parameters
    rg.seed = (rg.seed * 1103515245 + 12345) % (1 << 31);
    return (int)((rg.seed % ((max - min + 1) * 2)) - max + min);
}

