from typing import List, Dict

async def process_events(request: web.Request) -> web.Response:
    json_payload = await request.json()
    operation = json_payload.get('operation', None)
    if operation not in ['store', 'fetch']:
        return web.json_response({'status': 'error', 'data': 'Invalid operation'}, status=400)

    event_id = json_payload['event_id']
    source = json_payload['source']
    timestamp = json_payload['timestamp']
    payload = json_payload['payload']

    if operation == 'store':
        try:
            await CacheSystem().put(event_id, payload)
        except Exception as e:
            return web.json_response({'status': 'error', 'data': str(e)}, status=500)

        events_metadata[Event(event_id, source, timestamp).metadata] = True
    elif operation == 'fetch':
        try:
            cached_payload = await CacheSystem().get(event_id)
            if cached_payload:
                return web.json_response({'status': 'success', 'data': cached_payload})
        except Exception as e:
            return web.json_response({'status': 'error', 'data': str(e)}, status=500)

    return web.json_response({'status': 'success'})

events_metadata = {}
binary_data_storage = {}

async def clear_stored_data():
    try:
        CacheSystem().clear()
        events_metadata.clear()
        binary_data_storage.clear()
    except Exception as e:
        print(f"Error clearing stored data: {str(e)}")

loop = asyncio.get_event_loop()
loop.run_until_complete(clear_stored_data())
