// Define custom data structure for key-value pair
typedef struct {
    char* key;
    int id;
    float score;
} kv_pair;

// Define hash table node structure
typedef struct hash_node {
    char* key;
    kv_pair value;
    struct hash_node* next;
} hash_node;

// Define hash table structure
typedef struct {
    hash_node** buckets;
    int size;
    int capacity;
} hash_table;

// Function to create a new hash table with given capacity
hash_table* hash_create(int capacity) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->size = 0;
    ht->capacity = capacity;
    ht->buckets = (hash_node**)malloc(capacity * sizeof(hash_node*));
    for (int i = 0; i < capacity; i++) {
        ht->buckets[i] = NULL;
    }
    return ht;
}

// Function to insert a new key-value pair into the hash table
void hash_insert(hash_table* ht, char* key, int id, float score) {
    int index = hash(key) % ht->capacity;
    hash_node* node = (hash_node*)malloc(sizeof(hash_node));
    node->key = key;
    node->value.id = id;
    node->value.score = score;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
}

// Function to delete a key-value pair from the hash table
void hash_delete(hash_table* ht, char* key) {
    int index = hash(key) % ht->capacity;
    hash_node* current = ht->buckets[index];
    hash_node* prev = NULL;
    while (current != NULL && strcmp(current->key, key) != 0) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) return;
    if (prev == NULL) {
        ht->buckets[index] = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
}

// Function to perform a lookup operation in the hash table
kv_pair* hash_lookup(hash_table* ht, char* key) {
    int index = hash(key) % ht->capacity;
    hash_node* node = ht->buckets[index];
    while (node != NULL && strcmp(node->key, key) != 0) {
        node = node->next;
    }
    if (node == NULL) return NULL;
    return &node->value;
}

// Function to free the memory allocated for a hash table
void hash_free(hash_table* ht) {
    for (int i = 0; i < ht->capacity; i++) {
        hash_node* node = ht->buckets[i];
        while (node != NULL) {
            hash_node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

