#define MAX_RECORDS 1000
#define MAX_THRESHOLD (MAX_RECORDS * sizeof(record))

typedef struct {
    int value;
} record;

record* allocRecords(int count) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;
    memset(records, 0, count * sizeof(record));
    return records;
}

void* allocArrays(size_t* offset_count, size_t* key_count, int max_records) {
    size_t* offsets = (size_t*)malloc(max_records * sizeof(size_t));
    int* keys = (int*)malloc(max_records * sizeof(int));
    record* records = allocRecords(max_records);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    memset(offsets, 0, max_records * sizeof(size_t));
    memset(keys, 0, max_records * sizeof(int));

    return (void*)malloc(sizeof(void*) + max_records * sizeof(size_t) + max_records * sizeof(int) + max_records * sizeof(record));
}

int serializeRecords(record* records, int count, FILE* file) {
    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }
    return 0;
}

int deserializeRecords(record* records, int* count, FILE* file) {
    fread(count, sizeof(int), 1, file);
    *count = *(int*)count;
    for (int i = 0; i < *count; i++) {
        fread(&records[i], sizeof(record), 1, file);
    }
    return 0;
}

void freeArrays(void* ptr) {
    size_t* offsets = (size_t*)((char*)ptr - sizeof(void*));
    int* keys = (int*)((char*)ptr - sizeof(size_t) * sizeof(int));
    record* records = (record*)((char*)ptr - sizeof(size_t) * sizeof(int));

    free(ptr);
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int max_records = MAX_RECORDS;
    size_t max_threshold = MAX_THRESHOLD;

    void* ptr = allocArrays(&max_records, &max_records, max_records);

    if (!ptr) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Use the allocated memory...

    freeArrays(ptr);
    return 0;
}
