#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    char *str;
    struct node *next;
} node;

node* create_node(int key, char *str) {
    node *new_node = (node *)malloc(sizeof(node));
    if (!new_node) {
        return NULL;
    }
    new_node->key = key;
    new_node->str = str;
    new_node->next = NULL;
    return new_node;
}

void free_node(node *head) {
    while (head != NULL) {
        node *temp = head;
        head = head->next;
        free(temp);
    }
}

node* deserialize(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return NULL;
    }

    node *head = NULL;
    while (fread(&head, sizeof(node), 1, file)) {
        head->next = NULL; // reset next pointer for deserialization
    }
    fclose(file);
    return head;
}

void serialize(node *head, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return;
    }

    node *current = head;
    while (current != NULL) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(current->str, strlen(current->str) + 1, 1, file);
        current = current->next;
    }
    fclose(file);
}

void print_list(node *head) {
    while (head != NULL) {
        printf("Key: %d, String: %s\n", head->key, head->str);
        head = head->next;
    }
}

node* init_linked_list(int range, int length) {
    srand(time(NULL)); // initialize random number generator

    node *head = NULL;
    for (int i = 0; i < 5; i++) { // create 5 nodes
        int key = rand() % range;
        char str[100]; // fixed string length, adjust as needed
        for (int j = 0; j < length; j++) {
            str[j] = (char)(rand() % 26 + 'a');
        }
        str[length] = '\0'; // null-terminate the string

        node *new_node = create_node(key, str);
        if (!head) { // first node
            head = new_node;
        } else {
            node *temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }

    return head;
}

int main() {
    node *head = init_linked_list(100, 10); // create linked list with random nodes

    printf("Printing initial linked list:\n");
    print_list(head);

    char filename[50];
    sprintf(filename, "linked_list_%d.txt", time(NULL)); // generate unique file name
    serialize(head, filename);

    head = deserialize(filename);
    if (!head) {
        printf("Error deserializing linked list.\n");
    } else {
        printf("Printing restored linked list:\n");
        print_list(head);
    }

    free_node(head); // clean up dynamically allocated memory

    return 0;
}
