typedef struct {
    DatasetComponent* components;
    size_t component_count;
} Dataset;

void* malloc_dataset_component(size_t size) {
    return malloc(size);
}

void free_dataset_component(void* ptr, size_t size) {
    free(ptr);
}

Dataset* create_dataset() {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    dataset->components = NULL;
    dataset->component_count = 0;
    return dataset;
}

int add_component_to_dataset(Dataset* dataset, int offset, char* key, char* record) {
    size_t size = sizeof(DatasetComponent);
    DatasetComponent* component = (DatasetComponent*)malloc_dataset_component(size);
    component->offset = offset;
    strcpy(component->key, key);
    strcpy(component->record, record);
    component->metadata = NULL;

    dataset->components = realloc(dataset->components, (dataset->component_count + 1) * size);
    memcpy(dataset->components + dataset->component_count * size, component, size);
    dataset->component_count++;
    free_component(component);
}

void serialize_dataset(Dataset* dataset, FILE* file) {
    deflateInit2(&dzstream, Z_DEFAULT_COMPRESSION, Z_DEFAULT_WINDOW, 0, 8, 9);

    for (int i = 0; i < dataset->component_count; i++) {
        DatasetComponent* component = &dataset->components[i];
        unsigned char buffer[1024];

        // serialize and compress
        deflate(buffer, component->record, strlen(component->record));
        fwrite(&buffer, sizeof(unsigned char), strlen(component->record), file);

        // write metadata
        fwrite(&component->metadata, 1, 0, file); // adjust metadata size according to its type

        // reset buffer
        bzero(buffer, 1024);
    }

    deflateEnd(&dzstream);
}

void deserialize_dataset(Dataset* dataset, FILE* file) {
    inflateInit2(&dzstream, Z_DEFAULT_COMPRESSION, Z_DEFAULT_WINDOW, 0, 8, 9);

    for (int i = 0; i < dataset->component_count; i++) {
        DatasetComponent* component = &dataset->components[i];
        unsigned char buffer[1024];

        // read and decompress
        fread(&buffer, sizeof(unsigned char), strlen(component->record), file);
        inflate(buffer, buffer, strlen(component->record));
        strcpy(component->record, (char*)buffer);

        // read metadata
        fread(&component->metadata, 1, 0, file); // adjust metadata size according to its type

        // reset buffer
        bzero(buffer, 1024);
    }

    inflateEnd(&dzstream);
}

