node* create_node(char data) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(node** head, char data) {
    if (*head == NULL || data < (*head)->data) {
        node* new_head = create_node(data);
        new_head->next = *head;
        *head = new_head;
    } else {
        node* current = *head;
        while (current->next && current->next->data >= data) {
            current = current->next;
        }
        if (current->next && current->next->data == data) {
            printf("Error: duplicate value\n");
            return;
        }
        node* new_node = create_node(data);
        new_node->next = current->next;
        current->next = new_node;
    }
}

void print_list(node* head) {
    while (head) {
        printf("%c ", head->data);
        head = head->next;
    }
    printf("\n");
}

node* reverse_list(node* head) {
    node* prev = NULL;
    node* current = head;
    node* next = NULL;
    while (current) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    return prev;
}

