    *nodes[0]->next = nodes[1];
    *nodes[1]->next = nodes[2];

    insert_node(nodes, 'b');
    insert_node(&(*nodes[2]), 'c');

    node* reversed_list = reverse_list(*nodes[0]);

    print_list(reversed_list);

    free(doubles);
    free(chars);
    for (int i = 0; i < 3; i++) {
        free(nodes[i]);
