// Define the structure for nodes in the doubly linked list
typedef struct Node {
    char character;
    struct Node* prev;
    struct Node* next;
    int index;
} Node;

// Function to dynamically manage memory for a doubly linked list
Node* DLL_create() {
    return NULL; // Initialize an empty list
}

// Method to insert a new node at the head of the list, ensuring unique characters
void DLL_insert_head(Node** head, char character) {
    if (character == '\0') return; // Ignore null characters

    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->character = character;
    newNode->prev = NULL;
    newNode->next = *head;
    newNode->index = 0;

    if (*head != NULL) {
        (*head)->prev = newNode;
    }
    *head = newNode; // Update the head of the list
}

// Method to insert a new node at the tail of the list, ensuring unique characters
void DLL_insert_tail(Node** tail, char character) {
    if (character == '\0') return; // Ignore null characters

    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->character = character;
    newNode->prev = *tail;
    newNode->next = NULL;
    newNode->index = 0;

    if (*tail != NULL) {
        (*tail)->next = newNode;
    }
    *tail = newNode; // Update the tail of the list
}

// Method to traverse the list forward and print its contents
void DLL_forward_traversal(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%c ", current->character);
        current = current->next;
    }
    printf("\n");
}

// Method to traverse the list backward and print its contents
void DLL_backward_traversal(Node* tail) {
    Node* current = tail;
    while (current != NULL) {
        printf("%c ", current->character);
        current = current->prev;
    }
    printf("\n");
}

// Method to remove a node based on the specified index, handling edge cases
void DLL_remove_index(Node** head, Node** tail, int index) {
    if (*head == *tail || index < 0) return; // Handle invalid indices

    Node* current = *head;
    while (current != NULL && current->index != index) {
        current = current->next;
    }

    if (current == NULL) return; // Handle non-existent node

    if (current == *head) {
        *head = current->next;
    } else if (current == *tail) {
        *tail = current->prev;
    }
    current->prev->next = current->next;
    current->next->prev = current->prev;

    free(current);
}

// Method to batch delete nodes within a specified range of indices
void DLL_batch_delete(Node** head, Node** tail, int start, int end) {
    if (start > end || *head == *tail || start < 0 || end >= 0) return; // Handle invalid ranges

    Node* current = *head;
    while (current != NULL && current->index <= start) {
        current = current->next;
    }

    if (current == NULL) return; // Handle non-existent nodes in the range

    while (current != NULL && current->index <= end) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
}

// Method to track and reset the total number of nodes in the list
int DLL_get_node_count(Node* head, Node* tail) {
    int count = 0;
    for (Node* current = head; current != NULL; current = current->next) {
        count++;
    }
    return count;
}

// Method to reset the list to an empty state
void DLL_reset(Node** head, Node** tail) {
    *head = *tail = NULL;
}
