    if (offsets == NULL || sizeof(offsets[0]) != sizeof(long)) {
        free(offsets);
        return NULL;
    }

    int* keys = (int*)malloc(sizeof(int) * 5000);
    if (keys == NULL || sizeof(keys[0]) != sizeof(int)) {
        free(keys);
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < 5000; i++) {
        keys[i] = rand() % 10000 + 1;
    }

    // Ensure no duplicates
    int uniqueKeys[5000];
    int uniqueCount = 0;
    for (int i = 0; i < 5000; i++) {
        bool found = false;
        for (int j = 0; j < uniqueCount; j++) {
            if (keys[i] == uniqueKeys[j]) {
                found = true;
                break;
            }
        }
        if (!found) {
            uniqueKeys[uniqueCount++] = keys[i];
        }
    }

    record* records = (record*)malloc(sizeof(record) * 10000);
    if (records == NULL || sizeof(records[0]) != sizeof(record)) {
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    int max_value = 1000000;
    for (int i = 0; i < 10000; i++) {
        record r;
        r.value = (offsets[i] * uniqueKeys[i % uniqueCount] + rand() % 100) % max_value;
        records[i] = r;
    }

    // Ensure memory usage does not exceed 10MB
    size_t total_size = sizeof(long) * 10000 + sizeof(int) * 5000 + sizeof(record) * 10000;
    if (total_size > 10*1024*1024) {
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    // Handle edge cases
    for (int i = 0; i < 10000; i++) {
        if (records[i].value < -max_value || records[i].value >= max_value) {
            free(records);
            free(keys);
            free(offsets);
            return NULL;
        }
    }

    // Return pointer to the first element of the records array
    return records;
}
