typedef struct {
    int value;
} record;

record* generateRecords(int seed) {
    int max_value = 1000000;
    srand(time(NULL));

    // Allocate memory for offset array
    long* offsets = (long*)malloc((10000 / sizeof(long)) * sizeof(long));
    if (!offsets) return NULL;

    // Initialize random offset values
    for (int i = 0; i < 10000; i++) {
        offsets[i] = rand() % 2000000 - 1000000;
    }

    // Allocate memory for key array
    int* keys = (int*)malloc((5000 / sizeof(int)) * sizeof(int));
    if (!keys) return NULL;

    // Initialize random unique key values
    for (int i = 0; i < 5000; i++) {
        do {
            keys[i] = rand() % 10000 + 1;
        } while (i > 0 && binarySearch(keys, i, keys[i]) >= 0);
    }

    // Allocate memory for records array
    record* records = (record*)malloc((5000 / sizeof(record)) * sizeof(record));
    if (!records) return NULL;

    // Initialize record values using offset and key
    int offset_index = 0, key_index = 0;
    for (int i = 0; i < 5000; i++) {
        records[i].value = (offsets[offset_index] * keys[key_index] + seed) % max_value;
        if (++key_index >= 5000) key_index = 0;
        offset_index++;
    }

    // Free memory
    free(offsets);
    free(keys);

    return records;
}

int binarySearch(int* arr, int size, int target) {
    int left = 0, right = size - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}
