        process_string(payload);

        data_node* new_node = (data_node*)malloc(sizeof(data_node));
        new_node->payload = payload;
        insert_node(&list, new_node);

        unsigned int hash_index = custom_hash(payload) % table.size;
        if (table.num_elements >= table.size * 0.7) {
            // Resize the hash table as needed
            resize_hash_table(&table, table.size * 2);
        }
        table.buckets[hash_index] = new_node;

        free(payload);
    }

    // Deallocate memory and handle potential errors
    deallocate_memory(list.head, list.size);

    return 0;
}
