#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} record;

void init_data_structures(int n, int minValue, int maxValue) {
    if (n <= 0 || minValue > maxValue) {
        printf("Invalid parameters. Please check and try again.\n");
        return;
    }

    // Allocate array of long offsets
    long* offsets = (long*) malloc(n * sizeof(long));
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
    }

    // Allocate array of int keys
    int* keys = (int*) malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        keys[i] = i;
    }

    // Shuffle the keys to ensure uniqueness
    srand(time(NULL));
    for (int i = n - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = keys[i];
        keys[i] = keys[j];
        keys[j] = temp;
    }

    // Allocate array of record structures
    record* records = (record*) aligned_malloc(n * sizeof(record), 16);

    // Populate each record's int field with a random value within the given range
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].offset = offsets[i];
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    aligned_free(records);
}

void* aligned_malloc(size_t size, size_t alignment) {
    size_t offset = (size_t) alignment - 1;
    void* ptr = (void*) ((size_t) malloc((size + alignment - 1) / alignment * alignment)) + offset % alignment;
    return ptr;
}

void aligned_free(void* ptr) {
    free(ptr);
}
