#include <sys/stat.h>

#define MAX_FILE_SIZE 1024*1024*1024 // 1GB
#define MAX_ERROR_LOG_LENGTH 256

typedef struct {
    const EVP_MD *digest;
    X509 *public_key;
} SignatureVerificationOptions;

int verify_signature(const char *file_path, SignatureVerificationOptions *options) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        // File does not exist
        return -1; 
    }

    struct stat file_stat;
    fstat(fileno(file), &file_stat);
    size_t file_size = file_stat.st_size;

    if (file_size > MAX_FILE_SIZE) {
        // File is too large
        fclose(file);
        return -2; 
    }

    unsigned char *buffer = malloc(file_size);
    fread(buffer, 1, file_size, file);

    if (EVP_DigestVerifyInit(NULL, NULL, options->digest, 0, buffer, file_size) != 1) {
        // Signature verification failed
        free(buffer);
        fclose(file);
        return -3; 
    }

    EVP_DigestVerifyUpdate(NULL, buffer, file_size);

    unsigned char *signature = malloc(options->public_key->sigalg->si_length);
    EVP_DigestVerifyFinal(signature, options->public_key->sigalg->si_length);

    free(buffer);

    if (EVP_DigestVerifyFinal() != 1) {
        // Signature verification failed
        free(signature);
        fclose(file);
        return -4; 
    }

    free(signature);

    fclose(file);

    return 1; // Valid signature
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("Usage: %s <file_path> <signature_options>\n", argv[0]);
        exit(1);
    }

    SignatureVerificationOptions options;
    const EVP_MD *digest = EVP_md_sha256();
    X509 *public_key = NULL;

    // Initialize public key from external service or cache
    // ...

    int result = verify_signature(argv[1], &options);

    if (result < 0) {
        char error_message[MAX_ERROR_LOG_LENGTH];
        sprintf(error_message, "Error verifying signature for file '%s': %d", argv[1], result);
        // Log the error using a third-party logging framework
        // ...
    } else if (result == 1) {
        // Signature is valid
        printf("Signature verified successfully\n");
    }
}
