    for(int i = 0; i < size; i++) {
        Data* new_data = (Data*)malloc(sizeof(Data));
        new_data->value = (double)rand() / RAND_MAX;
        new_data->str = (char*)malloc((10 + rand() % 20) * sizeof(char));
        for(int j = 0; j < strlen(new_data->str); j++) {
            new_data->str[j] = (char)(rand() % 26 + 65);
        }
        new_data->str[strlen(new_data->str)] = '\0';
        if(*head) {
            Node* temp = (Node*)malloc(sizeof(Node));
            temp->data = *new_data;
            temp->next = (*head)->next;
            (*head)->next = temp;
        } else {
            *head = new_data;
        }
    }
}

void validate_data_structure(Data** head) {
    Node* current = *head;
    while(current) {
        if(current->data.value > 1.0 || current->data.value < 0.0) {
            printf("Invalid value in data structure\n");
        }
        for(int i = 0; i < strlen(current->data.str); i++) {
            if(current->data.str[i] < 65 || current->data.str[i] > 90) {
                printf("Invalid character in string\n");
            }
        }
        free(current->data.str);
        free(current);
        current = current->next;
    }
}

