typedef struct {
    int id;
    double value;
    char* name;
} CustomObject;

CustomObject** createCustomList(int capacity) {
    if (capacity <= 0 || capacity & (capacity - 1)) {
        return NULL; // error, capacity not a power of two
    }

    CustomObject** list = (CustomObject**)malloc((size_t)capacity * sizeof(CustomObject*));
    if (!list) {
        return NULL; // out of memory
    }
    list->size = 0;
    list->maxCapacity = capacity;

    return list;
}

void addObject(CustomObject** list, int id, double value, const char* name) {
    if (list->size >= list->maxCapacity) {
        list->maxCapacity *= 2;
        CustomObject** newList = (CustomObject**)realloc(list, (size_t)list->maxCapacity * sizeof(CustomObject*));
        if (!newList) {
            // out of memory
        }
        list = newList;
    }

    CustomObject* obj = (CustomObject*)malloc(sizeof(CustomObject));
    if (!obj) {
        // out of memory
    }
    obj->id = id;
    obj->value = value;
    obj->name = strdup(name);

    list[list->size++] = obj;
}

void removeObject(CustomObject** list, int index) {
    if (index < 0 || index >= list->size) {
        // out of range
    }

    CustomObject* obj = list[index];
    list[index] = NULL; // mark for garbage collection

    free(obj);
    list->size--;
}

void destroyList(CustomObject** list) {
    for (int i = 0; i < list->size; i++) {
        CustomObject* obj = list[i];
        if (!obj) continue;
        free(obj->name);
        free(obj);
    }
    free(list);
}
