        char name[MAX_LENGTH];
        sprintf(name, "Object_%d", i);

        if (strlen(name) > MAX_LENGTH || strlen(name) + sizeof(int) > MAX_MEMORY / n) return; // handle invalid names

        Object* obj = (Object*)malloc(sizeof(Object));
        strcpy(obj->name, name);
        obj->value = (rand() % (maxValue - minValue)) + minValue;

        if (!objects) {
            objects = (Object*)malloc(n * sizeof(Object));
        }

        for (j = 0; j < i; j++) {
            if (strcmp(objects[j].name, name) == 0) return; // ensure unique names
        }

        memmove(&objects[i], &objects[i - 1], (i) * sizeof(Object)); // shift previous objects to make room for new one
        memcpy(&objects[i], obj, sizeof(Object));
    }

    if (n > 0) {
        free(objects); // deallocate memory when done
    }
}
