// Define log levels
typedef enum {
    DEBUG,
    INFO,
    ERROR
} LogLevel;

// Structure to represent a log entry
typedef struct {
    time_t timestamp;
    LogLevel level;
    char* message;
} LogEntry;

// Circular buffer structure with configurable size and logging level filtering
typedef struct {
    int capacity;
    int current_size;
    int front;
    int rear;
    LogLevel min_level;
    LogEntry* entries;
} CircularBuffer;

CircularBuffer* circular_buffer_init(int capacity, LogLevel min_level) {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    buffer->capacity = capacity;
    buffer->current_size = 0;
    buffer->front = 0;
    buffer->rear = 0;
    buffer->min_level = min_level;
    buffer->entries = (LogEntry*)calloc(capacity, sizeof(LogEntry));
    return buffer;
}

void circular_buffer_append(CircularBuffer* buffer, LogLevel level, char* message) {
    if (buffer->current_size == buffer->capacity) {
        // Reclaim space in the buffer
        int old_front = buffer->front;
        buffer->front = (buffer->front + 1) % buffer->capacity;
        memmove(buffer->entries, &buffer->entries[old_front], sizeof(LogEntry));
    }
    LogEntry entry;
    entry.timestamp = time(NULL);
    entry.level = level;
    entry.message = message;
    buffer->entries[buffer->rear] = entry;
    buffer->rear = (buffer->rear + 1) % buffer->capacity;
    buffer->current_size++;
}

void circular_buffer_set_min_level(CircularBuffer* buffer, LogLevel new_min_level) {
    buffer->min_level = new_min_level;
}

int main() {
    CircularBuffer* buffer = circular_buffer_init(10, DEBUG);

    // Log entries
    circular_buffer_append(buffer, ERROR, "Error message");
    circular_buffer_append(buffer, INFO, "Info message");

    // Set minimum log level to WARNING
    circular_buffer_set_min_level(buffer, WARNING);

    return 0;
}
