        // Reallocate memory and reinit arrays
        doubles = (double*)realloc(doubles, size1 * sizeof(double));
        structs = (struct float_char*)realloc(structs, size2 * sizeof(struct float_char));
        flags = (bool*)realloc(flags, size3 * sizeof(bool));
        events = (Event*)realloc(events, max_events * sizeof(Event));

        // Reinit arrays
