        }
        for(int i = 0; i < size3; i++) {
            flags[i] = my_rand(0, 1) > 0;
        }
    }

    // Free allocated memory
    free(doubles);
    free(structs);
    free(flags);
    for(int i = 0; i < max_events; i++) {
        free(events[i].description);
