#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the custom data structure
typedef struct {
    int timestamp;
    char sensor_id[16];
    float value;
    char device_name[32];
} data_point;

// Define a node in the binary search tree and red-black tree
typedef struct {
    char* string;
    int value;
    struct Node* left, *right;
} Node;

// Function to initialize and manage dynamic memory allocation for custom data structure
void* init_data(struct data_point** dp, int* count) {
    // Initialize the linked list to store data points
    *dp = (struct data_point*)malloc(sizeof(struct data_point));
    (*dp)->timestamp = rand();
    strcpy((*dp)->sensor_id, "Sensor_ID");
    (*dp)->value = 1.0;
    strcpy((*dp)->device_name, "Device_Name");

    // Initialize the BST and RBT
    Node* bst_root = NULL;
    Node* rbt_root = NULL;

    // Initialize the external data source
    FILE* file = fopen("data_source.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return NULL;
    }

    // Read and process real-time sensor readings and timestamps from the file
    int i = 0;
    while (!feof(file)) {
        data_point* dp = (data_point*)malloc(sizeof(data_point));
        fscanf(file, "%d %s %f %s", &dp->timestamp, dp->sensor_id, &dp->value, dp->device_name);
        // Insert the data point into the BST and RBT
        insert_node(&bst_root, dp->value, dp->string);
        insert_node(&rbt_root, dp->value, dp->string);

        // Update the linked list
        (*count)++;
        (*dp) = (struct data_point*)realloc(*dp, sizeof(struct data_point) * (*count));
        (*dp)[*count - 1] = *dp;

        i++;
    }

    fclose(file);
    return NULL;
}

// Function to insert a node into the BST and RBT
void insert_node(Node** root, int value, char* string) {
    if (*root == NULL) {
        *root = (Node*)malloc(sizeof(Node));
        (*root)->value = value;
        (*root)->string = string;
        (*root)->left = NULL;
        (*root)->right = NULL;
    } else if (value < (*root)->value) {
        insert_node(&((*root)->left), value, string);
    } else {
        insert_node(&((*root)->right), value, string);
    }
}

// Function to traverse and search the BST and RBT
void traverse_node(Node* root) {
    if (root != NULL) {
        printf("%d %s\n", root->value, root->string);
        traverse_node(root->left);
        traverse_node(root->right);
    }
}
