Node* update_list(char** char_array, int length, Node* head) {
    Node* current = head;
    for (int i = 0; i < length; i++) {
        if (current != NULL) {
            free(current);
            current = current->next;
        } else {
            break;
        }
    }

    for (int i = 0; i < length; i++) {
        char byte = char_array[i][0];
        Node* new_node = create_node(byte);
        if (head == NULL) {
            head = new_node;
        } else {
            Node* last = head;
            while (last->next != NULL) {
                last = last->next;
            }
            last->next = new_node;
        }
    }

    return head;
}

