```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Custom hash function using FNV-1a
size_t custom_hash(const char* key) {
    size_t hash = 0x811C9DC5;
    while (*key != '\0') {
        hash ^= *key;
        hash *= 0x01ED5FA8;
        key++;
    }
    return hash;
}

// Hash table structure
typedef struct {
    int capacity;
    int size;
    int* buckets;
} HashTable;

// Initialize the hash table with a specified number of buckets
HashTable* initialize_hash_table(int num_buckets) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = num_buckets;
    table->size = 0;
    table->buckets = (int*)calloc(num_buckets, sizeof(int));
    return table;
}

// Insert a key-value pair into the hash table
void insert_hash_table(HashTable* table, const char* key, int value) {
    size_t index = custom_hash(key) % table->capacity;
    if (table->buckets[index] == 0) {
        table->size++;
    }
    // Quadratic probing for collision resolution
    while (table->buckets[index] != 0) {
        index = (index + 1) % table->capacity;
    }
    table->buckets[index] = value;
}

// Retrieve the value associated with a given key from the hash table
int retrieve_hash_table(HashTable* table, const char* key) {
    size_t index = custom_hash(key) % table->capacity;
    while (table->buckets[index] != 0 && strcmp((char*)&table->buckets[index], key) != 0) {
        index = (index + 1) % table->capacity;
    }
    if (table->buckets[index] == 0) {
        return -1; // Key not found
    } else {
        return table->buckets[index];
    }
}

// Free the allocated memory and reset the hash table
void free_hash_table(HashTable* table) {
    free(table->buckets);
    free(table);
}

int main() {
    HashTable* table = initialize_hash_table(16);
    insert_hash_table(table, "key1", 10);
    insert_hash_table(table, "key2", 20);
    printf("%d\n", retrieve_hash_table(table, "key1"));
    free_hash_table(table);
    return 0;
}
