void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle allocation failure
        printf("Memory allocation failed\n");
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

// Function to manage dynamic memory allocation and initialization
void initialize_data_structures(int num_keys, int num_records, int min_value, int max_value, size_t threshold) {
    // Allocate and initialize key array
    long* keys = (long*)my_malloc(num_keys * sizeof(long));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }

    // Allocate and initialize offset array
    int* offsets = (int*)my_malloc(num_keys * sizeof(int));
    for (int i = 0; i < num_keys; i++) {
        offsets[i] = i;
    }

    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min_value, max_value);

    // Allocate and initialize record array
    struct record* records = (struct record*)my_malloc(num_records * sizeof(struct record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = dis(gen);
        records[i].key_index = i % num_keys;
    }

    // Deallocate memory
    my_free(keys);
    my_free(offsets);

    // Handle memory threshold adjustment if needed
    size_t total_size = sizeof(long) * num_keys + sizeof(int) * num_keys + sizeof(struct record) * num_records;
    while (total_size > threshold && num_records > 0) {
        num_records--;
        records = (struct record*)realloc(records, num_records * sizeof(struct record));
        total_size = sizeof(long) * num_keys + sizeof(int) * num_keys + sizeof(struct record) * num_records;
    }

    // Deallocate remaining memory
    my_free((void*)records);
}
