#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the node structure
typedef struct Node {
    char* str;
    struct Node* next;
} Node;

// Function to create a new node with allocated memory
Node* newNode(char* str, int size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL; // Handle allocation failure

    node->str = (char*)malloc(size + 1); // Allocate space for string and null-terminator
    if (!node->str) {
        free(node);
        return NULL; // Handle allocation failure
    }

    strcpy(node->str, str);
    node->next = NULL;
    return node;
}

// Function to add a new node at the end of the list
void addNode(Node** head, char* str, int size) {
    Node* newNode = newNode(str, size);

    if (!*head) *head = newNode; // Add first node
    else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = newNode;
    }
}

// Function to free all allocated memory when the function returns
void freeMemory(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
}
