    for (int i = 0; i < graph->num_nodes; i++) {
        if (strcmp(graph->nodes[i]->id, from_node_id) == 0)
            from_node = graph->nodes[i];
        else if (strcmp(graph->nodes[i]->id, to_node_id) == 0)
            to_node = graph->nodes[i];
    }

    // Create a new edge and add it to the edges list
