    edge->from_node_id = from_node_id;
    edge->to_node_id = to_node_id;
    // Add more edge attributes as needed
    graph->num_edges++;
    Edge **edges = (Edge **)realloc(graph->edges, graph->num_edges * sizeof(Edge *));
    edges[graph->num_edges - 1] = edge;

