// Function to manage dynamic memory allocation and initialization
int manage_memory(int offset_size, int key_size, int record_count, float max_usage_threshold) {
    // Initialize arrays for offset values and keys
    void* offsets = alloc_array(offset_size, sizeof(long));
    void* keys = alloc_array(key_size, sizeof(int));

    // Initialize array of records
    void** records = (void**)malloc(sizeof(record*) * record_count);
    if (!records) {
        printf("Memory allocation failed!\n");
        exit(-1);
    }

    // Ensure memory usage does not exceed threshold
    float total_usage = (float)(offset_size + key_size + sizeof(record*) * record_count);
    while (total_usage > max_usage_threshold) {
        // Dynamically adjust array sizes to fit within the constraint
        offset_size /= 2;
        key_size /= 2;
        record_count /= 2;

        offsets = realloc(offsets, offset_size * sizeof(long));
        keys = realloc(keys, key_size * sizeof(int));

        for (int i = 0; i < record_count; i++) {
            records[i] = realloc(records[i], sizeof(record));
        }

        total_usage = (float)(offset_size + key_size + sizeof(record*) * record_count);
    }

