    for (int i = 0; i < numNodes; i++) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        nodes[i]->left = NULL;
        nodes[i]->right = NULL;
        nodes[i]->data = 0.0;
    }
    return nodes;
}

// Depth-first search function to calculate the sum of all double data fields
double DFS(Node* node) {
    if (node == NULL) {
        return 0.0;
    }
    return node->data + DFS(node->left) + DFS(node->right);
}

