void cleanUp(Node** nodes, int numNodes) {
    for (int i = 0; i < numNodes; i++) {
        free(nodes[i]);
    }
    free(nodes);
}

Node* createNode(double data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->left = NULL;
    node->right = NULL;
    node->data = data;
