typedef struct {
    float reading;
    char quality;
    time_t timestamp;
} sample;

sample* init_data(int n, float mean, float stddev) {
    int i;
    srand(time(NULL));

    // Calculate the valid range for sensor readings
    float min = mean - 2 * stddev;
    float max = mean + 2 * stddev;

    // Allocate memory for arrays
    sample* samples = (sample*)malloc(n * sizeof(sample));
    float* readings = (float*)malloc(n * sizeof(float));
    char* qualities = (char*)malloc(n * sizeof(char));

    // Initialize sensor readings using a Gaussian distribution
    for(i = 0; i < n; i++) {
        readings[i] = mean + (rand() / (RAND_MAX / (max - min)) * (max - min) + rand() % 2 ? stddev : -stddev);
    }

    // Initialize data quality indicators randomly
    char* flags = {"G", "O", "E"};  // Example flags for data quality
    for(i = 0; i < n; i++) {
        qualities[i] = flags[rand() % 3];
    }

    // Create sample records and assign readings, qualities, and timestamps
    for(i = 0; i < n; i++) {
        samples[i].reading = readings[i];
        samples[i].quality = qualities[i];
        samples[i].timestamp = time(NULL);
    }

    return samples;
}
