#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define RECORD_COUNT 1000
#define KEY_ARRAY_SIZE 50000
#define INT_MAX 1000000
#define HASH_TABLE_SIZE 128

typedef struct {
    int value;
    long* key;
} record_t;

record_t* records = NULL;
long* key_array = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int record_count = 0;
int hash_table[HASH_TABLE_SIZE] = {0};

void* allocate_block(int size) {
    void* block = malloc(size);
    if (!block) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return block;
}

void free_block(void* block, int size) {
    free(block);
}

int hash_function(long key) {
    return (int)(key % HASH_TABLE_SIZE);
}

long find_key(int index) {
    for (int i = 0; i < record_count; i++) {
        if (records[i].value == index && records[i].key != NULL) {
            return *records[i].key;
        }
    }
    return -1;
}

void* insert_record(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&lock);
    record_t* new_record = (record_t*)allocate_block(sizeof(record_t));
    new_record->value = rand() % INT_MAX;
    new_record->key = &key_array[index];
    records = realloc(records, (record_count + 1) * sizeof(record_t));
    for (int i = 0; i < record_count; i++) {
        hash_table[hash_function(*records[i].key)]++;
    }
    records[record_count++] = new_record;
    pthread_mutex_unlock(&lock);
    return NULL;
}

void* query_records(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].value == index && records[i].key != NULL) {
            printf("Found key %ld at index %d\n", *records[i].key, i);
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    srand(time(NULL));
    key_array = (long*)allocate_block(KEY_ARRAY_SIZE * sizeof(long));
    records = (record_t*)allocate_block(RECORD_COUNT * sizeof(record_t));

    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        key_array[i] = rand() % INT_MAX;
    }

    pthread_t threads[RECORD_COUNT];
    for (int i = 0; i < RECORD_COUNT; i++) {
        pthread_create(&threads[i], NULL, insert_record, &i);
    }
    for (int i = 0; i < RECORD_COUNT; i++) {
        pthread_join(threads[i], NULL);
    }

    // Query records
    for (int i = 0; i < RECORD_COUNT; i++) {
        pthread_create(&threads[i], NULL, query_records, &i);
    }
    for (int i = 0; i < RECORD_COUNT; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    free(records);
    free(key_array);

    return 0;
}
