    free(ptr);
}

record* manage_memory(int initial_size, int max_range) {
    record* records = (record*)my_malloc(initial_size * sizeof(record));
    long* offsets = (long*)my_malloc(initial_size * sizeof(long));

    for (int i = 0; i < initial_size; i++) {
        records[i].random = rand() % max_range;
        records[i].offset = &offsets[i];
        offsets[i] = i;
    }

    return records;
}

void resize_arrays(record** records, long** offsets, int new_size) {
    if (new_size <= 0) {
        // Handle error
        return;
    }

    record* new_records = (record*)my_realloc(*records, new_size * sizeof(record));
    long* new_offsets = (long*)my_realloc(*offsets, new_size * sizeof(long));

    for (int i = initial_size; i < new_size; i++) {
        new_records[i].random = rand() % max_range;
        new_records[i].offset = &new_offsets[i];
        new_offsets[i] = i;
    }

    my_free(*records);
    *records = new_records;

    my_free(*offsets);
    *offsets = new_offsets;

    initial_size = new_size;
}

int validate_record(record* record) {
