void* init_datastructures(int offset_size, int key_size, int record_size, int num_records) {
    // Calculate total size of arrays
    int total_size = (offset_size + key_size + record_size * sizeof(record_t)) * (num_records + 1);

    // Check if memory threshold exceeded
    if (total_size > MEMORY_THRESHOLD) {
        // Adjust array sizes to fit within constraint
        offset_size /= 2;
        key_size /= 2;
        record_size = MIN_RECORD_SIZE;

