        doubles = realloc(doubles, numDoubles * sizeof(double));
        floats = realloc(floats, numFloats * sizeof(float));
        measurements = realloc(measurements, numMeasurements * sizeof(measurement));
    }

    free(doubles);
    free(floats);
    free(measurements);
}

int main() {
    manageMemory(1000, 500, 2000);
    return 0;
}
