typedef struct {
    char* str;
    int val;
    struct entry* child;
} entry;

// Function to dynamically allocate memory for and initialize an array of entry structures
entry** createTree(entry root, int depthLimit) {
    // Dynamic allocation for the root node
    entry** tree = (entry**)malloc(sizeof(entry*) * 2);
    if (!tree) return NULL;  // Handle memory allocation failure

    tree[0] = &root;
    root.child = NULL;

    // Recursive function to populate child pointers based on depth limit
    int i;
    for (i = 1; i < depthLimit && tree[i-1]; i++) {
        tree[i] = (entry**)malloc(sizeof(entry*) * 2);
        if (!tree[i]) return NULL;  // Handle memory allocation failure

        // Initialize child node with string and integer value
        entry* child = &((*(tree+i))[0]);
        child->str = strdup("Child Node");
        child->val = i;
        child->child = NULL;

        // Set parent-child relationships
        ((*(tree[i-1])).child) = (void*)child;
    }

    return tree;
}

// Function to safely free all allocated memory
void freeTree(entry** tree, int depthLimit) {
    for (int i = 0; i < depthLimit; i++) {
        if (tree[i]) {
            entry* node = *(tree+i);
            free(node->str);
            free(node);

            // Recursively free child nodes
            freeTree(&node->child, depthLimit - i - 1);
        }
    }

    free(tree);
}

int main() {
    // Example usage:
    entry root;
    root.str = strdup("Root Node");
    root.val = 0;

    int depthLimit = 3;
    entry** tree = createTree(root, depthLimit);

    if (tree) {
        printf("Created tree of depth %d\n", depthLimit);
        // Process the tree here...
    } else {
        printf("Failed to allocate memory.\n");
    }

    // Free allocated memory
    freeTree(tree, depthLimit);

    return 0;
}
