typedef struct {
    long timestamp;
    int priority;
    char *buffer;
} entry;

entry *create_entry(long timestamp, int priority, size_t buffer_size) {
    entry *entry = malloc(sizeof(entry));
    entry->timestamp = timestamp;
    entry->priority = priority;
    entry->buffer = malloc(buffer_size);
    return entry;
}

void free_entry(entry *entry) {
    free(entry->buffer);
    free(entry);
}

typedef struct {
    double data;
    node *child[2];
} node;

node *create_node(double data) {
    node *node = malloc(sizeof(node));
    node->data = data;
    for (int i = 0; i < 2; i++) {
        node->child[i] = NULL;
    }
    return node;
}

void free_node(node *node) {
    for (int i = 0; i < 2; i++) {
        if (node->child[i] != NULL) {
            free_node(node->child[i]);
        }
    }
    free(node);
}

double dfs_sum(node *root, double sum) {
    if (root == NULL) {
        return sum;
    }
    sum += root->data;
    for (int i = 0; i < 2; i++) {
        sum = dfs_sum(root->child[i], sum);
    }
    return sum;
}

node *allocate_nodes(size_t size, double threshold) {
    node **nodes = malloc(sizeof(node *) * size);
    for (size_t i = 0; i < size; i++) {
        nodes[i] = create_node(i);
    }
    node *root = nodes[0];
    for (int i = 1; i < size; i++) {
        nodes[i]->child[0] = nodes[i - 1];
        nodes[i]->child[1] = NULL;
    }
    return root;
}

void deallocate_nodes(node *root) {
    if (root == NULL) {
        return;
    }
    for (int i = 0; i < 2; i++) {
        deallocate_nodes(root->child[i]);
    }
    free_node(root);
}

node *deallocate_nodes_safe(node *root, node **nodes, size_t size) {
    if (root == NULL) {
        return root;
    }
    for (int i = 0; i < 2; i++) {
        deallocate_nodes_safe(root->child[i], nodes, size);
    }
    free_node(root);
    for (size_t i = 0; i < size; i++) {
        if (nodes[i] == root) {
            nodes[i] = NULL;
            break;
        }
    }
    return NULL;
}

int main() {
    node *root = allocate_nodes(10, 1024);
    double sum = dfs_sum(root, 0.0);
    deallocate_nodes_safe(root, NULL, 0);
    return 0;
}
