#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    char* str;
    int val;
    struct entry* child;
} entry;

void serialize_entry(entry* e, FILE* file) {
    fwrite(&e->str, sizeof(char*), 1, file);
    fwrite(&e->val, sizeof(int), 1, file);
    if (e->child != NULL) {
        fwrite(&e->child, sizeof(struct entry*), 1, file);
    } else {
        fputc('\0', file); // indicate end of file
    }
}

entry* deserialize_entry(FILE* file) {
    entry* e = malloc(sizeof(entry));
    fread(&e->str, sizeof(char*), 1, file);
    fread(&e->val, sizeof(int), 1, file);
    if (fgetc(file) == '\0') {
        // end of file
        free(e);
        return NULL;
    }
    e->child = deserialize_entry(file);
    return e;
}

void traverse_tree(entry* root, int depth, FILE* file) {
    if (root == NULL) {
        return;
    }
    for (int i = 0; i < depth; i++) {
        fputc('\n', file); // indentation
    }
    fprintf(file, "%s: %d\n", root->str, root->val);
    traverse_tree(root->child, depth + 1, file);
}

void free_entry(entry* e) {
    if (e == NULL) return;
    free(e->str);
    free(e);
}

void serialize_tree(entry* root, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        // error handling
        return;
    }
    while (root != NULL) {
        serialize_entry(root, file);
        root = root->child;
    }
    fclose(file);
}

entry* deserialize_tree(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        // error handling
        return NULL;
    }
    entry* root = NULL;
    entry* current = NULL;
    while (fseek(file, 0, SEEK_END) > 0 || fgetc(file) != '\0') {
        current = deserialize_entry(file);
        if (root == NULL) {
            root = current;
        } else {
            entry* temp = root;
            while (temp->child != NULL) {
                temp = temp->child;
            }
            temp->child = current;
        }
    }
    fclose(file);
    return root;
}

void create_entry(entry** pentry, const char* str, int val, int depth, entry** ppchild) {
    *pentry = malloc(sizeof(entry));
    (*pentry)->str = strdup(str);
    (*pentry)->val = val;
    if (depth > 0) {
        (*pentry)->child = create_entry(&(*ppchild), "child", val + 1, depth - 1, ppchild);
    } else {
        (*pentry)->child = NULL;
    }
}

int main() {
    entry* root = create_entry(&root, "parent", 0, 2, &root->child);
    serialize_tree(root, "tree.bin");
    return 0;
}
