// Define the function to manage memory allocation and initialization
record* manageMemory(int numRecords, int maxStringLength) {
    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, maxStringLength);

    // Allocate memory for arrays aligned to cache line boundaries
    size_t offsetSize = sizeof(long) + (sizeof(long) % 64);
    long* offsets = (long*)malloc(offsetSize * numRecords);
    int* keys = (int*)malloc(sizeof(int) * numRecords);

    // Initialize arrays
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Allocate memory for record array and strings
    record* records = (record*)malloc(sizeof(record) * numRecords);
    char** strings = (char**)malloc(sizeof(char*) * numRecords);

    // Initialize records and strings
    for (int i = 0; i < numRecords; i++) {
        records[i].value = i;
        strings[i] = (char*)malloc(dis(gen));
        strcpy(strings[i], "Record ");
        itoa(i, strings[i] + strlen("Record "), 10);
    }

    // Return the memory management structure
    return records;
}

// Deallocate all allocated memory
void deallocateMemory(record* records) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i].string);
    }
    free(records);
    free(keys);
    free(offsets);
}
