    // Allocate memory from the external pool
    void* ptr = malloc(size);

    if (ptr) {
        // Store metadata for size and type
        char* metadata = (char*) ptr;
        *metadata = 0x01; // Type: CacheEntry

        return (void*) (metadata + sizeof(char));
    }

    return NULL;
}

void my_free(void* ptr) {
    // Check if the allocated block has metadata
    char* metadata = (char*) ptr - sizeof(char);

    if (*metadata == 0x01) { // Type: CacheEntry
        free(ptr);
    }
}

// Initialize the cache with a predefined set of entries
