class LinkedList {
public:
    // Constructor
    LinkedList() : head(nullptr) {}

    // Insert a new node at the end of the list
    void insert(const char* str, int value, const CustomObject& obj) {
        ListNode* newNode = new ListNode(str, value, std::shared_ptr<CustomObject>(new CustomObject(obj.id, obj.name)));
        if (!head) {
            head = newNode;
        } else {
            ListNode* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = newNode;
        }
    }

    // Delete a node from the list
    void deleteNode(const char* str) {
        if (!head) return;

        if (head->str == str) {
            ListNode* temp = head;
            head = head->next;
            delete temp;
            return;
        }

        ListNode* current = head;
        while (current && current->next && current->next->str != str) {
            current = current->next;
        }

        if (current && current->next) {
            ListNode* temp = current->next;
            current->next = current->next->next;
            delete temp;
        }
    }

    // Traverse the list
    void traverse() {
        ListNode* current = head;
        while (current) {
            std::cout << "String: " << current->str << ", Value: " << current->value << ", Object: " << current->obj->name << std::endl;
            current = current->next;
