public:
    // Constructor
    HashTable(int size) : tableSize(size), bucket(nullptr) {}

    // Insert a new node into the hash table
    void insert(const char* str, int value, const CustomObject& obj) {
        int hash = hashFunction(str);
        if (!bucket[hash]) {
            bucket[hash] = new HashNode;
            bucket[hash]->str = str;
            bucket[hash]->value = value;
            bucket[hash]->obj = obj;
        } else {
            HashNode* current = bucket[hash];
            while (current->next) {
                current = current->next;
            }
            current->next = new HashNode;
            current->next->str = str;
            current->next->value = value;
            current->next->obj = obj;
        }
    }

    // Delete a node from the hash table
    void deleteNode(const char* str) {
        if (!bucket[0]) return;

        int hash = hashFunction(str);
        HashNode* current = bucket[hash];
        if (current->str == str) {
            bucket[hash] = current->next;
            delete current;
            return;
        }

        while (current && current->next && current->next->str != str) {
            current = current->next;
        }

        if (current && current->next) {
            HashNode* temp = current->next;
            current->next = current->next->next;
            delete temp;
        }
    }

    // Traverse the hash table
    void traverse() {
        for (int i = 0; i < tableSize; i++) {
            if (bucket[i]) {
                HashNode* current = bucket[i];
                while (current) {
                    std::cout << "String: " << current->str << ", Value: " << current->value << ", Object: " << current.obj.name << std::endl;
                    current = current->next;
                }
            }
        }
    }

private:
    int tableSize;
    HashNode** bucket;

    // Custom hash function
    int hashFunction(const char* str) {
        int hash = 0;
        for (int i = 0; i < strlen(str); i++) {
            hash += (int)str[i];
        }
        return hash % tableSize;
    }
