void dynamic_memory_allocation(int offset_size, int key_size, int num_records) {
    // Initialize random seed for reproducibility and efficiency
    srand(time(NULL));

    // Calculate total memory required for arrays and records
    size_t array_total = (size_t)(offset_size + key_size);
    size_t record_total = sizeof(record) * num_records;

    if ((array_total + record_total) > (MAX_MEMORY_THRESHOLD / 2)) {
        printf("Error: Memory allocation exceeds threshold.\n");
        return;
    }

    // Allocate memory for arrays and records
    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));
    record* records = malloc(record_total);

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize arrays and records
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % RANDOM_RANGE;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % RANDOM_RANGE;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % RANDOM_RANGE;
    }

    // Monitor cumulative memory usage and adjust sizes if necessary
    size_t total_memory = array_total + record_total;

    while ((total_memory > MAX_MEMORY_THRESHOLD) || 
           (num_records > (MAX_RECORDS * 8 / 10))) {
        printf("Error: Memory allocation exceeds threshold. Adjusting sizes...\n");

        // Reduce array sizes
        offset_size /= 2;
        key_size /= 2;

        // Recalculate total memory and reallocate if necessary
        array_total = (size_t)(offset_size + key_size);
        record_total = sizeof(record) * num_records;

        // Adjust record count to maintain efficient performance
        num_records = MIN(MAX_RECORDS, num_records - record_total);

        // Reallocation strategy: Preallocate buffer space or use slab allocation techniques
        free(offsets);
        offsets = malloc(offset_size * sizeof(long));
        free(keys);
        keys = malloc(key_size * sizeof(int));
        free(records);
        records = malloc(record_total);

        if (offsets == NULL || keys == NULL || records == NULL) {
            printf("Error: Memory allocation failed.\n");
            return;
        }

        // Initialize arrays and records
        for (int i = 0; i < offset_size; i++) {
            offsets[i] = rand() % RANDOM_RANGE;
        }
