            records[i].value = rand() % RANDOM_RANGE;
        }

        // Monitor cumulative memory usage again
        total_memory = array_total + record_total;
    }

    // Deallocate all allocated memory upon function return
    free(offsets);
    free(keys);
    free(records);
}

