        return NULL;
    }
    for (int i = 0; i < n; i++) {
        offsets[i] = i * 10000L + rand();
    }
    return offsets;
}

void deallocate_offsets(long *offsets, int n) {
    free(offsets);
}

int main() {
    int n = 100000;
    record *records = allocate_records(n);
    if (!records) {
        printf("Failed to allocate records.\n");
        return -1;
    }

    long *offsets = allocate_offsets(n);
    if (!offsets) {
        printf("Failed to allocate offsets.\n");
        deallocate_records(records, n);
        return -1;
    }

    // Use the allocated memory...

