        records[i]->str = malloc(100); // dynamic string allocation
    }

    return records;
}

void resize_dynamic_array(record** records, int new_num_records) {
    record** new_records = (record**)malloc(new_num_records * sizeof(record*));

    for (int i = 0; i < new_num_records; i++) {
        new_records[i] = (record*)malloc(sizeof(record));
    }

    // Copy existing data to the new array
    for (int i = 0; i < new_num_records && i < *records[0]; i++) {
        new_records[i]->key = records[i]->key;
        new_records[i]->weight = records[i]->weight;
        strcpy(new_records[i]->str, records[i]->str);
    }

    // Deallocate old array
    for (int i = 0; i < *records[0]; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(*records);

    *records = new_records;
}

void deallocate_dynamic_array(record** records) {
    for (int i = 0; i < *records[0]; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(*records);
}
