#define MAX_FILE_NAME_LENGTH 255
#define MAX_EXTENSIONS 1000

typedef struct {
    long offset;
    int key;
} Record;

Record* initializeDataStructures(int* numRecords) {
    *numRecords = 0;
    return (Record*)malloc(MAX_EXTENSIONS * sizeof(Record));
}

void processDirectory(const char* dirPath, int* numExtensions, char*** extensions) {
    DIR* directory = opendir(dirPath);
    if (!directory) {
        perror("Error opening directory");
        exit(EXIT_FAILURE);
    }

    struct dirent* entry;
    Record* records = NULL;
    int numRecords = 0;

    while ((entry = readdir(directory))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        Record* record = (Record*)malloc(sizeof(Record));
        // Set random value for int field
        record->key = rand() % 100;

        // Process filename and generate new extension
        char oldName[MAX_FILE_NAME_LENGTH];
        strcpy(oldName, entry->d_name);
        char* newName = trimWhitespacesAndRemoveLeadingSpecialChars(oldName);

        char type[4] = "";
        if (newName) {
            for (int i = 0; i < strlen(newName); i++) {
                if (!isalnum((unsigned char)newName[i])) {
                    continue;
                }
                type[0] = tolower((unsigned char)getNameType((unsigned char)newName[i]));
                break;
            }
        }

        if (*type == '\0') {
            strcpy(type, "TXT");
        }

        // Check for conflicting extensions
        int foundExtension = 0;
        for (int i = 0; i < *numExtensions; i++) {
            if (strcmp(extensions[i][0], type) == 0) {
                foundExtension = 1;
                break;
            }
        }

        char* newExtension = generateNewExtension(type, &foundExtension);
        *newName = '\0';
        strcat(newName, oldName);
        strcat(newName, ".");
        strcat(newName, newExtension);
        free(oldName);

        // Add to records array
        record->offset = (long)strlen(newName);
        records = (Record*)realloc(records, (*numRecords + 1) * sizeof(Record));
        records[*numRecords].key = record->key;
        (*numRecords)++;

        free(record);
    }

    closedir(directory);

    // Allocate memory for arrays
    *numExtensions += *numRecords;
    *extensions = (char**)malloc(*numExtensions * sizeof(char*));

    int i, j;
    for (i = 0; i < *numExtensions - *numRecords; i++) {
        (*extensions)[i] = (char*)malloc(MAX_EXTENSIONS);
        strcpy((*extensions)[i], "A");
    }
    for (i = 0; i < *numRecords; i++) {
        (*extensions)[*numExtensions - 1 - i] = (char*)malloc(strlen(newName) + 1);
        strcpy((*extensions)[*numExtensions - 1 - i], newName);
    }

    free(records);
}

void generateNewExtension(char* type, int* foundExtension) {
    static char extensions[MAX_EXTENSIONS][MAX_EXTENSIONS];
    static int numExtensions = 0;

    for (int i = 0; i < *foundExtension; i++) {
        strcpy(extensions[numExtensions], type);
        strcat(extensions[numExtensions], "1");
        numExtensions++;
    }

    if (*numExtensions > MAX_EXTENSIONS) {
        printf("Too many extensions. Limit exceeded.\n");
        exit(EXIT_FAILURE);
    }
}
