Record** dataset = NULL;
int dataset_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_dataset(int size) {
    Record** temp = (Record**)malloc(size * sizeof(Record*));
    for (int i = 0; i < size; i++) {
        temp[i] = (Record*)malloc(sizeof(Record));
    }
    return temp;
}

void* deallocate_dataset(void* ptr) {
    Record** temp = (Record**)ptr;
    for (int i = 0; i < dataset_size; i++) {
        free(temp[i]);
    }
    free(ptr);
    return NULL;
}

int add_record(int key, long offset) {
    pthread_mutex_lock(&mutex);
    Record* new_rec = (Record*)malloc(sizeof(Record));
    new_rec->key = key;
    new_rec->offset = offset;

    if (dataset_size == 0) {
        dataset = allocate_dataset(1);
        dataset[0] = new_rec;
        dataset_size = 1;
    } else {
        Record** temp = (Record**)malloc((dataset_size + 1) * sizeof(Record*));
        for (int i = 0; i < dataset_size; i++) {
            temp[i] = dataset[i];
        }
        free(dataset);
        dataset = temp;
        dataset[dataset_size] = new_rec;
        dataset_size++;
    }
    pthread_mutex_unlock(&mutex);

    return 0;
}

void cleanup() {
    deallocate_dataset(dataset);
    dataset = NULL;
    dataset_size = 0;
}
