        total_memory_usage += sizeof(long) * (num_streams+1);
        num_streams++;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Set up record array
    int **records = malloc(num_streams * sizeof(int *));
    for (int i = 0; i < num_streams; i++) {
        records[i] = malloc(sizeof(int));
    }

    // Set values of each record's int field to a random value within a given range
    for (int i = 0; i < num_streams; i++) {
        *records[i] = rand() % 100;
    }

    // Flush random number generator states periodically to minimize memory overhead
    for (int i = 0; i < 10; i++) {
        srand(time(NULL));
    }

    // External video codec library integration
    VIDEO_FRAME_T **frames = malloc(num_streams * sizeof(VIDEO_FRAME_T *));
    for (int i = 0; i < num_streams; i++) {
        frames[i] = malloc(sizeof(VIDEO_FRAME_T));
    }

    // Compress and decompress frames using the external video codec library
    for (int i = 0; i < num_streams; i++) {
        // Handle potential errors from library calls
        if (compress_frame(frames[i]) == -1) {
            printf("Error compressing frame %d\n", i);
        }
        if (decompress_frame(frames[i]) == -1) {
            printf("Error decompressing frame %d\n", i);
        }
    }

    // Test latency and throughput of video processing pipeline
    int total_frames_processed = 0;
    for (int i = 0; i < num_streams; i++) {
        // Generate performance metrics or visualize frame rates
        printf("Frame rate: %.2f fps\n", get_frame_rate());
        total_frames_processed += get_number_of_frames();
    }

    // Support multi-threaded operation for concurrent stream handling
    pthread_t threads[num_streams];
    for (int i = 0; i < num_streams; i++) {
        pthread_create(&threads[i], NULL, process_stream, &frames[i]);
    }
    for (int i = 0; i < num_streams; i++) {
        pthread_join(threads[i], NULL);
    }

    // Caching mechanism for frequently accessed frames
    int *frame_cache = malloc(num_streams * sizeof(int));
    for (int i = 0; i < num_streams; i++) {
        frame_cache[i] = -1; // Invalidated cache entry
    }

    // Cache eviction policy to optimize memory usage and access speed
    for (int i = 0; i < num_streams; i++) {
        if (frame_cache[i] == -1) {
            printf("Cache miss: Frame %d not found in cache\n", i);
        } else {
            printf("Cache hit: Frame %d accessed from cache\n", i);
        }
    }

    // Free allocated memory
    for (int i = 0; i < num_streams; i++) {
        free(frames[i]);
        free(records[i]);
    }
    free(frames);
    free(records);
}
