#define MAX_RECORDS 100000
#define NAME_MAX_LENGTH 64
#define VALUE_MAX_SIZE 16
#define RANDOM_NAME_MIN_LENGTH 8
#define RANDOM_NAME_MAX_LENGTH 32
#define RANDOM_VALUE_MIN 0
#define RANDOM_VALUE_MAX 255

typedef struct {
    char* name;
    int value;
} Record;

Record* records = NULL;
int record_count = 0;
FILE* log_file = NULL;

void init_records(int max_name_length, int min_value, int max_value) {
    if (log_file == NULL) {
        log_file = fopen("record_operation.log", "w");
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->name = malloc((rand() % max_name_length + 1) * sizeof(char));
        strcpy(record->name, random_string(rand() % (MAX_NAME_LENGTH - RANDOM_NAME_MIN_LENGTH + 1) + RANDOM_NAME_MIN_LENGTH));
        record->value = rand() % (max_value - min_value + 1) + min_value;
        records[i] = record;
    }
}

void add_record(char* name, int value) {
    Record* record = malloc(sizeof(Record));
    record->name = name;
    record->value = value;
    // Add the new record to the existing collection
    for (int i = 0; i < record_count; i++) {
        if (strcmp(records[i]->name, name) == 0) {
            free(record);
            return;
        }
    }
    records[record_count] = record;
    record_count++;
}

void remove_record(char* name) {
    for (int i = 0; i < record_count; i++) {
        if (strcmp(records[i]->name, name) == 0) {
            free(records[i]->name);
            free(records[i]);
            for (int j = i; j < record_count - 1; j++) {
                records[j] = records[j + 1];
            }
            record_count--;
            return;
        }
    }
}

void log_operation(char* operation, char* name, int value) {
    fprintf(log_file, "%s: %s with value %d\n", operation, name, value);
    fflush(log_file);
}

char* random_string(int length) {
    static char buffer[NAME_MAX_LENGTH + 1];
    for (int i = 0; i < length; i++) {
        buffer[i] = 'a' + rand() % 26;
    }
    buffer[length] = '\0';
    return buffer;
}

void destroy_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]->name);
        free(records[i]);
    }
    free(records);
}
