#include <time.h>

typedef struct {
    int value;
    int *key;
} record;

record* initializeArrays(int sizeLimit, int recordCount) {
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    // Allocate arrays
    if ((offsets = (long*)malloc(sizeLimit * sizeof(long))) == NULL)
        return NULL;
    if ((keys = (int*)malloc(sizeLimit * sizeof(int))) == NULL) {
        free(offsets);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < sizeLimit; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Allocate records array
    if ((records = (record*)malloc(recordCount * sizeof(record))) == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < recordCount; i++) {
        records[i].value = -1;
        records[i].key = &keys[i % sizeLimit];
    }

    // Initialize records
    srand(time(NULL));
    int min = 1, max = 100;
    for (int i = 0; i < recordCount; i++) {
        do {
            records[i].value = rand() % ((max + 1) - min) + min;
        } while (findDuplicate(records, &records[i]) != NULL);
    }

    // Handle potential errors
    if (!checkMemoryUsage()) {
        printf("Error: Memory usage exceeded.\n");
        deallocateArrays(&offsets, &keys, &records);
        return NULL;
    }

    return records;
}

record* findDuplicate(record* records, record* target) {
    for (int i = 0; i < sizeof(records) / sizeof(record); i++) {
        if (records[i].value == target->value && records[i].key == target->key)
            return &records[i];
    }
    return NULL;
}

bool checkMemoryUsage() {
    // Check total memory usage
    if (getTotalMemoryUsage() > MEMORY_THRESHOLD) {
        printf("Error: Memory usage exceeded.\n");
        return false;
    }
    return true;
}

void deallocateArrays(long** offsets, int** keys, record** records) {
    free(*offsets);
    free(*keys);
    for (int i = 0; i < sizeof(records) / sizeof(record); i++) {
        free(records[i].key);
    }
    free(*records);
}
