        int index = hash_value % max_nodes;
        if (tree_nodes[index] == NULL || tree_nodes[index]->data == NULL) {
            tree_nodes[index]->data = current->data;
            tree_nodes[index]->index = current->index;
        } else {
            // Collision resolution strategy: linear probing or quadratic probing
            index = (index + 1) % max_nodes;
