    }

    *keys = (int *)malloc(maxSize * sizeof(int));
    *offsets = (long *)malloc(maxSize * sizeof(long));

    if (!*keys || !*offsets) {
        printf("Error: Memory allocation failed.\n");
        free(*keys);
        free(*offsets);
        *keys = NULL;
        *offsets = NULL;
    }
}

