#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_RECORDS 1000
#define RECORD_OVERHEAD 16
#define RANDOM_RANGE 1000
#define CACHE_SIZE 1024
#define MEMORY_THRESHOLD (MAX_RECORDS * (sizeof(long) + sizeof(int)) + (2 * sizeof(long)))

typedef struct {
    int value;
} record_t;

record_t* initialize_data_structures(int array_size, int num_records, int record_overhead_enabled, double threshold) {
    long* offsets = malloc(array_size * sizeof(long));
    int* keys = malloc(array_size * sizeof(int));

    // Initialize arrays and records
    for (int i = 0; i < array_size; i++) {
        offsets[i] = i;
        keys[i] = i % RANDOM_RANGE;
    }

    record_t* records = malloc(num_records * sizeof(record_t));
    for (int i = 0; i < num_records; i++) {
        if (!record_overhead_enabled || i < RECORD_OVERHEAD) {
            records[i].value = rand() % RANDOM_RANGE;
        } else {
            // Adjust record size based on position
            int adjusted_record_size = sizeof(record_t) + (i * 4);
            void* new_records = realloc(records, adjusted_record_size * num_records);
            if (!new_records) {
                printf("Memory allocation failed.\n");
                return NULL;
            }
            records = new_records;
        }
    }

    // Manage cache
    int* random_cache = malloc(CACHE_SIZE * sizeof(int));
    int cache_index = 0;

    for (int i = 0; i < num_records; i++) {
        if (records[i].value >= RANDOM_RANGE / 2) {
            records[i].value = random_cache[cache_index % CACHE_SIZE];
            cache_index++;
        } else {
            // Generate new random number
            int new_random = rand() % RANDOM_RANGE;
            while (new_random > RANDOM_RANGE / 2) {
                new_random = rand() % RANDOM_RANGE;
            }
            records[i].value = new_random;
            random_cache[cache_index++ % CACHE_SIZE] = new_random;
        }

        // Check memory threshold
        if ((i + 1) * sizeof(record_t) > MEMORY_THRESHOLD) {
            array_size *= 2;
            offsets = realloc(offsets, array_size * sizeof(long));
            keys = realloc(keys, array_size * sizeof(int));

            num_records *= 2;
            records = realloc(records, num_records * sizeof(record_t));

            // Reinitialize arrays and records
            for (int j = 0; j < array_size; j++) {
                offsets[j] = j;
                keys[j] = j % RANDOM_RANGE;
            }

            for (int j = 0; j < num_records; j++) {
                if (!record_overhead_enabled || j < RECORD_OVERHEAD) {
                    records[j].value = rand() % RANDOM_RANGE;
                } else {
                    // Adjust record size based on position
                    int adjusted_record_size = sizeof(record_t) + (j * 4);
                    void* new_records = realloc(records, adjusted_record_size * num_records);
                    if (!new_records) {
                        printf("Memory allocation failed.\n");
                        return NULL;
                    }
                    records = new_records;
                }
            }

            // Manage cache
            for (int j = 0; j < CACHE_SIZE; j++) {
                random_cache[j] = rand() % RANDOM_RANGE;
            }
        }
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);
    free(random_cache);

    return records;
}

void deallocate_data_structures(record_t* records) {
    free(records);
}
