    record* records = (record*)malloc(num_records * sizeof(record));

    // Check if memory allocation exceeded threshold
    size_t total_size = num_offsets * sizeof(long) + num_keys * sizeof(int) +
                        num_records * sizeof(record);
    if (total_size > threshold) {
        // Adjust array sizes and record count to fit within threshold
        int adjusted_num_offsets = num_offsets;
        while (adjusted_num_offsets * sizeof(long) > threshold / 3) {
            adjusted_num_offsets--;
        }
        int adjusted_num_keys = num_keys;
        while (adjusted_num_keys * sizeof(int) > threshold / 3) {
            adjusted_num_keys--;
        }
        int adjusted_num_records = num_records;
        while (adjusted_num_records * sizeof(record) > threshold / 3) {
            adjusted_num_records--;
        }

        // Reallocate arrays
        long* new_offsets = (long*)realloc(offsets, adjusted_num_offsets *
                                             sizeof(long));
        int* new_keys = (int*)realloc(keys, adjusted_num_keys * sizeof(int));
        record* new_records = (record*)realloc(records,
                                                 adjusted_num_records * sizeof(record));

        // Update array pointers
        offsets = new_offsets;
        keys = new_keys;
        records = new_records;

        num_offsets = adjusted_num_offsets;
        num_keys = adjusted_num_keys;
        num_records = adjusted_num_records;
