record* allocateArrays(int size, int threshold) {
    if (size > threshold / RECORD_SIZE) {
        printf("Memory exceeds the threshold. Adjusting array sizes.\n");
        size = threshold / RECORD_SIZE;
    }

    record* arrays[4];
    arrays[0] = (record*) malloc(size * sizeof(long));
    arrays[1] = (int*) malloc(size * sizeof(int));
    arrays[2] = (record*) malloc(size * sizeof(record));
    arrays[3] = (char**) malloc(size * sizeof(char*));

    for (int i = 0; i < size; i++) {
