            arrays[0][i], arrays[1][i], arrays[2][i].value, arrays[3][i]);
    }
}

void cleanUpLRUCache(record** cache, int size) {
    record* evicted = NULL;
    int leastRecentIndex = -1;

    for (int i = 0; i < size; i++) {
        if (leastRecentIndex == -1 || cache[i]->offset > cache[leastRecentIndex]->offset) {
            leastRecentIndex = i;
            evicted = cache[i];
        }
    }

    for (int i = leastRecentIndex; i < size - 1; i++) {
        cache[i] = cache[i + 1];
    }
    free(evicted);
}

void renderArraysAsFooter(record* arrays, int size) {
    printf("<footer>");
    for (int i = 0; i < size; i++) {
        printf("<script>var record = { offset: %ld, key: %d, value: %.2f };</script>\n",
