    int field2;
    int field3;
} Record;

void processDirectory(const char* directoryPath, int numOffsets, int numKeys) {
    // Allocate and initialize arrays
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    int* keys = (int*)malloc(numKeys * sizeof(int));

    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % 10000;
    }

    for (int i = 0; i < numKeys; i++) {
        keys[i] = rand() % 10;
    }

    // Allocate and initialize array of Record objects
    Record* records = (Record*)malloc(numOffsets * sizeof(Record));

    for (int i = 0; i < numOffsets; i++) {
        records[i].field1 = rand() % 100;
        records[i].field2 = rand() % 200;
        records[i].field3 = rand() % 300;
    }

    // Process files in directory
    char filePath[256];
    DIR* dir = opendir(directoryPath);
    struct dirent* ent;

    while ((ent = readdir(dir))) {
        if (ent->d_type == DT_REG) { // Check for regular file
            strcpy(filePath, directoryPath);
            strcat(filePath, "/");
            strcat(filePath, ent->d_name);

            int nonNumericChars = 0;
            for (int i = 0; i < strlen(ent->d_name); i++) {
                if (!isdigit(ent->d_name[i])) {
                    nonNumericChars++;
                }
            }

            // Generate unique identifier
            uint32_t checksum = crc32(ent->d_name);
            uint16_t hashValue = hashFunction(checksum);

            int fileExtension;
            if (nonNumericChars > 0) {
                fileExtension = nonNumericChars % 100;
            } else {
                fileExtension = 1;
            }

            // Normalize filename
            char* normalizedFileName = trimWhitespace(removeLeadingSpecialChars(ent->d_name));

            // Determine file type
            int fileTypeIndex = 0;
            for (int i = 0; i < strlen(normalizedFileName); i++) {
                if (!isdigit(normalizedFileName[i]) && !isalpha(normalizedFileName[i])) {
                    fileTypeIndex = i;
                    break;
                }
            }

            char* fileType = malloc(strlen(normalizedFileName) - fileTypeIndex);
            strncpy(fileType, normalizedFileName + fileTypeIndex, strlen(normalizedFileName) - fileTypeIndex);
            strcpy(normalizedFileName, fileType);

            // Initialize record
            Record* record = &records[hashValue % numOffsets];
            record->field1 = rand() % 100;
            record->field2 = rand() % 200;
            record->field3 = rand() % 300;

            printf("Processed file: %s\n", normalizedFileName);
        }
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    for (int i = 0; i < numOffsets; i++) {
        free(&records[i]);
    }
    free(records);

    closedir(dir);
}

