        free((void*)result->offset_array);
        free(result);
        return NULL; // Allocation failed
    }
    memset(result->key_array, 0, sizeof(int) * key_size);

    result->record_array = aligned_alloc(record_alignment, sizeof(record) * record_size);
    if (!result->record_array) {
        free((void*)result->offset_array);
        free((void*)result->key_array);
        free(result);
        return NULL; // Allocation failed
    }
    memset(result->record_array, 0, sizeof(record) * record_size);

    result->error_code = 0;
    return result;
}

void deallocate_memory(memory_management_struct* mm) {
    if (!mm) return;

    free((void*)mm->offset_array);
    free((void*)mm->key_array);
    free((void*)mm->record_array);
    free(mm);

    mm->error_code = -1; // or some other error code to indicate successful deallocation
}
