} record;

record** records;
int* keys;
long* offsets;
int num_records = 0;
int allocated_size = 10; // initial allocation size
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void cleanup() {
    for (int i = 0; i < num_records; i++) {
        free(records[i]->key);
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}

record** init_records(int size) {
    records = (record**)malloc(size * sizeof(record*));
    for (int i = 0; i < size; i++) {
        records[i] = (record*)malloc(sizeof(record));
    }
    return records;
}

void init_keys(int size, int range_start, int range_end) {
    keys = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
    }
}

long* init_offsets(int size) {
    offsets = (long*)malloc(size * sizeof(long));
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
    }
    return offsets;
}

void resize_arrays() {
    int new_allocated_size = allocated_size * 2;
    record** new_records = init_records(new_allocated_size);
    int* new_keys = (int*)malloc(new_allocated_size * sizeof(int));
    long* new_offsets = (long*)malloc(new_allocated_size * sizeof(long));

    // copy existing data to new arrays
    for (int i = 0; i < allocated_size; i++) {
        new_records[i]->key = &new_keys[i];
        new_records[i] = records[i];
    }

    free(records);
    free(keys);
    free(offsets);

    records = new_records;
    keys = new_keys;
    offsets = new_offsets;

    allocated_size = new_allocated_size;
}

record** manage_memory(int num_records) {
    if (num_records > allocated_size) {
        resize_arrays();
    }

    for (int i = 0; i < num_records; i++) {
        records[i]->key = &keys[offsets[i]];
    }

    return records;
}

void* process_data(void* arg) {
    int record_count = *(int*)arg;

    pthread_mutex_lock(&lock);
    record** processed_records = manage_memory(record_count);
    pthread_mutex_unlock(&lock);

    // process the records
    for (int i = 0; i < record_count; i++) {
        printf("Record %d: key=%d, value=%d\n", i, *(processed_records[i]->key), processed_records[i]->value);
    }

    return NULL;
}

int main() {
    int num_threads = 4;
    int record_per_thread = 10;

    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; i++) {
        int* record_count = &record_per_thread;
        pthread_create(&threads[i], NULL, process_data, record_count);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup();

    return 0;
}
