    manager->records = malloc((record_size / 2 + 1) * sizeof(short*));
    for (int i = 0; i < (record_size / 2 + 1); i++) {
        manager->records[i] = aligned_alloc(16, record_size * sizeof(short));
        if (!manager->records[i]) {
            printf("Error allocating memory for records.\n");
            free(manager->offsets);
            free(manager->keys);
            free(manager->records);
            return NULL;
        }
