#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* allocate_records(int count) {
    int size = sizeof(record);
    record* records = (record*)malloc(size * count);
    if (!records) return NULL;
    for (int i = 0; i < count; i++) {
        records[i].value = rand();
    }
    return records;
}

void set_record_values(record** records, int count, int min, int max) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        (*records)[i].value = rand() % (max - min + 1) + min;
    }
}

record* resize_record_array(record** records, int old_count, int new_count) {
    record* temp = (record*)malloc(sizeof(record) * new_count);
    if (!temp) return NULL;
    for (int i = 0; i < old_count && i < new_count; i++) {
        temp[i] = (*records)[i];
    }
    free(*records);
    *records = temp;
    return *records;
}

void adjust_memory_usage(record** records, int old_count, int threshold) {
    int total_size = sizeof(record) * old_count;
    while (total_size > threshold) {
        old_count /= 2;
        resize_record_array(records, old_count, old_count);
        total_size = sizeof(record) * old_count;
    }
}

record* manage_memory(int key_count, int record_count, int min_value, int max_value, int threshold) {
    // Initialize memory pool for arrays
    long* offset_values = (long*)malloc(sizeof(long));
    if (!offset_values) return NULL;
    int* keys = (int*)malloc(sizeof(int));
    if (!keys) free(offset_values);
    *offset_values = 0;
    *keys = 0;

    // Initialize record array
    record* records = allocate_records(record_count);

    set_record_values(&records, record_count, min_value, max_value);

    adjust_memory_usage(&records, record_count, threshold);

    return records;
}
