#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the log_entry structure
typedef struct {
    time_t timestamp;
    int log_level;
    char message[256];
    void* metadata;
    struct log_entry* next;
    struct log_entry* prev;
} log_entry;

// Initialize the circular buffer with a specified size
void init_circular_buffer(log_entry** buffer, int capacity) {
    *buffer = (log_entry*)malloc(capacity * sizeof(log_entry));
    for (int i = 0; i < capacity; i++) {
        (*buffer)[i].next = &((*buffer)[(i + 1) % capacity]);
        (*buffer)[i].prev = &((*buffer)[((i - 1) + capacity) % capacity]);
    }
}

// Insert a log entry into the circular buffer
void insert_log_entry(log_entry** buffer, int* head, int* tail, log_entry* new_entry) {
    new_entry->next = (*buffer)[(*tail)].next;
    new_entry->prev = &((*buffer)[(*tail)]);
    (*buffer)[(*tail)].next = new_entry;
    (*buffer)[(*tail)].prev = &((*buffer)[(*head)]);
    (*tail) = ((*tail) + 1) % capacity;
}

// Get the next log entry from the circular buffer
log_entry* get_next_log_entry(log_entry** buffer, int* head, int* tail) {
    return (*buffer)[(*head)].next;
}

// Define the log_batch structure
typedef struct {
    double metrics[10];
    char tags[256][32];
    time_t timestamp;
    char source[16];
} log_batch;

// Initialize the log batch with a specified size
void init_log_batch(log_batch* batch, int capacity) {
    batch->metrics = (double*)malloc(capacity * sizeof(double));
    batch->tags = (char**)malloc(capacity * sizeof(char*));
    for (int i = 0; i < capacity; i++) {
        batch->tags[i] = (char*)malloc(32 * sizeof(char));
    }
}

// Define the data_source structure
