#include <string.h>

typedef struct node {
    char* str;
    int priority;
    struct node* next;
} Node;

Node* init_node(int idx) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->str = (char*) malloc((idx+1)*sizeof(char));
    sprintf(node->str, "%d", idx);
    node->priority = idx;
    node->next = NULL;
    return node;
}

void init_tree(Node** root, int* count) {
    *root = NULL;
    *count = 0;
}

Node* insert_node(Node** root, Node* new_node) {
    if (*root == NULL || new_node->priority < (*root)->priority) {
        new_node->next = *root;
        *root = new_node;
    } else {
        Node* current = *root;
        Node* prev = NULL;
        while (current != NULL && current->priority >= new_node->priority) {
            prev = current;
            current = current->next;
        }
        if (current == NULL) {
            prev->next = new_node;
        } else {
            new_node->next = current;
            prev->next = new_node;
        }
    }
}

void traverse(Node* root, int threshold) {
    Node* current = root;
    while (current != NULL && *threshold > 0) {
        printf("%s\n", current->str);
        if (*threshold <= 0) break;
        *threshold -= strlen(current->str) + 1;
        current = current->next;
    }
}

void free_tree(Node* root) {
    Node* current = root;
    while (current != NULL) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
}

int main() {
    int count = 0;
    Node* root = NULL;

    // Initialize the tree
    init_tree(&root, &count);

    // Insert nodes into the tree
    for (int i = 0; i < 10; i++) {
        Node* new_node = init_node(i);
        insert_node(&root, new_node);
    }

    // Traverse the tree and retrieve node identifiers
    int threshold = 100;
    traverse(root, &threshold);

    // Free memory allocated for the tree
    free_tree(root);

    return 0;
}
