node_t* create_linked_lists(size_t num_lists, size_t rec_per_list,
                             long min_val, long max_val, size_t label_len) {
    if (num_lists == 0 || rec_per_list == 0 || label_len > sizeof(record_t)/sizeof(char))
        return NULL;

    node_t* lists = malloc(num_lists * sizeof(node_t));
    if (!lists)
        return NULL;

    for (size_t i = 0; i < num_lists; ++i) {
        lists[i].prev = &lists[i - 1];
        lists[i].next = &lists[(i + 1) % num_lists];

        size_t rec_count = rec_per_list;
        record_t** rec_ptrs = malloc(rec_count * sizeof(record_t*));
        if (!rec_ptrs)
            return NULL;

        for (size_t j = 0; j < rec_count; ++j) {
            long offset = rand_r(NULL) % (max_val - min_val + 1) + min_val;
            int key = rand() % INT_MAX;
            record_t* rec = malloc(sizeof(record_t));
            if (!rec)
                return NULL;

            rec->value = key;
            sprintf(rec->label, "Record %d", j);

            rec_ptrs[j] = rec;
        }

        lists[i].records = rec_ptrs;
        lists[i].len = rec_per_list;
    }

    node_t* head = &lists[0];
    for (size_t i = 1; i < num_lists; ++i)
        head->next->prev = &lists[i];

    return head;
}
