    double threshold = 1024 * 1024; // 1MB
    int array_sizes[3] = {0};

    // Allocate memory for arrays and check for overflow
    while (true) {
        if (array_sizes[0] + array_sizes[1] + sizeof(struct point) * num_records > threshold) {
            break;
        }
        array_sizes[0]++;
        array_sizes[1]++;
        num_records /= 2;
    }

    // Allocate memory for arrays
    double* doubles = malloc(array_sizes[0] * sizeof(double));
    char** strings = malloc(array_sizes[1] * sizeof(char*));
    struct point* points = malloc(num_records * sizeof(struct point));

