node* allocateRecords(int count, int minValue, int maxValue, int labelLength, time_t minTimestamp, int status) {
    if (count < 0 || !minValue || !maxValue || !labelLength || !minTimestamp) return NULL;

    node* head = NULL;
    record** records = (record**)malloc(count * sizeof(record*));
    if (!records) return NULL; // failed to allocate memory

    srand(time(NULL)); // seed random number generator
    for (int i = 0; i < count; i++) {
        int value = rand() % ((maxValue - minValue) + 1) + minValue;
        char* label = (char*)malloc((labelLength+1)*sizeof(char));
        if (!label) return NULL; // failed to allocate memory
        strcpy(label, "Label"); // default label
        time_t timestamp = minTimestamp + rand() % ((time(NULL) - minTimestamp) + 1);

        record* rec = (record*)malloc(sizeof(record));
        if (!rec) return NULL; // failed to allocate memory
        rec->offset = i;
        rec->key = i;
        rec->value = value;
        strcpy(rec->label, label);
        rec->timestamp = timestamp;
        rec->status = status;

        records[i] = rec;

        node* newNode = (node*)malloc(sizeof(node));
        if (!newNode) return NULL; // failed to allocate memory
        newNode->data = rec;
        newNode->size = 1;
        newNode->next = head;
        head = newNode;
    }

    for (int i = 0; i < count - 1; i++) {
        records[i]->next = records[i+1];
    }
    records[count-1]->next = NULL;

    return head;
}
