#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

Record** createDatabase(int capacity) {
    return (Record**)malloc(sizeof(Record*) * capacity);
}

void addRecord(Record** database, int capacity, int key, long offset) {
    // Check if the key is already in use
    for (int i = 0; i < capacity; i++) {
        if (database[i]->key == key) {
            return;
        }
    }

    // Allocate memory for a new record
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = rand() % 1000;  // Generate random offset within [0, 1000)

    // Find the first empty slot in the database
    int i;
    for (i = 0; i < capacity; i++) {
        if (!database[i]) {
            break;
        }
    }

    // Insert the new record into the database
    database[i] = newRecord;
}

Record* lookupRecord(Record** database, int capacity, int key) {
    for (int i = 0; i < capacity; i++) {
        if (database[i]->key == key) {
            return database[i];
        }
    }

    // If the record is not found, return NULL
    return NULL;
}

void freeDatabase(Record** database, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (database[i]) {
            free(database[i]);
        }
    }

    free(database);
}
