void* dynamic_memory_allocation(int num_offsets, int num_records) {
    // Allocate and initialize arrays for offset values and keys
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    int* keys = (int*)malloc(num_offsets * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Allocate memory for and initialize array of record structures
    record* records = (record*)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = i;
    }

    // Implement a custom random number generator
    int seed = time(NULL);
    srand(seed);

    // Ensure total memory usage does not exceed a predefined threshold
    const long MEM_THRESHOLD = 1024 * 1024 * 10;
    if (num_offsets * sizeof(long) + num_records * sizeof(record) > MEM_THRESHOLD) {
        // Dynamically adjust array sizes to fit within the constraint
        int new_num_offsets = num_offsets / 2;
        int new_num_records = num_records / 2;
        offsets = (long*)realloc(offsets, new_num_offsets * sizeof(long));
        keys = (int*)realloc(keys, new_num_offsets * sizeof(int));
        records = (record*)realloc(records, new_num_records * sizeof(record));

        // Reinitialize arrays
        for (int i = 0; i < new_num_offsets; i++) {
            offsets[i] = i;
            keys[i] = i;
        }
        for (int i = 0; i < new_num_records; i++) {
            records[i].value = i;
        }

        // Update memory usage
        num_offsets = new_num_offsets;
        num_records = new_num_records;
    }

    return (void*)records;
}
