#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structure for node in binary search tree (BST)
typedef struct Node {
    char* string;
    int value;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new node with given string and value
Node* createNode(char* str, int val) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->string = strdup(str);
    newNode->value = val;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a node into the BST
Node* insertNode(Node* root, char* str, int val) {
    if (!root) return createNode(str, val);

    Node* current = root;
    while (1) {
        if (strcmp(str, current->string) < 0) {
            if (!current->left)
                current->left = createNode(str, val);
            current = current->left;
        } else if (strcmp(str, current->string) > 0) {
            if (!current->right)
                current->right = createNode(str, val);
            current = current->right;
        } else
            return root; // node already exists, so return the root

    }
}

// Function to delete a node from the BST
Node* deleteNode(Node* root, char* str) {
    if (!root) return NULL;

    Node* current = root;
    while (1) {
        if (strcmp(str, current->string) < 0)
            current = current->left;
        else if (strcmp(str, current->string) > 0)
            current = current->right;
        else
            break; // node found, so break the loop

    }
    if (!current->left && !current->right) {
        free(current->string);
        free(current);
        return NULL;
    }

    Node* temp = current;
    current = (current->left ? current->left : current->right);
    free(temp->string);
    free(temp);

    if (!current)
        return root;

    // Perform the actual deletion
    if (current->left && current->right) {
        if (rand() % 2) { // Choose left or right child randomly
            Node* temp = current->right;
            current->right = NULL;
            free(temp->string);
            free(temp);
        } else {
            Node* temp = current->left;
            current->left = NULL;
            free(temp->string);
            free(temp);
        }
    }

    return root;
}

// Function to traverse the BST
void traverse(Node* root) {
    if (!root)
        return;

    traverse(root->left);
    printf("%s: %d\n", root->string, root->value);
    traverse(root->right);
}

// Define structure for node in red-black tree (RBT)
typedef struct Node {
    char* string;
    int value;
    struct Node* left;
    struct Node* right;
    struct Node* parent;
} Node;

// Function to create a new node with given string and value
Node* createNode(char* str, int val) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->string = strdup(str);
    newNode->value = val;
    newNode->left = newNode->right = newNode->parent = NULL;
    return newNode;
}

// Function to insert a node into the RBT
Node* insertNode(Node* root, char* str, int val) {
    if (!root) return createNode(str, val);

    Node* current = root;
    while (1) {
        if (strcmp(str, current->string) < 0)
            if (!current->left)
                current->left = createNode(str, val);
            else
                current = current->left;
        else if (strcmp(str, current->string) > 0)
            if (!current->right)
                current->right = createNode(str, val);
            else
                current = current->right;
        else
            return root; // node already exists, so return the root

    }

    // Perform actual insertion and balancing
    Node* temp = current;
    while (1) {
        if (!temp->left || !temp->right)
            break;

        if (rand() % 2) { // Choose left or right subtree randomly
            temp = temp->left;
        } else {
            temp = temp->right;
        }
    }

    Node* newNode = temp;
    temp = newNode;
    while (1) {
        if (!temp->parent)
            break;

        if (rand() % 2) { // Choose left or right child randomly
            Node* temp2 = temp->parent;
            temp = temp2;
        } else {
            Node* temp2 = temp->parent;
            temp = temp2;
        }
    }

    return root;
}

// Function to delete a node from the RBT
Node* deleteNode(Node* root, char* str) {
    if (!root) return NULL;

    // Find the node to be deleted
    Node* current = root;
    while (1) {
        if (strcmp(str, current->string) < 0)
            current = current->left;
        else if (strcmp(str, current->string) > 0)
            current = current->right;
        else
            break; // node found, so break the loop

    }

    // Perform actual deletion and balancing
    Node* temp = current;
    while (1) {
        if (!temp->left && !temp->right) {
            free(temp->string);
            free(temp);
            return root;
        }

        if (!temp->parent)
            break;

        if (rand() % 2) { // Choose left or right child randomly
            Node* temp2 = temp->parent;
            temp = temp2;
        } else {
            Node* temp2 = temp->parent;
            temp = temp2;
        }
    }

    return root;
}

// Function to traverse the RBT
void traverse(Node* root) {
    if (!root)
        return;

    traverse(root->left);
    printf("%s: %d\n", root->string, root->value);
    traverse(root->right);
}
