void* manage_memory(int array_size, int record_num) {
    // Allocate arrays for long offset values and int keys
    long* offsets = (long*)malloc(array_size * sizeof(long));
    int* keys = (int*)malloc(array_size * sizeof(int));

    // Initialize arrays with default values
    for (int i = 0; i < array_size; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Allocate memory for and initialize record structures
    record* records = (record*)malloc(record_num * sizeof(record));

    // Initialize records with default values
    for (int i = 0; i < record_num; i++) {
        records[i].value = i;
    }

    // Generate random numbers for record values
    srand(time(NULL));
    for (int i = 0; i < record_num; i++) {
        int rand_val = rand() % 100 + 1;
        records[i].value = rand_val;
    }

    // Initialize memory usage tracking variables
    size_t total_memory_usage = array_size * sizeof(long) + array_size * sizeof(int) + record_num * sizeof(record);
    size_t max_allowed_memory = 1024 * 1024 * 100; // 100MB

    while (total_memory_usage > max_allowed_memory) {
        // Resize arrays and records to fit within the constraint
        array_size /= 2;
        record_num /= 2;

        // Reallocate memory for arrays and records
        offsets = realloc(offsets, array_size * sizeof(long));
        keys = realloc(keys, array_size * sizeof(int));
        records = realloc(records, record_num * sizeof(record));

        // Initialize arrays and records with default values
        for (int i = 0; i < array_size; i++) {
            offsets[i] = i;
            keys[i] = i;
        }
        for (int i = 0; i < record_num; i++) {
            records[i].value = i;
        }

        // Recalculate memory usage tracking variables
        total_memory_usage = array_size * sizeof(long) + array_size * sizeof(int) + record_num * sizeof(record);
    }

    return records;
}
