    record *newRecords = NULL;
    size_t totalMemUsed = 0;
    int i = 0;

    while (totalMemUsed < totalMemLimit && i < numRecords) {
        record *recordPtr = (record *)malloc(sizeof(record));
        if (!recordPtr) {
            printf("Memory allocation failed. Total memory used: %zu bytes.\n", totalMemUsed);
            break;
