            records = realloc(records, (i + 1) * sizeof(record));
            if (!records) {
                printf("Memory allocation failed. Total memory used: %zu bytes.\n", totalMemUsed);
                free(recordPtr);
                break;
            }
        } else {
            records = recordPtr;
        }

        newRecords = records;
        totalMemUsed += sizeof(record);

        i++;
    }

    if (i < numRecords) {
        printf("Memory usage exceeded the specified limit. Number of records: %d.\n", i);
    } else if (!overwriteDups && i > 0) {
        int uniqueKeyCount = i;
        printf("Number of duplicate keys: %d.\n", i - uniqueKeyCount);
    }

    return newRecords;
