    int key;
    char* buffer;
} record;

record** records = NULL; // dynamic array of records
int size = 0;            // current size of the array
int capacity = 1000;     // initial capacity

// function to generate a random alphanumeric string
void generateBuffer(char* buffer) {
    const char* chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    int len = rand() % (20 - 10 + 1) + 10;
    for (int i = 0; i < len; i++) {
        buffer[i] = chars[rand() % strlen(chars)];
    }
    buffer[len] = '\0';
}

void freeRecords(record** records, int size) {
    for (int i = 0; i < size; i++) {
        if (records[i]->buffer != NULL) {
            free(records[i]->buffer);
        }
    }
    free(records);
}

record* createRecord() {
    record* newRecord = malloc(sizeof(record));
    if (newRecord == NULL) return NULL;
    newRecord->offset = rand() % 2000000 - 1000000;
    newRecord->key = rand() % 1001;
    char buffer[50];
    generateBuffer(buffer);
    newRecord->buffer = strdup(buffer);
    return newRecord;
}

void recordManager(record** records, int size) {
    for (int i = 0; i < size; i++) {
        // process the record
        printf("Offset: %ld, Key: %d, Buffer: %s\n", records[i]->offset, records[i]->key, records[i]->buffer);
    }
    freeRecords(records, size);
}

void recordManager_batch(record** records, int batchSize) {
    if (batchSize > capacity * 2) {
        // resize the array to accommodate new batch
        record** newRecords = realloc(records, sizeof(record*) * (capacity *= 2));
        capacity /= 2; // reset capacity after resizing
    }
    for (int i = 0; i < batchSize; i++) {
        record* newRecord = createRecord();
        if (records == NULL) { // first batch, initialize the array
            records = malloc(sizeof(record*) * capacity);
            size = 0;
        } else {
            records = realloc(records, sizeof(record*) * ++size);
        }
        records[size - 1] = newRecord;
    }
    recordManager(records, size);
}

int main() {
    // testing the function
    srand(time(NULL));
    int batchSize = 1000; // adjust this value to simulate different loads
    recordManager_batch(NULL, batchSize); // start processing records
    return 0;
}
