#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key[4];
} record;

record* load_module(const char* libname) {
    void* handle = dlopen(libname, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return NULL;
    }

    // Load and initialize module
    int (*init)(void);
    init = dlsym(handle, "init");
    if (init == NULL || *init() < 0) {
        dlclose(handle);
        return NULL;
    }

    // Get pointers to key arrays and offset values
    long* offsets = (long*)dlsym(handle, "offsets");
    int** keys = (int**)dlsym(handle, "keys");

    if (!offsets || !keys) {
        dlclose(handle);
        return NULL;
    }

    // Initialize record array
    size_t num_records = *init() + 1;
    record* records = (record*)calloc(num_records, sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        memcpy(records[i].key, keys[i], sizeof(int) * 4);
    }

    // Deallocate temporary data
    dlclose(handle);
    free(offsets);
    for (int i = 0; i < num_records; i++) free(keys[i]);
    free(keys);

    return records;
}

void unload_module(record* module, size_t num_records) {
    if (!module) return;

    // Deallocate record array
    free(module);
}
