record *init_module(int offset_size, int key_size, int record_count) {
    if (offset_size > THRESHOLD || key_size > THRESHOLD || record_count > THRESHOLD) {
        printf("Error: Size exceeds threshold.\n");
        return NULL;
    }

    long *offsets = (long *)malloc(offset_size * sizeof(long));
    int *keys = (int *)malloc(key_size * sizeof(int));

    for (int i = 0; i < offset_size; i++) {
        offsets[i] = (long)rand();
    }

    for (int i = 0; i < key_size; i++) {
        keys[i] = rand();
    }

    record *records = (record *)malloc(record_count * sizeof(record));

    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % 100;
    }

    // Load library
    void *handle = dlopen("libmylib.so", RTLD_LAZY);
    if (!handle) {
        printf("Error: Failed to load library.\n");
        dlerror();
        return NULL;
    }

    // Initialize module in the loaded library
    int (*init_func)(int, int, record *) = (int (*)(int, int, record *))dlsym(handle, "init_module");
    if (!init_func) {
        printf("Error: Failed to find init function.\n");
        dlclose(handle);
        return NULL;
    }

    int result = init_func(offset_size, key_size, records);

    // Release memory
    free(offsets);
    free(keys);
    free(records);

    // Close library
    dlclose(handle);

    return NULL;  // or return the result
}

