                        {
                            byte[] base64DecodedMessage = Convert.FromBase64String(message);
                            cs.Write(base64DecodedMessage, 0, base64DecodedMessage.Length);
                            cs.FlushFinalBlock();

                            decryptedBytes = ms.ToArray();
