        if ((records = realloc(records, sizeof(record_t) * (size + 1))) == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        for (i = 0; i < size; ++i) {
            if (rand() % 101 > records[i].key) break;
