typedef struct {
    int value;
} record;

record* init_records(int offset_count) {
    srand(time(NULL));

    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(offset_count * sizeof(int));
    record** records = (record**)malloc(offset_count * sizeof(record*));

    for (int i = 0; i < offset_count; i++) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % 10;
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = rand() % 100;
    }

    int* values = (int*)malloc(offset_count * sizeof(int));

    for (int i = 0; i < offset_count; i++) {
        values[i] = records[i]->value;
    }

    return (record*)records;
}

void update_record(record** records, int key, long offset, int value) {
    pthread_mutex_lock(pthread_mutex_self());
    for (int i = 0; i < offset_count; i++) {
        if (keys[i] == key && offsets[i] == offset) {
            records[i]->value = value;
            break;
        }
    }
    pthread_mutex_unlock(pthread_mutex_self());
}

void log_init(int level, int detail) {
    if (level <= 2) {
        printf("Records initialized with %d elements.\n", offset_count);
    } else if (level >= 3 && level <= 4) {
        for (int i = 0; i < offset_count; i++) {
            printf("Offset: %ld, Key: %d, Value: %d\n", offsets[i], keys[i], values[i]);
        }
    }
}

void log_update(int level, int key, long offset, int value) {
    if (level <= 2) {
        printf("Record updated at offset %ld with key %d and new value %d.\n", offset, key, value);
    } else if (level >= 3 && level <= 4) {
        for (int i = 0; i < offset_count; i++) {
            if (keys[i] == key && offsets[i] == offset) {
                printf("Record updated at offset %ld with key %d and new value %d.\n", offset, key, value);
                break;
            }
        }
    }
}

void destroy_records(record** records) {
    for (int i = 0; i < offset_count; i++) {
        free(records[i]);
    }
    free(keys);
    free(offsets);
    free(values);
}
