#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structures for nodes in binary search tree (BST) and red-black tree
typedef struct Node {
    char* data;
    int value;
} Node;

// Function to allocate memory for BST node
Node* createNode(char* data, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;  // Check if memory allocation failed
    newNode->data = (char*)malloc(strlen(data) + 1);
    strcpy(newNode->data, data);
    newNode->value = value;
    return newNode;
}

// Function to free memory allocated for BST node
void destroyNode(Node* node) {
    if (!node) return;  // Check if the node is NULL
    free(node->data);
    free(node);
}

// Define structure for BST node
typedef struct TreeNode {
    Node* data;
    int height;
} TreeNode;

// Function to allocate memory for BST node
TreeNode* createTreeNode(Node* data, int height) {
    TreeNode* newNode = (TreeNode*)malloc(sizeof(TreeNode));
    if (!newNode) return NULL;  // Check if memory allocation failed
    newNode->data = data;
    newNode->height = height;
    return newNode;
}

// Function to free memory allocated for BST node
void destroyTreeNode(TreeNode* node) {
    if (!node) return;  // Check if the node is NULL
    free(node);
}

// Define structure for red-black tree (RBT) node
typedef struct RNode {
    Node* data;
    int color;
} RNode;

// Function to allocate memory for RBT node
RNode* createRNode(Node* data, int color) {
    RNode* newNode = (RNode*)malloc(sizeof(RNode));
    if (!newNode) return NULL;  // Check if memory allocation failed
    newNode->data = data;
    newNode->color = color;
    return newNode;
}

// Function to free memory allocated for RBT node
void destroyRNode(RNode* node) {
    if (!node) return;  // Check if the node is NULL
    free(node);
}

// Define structure for memory pool allocator
typedef struct MemoryPool {
    void** memoryBlocks;
    int blockCount;
    int blockSize;
} MemoryPool;

// Function to create a new memory pool
MemoryPool* createMemoryPool(int blockCount, int blockSize) {
    MemoryPool* memoryPool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!memoryPool) return NULL;  // Check if memory allocation failed
    memoryPool->memoryBlocks = (void**)malloc(blockCount * sizeof(void*));
    if (!memoryPool->memoryBlocks) {
        free(memoryPool);
        return NULL;
    }
    memoryPool->blockCount = blockCount;
    memoryPool->blockSize = blockSize;
    return memoryPool;
}

// Function to allocate a block of memory from the pool
void* allocateMemoryBlock(MemoryPool* memoryPool) {
    if (!memoryPool) return NULL;  // Check if the memory pool is NULL
    for (int i = 0; i < memoryPool->blockCount; i++) {
        if (!memoryPool->memoryBlocks[i]) {
            void* block = (void*)malloc(memoryPool->blockSize);
            if (!block) return NULL;  // Check if memory allocation failed
            memoryPool->memoryBlocks[i] = block;
            return block;
        }
    }
    return NULL;  // All blocks are allocated, cannot allocate more
}

// Function to deallocate a block of memory from the pool
void deallocateMemoryBlock(MemoryPool* memoryPool, void* block) {
    if (!memoryPool || !block) return;  // Check if the memory pool or block is NULL
    for (int i = 0; i < memoryPool->blockCount; i++) {
        if (memoryPool->memoryBlocks[i] == block) {
            free(block);
            memoryPool->memoryBlocks[i] = NULL;
            return;
        }
    }
}

// Define structure for BST
typedef struct BinarySearchTree {
    TreeNode* root;
    MemoryPool* memoryPool;
} BinarySearchTree;

// Function to create a new binary search tree (BST)
BinarySearchTree* createBinarySearchTree() {
    BinarySearchTree* bst = (BinarySearchTree*)malloc(sizeof(BinarySearchTree));
    if (!bst) return NULL;  // Check if memory allocation failed
    bst->root = NULL;
    bst->memoryPool = createMemoryPool(16, 1024);  // Allocate initial memory pool with 16 blocks of size 1024 bytes each
    return bst;
}

// Function to insert a node into the BST
void insertNode(BinarySearchTree* bst, Node* node) {
    if (!bst || !node) return;  // Check if the BST or node is NULL
    TreeNode* newNode = createTreeNode(node, 1);  // Create new node with height 1
    if (bst->root == NULL) {
        bst->root = newNode;
    } else {
        TreeNode* current = bst->root;
        while (current != NULL) {
            int compare = strcmp(node->data, current->data->data);
            if (compare < 0) {
                if (current->height % 2 == 1) {
                    current->height++;
                }
                current = current->left;
            } else if (compare > 0) {
                if (current->height % 2 == 0) {
                    current->height++;
                }
                current = current->right;
            } else {
                destroyTreeNode(current);
                bst->root = newNode;
                return;  // Node already exists in the BST, no need to insert
            }
        }
    }
}

// Function to delete a node from the BST
void deleteNode(BinarySearchTree* bst, Node* node) {
    if (!bst || !node) return;  // Check if the BST or node is NULL
    TreeNode* current = bst->root;
    while (current != NULL) {
        int compare = strcmp(node->data, current->data->data);
        if (compare < 0) {
            current = current->left;
        } else if (compare > 0) {
            current = current->right;
        } else {
            destroyTreeNode(current);
            if (current == bst->root) {
                bst->root = NULL;
            }
            return;  // Node found and deleted
        }
    }
}

// Function to traverse the BST in-order
void inOrderTraversal(BinarySearchTree* bst, void (*callback)(Node*)) {
    if (!bst || !callback) return;  // Check if the BST or callback is NULL
    TreeNode* current = bst->root;
    while (current != NULL) {
        if (current->left != NULL) {
            current = current->left;
        }
        callback(current->data);
        current = current->right;
    }
}

// Define structure for memory pool allocator
typedef struct MemoryPoolAllocator {
    void* memoryBlock;
    int blockCount;
    int blockSize;
} MemoryPoolAllocator;

// Function to create a new memory pool allocator
MemoryPoolAllocator* createMemoryPoolAllocator(int blockCount, int blockSize) {
    MemoryPoolAllocator* allocator = (MemoryPoolAllocator*)malloc(sizeof(MemoryPoolAllocator));
    if (!allocator) return NULL;  // Check if memory allocation failed
    allocator->memoryBlock = allocateMemoryBlock();
    allocator->blockCount = blockCount;
    allocator->blockSize = blockSize;
    return allocator;
}

// Function to deallocate a block of memory from the pool
void deallocateMemoryBlock(MemoryPoolAllocator* allocator) {
    if (!allocator) return;  // Check if the allocator is NULL
    free(allocator->memoryBlock);
    allocator->memoryBlock = NULL;
}

// Define structure for red-black tree (RBT)
typedef struct RedBlackTree {
    RNode* root;
    MemoryPoolAllocator* memoryAllocator;
} RedBlackTree;

// Function to create a new red-black tree (RBT)
RedBlackTree* createRedBlackTree() {
    RedBlackTree* rbt = (RedBlackTree*)malloc(sizeof(RedBlackTree));
    if (!rbt) return NULL;  // Check if memory allocation failed
    rbt->root = NULL;
    rbt->memoryAllocator = createMemoryPoolAllocator(16, 1024);  // Allocate initial memory pool with 16 blocks of size 1024 bytes each
    return rbt;
}

// Function to insert a node into the RBT
void insertNode(RedBlackTree* rbt, Node* node) {
    if (!rbt || !node) return;  // Check if the RBT or node is NULL
    RNode* newNode = createRNode(node, BLACK);  // Create new node with color BLACK
    if (rbt->root == NULL) {
        rbt->root = newNode;
    } else {
        RNode* current = rbt->root;
        while (current != NULL) {
            int compare = strcmp(node->data, current->data->data);
            if (compare < 0) {
                if (current->color == BLACK) {
                    current->color = RED;  // Color the node red
                    current->height++;
                }
                current = current->left;
            } else if (compare > 0) {
                if (current->color == BLACK) {
                    current->color = RED;  // Color the node red
                    current->height++;
                }
                current = current->right;
            } else {
                destroyRNode(current);
                rbt->root = newNode;
                return;  // Node already exists in the RBT, no need to insert
            }
        }
    }
}

// Function to delete a node from the RBT
void deleteNode(RedBlackTree* rbt, Node* node) {
    if (!rbt || !node) return;  // Check if the RBT or node is NULL
    RNode* current = rbt->root;
    while (current != NULL) {
        int compare = strcmp(node->data, current->data->data);
        if (compare < 0) {
            current = current->left;
        } else if (compare > 0) {
            current = current->right;
        } else {
            destroyRNode(current);
            if (current == rbt->root) {
                rbt->root = NULL;
            }
            return;  // Node found and deleted
        }
    }
}

// Function to traverse the RBT in-order
void inOrderTraversal(RedBlackTree* rbt, void (*callback)(Node*)) {
    if (!rbt || !callback) return;  // Check if the RBT or callback is NULL
    RNode* current = rbt->root;
    while (current != NULL) {
        if (current->left != NULL) {
            current = current->left;
        }
        callback(current->data);
        current = current->right;
    }
}

// Function to free memory allocated for BST and RBT nodes
void destroyNodes(Node* node, int count) {
    for (int i = 0; i < count; i++) {
        if (node[i]) {
            destroyNode(node[i]);
        }
    }
}

// Function to print the contents of a binary search tree (BST)
void printBinarySearchTree(BinarySearchTree* bst) {
    if (!bst) return;  // Check if the BST is NULL
    inOrderTraversal(bst, (void(*)(Node*))printf("Data: %s, Value: %d\n"));  // Traverse the BST and print each node's data and value
}

// Function to print the contents of a red-black tree (RBT)
void printRedBlackTree(RedBlackTree* rbt) {
    if (!rbt) return;  // Check if the RBT is NULL
    inOrderTraversal(rbt, (void(*)(Node*))printf("Data: %s, Value: %d\n"));  // Traverse the RBT and print each node's data and value
}

int main() {
    BinarySearchTree* bst = createBinarySearchTree();
    RedBlackTree* rbt = createRedBlackTree();

    Node* node1 = createNode("Apple", 10);
    Node* node2 = createNode("Banana", 20);
    Node* node3 = createNode("Cherry", 30);

    insertNode(bst, node1);
    insertNode(bst, node2);
    insertNode(bst, node3);

    printBinarySearchTree(bst);

    deleteNode(bst, node1);

    printBinarySearchTree(bst);

    Node* node4 = createNode("Date", 40);
    Node* node5 = createNode("Elderberry", 50);

    insertNode(rbt, node4);
    insertNode(rbt, node5);

    printRedBlackTree(rbt);

    deleteNode(rbt, node4);

    printRedBlackTree(rbt);

    destroyNodes(node1, 3);  // Free memory allocated for BST and RBT nodes
    deallocateMemoryBlock(bst->memoryPool);
    deallocateMemoryBlock(rbt->memoryAllocator);

    return 0;
}

