record* init_record_array(int size) {
    record* arr = (record*)malloc(size * sizeof(record));
    if (!arr) return NULL; // Handle allocation error
    for (int i = 0; i < size; i++) {
        arr[i].value = rand() % 100; // Initialize with random values
    }
    return arr;
}

void* init_array(int size, int type) {
    void* ptr = malloc(size * sizeof(type));
    if (!ptr) return NULL; // Handle allocation error
    for (int i = 0; i < size; i++) {
        *(type*)ptr + i = rand() % 100; // Initialize with random values
        ptr = (void*)((char*)ptr + sizeof(type)); // Increment pointer
    }
    return ptr;
}

void deallocate_all(record** arr, long* offsets, int* keys) {
    if (arr) free(*arr);
    if (offsets) free(offsets);
    if (keys) free(keys);
}

int main() {
    int size = 1000; // Specify desired array sizes
    record* records = init_record_array(size);

    long* offsets = (long*)init_array(size, long);
    int* keys = (int*)init_array(size, int);

    deallocate_all(&records, &offsets, &keys);
    return 0;
}
