use tokio::prelude::*;
use tokio::sync::{mpsc, oneshot};
use std::env;
use std::fs;
use serde_json::json;

async fn command_processor(mut commands: mpsc::Receiver<String>) {
    let mut executors = vec![];
    for command in commands.recv_async().await {
        let (tx, rx) = oneshot::channel();
        let executor = tokio::spawn(async move {
            match exec_command(command).await {
                Ok(result) => tx.send(result).unwrap(),
                Err(error) => tx.send(Err(error)).unwrap(),
            }
        });
        executors.push((executor, rx));
    }

    for (executor, rx) in &mut executors {
        let result = rx.await.unwrap_or_else(|_| {
            tokio::time::sleep(std::time::Duration::from_millis(1000)).await;
            Err("Command timed out".to_string())
        });
        println!("Command completed: {}", result);
    }
}

async fn exec_command(command: String) -> Result<String, String> {
    // Execute command here
    // Return a JSON string with the execution status
    Ok(json!({
        "status": "success",
        "message": "Command executed successfully"
    }).to_string())
}

#[tokio::main]
async fn main() {
    let mut commands = mpsc::channel(10);
    for arg in env::args().skip(1) {
        if let Err(_) = commands.send(arg) {
            break;
        }
    }
    command_processor(commands).await;
}
